INSERT INTO `LatexNotes` (id, title, content, userId, type) VALUES (2,'Appunti OGA','\\documentclass{article}\r\n\\usepackage{graphicx} % Required for inserting img/images\r\n\\graphicspath{{/Users/simone/agora\\_documenti/img/Appunti\\_OGA} {/home/simone/agora/img/Appunti\\_OGA}}\r\n\\usepackage{geometry}\r\n\\usepackage{subcaption}\r\n\\geometry{a4paper, top=1 cm, bottom=1.5cm, left=1.5cm, right=2cm, bindingoffset=5mm}\r\n\\newenvironment{sistema}% \r\n{\\left\\lbrace\\begin{array}{@{}l@{}}}% \r\n{\\end{array}\\right.} \r\n\\usepackage{hyperref}\r\n\\usepackage{color}\r\n\\usepackage{amssymb}\r\n\\usepackage{amsmath}\r\n\\usepackage{textcomp}\r\n\\hypersetup{\r\n    colorlinks=true, \r\n    linktoc=all,     \r\n    linkcolor=black,  \r\n}\r\n\\DeclareMathSizes{11}{11}{11}{11}\r\n\\definecolor{dkgreen}{rgb}{0,0.6,0}\r\n\\definecolor{gray}{rgb}{0.5,0.5,0.5}\r\n\\definecolor{mauve}{rgb}{0.58,0,0.82}\r\n\\usepackage{xcolor}\r\n\\colorlet{keyword}{blue!100!black!80}\r\n\\colorlet{comment}{green!90!black!90}\r\n\\usepackage{listings}\r\n\r\n\\lstdefinelanguage{C}{\r\n  morekeywords={\r\n    void, int, int64, while, for, boolean, bool, true, false\r\n  },\r\n  morecomment=[l]--\r\n}\r\n\\lstdefinestyle{C}{\r\n  language     = C,\r\n  basicstyle   = \\ttfamily,\r\n  keywordstyle = [1]\\color{keyword}\\bfseries,\r\n  commentstyle = \\color{comment}\r\n}\r\n  \r\n\r\n\\title{Appunti OGA}\r\n\\author{Simone Battisti}\r\n\\date{2026-03-10}\r\n\r\n\\begin{document}\r\n\r\n\\maketitle\r\n\\tableofcontents\r\n\\pagebreak\r\n\r\n\\large\r\n\\section{Elementi di un\'Organizzazione}\r\n\r\n\\subsection{Gerarchie Aziendali}\r\n\r\nNealla crazioendi un\'azienda abbiamo bisogno di identificare degli\r\n\\textbf{organi} a livello aziendale, che definiscono \\textit{ruoli e\r\ndecisioni}. Questa gerarchia pu\\`o essere definita \\textbf{orizzontale},\r\ndove abbiamo uan divisione del lavorosulla base della\r\n\\textit{specializzazione}, oppure \\textbf{verticale}, dove abbiamo una\r\nvera e propria gerarchia di livelli e ruoli.\r\n\r\n\\begin{center}\\includegraphics[width=3.34583in,height=1.79444in]{img/image1.png}\\end{center}\r\n\r\nGli organi di \\textbf{staff} invece rappresentano organi che \\textit{non\r\nimpattano sulle decisioni}, ma supportano le decisioni dei manager.\r\n\r\nPer una divisione \\textit{orizzontale} avremo una divisione che porter\\`a\r\nalal formazioni di \\textit{gruppi}, raggruppati principal-mente da\r\n\\textbf{funzioni variamente specializzate} (aree specializate in diversi\r\nobiettivi). Esistono diversi approcci per questo tipo di divisione:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Per input}: divisione pr funzione\r\n\r\n\\item \\textbf{Per output}: per famiglia di prodotti, area geografica,\r\nclientela,...\r\n\r\n\\item \\textbf{Per inpute e per output}: strutturare l\'organizzazione a\r\n\\textit{matrice}\r\n\\end{itemize}\r\n\r\nLe scelte organizzative vengono definite secondo due parametri:\r\n\\textbf{obiettivi di massima efficacia}, compatibili con \\textbf{un\r\nelevato grado di efficienza}.\r\n\r\nL\'\\textit{efficacia} di un\'azienda definisce la possibilit\\`a di arrivare\r\nad un obiettivo preposto, mentre l\'\\textit{efficienza} indica quanto\r\nl\'azienda \\`e riuscita a produrre comparato con il costo delle risorse.\r\n\r\n\\subsection{Organigrammi}\r\n\r\nUn organigramma \\`e un modo per definire con uno schema grafico\r\nl\'impresa. Viene principalmente usato per:\r\n\r\n\\begin{itemize}\r\n\\item Chiarire i ruoli e le rispettive funzioni.\r\n\r\n\\item Delimitare i compiti e le aree di intervengo di singoli e di gruppi di\r\nutenti.\r\n\r\n\\item Precisare le relazioni gerarchiche.\r\n\\end{itemize}\r\n\r\n\\begin{center}\\includegraphics[width=3.34583in,height=2.04306in]{img/image2.png}\\end{center}\r\n\r\n\\subsection{Tipi di Strutture}\r\n\r\nLe organizzaioni possono avere diversi tipi di struttura:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Struttura semplice}: solitamente adottata da aziende di\r\npiccole dimensioni, dove abbiamo un accen-tramento delle funzioni\r\nsull\'imprenditore e una bassa specializzazioen dei compiti, dove sempre\r\ntutto \\`e coordinato dall\'imprenditore. Questo tipo di struttura permette\r\ndecisioni rapide ed una alta flessibilit\\`a operativa.\r\n\\end{itemize}\r\n\r\n\\begin{center}\\includegraphics[width=3.17361in,height=1.47361in]{img/image3.png}\\end{center}\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Struttura Polifunzionale}: ogni funzione di focalizza su\r\ndeterminati compiti. Il ruolo decisionale \\`e molto sviluppato in\r\ngerarchia con un \\textit{decentramento limitato}, inatti in questo caso\r\nabbiamo diversi enti che prendono decisioni nelle loro aree funzionali.\r\nQuesto tipo di struttura definisce una maggioreefficienza all\'interno\r\ndel sistema aziendale, un economia di scala e favorisce lo sviluppo di\r\ncompetenze specialistiche, incrementando la produttivit\\`a. I problemi\r\ndi questo tipo di struttura possono essere i \\textit{disallineamenti tra}\r\n\\textit{le diverse aree}, perdendo l\'attenzione su determinati obiettivi,\r\nsfavorendo la collaborazioen tra le funzioni.\r\n\\end{itemize}\r\n\r\n\\begin{center}\\includegraphics[width=3.17361in,height=1.96528in]{img/image4.png}\\end{center}\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Struttura Multifunzionale}: questa struttura definisce una\r\n\\textit{divisione per attivit\\`a}, che vengono raggrup-pate in \\textit{modo\r\norizzontale}. L\'azienda viene divisa in \\textbf{divisioni}, dopve ogni\r\ndivisione \\`e divisa a sua volta in varie aree, portando ad una maggiore\r\nspecializzazione. Questa specializzazione permette anche una\r\n\\textit{divisione decisionale}. Il problema di questa struttura \\`e\r\ndefinito come \\textit{ridondanza}, poinch\\\'e dato che lo stesso ente verr\\`a\r\ndefinito per pi\\`u aree diverse, portando ad una ripetitivitit\\`a\r\ndelle operazioni e maggiori costi.\r\n\\end{itemize}\r\n\r\n\\begin{center}\\includegraphics[width=3.17361in,height=2.49722in]{img/image5.png}\\end{center}\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Struttura a Matrice/Progetto}: abbiamo specifici progetti che\r\nfanno riferimento a diversi manager. Le attivit\\`a sono orgasnizzate per\r\n\\textit{input} e per \\textit{output}, infatti le divisioni vengono\r\norganizzate per funzione e per prodotto/clientela. I singoli gruppi\r\noperano al di sotto di un manager deciso per prodotto. Nell\'utilizzo di\r\nquesta struttura \\`e sempre meglio dare molta attenzione e chiarezza\r\ndata la \\textit{multilinea di comando}.\r\n\\end{itemize}\r\n\r\n\\begin{center}\\includegraphics[width=3.17361in,height=2.00972in]{img/image6.png}\\end{center}\r\n\r\n\\subsection{Logica di Processo}\r\n\r\nLa logica per processo raggruppa le attivit\\`a per \\textbf{processi\r\nchiave}, tenendo conto del contributo del singolo. In questo processo le\r\naziende ristrutturano i propri processi guardando soprattutto al\r\n\\textbf{cliente}. Bisogna creare un processo di prodotto per far\r\n\\textbf{collaborare le diverse aree aziendali}. Uno degli approcci pi\\`u\r\nconsolidati \\`e la \\textbf{struttura per processi}, dove tutte le decisioni\r\nsono date al cliente, superando una visione frammentata e generando\r\ncollaborazioni fra reparti.\r\n\r\n\\begin{center}\\includegraphics[width=3.34583in,height=2.12361in]{img/image7.png}\\end{center}\r\n\r\n\\subsection{Meccanismi di Coordinamento del Lavoro}\r\n\r\nUnaa perosna che lavora in azienda defve avere un\'idea chiara della sua\r\nposizione e le mansioni che svolger\\`a, detto \\textbf{mansionario}.\r\nQueste mansion idevono essere svolte secondo delle \\textbf{norme\r\nprocedurali}, che definiscono concretamente come decono essere svolti\r\nspecifici compiti. I manager di ogni funzionario sono definiti da\r\n\\textbf{stili di leadership}, che definiscono i comportamenti degli\r\norgani direttivi e la modalit\\`a di esecuzione del loro potere.\r\n\r\n\\subsection{Terminologia Aziendale}\r\n\r\nNell\'ambito aziendale molti termmini vengono caratterizzati da\r\ndefinizioni diverse. Il primo \\`e la divisione tra \\textbf{azienda},\r\n\\textbf{impresa} e \\textbf{societ\\`a}:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Azienda}: aspetto materiale, definito dal dispiegamento delle\r\nrisorse.\r\n\r\n\\item \\textbf{Impresa}: attivit\\`a imprenditoriale.\r\n\r\n\\item \\textbf{Societ\\`a}: concretizza, in termini giuridici, le 2\r\ndefinizioni precedenti.\r\n\\end{itemize}\r\n\r\nUna societ\\`a pu\\`o essere dfinita come: \\textbf{Societ\\`a di Persone},\r\nla cui responsabilit\\`a \\`e dedicata a delle persone fisiche, o \\textbf{Societ\\`a di Capitali}, dove la resposabilit\\`a \\`e dedicata al\r\ncapitale investito. \r\nAlcuni ruoli devono \\textbf{monitorare l\'impresa} a livello giuridico, questi\r\nsono i \\textbf{governance}, che a loro volta sono divisi in:\r\n\\textbf{assemblea dei soci}, \\textbf{consiglio di amministrazione},\r\n\\textbf{collegio sindacale}, \\textbf{amministratore delegato} e\r\n\\textbf{direttore generale}.\r\n\r\nUn\'azienda quando lavora opera in un \\textbf{ambiente} che definisce\r\nsolitamente il tipo di prodott osviluppato e dove l\'azienda deve andare\r\na vendere.\r\n\r\nIl \\textbf{mercato} invece \\`e un tipo di ambito da cui l\'azienda prende o fornisce risorse\r\n(capitali, investimenti, materie prime,...). Il mercato pu\\`o essere \\textbf{mercato del lavoro}, dove\r\nvengono trovati i dipendenti, \\textbf{mercato di ap-provigionamento}, da\r\ndove vengono reperite le materie prime per la costruzione del prodotto\r\nfinale, oppure il \\textbf{mercato delle vendite}, dove l\'azienda vender\\`a\r\nil proprio prodotto.\r\n\r\n\\subsection{Perfomance di un\'Azienda}\r\n\r\nUn\'azienda viene giudicata ancheda degli indicatori per consolidare le\r\nproprie decisioni. Questi parametri sono ad esempio l\'\\textbf{utile}:\r\n\r\n\\[ \\textit{utile} = \\textit{ricavi} - \\textit{costi} \\]\r\nL\'utile definisce se l\'azienda sta\r\nlavorando \\textbf{in perdita} o \\textbf{in crescita}.\r\n\r\nUn altro parametro \\`e la \\textbf{reddittivit\\`a}, deifnito come\r\nl\'\\textbf{investimento} che c\'\\,\\`e stato per arrivare ad un prodotto e\r\nquanto questo prodotto porter\\`a profitto.\r\n\r\nUn\'azienda pu\\`o agire sopra le performance tramite le \\textbf{leve\r\noperative}, delle tecniche di gestione aziendale che permettono un\r\n\\textbf{minore spreco} e dunque una \\textbf{reddittivit\\`a maggiore}.\r\n\r\n\\section{L\'Evoluzione del Pensiero Organizzativo}\r\n\r\n\\subsection{La Scuola Classica e l\'Approccio Deterministico}\r\n\r\nLa domanda principale che si \\`e fatta negli anni della definizione di\r\n\\textbf{pensiero organizzativo} \\`e: \\textit{perch\\\'e dobbi-amo studiare\r\nl\'evoluzione del pensiero organizzativo?}. LA risposta \\`e che solo\r\ncomprendendo l\'evoluzione delle strutture e modelli di gestione possiamo\r\ndefinire un modello che sia coerente con gli studi che sono stati fatti\r\nnegli anni.\r\n\r\nNella storia vari studi sono stati definiti su questo argomento e si\r\nsono formate diverse \\textbf{teorie} dietro al pensiero organizzativo,\r\ndivise principalmente dal focus che va dagli \\textbf{individui} a quelle\r\nche si concentrano sui \\textbf{sistemi}, definendo una dimensione di\r\napproccio pi\\`u \\textbf{deterministica} o pi\\`u \\textbf{probabilistica}.\r\n\r\nIncrociando queste 2 dimensioni possiamo definire nel quadrante\r\n\\textit{deterministico} la \\textbf{Scuola Classica}, definita durante la\r\nRivoluzione Industriale per risolveew i problemi dei nascenti sistemi di\r\n\\textit{fabbriche}. Il padre di questa teoria \\`e \\textbf{Frederick Taylor}, che\r\naveva l\'intento di trasformare l\'organizzazione empiritca ad una vera e\r\npropria scienza basata su \\textbf{principi scientifici}. Questi principi\r\nincludevano la divisione del lavoro in \\textbf{formule}, per selezionare\r\ne formare singolarmente la mandopera, imponendo una rigida\r\ncollaborazione dove \\textit{i dirigenti dettano le regole e gli operai\r\neseguono con determinazione}. La teoria di Taylor subisce per\\`o una\r\nforte critica perch\\\'e ignora completamente gli aspetti umani e sociali,\r\nnon tenendo conto degli ambienti imprevedibili a cui le persone si\r\ndevono adattare.\r\n\r\nIl secondo autore della Scuola Classica fu \\textbf{Henri Fayol} con la\r\nsua \\textbf{teoria amministrativa}, che sposta l\'attenzione della\r\nfabbrica principalemnte sulla \\textbf{classe dirigenziale}. Fayol\r\ndefinisce l\'attivit\\`a di \\textbf{Direzione}, come la capacit\\`a di una\r\npersona o gruppo di persone di \\textit{prevedere, organizzare, comandare,\r\ncoordinare e con-trollare} un\'azienda. Scompone l\'azienda in 6 funzioni\r\nprincipali: \\textbf{tecnica, commerciale, sicurezza, ammin-istrativa,\r\nfinanziaria e direttiva}, introducendo principi cardine come la\r\n\\textbf{centralizzazione del comando}, la \\textbf{importanza della gerarchia}, l\'\\textbf{equit\\`a} e la possibilit\\`a di \\textbf{subordinare gli interessi personali rispetto}\r\na \\textbf{queli aziendali}.\r\n\r\nIl terzo pilastro della Scuola Classica fu \\textbf{Max Weber} con la sua\r\n\\textbf{Teoria Burocratica}. Per Weber l\'organizzaione perfetta si basa\r\nsu una \\textbf{rigida divisione del lavoro}, con una chiara gerarchia,\r\nla quale deve sottostare ad una serie di regole generali scritte per\r\ngovernare ogni decisisione. Il modello di Weber definisce una totale\r\n\\textbf{impersonalit\\`a nelle relazioni} per\r\ngarantire la massima uniformit\\`a dei comportamenti.\r\n\r\n\\subsection{Relazioni Umane e Stili di Direzione}\r\n\r\nIn contrapposizione alla rigidit\\`a della Scuola Classica si contrappone\r\nla \\textbf{Scuola delle Relazioni Umane}. QUesta corrente riconosce che\r\nl\'uomo non \\`e spinto solamente dalla razionalit\\`a economica, ma ha\r\nbisogi fisici, psicologici e sociali. Il pilastro di questa corrente \\`e\r\n\\textbf{Elton Mayo} che \'\'scopr\\`\\i\'\' quanto fondamentale fossero le\r\ncondizioni umane all\'interno di un\'azienda e quanto queste comportino un\r\ngrande \\textbf{aumento della produt-tivit\\`a}, definite \\textbf{teorie\r\nmotivazionali}:\r\n\r\n\\begin{center}\\includegraphics[width=3.34583in,height=2.15972in]{img/image8.png}\\end{center}\r\n\r\nQuesta piramide, detta \\textbf{Piramide di Maslow}, definisce in modo\r\ngerarchico i bisogni umani per aumentare la produzione e il benessere\r\ndei propri dipendenti.\r\n\r\nStrettamente legata a questa scuola \\`e la \\textbf{Teoria sugli Stili di\r\nDirezione} di \\textbf{Likert}, la quale definisce 4 modi in cui un\r\nmanager pu\\`o comportarsi con i propri dipendenti:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Stile autoritario}: il manager decide tutto da solo imponendo\r\nle sue scelte\r\n\r\n\\item \\textbf{Stile paternalistico}: il capo prende le decisioni principali\r\nma delega ai subordinati l\'esecuzione.\r\n\r\n\\item \\textbf{Stile consultivo}: nel quale il manager prende ancora le\r\ndecisioni importanti ma incoraggia i dipendenti a dare consigli o idee.\r\n\r\n\\item \\textbf{Stile partecipativo}: dove il management ha uno stile molto\r\ndemocratico e caratterizzato dai vari dipendenti che prendono\r\ndecisioni \\textit{assieme}.\r\n\\end{itemize}\r\n\r\n\\subsection{Dalle Contingenze ai Modelli Snelli: Come si Adatta\r\nl\'Organizzazione}\r\n\r\nSpostando l\'attenzione sulle teorie che si basano sui \\textbf{sistemi},\r\ntra gli anni \'60 e \'70 si \\`e sviluppata la \\textbf{Teoria di\r\nContingenza} la quale definisce che:\r\n\r\n\\begin{quote}\r\n\\textbf{\'\'Non esiste un unico modello organizzativo perfetto, ma la\r\nstruttura migliore \\`e quella che si adatta ad una serie di fattori\r\ncontingenti interni ed esterni all\'organizzazione\'\'}\r\n\\end{quote}\r\n\r\nLa continguenza pu\\`o essere divisa in 4 categorie principali:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Ambientale}: l\'impresa che opera in un ambiente instabile e\r\ndinamico \\`e pi\\`u produttiva di una che opera un un ambiente\r\nstatico/meccanico.\r\n\r\n\\item \\textbf{Strategica}: afferma che l\'assetto organizzativo dipende dalla\r\nstrategia decisa dall\'azienda e non viceversa.\r\n\r\n\\item \\textbf{Tecnologica}: la struttura verticale di un\'azienda \\`e\r\nstrettamente correlata al tipo di tecnologia produttiva utilizzata.\r\n\r\n\\item \\textbf{Dimensionale}: sostiene che le organizzazioni pi\\`u grandi\r\nnecessitano di maggiore specializzazione, for- mazione e pianigicazione,\r\nrispetto a quelle pi\\`u piccole.\r\n\\end{itemize}\r\n\r\nSempre tra le scuole che riguardano il sistema troviamo la\r\n\\textbf{Teoria dei COsti di Transazione} che indaga perch\\\'e certe\r\ntransazioni avvengano all\'interno dell\'azienda o affidate al mercato.\r\nL\'obiettivo strategico di un\'azienda diventa la \\textbf{minimizzazione\r\ndi questi costi}. Un esempio ne \\`e la \\textbf{Strategic Integration\r\nContinuum}:\r\n\r\n\\begin{center}\\includegraphics[width=3.34583in,height=1.48333in]{img/image9.png}\\end{center}\r\n\r\nPi\\`u recenti sono le aziende che vengono definite \\textbf{snelle}. Le\r\nquali concentrano le risorse sul core business aiendale, esternizzando\r\nle attivit\\`a \\textit{non essenziali}, riducendo i livelli gerarchici in\r\nfavore di sturtture orizzontali. Famoso \\`e l\'esempio del \\textit{Tempio\r\ndel Total Quality Management} (TQM), il quale definsice una struttura\r\nsolida della costruzione di un\'azienda basata su 5 pilastri\r\nfindamentali:\r\n\r\n\\begin{center}\\includegraphics[width=3.34583in,height=2.02778in]{img/image10.png}\\end{center}\r\n\r\n\\subsection{I Fondamenti della Strategia}\r\n\r\nDurante la creazione di un\'impresa dobbiamo definire la\r\n\\textbf{strategia} aziendale che la nostra impresa adotter\\`a. Essa\r\nrappresenta il raccordo fondamentale tra l\'esterno e l\'azienda stessa.\r\nPer avere un impatto decisivo e performante la strategia deve trovare\r\nuna buona via di mezzo tra queste 2 entit\\`a.\r\n\r\nE molto importante \\textbf{distinguere la strategia dalla tattica}. La\r\nstrategia \\`e uno \\textbf{schema generale d\'azione a lungo termine},\r\nil cui fine \\`e il portare l\'azienda al massimo delle performance. La\r\ntattica, al contrario, \\`e un\'\\textbf{azione specifica all\'interno del\r\nquadro generale} per riuscire a far \'\'vincere\'\' determinate sequenze\r\nalla propria azienda. Entrambe vanno a pari passo, dato che la strategia\r\ndefinisce la tattica e viceversa.\r\n\r\nLa strategia opera su 3 livelli decisionali interconnessi:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Strategia di Corporate}: decide in quali settori investire per\r\nottenere profitto superiore alla media, distribuendo le risorse\r\naziendali di conseguenza.\r\n\r\n\\item \\textbf{Strategia di Business}: definisce le modalit\\`a pratiche da\r\nintraprendere per avere un vantaggio rispetto alla concorrenza.\r\n\r\n\\item \\textbf{Strategia Funzionale}: si occupa di implementre\r\nquotidianamente la strategia di business verso le singole funzioni\r\noperative.\r\n\\end{itemize}\r\n\r\n\\section{Modello delle 5 Forze di Porter}\r\n\r\n\\subsection{Il Paradigma S-C-P}\r\n\r\nPer \\textbf{settore} di un impresa intendiamo l\'insieme di imprese che\r\nproducono beni o servizi in concorrenza diretta tra loro. Per far parte\r\ndi uno specifico settore le aziende devono produrre dei prodotti,\r\nidentici o parzialmente identici. Solitamente ogni azienda tenta di\r\ncostruire una strategia in base al settore in cui si trova per\r\n\\textbf{superare la concorrenza}.\r\n\r\nPer molti anni lo studio della competitivit\\`a si \\`e basato sul\r\n\\textbf{Paradigma S-C-P} (\\textit{Struttura, Condotta e Per-formance}).\r\nQuesto modello sostiene che un\'impresa deve sottostare ad un modello\r\ndefinito da una \\textbf{Struttura} che deve determinatre degli schemi di\r\ncomportamento che definiscono la \\textbf{Condotta}, che l\'impresa \\`e\r\ndestinata a seguire per elevare le proprie \\textbf{Performance}.\r\n\r\nQuesta evoluzione di pensiero porta alla costruzione della\r\n\\textbf{Scuola del Valore}, al quale cerca di ribaltare l\'approccio\r\ndeterministico della Scuola Classica, elevando il cliente ad un livello\r\nsuperiore.\r\n\r\n\\subsection{Il Modello delle 5 Forze Competitive}\r\n\r\nPer valutare l\'attrattivit\\`a di un settore in aziende che seguono la\r\nScuola del Valore si usa il \\textbf{Modello delle 5 Forze}:\r\n\r\n\\begin{center}\\includegraphics[width=3.34583in,height=2.02917in]{img/image11.png}\\end{center}\r\n\r\nDefiniamo le diverse forze del principio di Porter:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Rivalit\\`a Concorrenziale tra i Soggetti Esistenti}: pi\\`u\r\nquesta \\`e accesa, maggiuore sar\\`a la presione sui prezzi e l\'erosione\r\ndei margini. La rivalit\\`a viene intensificata quando ci sono molti\r\nconcorrenti nel settore, quando la crescita nel settore \\`e\r\nlenta, quando i costi fissi sono alti e quando c\'\\,\\`e poca differenza\r\ntra i prodotti nel settore. Ad aggravare la rivalit\\`a sono anche le\r\nelevate \\textit{barriere all\'uscita}, come macchinari specializzati o\r\ncostosi.\r\n\r\n\\item \\textbf{Potere Contratturale del Fornitori}: essi possono minacciare\r\nla reddittivit\\`a alzando o abbassando la qualit\\`a delle loro forniture\r\n(macchinari, materie prime,...). Il loro potere viene reso forte in base\r\nalla quantit\\`a di aziende che ci sono all\'interno di un settore, al\r\ncosto che comporta ad un\'azienda il cambio o se non esistono materiali\r\nsostitutivi di cui sono gli unici fornitori.\r\n\r\n\\item \\textbf{Potere Contrattuale dei Clienti}: i clienti sono forti e\r\npossono pretendere sconti quando sono pochi o acquistano grandi volumi.\r\nSono molto sensibili ai prezzi sia della singola azienda sia nel\r\ncomplessivo settore e c\'\\,\\`e sempre la possibilit\\`a che il cliente si\r\nsviluppi per produrre il componente da se.\r\n\r\n\\item \\textbf{Minaccia dei Nuovi Concorrenti}: se un settore richiede alte\r\neconomie di scala, investimenti colossali in macchinari o possono\r\nvantare di una grande fedelt\\`a della marca, i nuovi entranti saranno\r\nsvantaggiati, se no rischiano il collasso/crollo.\r\n\r\n\\item \\textbf{Minaccia dei Prodotti Sostitutivi}: quando un\'azienda viene\r\nspecializzata nella vendita di un singolo prodotto e un\'altro prodotto,\r\nmagari meno costoso o semplicemente pi\\`u performante, entra nel\r\nmercato, se l\'azienda non viene aggiornata si rischia il crollo. Non per\r\nforza si tratta di prodotti identici, ma di alternative che convincono\r\nil cliente a passare ad un altro fornitore per convenienza.\r\n\\end{itemize}\r\n\r\n\\subsection{Vantaggio competitivo, Strategie Base e Raggruppamenti\r\nStrategici}\r\n\r\nUna olta analizzato il settore l\'azioenda deve capire come posizionarsi\r\nper avere delle buone performance rispetto ai concotrrenti. Il vantaggio\r\nnasce dal \\textbf{valore} che un\'impresa pu\\`o creare, inteso in pratica\r\ncome \\textbf{quanto l\'azienda \\`e disposta a pagare}. Questo valore pu\\`o\r\nalzarsi in 2 modi: offrendo \\textbf{gli stesi prodotti degli altri ad\r\nun prezzo inferiore}, oppure \\textbf{offrendo qualcosa di unico che\r\ngiustifichi il loro prezzo uguale o superiore della concorrenza}.\r\n\r\nDa questo concetto derivano le \\textbf{Strategie di Base}:\r\n\r\n\\begin{center}\\includegraphics[width=3.34583in,height=2.01944in]{img/image12.png}\\end{center}\r\n\r\nDa questa matrice che definisce un incrocio tra \\textit{Vantaggio\r\ncompetitivo} con \\textit{Ambito conpetitivo}, definiamo 3 strategie\r\nprincipali:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Leadership di costo/prezzo}: l\'azienda si rivolge all\'intero\r\nmercato puntando su un\'efficienza strutturale che permette di abbattere\r\ni costi e offrire prezzi a ribasso.\r\n\r\n\\item \\textbf{Differenziazione}: l\'impresa si rivolge ad un intero mercato\r\nma offre prodotti concepiti \'\'\\textit{superiori}\'\' soltanto per il nome\r\ndel brand (es: Apple).\r\n\r\n\\item \\textbf{Focalizzazione}: l\'azienda si concentra su una piccola nicchia\r\ndi mercato focanizzandosi su \\textit{costi} e \\textit{dif-}\r\n\\textit{ferenziazione}.\r\n\\end{itemize}\r\n\r\nL\'impresa deve scegliere in modo netto una di queste vie, l\'errore\r\nprincipale per\\`o della maggior parte delle aziende \\`e quello di\r\ncercare una \\textbf{via di mezzo} tra questi campi, perdendo\r\nl\'esclusivit\\`a o l\'economicit\\`a. Per visualizare in modo pratico\r\nqueste dinamiche si usano solitamente dei \\textbf{Raggruppamenti\r\nStrategici}, dei grafici che raggruppano i concorrendi di un settore in\r\nbase a 2 variabili chiave: \\textbf{Costi} e \\textbf{Qualit\\`a}. Tramite\r\nquesta mappatura emergono chiaramente 4 gruppi: chi fa pi\\`u\r\ndifferenziazione con costi alti, chi si focalizza sui bassi costi ed\r\neccellente qualit\\`a, chi detiene la leadership nel settore e i gruppi\r\nbloccati con un basso rapporto di qualit\\`a-prezzo. Questo esempio\r\ndefinisce il settore aereo negli USA:\r\n\r\n\\begin{center}\\includegraphics[width=3.34583in,height=1.60972in]{img/image13.png}\\end{center}\r\n\r\n\\subsection{Analisi dell\'Ambiente Interno}\r\n\r\nSe le 5 forze analizzano l\'ambiente esterno di un\'azienda, possiamo\r\ndeterminare anche un\'analisi dell\'\\textit{ambiente interno} ad un\'azienda.\r\nQuesto viene solitamente fatto con lo strumento denominato\r\n\\textbf{Catena del Valore}. Questo grafico, determinato da una freccia\r\nche va verso destra, determina vari scomparti orizzontali e verticali,\r\nmostrando tutte le attivit\\`a svolte, evidenziato ogni loro contributo\r\nall\'interno della produzione.\r\n\r\n\\begin{center}\\includegraphics[width=3.34583in,height=1.95139in]{img/image14.png}\\end{center}\r\n\r\nL\'estremit\\`a della freccia culmina con il \\textbf{Margine}, la cui\r\nformula \\`e semplicemente:\r\n\r\n\\[ \\textit{Valore Creato} - \\textit{Costi} \\]\r\n\r\nPer effettuare questa disgregazione la catena si divide in 2 grandi\r\nblocchi operativi. Alla base ci sono le \\textbf{Attivit\\`a Primarie}, le\r\nquali sono direttamente protagoniste della creazione fisica del\r\nprodotto. Eseguono un ciclo di vita definito da:\r\n\r\n\\begin{itemize}\r\n\\item \\textit{Logistica in entrata}: magazzinaggio e gestione dei materiali\r\n\r\n\\item \\textit{Attivit\\`a operative}: lavorazione, assemblaggio e vera e\r\npropria creazione del prodotto.\r\n\r\n\\item \\textit{Logistica in uscita}: stoccaggio e distribuzione.\r\n\r\n\\item \\textit{Markeding e vendite}: promozione, pubblicit\\`a del prodotto e\r\nvendita di quest\'ultimo.\r\n\r\n\\item \\textit{Servizi post-vendita}: servizio dato al cliente, se possibile,\r\ndopo la vendita del prodotto.\r\n\\end{itemize}\r\n\r\nLa parte superiore della freccia invece \\`e identificata dalle\r\n\\textbf{Attivit\\`a di Supporto}. Queste, anche se non partecipano\r\nfisicametne alla creazione del prodotto finale, rendono disponibili alle\r\nattivit\\`a produttive le materie prime.\r\n\r\n\\subsection{La Resource Based View e l\'Approccio Integrativo}\r\n\r\nLa Catena del Valore negli anni \\`e stata sicuramente superata. La sua\r\nevoluzione viene definita \\textbf{Resource Based View} (RBV), ovvero la\r\nprospettiva \\textbf{fondata sulle risorse}. Questo approccio vde\r\nl\'impresa come un insieme unico ed eterogenero di risorse/competenze che\r\ncostruiscono il \\textbf{vero motore dell\'azienda}. Le risorse si\r\ndividono in:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Tangibili}: finanze, materiali, macchianri,...\r\n\r\n\\item \\textbf{Intangibili}: brevetti, capacit\\`a di analisi dei\r\ndipendenti,...\r\n\r\n\\item \\textbf{Umane}: conoscenze, capacit\\`a,...\r\n\\end{itemize}\r\n\r\nDa sole queste risorse non bastano, servono in azienda le\r\n\\textbf{competenze}, ovvero la reale capacit\\`a di \\textbf{saper\r\ncombinare e coordinare le varie risorse in modo coeso}.\r\n\r\n\\section{Introduzione al Processo di Acquisto Industriale}\r\n\r\n\\subsection{Il Ruolo Strategico degli Acquisti e il Mercato}\r\n\r\nI fornitori consegnano le paterie prime all\'impresa, la quale a sua\r\nvolta si affida a degli intermediari per far arrivare il prodotto ai\r\nconsumatori finali. L\'idea fondametnale \\`e he un\'azienda non opera in\r\nisolamento, infatti i prezzi spesso sono variabili e possono cambiare in\r\nbase alla competitivit\\`a del mercato, ma questa decrescita o crescita\r\ndipende principalmente dai \\textbf{fornitori}, i quali devono mantenere\r\nuna base di prezzo che possa portare guadagno all\'azienda comprante.\r\n\r\nL\'impatto degli acquisti di un\'azienda varia enormemente in base al\r\nsettore industriale. Nei settori come il \\textit{retail, elettronica o\r\nl\'informatica}, gli acquisti possono rappresentare il 60/85\\% del costo\r\nfinale, mentre in aziende per esempio di ambito \\textbf{farmaceutico} le\r\npercentuali scendono, arrivando anche tra il 10/50\\%.\r\n\r\n\\subsection{L\'Effetto Leva degli Acquisti}\r\n\r\nUno dei concetti finanziari pi\\`u importanti \\`e definito come\r\n\\textbf{Effetto leva degli acquisti} o \\textbf{Purchase Leverage\r\nEffect}, che dimostra praticamente come una piccola ruduzione\r\ndei costi di approvvigionamento comporti un\r\n\\textbf{impatto importante alla reddittivit\\`a aziendale}.\r\n\r\nPer comprenderlo a pieno prima bisogna definire 2\r\nprincipali indicatori di bilancio aziendale:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{ROS}: Return of Sales. Misura la reddittivit\\`a delle vendite\r\ne viene calcolato come:\r\n\r\n\\[ \\text{ROS} = \\frac{\\text{Margine Operativo}}{\\text{Fatturato}} \\]\r\n\r\n\\item \\textbf{Indice di Rotazione}: misura quanto velocemente il capitale\r\ninvestito genera rendite. Si calcola tramite la formula:\r\n\\end{itemize}\r\n\r\n\\[ \\text{Indice di Rotazione} = \\frac{\\text{Fatturato}}{\\text{Attivit\\`a Totali}} \\]\r\n\r\nIl ROA esprime la reddittivit\\`a complessiva del capitale investito e si\r\nottiene:\r\n\r\n\\[ \\textit{ROA} = \\textit{ROS} \\times \\textit{Indice di Rotazione} \\]\r\n\r\nDopo aver calcolato questi parametri possiamo sceglere due vie in base\r\nalle performance dell\'azienda. La \\textbf{prima strategia} \\`e quella di\r\naumentare il fatturato, richiedendo un aumento dei costi. Oppure\r\npossiamo adottare la \\textbf{seconda strategia}, decisamente pi\\`u\r\nperformante, nella quale definiamo una \\textit{riduzione dei costi dei\r\nmateriali}, aumentando di norma il margine operativo e abbassando le\r\nattivit\\`a totali investite.\r\n\r\n\\subsection{In Contesto Business to Business (B2B)}\r\n\r\nTutte le dinamiche viste fin\'ora definiscono delle idee di mercato di\r\nun\'azienda. In particolare un mercato \\textbf{B2B} o un mercato\r\n\\textbf{BTC} (\\textit{Business for Consumer}). Nel B2C un\'azienda vende\r\ndirettamente al consumatore finale, entre nel B2B le transazioni\r\navvengono tra amministrazioni, dove beni e servizi sono comprati per\r\nessere impiegati in ulteriori processi produttivi.\r\n\r\nLe differenze tra questi due modelli sono molteplici. Il B2B definisce\r\nun rapporto diretto all\'itente finale, innes-cando l\'\\textbf{Effetto\r\nBullwhip} (o \\textit{effetto frusta}), nel quale una piccola variazione\r\ndella domanda del cliente finale si amplifica\r\nman mano che risale le categorie, costringendo i produttori a variazioni\r\nsempre pi\\`u \\textbf{imprevedibili.}\r\n\r\n\\begin{center}\\includegraphics[width=3.34583in,height=2.10972in]{img/image15.png}\\end{center}\r\n\r\nNel mercato B2B solitamente gli acquisti sono di \\textbf{grandi\r\nproporzioni} con \\textbf{ingenti somme}, perch\\\'e spesso si ha a che fare\r\ncon un numero limitato di clienti o fornitori, spesso concentrati in\r\ndistretti industriali.\r\n\r\n\\subsection{Il Processo di Approvvigionamento}\r\n\r\nIl processo di acquisto viene influenzato per ogni passaggio dal\r\nprecedente, secondo la logica detta \\textbf{Garbage In, Garbage Out}.\r\n\r\nIL processo di acquisto viene diviso in \\textbf{6 fasi}. Le prime 3 fasi\r\nsono definite di natura \\textit{strategica}, in quanto coinvolgono pi\\`u\r\ndecisori aziendali e richiedono molte informazioni, mentre le ultime 3\r\ninvece sono pi\\`u di natura \\textit{operativa}.\r\n\r\nLa prima fase strategica \\`e la \\textbf{definizione delle specifiche}, dove l\'azienda deve\r\nimpostare delle caratteristiche\r\ntecniche e di durata dei beni necessari, stimando i fabbisogni nel\r\nmedio-lungo termine. Viene seguita dalla fase di \\textbf{identificazione\r\ne qualificazione dei fornitori}, nella quale personale specializzato\r\nprepara una lista di \\textit{potenziali aziende} a cui bendere il\r\nprodotto, analizzando informazioni online e altre fonti.\r\n\r\nSuccessivamente c\'\\,\\`e la fase della \\textbf{selezione dei fornitori e\r\nla neogziazione}, dove, dopo aver scelto i potenziali acquirenti,\r\nvengono costruiti preventivi e eventuali offerte. Per fare ci\\`o si\r\nsfruttano strumenti come il \\textbf{Total Cost of Ownership} (TCO),\r\novvero l\'analisi di tutti i costi legati al ciclo di vita del bene,\r\noppure l\'\\textbf{Analytical\r\nHierarchy Process} (AHP), nella quale si cerca di assegnare dei\r\npesi ai criteri decisionali per arrivare ad una scelta oggettiva.\r\n\r\nTerminata la prima fase strategica si passa alla parte pi\\`u operativa.\r\nLa prima fase \\`e qiella di \\textbf{emisione dell\'ordine}, nella quale\r\nil fornitore accetta la richiesta e vengon stipulate date di consegna.\r\nSi ha poi la fase d i\\textbf{monitoraggio e controllo}, nella quale\r\nc\'\\,\\`e un tracking e monitoraggio dell\'ordine spedito. L\'ultima fase \\`e\r\nquella del \\textbf{post-acquisto e valutazione dei fornitori}, in\r\nquesta sede l\'azienda acquistante definisce una recensione\r\ndell\'esperienza avuta col fornitore valutandolo. Per questa fase lato\r\nimpresa spedente si sfrut-tano strumenti come il \\textbf{Key Performance\r\nIndicator}, che in base alle valutazioni fornisce una perfomrance\r\ndell\'azienda.\r\n\r\n\\subsection{Il Buygrid Model}\r\n\r\nPer definire al meglio questi passaggi nel 1967 \\`e stato definito i\r\n\\textbf{Buygrid MOdel}. Questo framework man-ageriale ci spiega che non\r\nsempre un\'azienda deve eseguire scrupolosamente tutte le fasi del\r\nprocesso appena descritto, poich\\\'e il livello di sforzo dipende da 2\r\nvariabili: il \\textbf{grado di novit\\`a dell\'acquisto} e il\r\n\\textbf{livello di incertezza di rischio associato}. Da queste variabili\r\nnascono 3 tipologie (o \\textit{classi}) di acquisto:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Riacquisto Diretto} (Straight Rebuy): si verifica quando si\r\nordinano beni standard, ripetitvi e a bassa incertezza da un fornitore\r\nconosciuto e con convenzioni gi\\`a negoziate. Essendo una procedura di\r\nroutine la decisione \\`e rapida e spesso automatizzata.\r\n\r\n\\item \\textbf{Riacquisto Modificato} (Modified Rebuy): avviene quando i\r\nprodotto \\`e noto, ma si manifesta la necessit\\`a di cambiare fornitore o\r\ndi aggiornare il prodotto per ottenere alternative migliori.\r\nL\'incertezza aumenta e si devono raccogliere maggiori informazioni per\r\nportare a casa un buon risultato di offerta.\r\n\r\n\\item \\textbf{Nuovo Acquisto} (New Task): si affronta quando l\'azienda deve\r\nrisolvere un problema inedito, interfacciandosi con un prodotto e un fornitore mai visti prima. \r\nIn questo caso il rischio \\`e altissimo e le informazioni\r\nnecessarie sono moltissime.\r\n\\end{itemize}\r\n\r\nIl Buygrid Model espande le 6 fasi del processo di approvvigionamento\r\nviste in precedenza, mappandole sulle 3 tipologie di acquisto appena\r\nviste:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Nuovo Acquisto} \\textit{$\\rightarrow$ Attraversamento completo delle prime 3\r\nfasi}\r\n\\item \\textbf{Riacquisto Modificato} \\textit{$\\rightarrow$ Lo sforzo va speso sulla fase di\r\nvalutazione}\r\n\\item \\textbf{Riacquisto Diretto} \\textit{$\\rightarrow$ Ci si concentra\r\nsull\'identificazione del bisogno e sulla selezione di una routine\r\nordinaria}\r\n\\end{itemize}\r\n\r\n\\subsection{Selezione dei Fornitori tramite Vendor Grid}\r\n\r\nUna volta che abbiamo stilato una lista di fornitori dobbiamo\r\nselezionare quelli pi\\`u validi per lo scopo dell\'impresa. Per la\r\nselezione abbiamo uno strumento molto utilizzato nelle imprese chiamato\r\n\\textbf{Vendor Grid} Questo stru-mento definisce un metodo per il quale\r\nassegnamo ad ogni fornitore un \\textbf{punteggio} chiamato, \\textit{vendor\r\nrating}, con una formula matematica poi definitamo il punteggio finale\r\ndi ogni fornitore in base a vari parametri:\r\n\r\n\\[ F_k = \\sum_{i=1}^{n} w_i \\times c_{i,k} \\]\r\n\r\nIn questa funzione $F_k$ rappresenta il punteggio totale ottenuto\r\ndel k-esimo fornitore, $n$ rappresenta i $criteri di\r\nvalutazione selezionati$, $w_i$ rappresenta il $peso$ in\r\npercentuale del coefficeinte, mentre $c_{i,k}$ \\`e il $voto$\r\n(spesso da $1 a 5$) del k-esimo fornitore.\r\n\r\n\\subsection{Classificazione ABC}\r\n\r\nPer definire le priorit\\`a possiamo usare un\'altro metodo fondamentale\r\ndi classificazione, chiamato \\textbf{Classifi-cazione ABC}. Questa\r\nclassificazione definisce una \\textbf{curva ABC}, che ci aiuta ad\r\nindividuare pochi fornitore critici su cui va concentrata la massima\r\nattenzione gestionale.\r\n\r\nLa procedura matematica per costruire questa classificazione prevede 4\r\nstep sequenziali:\r\n\r\n\\begin{itemize}\r\n\\item Ordinare i fornitori in bodo decrescente in base al valore annuo degli\r\nacquisti degli acquisti effettuati.\r\n\r\n\\item Si calcola qule percentuale degli acquisti rappresenta ogni singolo\r\nfornitore.\r\n\r\n\\item Si calcola la percentuale cumulata man mano che si scende la lista.\r\n\r\n\\item Si definiscono i tagli per raggruppare i fornitori in classi A, B e C.\r\n\\end{itemize}\r\n\r\nQuesto strumento viene definito dal \\textbf{Principio di Pareto}:\r\n\r\n\\begin{center}\\includegraphics[width=3.34583in,height=2.00972in]{img/image16.png}\\end{center}\r\n\r\n\\section{La Gestione Strategica dei Fornitori}\r\n\r\n\\subsection{Introduzione alle Strategie di Sourcing}\r\n\r\nIl punto di partenza per comprendere la gestione dei fornitori \\`e\r\nl\'analizzazione del \\textbf{sourcing}, ovvero le modalit\\`a con cui\r\nl\'azienda decide di approvvigionarsi di un determinato bene o servizio.\r\n\r\nLa prima opzione di sourcing \\`e il \\textbf{Single Sourcing}, nel quale\r\nun\'azienda cliente decide volontariamente di affidarsi ad un\r\n\\textbf{unico fornitore} per un dato prodotto, \\textit{anche avendo altre\r\nalternative sul mercato}. Optare per questo tipo di sourcing \\`e molto conveniente\r\npoich\\\'e si crea un buon rapporto tra cliente\r\ne fornitore che pu\\`o\r\nportare a volte a riduzioni o sconti, tuttavia questa strategia espone\r\nl\'azienda a vulnerabilit\\`a in caso di problemi di consegna o fornitura,\r\ndiventando \\textbf{dipendente principalmente dal fornitore}.\r\n\r\nUn\'altra opzione di sourcing \\`e il \\textbf{Sole Sourcing}, nel quale il\r\ncliende \\`e legato ad un unico fornitore, non per scelta, ma \\textit{per necessit\\`a}. In questo\r\ncaso il fornitore o \\`e l\'unico possibile che pu\\`o fornire una\r\ndeterminata materia,\r\noppure ha il monopolio nel settore. Il fornitore in questo caso si trova\r\nin una posizione di \\textit{predominanza assoluta}, mentre il cliente deve\r\nsubire qualsiasi problematica il fornitore pu\\`o avere.\r\n\r\nUna opzione meno rischiosa \\`e il \\textbf{Dual Sourcing}, che consiste\r\nnell\'acquistare le materie da 2 fornitori diversi, consentendo di\r\nlimitare i rischi e ottenere un maggiore controllo sulla relazione,\r\ncreando una \\textit{competizione fra i fornitori}, cosa che giova\r\nsoprattutto al cliente.\r\n\r\nInfine abbiamo l\'approccio pi\\`u utilizzato di \\textbf{Multi SOurcing},\r\ndove il cliente si affida contemporaneamente a pi\\`u fornitori per\r\nreperire lo stesso prodotto. I vantaggi in questo caso \\textit{sono\r\nspeculari agli svantaggi del single sourcing}. C\'\\,\\`e una forte\r\ncompetizione tra i fornitori, i quali cercheranno sempre di diventare\r\nprincipali fornitori dell\'azienda. Di contro questa scelta ha il fatto\r\ndi aumentare la difficolt\\`a di stimo verso i fornitori singoli,\r\naumentando la variabilit\\`a delle caratteristiche.\r\n\r\nNel panorama moderno si sta puntando sempre pi\\`u verso l\'\\textbf{avere\r\nmeno fornitori possibili}, senza mai arrivare al single sourcing, in\r\nmodo da limitare i rischi ma comunque mantenersi stretti i pochi\r\nfornitori.\r\n\r\n\\subsection{Il modello di Fujimoto e le Dinamiche Relazionali}\r\n\r\nQuando si analizzano i rapporti di approvigionamento, l\'errore pi\\`u\r\ncomune \\`e guardarli unicamente dal punto di vista del cliente. IL\r\n\\textbf{Modello di Fujimoto} interviene proprio per \\textit{correggere\r\nquesta prospettiva}, suggerendo che risulta opportuno \\textbf{analizzare\r\nla relazione tra clientee fornitore}, analizzando anche il punto di\r\nvista di quest\'ultimo.\r\n\r\nFujimoto delinea 4 situazioni distinte:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Single sourcing da fornitore dedicato}: in questo scenario\r\nentit\\`a, client e fornitori \\textit{sono direttamente dipendenti l\'uno\r\ndall\'altro}. Questa situazione genera un terreno \'\'fertile\'\' per lo\r\nsviluppo di collaborazioni fra cliente e fornitore.\r\n\r\n\\item \\textbf{Single sourcing da fornitore indipendente}: sebbene il cliente\r\nusi un solo fornitore, quest\'ultimo \\textit{non e dedicato solamente a\r\nlui}. Il fornitore ha diversi clienti, che gli garantiscono una\r\npredominanza sulle aziende clienti.\r\n\r\n\\item \\textbf{Multi sourcing da fornitori dedicati}: in questo caso il\r\ncliente ha molti fornitori, che lavorano \\textit{tutti} \\textit{solo per\r\nlui},, generando una condizione di forte dipendenza dei fornitori\r\nrispetto al cliente.\r\n\r\n\\item \\textbf{Multi sourcing da fornitori indipendenti}: la situazione\r\nmoderna nel quale abbiamo \\textit{un cliente che ha pi\\`u fornitori e\r\nquesti fornitori hanno pi\\`u clienti}. Questa situazione comporta una\r\ngrossa difficolt\\`a nel costruire collaborazioni stabili vere e proprie.\r\n\\end{itemize}\r\n\r\n\\subsection{La Matrice della Dipendenza Cliente-Fornitore}\r\n\r\nPer quantificare e visualizzare le situazioni definite da Fujimoto,\r\npossiamo utilizzare la \\textbf{Matrice della Dipen-denza}.\r\n\r\nPer costruirla mettiamo sull\'asse verticare il \\textbf{Potere del\r\ncliente (buyer) rispetto al fornitore (supplier)}. Questo valore \\`e\r\nmisurato calcolando la \\textit{percentuale del fatturato del fornitore}\r\n(\\textit{X}), che deriva dagli acquisti del cliente (\\textit{Y} ). Pi\\`u\r\nquesta percentuale \\`e alta pi\\`u il cliente ha potere. Sull\'asse\r\norizzontale invece calcoliamo il \\textbf{Potere di acquisto del supplier\r\nrispetto al buyer}, definito in modo reciproco. Dall\'incrocio di valori\r\nbassi e alti di queste variabili generiamo 4 quadranti che ci indicano i\r\npoteri di buyer e supplier in tutti i casi:\r\n\r\n\\begin{center}\\includegraphics[width=3.34583in,height=1.92778in]{img/image17.png}\\end{center}\r\n\r\nQuando le percentuali sono alte da entrambe le parti si entra della fase\r\ndi \\textbf{Interdependence}, dove nessuno ha il potere sull\'altro,\r\nfavorendo partnership strategiche.\r\n\r\n\\subsection{L\'Analisi del Portafoglio Fornitori e il Modello di Olsen ed\r\nEllram}\r\n\r\nPer le aziende al giorno d\'oggi \\`e meglio adottare un \\textbf{approccio\r\ndifferenziato}, basandosi su un\'analisi appro-fondita di tutti i\r\nprodotti e materie utilizzate. Questo processo si chiama\r\n\\textbf{Segmentazione del Portafoglio Fornitori}. Definiamo un\r\n\\textbf{portfolio model}, un vero e proprio strumento che semplifica il\r\nproblema attraverso la classificazione di \\textbf{variabili in una\r\nmatrice}, definendo strategie specifiche per ogni cella.\r\n\r\nIl modello di matrice pi\\`u consolidato \\`e il \\textbf{Modello normativo\r\ndi Olsen ed Ellram}, il quale fornisce all\'impresa una guida strutturata\r\nin 3 step per l\'analisi e gestioni del portafoglio fornitori.\r\n\r\nIl primo step \\`e \\textbf{l\'analisi degli acquisti}, poi abbiamo un\r\nsecondo step che determina un\'\\textbf{analisi ravvicinata delle\r\nrelazioni con i fornitori} e infine abbiamo l\'ultimo step che consiste\r\nnello \\textbf{sviluppo di piani d\'azione concreti}.\r\n\r\nIl primo step richiede la classificazione in diverse aree, definendo in\r\ngenerale \\textit{2 macro-dimensioni} chiave: l\'\\textbf{importanza\r\nstrategica dell\'acquisto} e la \\textbf{difficolt\\`a di gestione\r\ndell\'acquisto}.\r\n\r\nL\'importanza strategica \\`e definita da \\textbf{fattori di competenza},\r\n\\textbf{fattori economici} e \\textbf{fattori di immagine}. LA difficolt\\`a\r\ndi gesione invece dipende dale \\textbf{caratteristiche del\r\nprodotto}, dalla \\textbf{peculiarit\\`a del mercato della fornitura} e\r\ndalle \\textbf{caratteristiche abiendali pi\\`u amplie} (rischio,\r\nincertezza, costi logistici elevati o lunghi termini di consegna). A\r\ntutti questi problemi vengono assegnati dei pesi specifici per collocare\r\nnella matrice l\'acquisto.\r\n\r\n\\subsection{La Matrice di Kraljic e l\'Applicazione Strategica}\r\n\r\nIl culmine della strategia di gestione degli acquisti viene raggiunto\r\ncon l\'utilizzo della \\textbf{Matrice di Kraljic}. Questo strumento\r\nmatematico prende nei due assi i 2 valori precedentemente citati di:\r\n\\textbf{importanza dell\'acquisto per l\'azienda}, sull\'asse orizzontale,\r\ne \\textbf{difficolt\\`a dietro l\'acquisto}, sull\'asse verticale.,\r\nassegnando a tutti i punti dei valori \\textbf{Alto} o \\textbf{Basso}.\r\nL\'incrocio di questi due parametri determina \\textbf{4 principali\r\ncategorie di acquisto}:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Acquisto non critico}: quando sia difficolt\\`a che importanza\r\nsono basse. In questo caso l\'obiettivo principale dell\'azienda \\`e\r\nl\'efficenza, infatti dovrebbe: \\textit{ridurre il numero di fornitori} o\r\n\\textit{standardizzare il pi\\`u} \\textit{possibile i prodotti}. Lo scopo\r\nprincipale di questi acquisti \\`e \\textit{l\'abbattimento dei costi\r\naministrativi o logistici}.\r\n\r\n\\item \\textbf{Acuisto a collo di bottiglia}: quando la difficolt\\`a \\`e\r\nalta, mentre l\'importanza \\`e bassa. \\`E una situazione fastidiosa\r\nperch\\\'e pur essendo un bene non strategico le complesit\\`a sono alte.\r\nL\'obiettivo qui \\`e la riduzione o l\'eliminazione del problema, cercando di trovare altre\r\nsoluzioni, magari attraverso la produzione interna.\r\n\r\n\\item \\textbf{Acquisto Leva}: si presenta con alta importanza strategica e\r\nbassa difficolt\\`a. Qui il valore dell\'acquisto \\`e alto per l\'azienda\r\nsenza sforzi. In questo quadrante la bilancia pende a favore\r\ncompletamente dalla parte del cliente, che dovr\\`a ottenere prezzi\r\nsempre pi\\`u bassi per la materia di acquisto e sfruttare il potere di\r\nacquisto che si ha.\r\n\r\n\\item \\textbf{Acquisto Strategico}: l\'ultimo quadrante che si sviluppa con\r\nalta difficlt\\`a e alta importanza. IN quesot caso dobbiamo acquistare\r\ncomponenti fondamentali per l\'azienda anche se le difficolt\\`a sono\r\nalte. La migliore strategia in questo caso \\`e la creazione di\r\n\\textbf{Partnership} tra cliente e fornitore/i, stabilendo ottime\r\nrelazioni col fornitore.\r\n\\end{itemize}\r\n\r\n\\section{Introduzione al Marketing Strategico}\r\n\r\n\\subsection{La Pianificazione Strategica d\'Impresa}\r\n\r\nLa pianificazione strategica di un impresa \\`e un process fondmentale\r\nche permette ad un\'organizzazione di allineare i propri obiettivi e\r\nrisorse in modo opportuno.\r\n\r\nUn principio di questa fase \\`e che l\'intera strategia dell\'impresa deve\r\nessere fortemetne \\textbf{orientata al cliente}. Questo processo viene\r\ndefinito su diversi layer aziendali, partendo dal livello aziendale,\r\nfino a scendere al livello della singola business unit, poi il prodotto\r\ne infine il mercato.\r\n\r\nIl primo passo di questo percorso \\`e la \\textbf{formulazioen della missione aziendale}, che rappresenta lo\r\nscopo ultimo dell\'organizzazione, ovvero l\'\\textit{insieme di obiettivi che\r\nl\'impresa intende raggiungere nell\'ambiente in cui opera}. Un aspetto\r\ncriciale \\`e che la missione deve essere \\textbf{rigorosamente orientata\r\nal mercato e ai clienti}. Questi obiettivi fungono da linee guida\r\ndirette per il management, poich\\\'e ogni azienda deve definire degli\r\nobiettivi chiari pe rgarantire un allineamento all\'interno della\r\nstruttura.\r\n\r\n\\subsection{Analisi del Portafiglio e Matrici di Valutazione}\r\n\r\nDefiniti gli obiettivi l\'attivit\\`a deve definire il proprio\r\n\\textbf{portafoglio di attvit\\`a}, che consiste nellacombinazione di\r\ntutte le attivit\\`a e prodotti di cui l\'azienda \\`e composta.\r\n\r\nIl processo nel quale l\'attivit\\`a compie questo passo di analisi di attivit\\`a e prodotti \\`e definito \\textbf{analisi del}\r\n\\textbf{portafoglio}. L\'obiettivo principale \\`e quello di definire il\r\nmiglior portafoglio possibile, per garantire una stabilit\\`a aziendale,\r\nadattandolo su tutti i punti di forza e deboleza dell\'impresa.\r\n\r\nPer fare ci\\`o si individuano le \\textbf{Aree Strategiche di Affari}\r\n(SBU) che valutano l\'attrattivit\\`a e ne calcola il supporto manageriale\r\ned economico adatto. Per supportare queste decisioni si possono usare\r\ndiversi modelli matematici. Il pi\\`u utilizzato \\`e il modello della\r\n\\textbf{Matrice BCG} (\\textit{Boston Consulting Group}).\r\n\r\n\\begin{center}\\includegraphics[width=3.34583in,height=2.1in]{img/image18.png}\\end{center}\r\n\r\nQuesta matrice incrocia 2 dimensioni fondmentali: il \\textbf{tasso di\r\ncrescita del mercato} e la \\textbf{quota di mercato relativa}. Da questo\r\nincrocio vengono guori delle unit\\`a di business che possono essere:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Stars}: quando la quota di mercato \\`e in forte espansione e\r\nrichiedono ingenti investimenti per avere una rapida crescita. Queste\r\nunit\\`a in futuro avranno un rallentamento en mercato portandole a\r\ndiventare forti fonti di reddito.\r\n\r\n\\item \\textbf{Cash Cows}: prodotti con un\'alta quota in un mercato ormai\r\nmaturo e a bassa crescita. In queste attivit\\`a i finanziamenti sono\r\nminimi e generano profitti enormi.\r\n\r\n\\item \\textbf{Question Marks}: in questo caso abbiamo una bassa quota nei\r\nmercati, con per\\`o uun fabisogno di grande investimento per crescere.\r\nSono in dubbio perch\\\'e l\'investimento in queste potr\\`a essere profiquo\r\no no.\r\n\r\n\\item \\textbf{Dogs}: questo uiltimo caso abbiamo una ridotta quota di\r\nmercato che va in parallelo con una basso fabisogno di investimenti,\r\nporatando la scelta ad una sorta di \\textit{sopravvivenza aziendale}.\r\n\\end{itemize}\r\n\r\nUn altro strumento moplto utilizzato \\`e la \\textbf{Matrice di Ansoff},\r\nun solido framework che fornisce un aiuto durtante le decisioni\r\nincrociando \\textbf{porodotti} e \\textbf{mercati}. Se l\'impresa decide\r\ndi concentrarsi su prodott igi\\`a esistenti in mercati gi\\`a predsidiati\r\nadotta una strategia di \\textbf{Penetrazione del mercato}, mirando ad\r\naumentare le vendite sfruttando la base di clienti attuale.\r\n\r\nQualora l\'aizenda voglia puntare su nuovi mercati o nicchie si parla di\r\n\\textbf{Sviluppo del mercato} o \\textbf{espansione}. Se invece l\'azienda\r\nsi vuole buttare su un mercato completamente nuovo siu ha uno\r\n\\textbf{Sviluppo del prodotto} che si basa su forti concett idi\r\ninnovazione.\r\n\r\nInfine abbiamo al \\textbf{Diversificazione} che definisce l\'impresa di\r\nun\'azienda di avviare o acquistare nuove attivit\\`a che risultano\r\ncompletamente esterne ai mercati attuali.\r\n\r\n\\begin{center}\\includegraphics[width=3.34583in,height=3.10694in]{img/image19.png}\\end{center}\r\n\r\n\\subsection{Comprendere il Mercato: Bisogni, Valore e Soddisfazione del\r\nCliente}\r\n\r\nIl \\textbf{marketing} \\`e un processo articolato mediante il quale le\r\nimprese \\textbf{creano un reale valore} per i clienti e instaurano\r\n\\textbf{duraturi rapporti}. Il primissimo passo di questo percorso\r\nrisiede nella profonda comprensione del mercato e nei \\textbf{bisogni\r\nintimi del consumatore}.\r\n\r\nLa teoria impone di distinguere tra:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Bisogni}: cndizione psicologica o fisica in cui un individuo\r\ndesidera un prodotto. Pu\\`o essere di tipo fisico e funzionale,\r\npsicologico o sociale e simbolico.\r\n\r\n\\item \\textbf{Desideri}: i desideri sono ancora pi\\`u soggettivi dei bisogni\r\ne nascono come loro diretta evoluzione. Non indicano un bisogno vero e\r\nproprio, ma solo il desiderio di avere un prodotto.\r\n\r\n\\item \\textbf{Domanda}: quando i desideri individuali sono supportati da un\r\nnecessario potere di acquisto nascono le domande di mercato, che\r\nindicano che ci sipu\\`o investire sul prodotto.\r\n\\end{itemize}\r\n\r\nL\'azienda si basa alla \\textbf{risposta della domanda}. In questa fase\r\ndi sviluppo i manager devono prestare la massima attenzione alla\r\ndomanda, rimanendo sempre aggiorati su quest\'ultima, per non incorrere\r\nnella \\textit{miopia di marketing}, un errore comune che si verifica\r\nquando un\'azienda da troppa improtanza ad un prodotto senza domanda,\r\nproducendo in perdita.\r\n\r\nI responsabili del marketing sono responsabili per portare i libello di\r\naspettative dei consumatori in modo accurato. Questo livello non deve\r\nessere mai troppo alto per evitare le delusioni, ma nemmeno troppo basso\r\nda non attrarre clienti. La \\textbf{soddisfazione del livello} viene\r\nraggiunta quando \\textit{l\'aspettativa del cliente viene confermata o\r\nsuperata con il prodotto finito}.\r\n\r\n\\subsection{Gli Orientamenti e la Creazioen della Proposta di Valore}\r\n\r\nLedue grandi domande a cui un\'impresa deve rispondere quando svilpuuano\r\nun prodotto sono: \\textbf{chi sono i nostri clienti?} e \\textbf{come\r\npossiamo servirli nel modo migliore possibile?}. La prima risposta\r\nstrategica si ottiene attraverso le pratiche disegmentazione del\r\nmercato, \\textit{dividendono in piccoli sotto-segmenti} omogenei di\r\nclienti con le loro caratteristiche, passando poi per il\r\n\\textbf{targeting} e scengliere di quali specifici segmenti l\'impresa si\r\nvuole occupare.\r\n\r\nPer strutturare questa scelta viene usata solitamente la \\textbf{Value\r\nProposition Canvas}, che combacia i lavori da svolgere, i vantaggi\r\ndesiderati e le difficult\\`a che potranno portare ai clienti le varie\r\nscelte.\r\n\r\nIl concetto principale durante la definizione di un\'azienda \\`e sempre\r\nil puntare ossessivamente alla \\textbf{efficienza} e alla\r\n\\textbf{riduzione delle spese}, esponendo le azienda alla miopia\r\ndefinita precedentemente. Su questa base si basa il \\textbf{concetto di\r\nvendita}, in quale adotta una stretta prospettiva tra esterno ed\r\ninterno, partendo da prodotti gi\\`a realizzati, riducendo consumi e\r\ncosti per arrivare ad un guadagno superiore. Questa scelta \\`e\r\nforetemente contrapposta nel marketing moderno, infatti in questo caso\r\nil mercato globale si parte dal mercato globale e si sposta il focus\r\nssui \\textbf{bisogni dei clienti}.\r\n\r\nL\'evoluzione di questi concetti viene definita come \\textbf{Marketing\r\nSociale}, secondo cui l\'impresa evoluta non deve limitarsi a soddisfare\r\ni desideri dei consumatori, ma allo stesso tempo trovare un guadagno da\r\nquesta impresa.\r\n\r\n\\subsection{Il Customer Relation Management e il Valore Generato}\r\n\r\nIl pilastro fondamentale del marketing moderno \\`e il \\textbf{Customer\r\nRelationship Management}, dove l\'azienda deve poter gestire il proprio\r\nrapporto co il cliente, mantenendo tutte le relazioni durevoli e\r\nprofittevoli. Queste relazioni non sono identiche per tutte le azienda,\r\nma si declinano lungo diversi parametri, come la \\textit{variabilit\\`a\r\ndell\'offerta} o la \\textit{visibilit\\`a di servizio}. Si spazia delle\r\ninterazioni ad altissima automazione e bassissimo contatto umano\r\npersonale, fino a giungere alle \\textbf{interazioni esclusive}e\r\n\\textbf{altamente personalizzabili} per ogni utente.\r\n\r\nQuesto basilare concetto \\`e ddefinito ocme il \\textbf{Valore del ciclo di vita del cliente}, che\r\nstima in termini eco-nomici il valore dell\'intero e ininterrotto flusso di acquisti che iun\r\nsingolo individuo effettua nel corso del tempo mentre mantiene una salda\r\ninterazione col prodotto.\r\n\r\nLe aziende devono puntare ad aumentare la propria \\textbf{Quota di\r\nclientela}, che non \\`e altro che la fetta percentuale degli acquisti\r\ntotali di un dato consumatore che l\'impresa riesce efficacemente ad\r\nintercettare per la propria categoria. La somma aritmetica del valore\r\ndel cliclo di vita dei clienti \\`e definita invece come \\textbf{Cosumer\r\nEquity}. Per gestire tutto ci\\`o viene definito un \\textbf{Customer\r\nJourney}, il viaggio che porta un potenziale consumatore dalla fase di\r\nricerca all\'educazione profodna sui benefici dei vari servizi fino ad un\r\nrapporto di collaborazione e di vendita del prodotto.\r\n\r\n\\subsection{L\'Allineamento tra Marketing Strategico e Operativo}\r\n\r\nIl marketing strategico si posizione come il \\textbf{processo\r\nprevalente} nella definizione delle strategie aziendali. Il suo\r\nintrinseco orizzontale guarda al \\textbf{lontano-lungo periodo}\r\npontndosi l\'arduo obiettivo di monitorare l\'andamento macroeconomico per\r\npoter individuare preventivamente nuovi e inesplorati segmenti di\r\nmercato, basandosi sui nuovi continui bisogni. A questo viene appoggiato\r\nil \\textbf{marketing operativo}, che si basa sull\'uso di prezzi\r\ncontingenti e ingenti campagne di marketing, per puntare solamente\r\nsull\'economia dell\'azienda.\r\n\r\nPer far collaborare queste 2 realt\\`a le azienda si adottano di un\r\n\\textbf{Market Strategy Blueprint}, il quale definisce un piano rogoros\r\ne articolati azioni da intramprendere:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Fase 1}: risponde a \'\'\\textit{Dove siamo ora?}\'\', scansionando\r\nl\'ambiente competitivo e considerando eventuali sviluppo per poter\r\nvalutare se l\'azienda pu\\`o svilupparsi sul mercato.\r\n\r\n\\item \\textbf{Fase 2}: risponde a \'\'\\textit{Dove vogliamo arrivare}\'\',\r\ndissando le direzioni furture e si procee con la segmentazione,\r\ntargeting e posizionametno della marca.\r\n\r\n\\item \\textbf{Fase 3}: risponde a \'\'\\textit{Come ci arriveremo?}\'\', portando\r\nl\'azienda a sviluppare a piani d\'azione solidi e calcolare eventuali\r\nproblemi finanziali e imprevisti settoriali.\r\n\r\n\\item \\textbf{Fase 4}: risponde a \'\'\\textit{Siamo arrivati dove volavamo?}\'\',\r\nse rispettiamo tutte le fasi possiamo definire se l\'azienda pu\\`o\r\narrivare al risultato prospettato tramite una fredda analisi dei\r\nrisultati ottenuti fin\'ora.\r\n\\end{itemize}\r\n\r\n\\section{Segmentazione}\r\n\r\n\\subsection{Introduzione alla Strategia Orientata al Cliente}\r\n\r\nDopo aver definuto l\'allineamento tra marketing strategico ed operativo,\r\nil passo successivo per un\'impresa \\`e deifinire come \\textit{approcciare il\r\nmercato}. Questo percorso si concetizza in una \\textbf{strategia di\r\nmarketing orientata al cliente}, divisa in varie fasi:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Segmetnazione del Mercato}: processo per il quale l\'aienda\r\nsuddivide il vasto mercato globale in \\textit{sottogruppi}, in base a\r\nqualit\\`a simili, prodotti di mercato e acquirenti.\r\n\r\n\\item \\textbf{Targeting}: una rigorosa valutazione dell\'attivit\\`a di\r\nciascun mercato scelto ed individuato, per selezionare quelli pi\\`u\r\npromettenti a cui rivolgere la propria offerta.\r\n\r\n\\item \\textbf{Positioning}: una serie d iazioni affinch\\\'e i proprio prodotto\r\noccupi una \\textit{posizione chiara} nel mercato/i scelto/i, definendo una\r\ncaratteristica che lo differnezi completamente dalla concorrenza.\r\n\r\n\\item \\textbf{Merketing Mix}: l\'azione delel leve di mercato di attuare la\r\nstrategia. Queste leve indicano l\'\\textit{applicazione} \\textit{delle 4P}:\r\n\\textit{prodotto}, \\textit{prezzo}, \\textit{posizione} e \\textit{promozione}.\r\n\\end{itemize}\r\n\r\n\\subsection{Segmentazione: Vantaggi e Svantaggi}\r\n\r\nLa segmentazione \\`e un passaggio fondamentale nell\'inserimento del\r\nmercato di un\'azienda. Segmentare significa \\textbf{creare sottogruppi}\r\nnel mercato, definendo per ogni sottogruppo una fondamentale\r\n\\textbf{omogeneit\\`a} tra di loro e una forte \\textbf{etrogeneit\\`a}\r\nverso l\'esterno. In sostanza la segmentazioen rappresenta una delcato\r\ncompromesso di mercato tra 2 approcci principali: il \\textbf{marketing\r\nindifferenziato}, nel quale l\'azienda considera tutti i clienti come\r\nun\'entit\\`a simile e ne definisce un singolo prodotto per tutti, e il\r\n\\textbf{marketing one-to-one}, dove l\'azienda definisce i vari clienti\r\n\\textit{uno per uno}, definendo un prodotto diverso per le specificit\\`a\r\nindividuali. La segmentazione\r\nsi definisce in mezzo a questi 2 mercati, portantdo prodotti e offerte\r\nad hoc per i diversi sottogruppi di clienti. Questa tecnica comporta\r\novviemente degli \\textbf{svantaggi}. Suddividere l\'offerta per\r\naccontentare molti segmenti comporta un \\textbf{naturale aumento dei\r\ncosti di produzione}, oltre a generare un incremento delle scorte in\r\nmagazzino. Si crea inoltre una forte ridondanza nei vari settori\r\ndell\'azienda che dovranno occuparsi dello stesso prodotto ma magari con\r\nuna leggera modifica.\r\n\r\nPer mitigare questi costi ingenti in molte imprese moderne sfruttano\r\ndelle tecniche di \\textbf{standardizzazione e modularizzazione},\r\ndefinendo una \\textbf{base univoca dalla quale partire} per arrivare ad\r\nuna personalizzazione verso le fasi finali.\r\n\r\nAffinch\\\'e un segmento sia realmente sfruttabile dall\'impresa deve\r\nsoddisfare 5 caratteristiche fondamentali. Par-tendo dalla prima, il\r\nsegmento deve essere \\textbf{misurabile}, cio\\`e deve permettere\r\nall\'azienda di quantificare le dimenzioni del potere d\'acquisto. Deve\r\npoi risultare \\textbf{accessibile}, ovvero l\'impresa deve raggiungere il\r\ncliente in modo semplice e a basso costo. Deve garantire\r\nl\'\\textbf{omogeneit\\`a ed eterogeneit\\`a}, come definito all\'inzio un\r\ngruppo deve essere omogeneo con l\'interno ed eterogeneo all\'esterno.\r\nDeve possedere una certa \\textbf{importanza} in termini di volume, per\r\ngarantire un buon ritorno all\'impresa vendente. Deve poi possedere una\r\nbuona \\textbf{im-portanza} nel settore che giustifichi lo sforzo fatto\r\ndall\'produttore. Infine deve avere una \\textbf{durata} intrinsica\r\nsufficiente per essere sfruttata per un lungo periodo di tempo.\r\n\r\n\\subsection{Le Variabili Base della Segmentazione}\r\n\r\nPer poter dividere il mercato in modo metodico ci sono dei criteri\r\nsoggettivi ed oggettivi che vanno valutati dalla parte dell\'azienda.\r\nQueste informazioni vengono meticolosamente raccolte per essere\r\nutilizzate durante la segmentazione.\r\n\r\nIn un contesto di aziende definite come B2C le basi della segmentazion\r\nderivano principalemte dalle caratter-istiche fisiche e mentali dei\r\n\\textbf{clienti}. Tra le caratteristiche troviamo l\'\\textit{et\\`a, sesso,\r\netnia, religione o occupazione lavorativa}. Si aggiungono poi molto\r\nimportanti le \\textit{variabili geografiche}, distinguendo il mercato tra\r\nin base ai u mirati e difficili da reperire sono le \\textbf{variabili}\r\nclienti di una precisa azienda o gruppo di aziende. Molto pi\\`u\r\n\\textbf{psicografiche}, solitamente reperite tramite \\textit{sondaggi} o\r\n\\textit{studi mirati}.\r\n\r\nSpostando il focus organizzativo sul rapporto che il cliente instaura\r\ncol prodotto vengono fuori le \\textbf{caratteris-tiche comportamentali},\r\ndefinite dalle \\textit{abitudini di acquisto}, che analizzano la frequenza\r\nper cui un prodotto viene comprato, delineando differenze sostanziali\r\ntra chi comrpa i prodotto nel \\textit{punto vendita fisico} e chi compra\r\nda \\textit{prodotti e-commerce}. Altrettanto importante \\`e l\'analisi\r\ndell\'\\textit{utilizzo del prodotto}, che permette di distinguere in\r\nmaniera metodica i clienti.\r\n\r\n\\subsection{I Metodi e gli Approcci alla Segmentazione}\r\n\r\nUNa volta definite in via teorica le variabili si deve scegliere la\r\ntecnica di raggruppamento adatta per la creazione degli insiemi. Un\r\nprimom metodo \\`e il \\textbf{metodo matematico}, che si fonda su\r\nalgoritmi rigidi che analizzano i dati definiti prima. In questo\r\nscenario tecnico i raggruppamenti sono definiti tramite massicce\r\noperazioni di \\textbf{clustering}, individuando raggruppamenti logici\r\nbasati sulle intime similarit\\`a dei dati raccolti, per poi passare alla\r\nfase finale che definisce una descrizione del segmento creato.\r\n\r\nIN almternativa possiamo utilizzare il \\textbf{metodo euristico}, che si\r\nbasa in maniera preponderante sull\'esperienza pregressa, sull\'intuizione\r\nstrategica e sulla profonda consocenza del settore. In questo caso il\r\nprocesso viene diviso in 2 fasai principali: la\r\n\\textbf{macro-segmentazione} in cui si analizzano le ampie\r\ncaratteristiche esterne, mentre in seguito si ha uno step di\r\n\\textbf{micro-segmentazione}, che scende nel dettagio della\r\nsegmentazione dei gruppi appena creati definendo i pi\\`u piccoli gruppi\r\ndi segmentazione. Un altro modello per il metodo auristico viene\r\ndefinito \\textbf{Nested approach}, un \\textit{approccio multi-fase}, che\r\nimmagina la segmentazione come una struttura \\textbf{stratificata}. Si\r\nparte dale variabili demografiche pi\\`u esterne e facili da individuare,\r\nper poi giugnere a fattori situazionali legati alla singla vendita. personali dell\'eventuale\r\ncliente.\r\n\r\nAndando avanti cos\\`\\i si arriva infine al nucleo definito dai parametri\r\n\r\n\\begin{center}\\includegraphics[width=3.34583in,height=1.69028in]{img/image20.png}\\end{center}\r\n\r\n\\subsection{Il Metodo delle Eliminazioni SUccessive}\r\n\r\nTra le molteplici tecniche euristiche una viene molto utilizzata, il\r\n\\textbf{Metodo delle Eliminazioni Successive}.\r\n\r\nSI tratta di una procedura qualitativa e iterativa, basata\r\nstrutturamente una selezione non ordinata delle basi di segmentazione, facendo largo affidamento sull\'intuito e\r\nsull\'esperienza di chi la applica, eliminando i calcoli complessi del\r\nclustering.\r\n\r\nIl processo parte da una basta \\textbf{check-ist di varaibili}, da cui\r\nvengono estratte quelle realmente utili alla segmentazione. Le varaibili\r\nestratte vengono confrontate a coppie tramite un processo di\r\n\\textbf{incrocio di amtrici}. Analizzando i quadranti si creano il\r\nmanagement procede ad \\textbf{eliminare progressivamente gli incroci}\r\nmeno significativi, irrealistici o poco interessanti.\r\n\r\nPer comprendere a pieno questa \\textit{scrematura} possiamo prendere il\r\ncaso di una grande compagnia telefonica.\r\nL\'azienda pu\\`o facilemtne trovare le varie varaiabili chiave e incrociandole crea\r\nsvariate varianti e numerosi potenziali segmenti, tuttavia alcuni incroci possono risultre strani,\r\ntipo un segmento che definisce \'\'minori che comprano una linea fissa per\r\nse stessi\'\', caso irreale da elimianre. Dopo questa eliminazione\r\nl\'azienda si trova in mano una serie di gruppi di mercato ben definiti.\r\n\r\n\\subsection{Le Strategie di Copertura del Mercato}\r\n\r\nDeinire operativametne i segmenti sifhifica compiere la scelta pi\\`u\r\nimportante per l\'azienda, perch\\\'e definisce il proprio sistema\r\ncompetitivo, i clienti attuali o potenziali da soddisfare, inquadrando\r\nanche con precisione i concorrenti diretti con cui si andr\\`a\r\ninevitabilemnte a competere. L\'azienda, tenendo conto delle proprie\r\npotenzialit\\`a e debolezze strutturali ha a disposizione 3 opzioni\r\nstrategiche principali per agire sul mercato:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Marketing Indifferenzialto}: scenario nel uale l\'impresa\r\ndecide di ignorare le sottili differenze e non \\textit{non segmentare},\r\nrivolgendosi alla totalit\\`a dei consumatori con una strategia\r\namplissima e un unico piano operativo centralizzato. In questo caso\r\nl\'azienda opera su mercati con una domanda molto omogenea.\r\n\r\n\\item \\textbf{Marketing Diffenziato}: l\'azienda decide di presidiare\r\nsimultaneamente pi\\`u segmetni sul mercato, ma sviluppando con ingenti\r\nsforzi un prodotto custom per ogni segmento diverso. Questo approccio\r\nviene solitamente supportato da una strategia di business orientata\r\nsulla \\textit{differenziazione del brand}.\r\n\r\n\\item \\textbf{Marketing Concentrato}: l\'impresa decide di focalizzare in\r\nmodo quasi ossessivo un solo segmento di mercato, rinunciando alla\r\nvastit\\`a del pubblico. Questo approccio garantisce all\'azienda una\r\n\\textit{alta specializ-zazione} dell\'azienda su un singolo prodotto.\r\nQuesta strategia viene solitamente spinta nelle imprese \\textit{B2B} che\r\ntentano di definire un loro prodotto da vednre a pochi e grandi clienti.\r\n\\end{itemize}\r\n\r\n\\section{Il Targeting e il Positioning}\r\n\r\nDopo aver \'affettato\' il processo di marketing strategico, il passo\r\nsuccessivo \\`e quello di definire il mercato obiettivo, detto\r\n\\textbf{Target Market}. Questo signfica dover decidere razionalmente in\r\nquale specifico segmento concentrare i propri sforzi ed implementare una\r\nstrategia di approccio adeguata.\r\n\r\nPEr prendere una decisioneefficace su quale segmento attaccaere\r\nsolitamente in management sfrutta lo strumetno detto \\textbf{Analisi\r\nSWOT}, questa definsice due prospettive fondamentali di indagine:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Contesto Interno}: questa dimensione prende i \\textit{punti di\r\nforza} (\\textit{Strengths}) e i \\textit{punti di debolezza}\r\n(\\textit{Weak-nesses}) dell\'organizzazione. Si guarda dentro l\'azienda\r\ncercando di capire cosa eccelle e dove invece si fatica.\r\n\r\n\\item \\textbf{COntesto Esterno}: questa prospettiva riguarda le\r\n\\textit{opportunit\\`a} (\\textit{Opportunities}) e le \\textit{minacce}\r\n(\\textit{Threats}) dell\'organizzazione. L\'obiettivo \\`e scrutare il\r\nemrcato per cogliere trend emergenti favorevoli o pericoli imminenti\r\ncausati dalla concorrenza.\r\n\\end{itemize}\r\n\r\nTUtte queste opportunit\\`a, minacce, punti di forxa e debolezze vengono\r\ntrovati dal management, ma la dot-trinaorganizzativa suggerisce che \\`e\r\nnettamente preferibile applicare modelli strutturai come le\r\n\\textbf{matrici} onde evitare di ottenere risultati semplicistici o\r\nviziati da opinioni personali.\r\n\r\n\\begin{center}\\includegraphics[width=3.34583in,height=2.42917in]{img/image21.png}\\end{center}\r\n\r\n\\subsection{Valutare l\'Attrattivit\\`a: Domanda, PEST e 5 Forze}\r\n\r\nPer definire in modo strutturato quanto un segmento sia\r\n\\textbf{attraente}, l\'analisi esterna si appoggia su 3 grandi pilastri\r\nmetodici:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Analisi della domanda}: la domanda \\`e data dalla soma\r\nmatematica delle quantit\\`a acquistte da un gruppo di clienti in un\r\nperiodo specifico. \\`E essenziale analizzare in quale fase del ciclo di\r\nvita si trovi tale domanda. Solutamente la curva pu\\`o superare diverse\r\nepoche: \\textit{fase di sviluppo}, \\textit{introduzione}, \\textit{crescita},\r\n\\textit{turbolenza},...\r\n\\end{itemize}\r\n\r\n\\begin{center}\\includegraphics[width=3.17361in,height=1.48194in]{img/image22.png}\\end{center}\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Analisi Macroambientale (PEST)}: questa fase valuta l\'impatto\r\ndei grandi \\textit{fattori sistemici}. Essi comprendono aspetti\r\n\\textit{politici}, \\textit{economici}, \\textit{sociali}, \\textit{tecnnologici} ,\r\n\\textit{legali} ed \\textit{ecologici}.\r\n\r\n\\item \\textbf{Modello delle 5 Forze di Porter}: gi\\`a trattato, viene\r\nutilizzato anche in questo caso per rivelare gli aspetti critici\r\ndell\'ambiente competititvo di uno specifico settore.\r\n\\end{itemize}\r\n\r\n\\subsection{Valutare la Competitivit\\`a: la Catena del Valore}\r\n\r\nParallelamente bisogna valutare la competitivit\\`a aziendale nel\r\nsegmento. L\'impresa utilizza lo strumetno della \\textbf{Catena del\r\nValore} per identificare il proprio vantaggio competitivo. L\'impresa\r\nviene intesa come un insieme di attivit\\`a volte ad ideare, produrre,\r\ncommerciare e distribuire uno o pi\\`u prodotti, disgregando la struttura\r\nin attivit\\`a \\textbf{primarie} o di \\textbf{supporto}, il management\r\nsetaccia ogni reparto epr trovare valore.\r\n\r\nPer ciascuna di questa attivit\\`a vengono valutati due aspetti\r\nstrategici:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Vantaggi di Costo}: si indaga l\'efficienza interna tramite\r\nl\'analisi del bilancio e attvit\\`a di contro i concorrenti. L\'obiettivo\r\n\\`e capire se si pu\\`o competere all\'interno del mercato pur mantenendo\r\nla qualit\\`a invariata. Se il prodotto e la sua creazione ha un costo\r\nmaggiore rispetto alla media della concorrenza viene aggiunta una\r\n\\textit{Weakness} nella SWOT\r\n\r\n\\item \\textbf{VAntaggio di DIfferenziazione}: si calcola la quota di mercato\r\ne si cercano element di eccellenza. Questo vantaggio permette di\r\ndistaccarsi lotta sui prezzi, perch\\\'e si compete con una qualit\\`a\r\nsuperiore, cos\\`\\i che i clienti sono pi\\`u convinti ad acquistare da noi\r\nrispetto che dalla concorrenza perch\\\'e forniamo un prodotto migliore a\r\nprezzo poco maggiorato.\r\n\\end{itemize}\r\n\r\n\\subsection{I Modelli Decisionali di Portafoglio}\r\n\r\nConclusa l\'analisi congiunta di attrattivit\\`a e competitivit\\`a il nodo\r\ncruciale \\`e l\'individuazione dei \\textbf{segmenti target}. Per arrivare\r\na questo oviettivo vengono sfruttati 2 strumenti principali: la\r\n\\textbf{matrice GE-McKinsey} e la \\textbf{Matrice BCG}.\r\n\r\nLa MAtrice GE-McKinsey incrocia proprio \\textbf{l\'attrattivit\\`a del mercato} e la posizione \\textbf{competitivit\\`a dell\'azienda},\r\nelevandole su i 2 assi cartesiani. La matrice \\`e solitamente composta\r\nda 9 caselle definite dall\'incrocio dei val-ori, ognuna delle quali\r\ndetermina un comportamento strategico ottimale. IL posizionamento non\r\navviene in maniera soffettiva, ma vien effettuato mediante la\r\nvalutazione di un determinato numero di fattori. Per farlo il management\r\nassegna un \\textbf{peso} e un \\textbf{valore} ai criteri. Posizionato il\r\nprodott osi agisce secondo 3 filoni strategici:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Investimento e Crescita}: si inietta capitale per dominare il\r\nsettore.\r\n\r\n\\item \\textbf{Selettivit\\`a e Guadagno}: si mantiene una posizione prudente\r\nottimizzando le rese.\r\n\r\n\\item \\textbf{Disinvestimetno o Eliminazione}: impegnativo tagliare i rami\r\nsecchi abbandonando il mercato.\r\n\\end{itemize}\r\n\r\n\\begin{center}\\includegraphics[width=3.34583in,height=2.55972in]{img/image23.png}\\end{center}\r\n\r\nPi\\`u utilizzata \\`e la \\textbf{Matrice BCG}, gi\\`a vista, ma in questo\r\ncaso focalizzata sulla generazione e redistribuzione finanziaria. La BCG\r\nsfrutta il tasso di \\textbf{crescita del mercato} per determinare\r\nl\'attivit\\`a e la \\textbf{quota di mercato} orelatia per la\r\ncompetitivit\\`a. L\'approccio logico impone che l\'impresa incassi ingenti\r\nrisorse generate continua-mente da prodotti maturi e affermati.\r\n\r\n\\subsection{Il Posizionamento Strategico (Positioning)}\r\n\r\nUna volta stabilito il segmento esatto nel targeting si arriva\r\nall\'interrogativo finale, il \\textbf{posizionamento strate-gico} o\r\n\\textbf{positioning}, che formalmente il valore percepito dai clienti\r\nmettendolo in diretta relazione al prezzo richiesto. L\'obiettivo\r\nassoluto del positioning \\`e quello di \\textbf{distinguersi nel mercato\r\nscelto}.\r\n\r\nL\'approccio pi\\`u famoso al positioning \\`e quello tramite la\r\n\\textbf{Mappa delle Percezioni}. Questo modello visivo permette di\r\nposzionare graficamente il prodotto come viene agli occhi del cliente.\r\nLA chiave del successo di questo trumento sta nell\'astuzia usata per\r\nl\'individuare gli attributi realmente significativi, analizzando\r\n\\textit{sia il prodotto offerto sia il comportamento dei competitors} alla\r\nnostra entrata nel mercato.\r\n\r\n\\begin{center}\\includegraphics[width=3.34583in,height=2.21806in]{img/image24.png}\\end{center}\r\n\r\nPer andare in profondit\\`a e tradurre le azioni pratiche di sviluppo si\r\nusa un modello pi\\`u evoluto chiamato \\textbf{Importance-Performance\r\nMatrix}. Questa matrice \\`e molto intelligente perch\\\'e incrocia 2\r\ndimensioni cruciali:\r\n\r\n\\begin{itemize}\r\n\\item Il posizionamento della nostra azienda rispetto ai concorrenti in\r\ntermini di \\textbf{performance fisica}.\r\n\r\n\\item L\'importanza \\textbf{oggettiva} e riconosciut ache tale prestazione\r\nriveste per i clienti tale segmento di mercato.\r\n\\end{itemize}\r\n\r\nL\'utilit\\`a della matrice avviene \\textbf{studiando il grafico\r\nrisultante}, dove il manager capisce immediatamente quali valori\r\noperativi o di servizio del prodott orisultano essere\r\n\\textit{sottodimensionati} o \\textit{economicamente eccessivi} rispetto\r\nall\'importanza che gli da il cliente. LA matrice traccia delle curve\r\nmatematiche che dividono lo spazion in 4 zone strategiche:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{Excess?}: stiamo ottenendo performance eccezionali su una\r\nvariabile che il cliente ritiene poco importanti \\textit{$\\rightarrow$ Soldi e sforzi\r\nsprecati}.\r\n\r\n\\item \\textbf{Appropriate}: stiamo operando in un eccellente equilibrio di\r\nsforzo ed importanza \\textit{$\\rightarrow$ Nulla da sistemare}.\r\n\r\n\\item \\textbf{Improve}: offriamo prestazioni mediocri su funzioni che iniziano ad essere\r\nimportanti \\textit{$\\rightarrow$ Da sistemare}.\r\n\r\n\\item \\textbf{Urgent Action}: il campanello di allarme. PArte quando abbiamo prestazioni pessime in fattori vitali per l\'acquisto del cliente. \\textit{$\\rightarrow$ Soluzione immediata: Rischio crollo}.\r\n\\end{itemize}\r\n\r\n\\subsection{La Misuarazione della Qualit\\`a}\r\n\r\nPer l\'azienda \\`e fondamentale \\textbf{non autoingannarsi} sulle proprie\r\nperformance ed utilizzare strumenti formali\r\nper analizzare criticamente le misurazioni degli scostamente tra i\r\nlibelli desiderati.\r\n\r\nIn questo panorama brilla uno degli strumenti pi\\`u affermati del\r\nmanagement dei servizi: il modello \\textbf{SERVQUAL}.\r\n\r\nL\'obiettivo che si prefigge \\`e il \\textbf{ridurre drasticamente la\r\ndeformazione delle percezioni che si definisce}\r\n\\textbf{all\'interno dell\'azienda}, evitando che il management finsice\r\nper operare dentro modelli di \\textit{auto-compiacimento}.\r\n\r\nIL SERVQUAL \\`e tecnicamente uno strumento di ricerca multidimensionale,\r\nprogettato per catturare sia le \\textbf{intime aspettative dei consumatori}, sia le \\textbf{percezioni di\r\nerogazione di un servizio}. Sviscera 5 \\textbf{Gap} fatali\r\nche minano la qualit\\`a:\r\n\r\n\\begin{itemize}\r\n\\item \\textbf{GAP 1}: sconnessione tra quello che gli utenti si aspettano\r\nrispetto a quello che il prodott o \\`e realmente.\r\n\r\n\\item \\textbf{GAP 2}: scostamento interno che si forma tra le percezioni del\r\nmanagement e le limitate specifiche di qualit\\`a del servizio.\r\n\r\n\\item \\textbf{GAP 3}: la deludente differenza tra le specifiche rigorose\r\nimposte e la erogata produzione del servizio non rispettante queste specifiche.\r\n\r\n\\item \\textbf{GAP 4}: la discrepanza tra il servizio erogato e le\r\ncomunicazioni esterne, causando delusioni al cliente finale.\r\n\r\n\\item \\textbf{GAP 5}: la somma e il culmine del fallimento. \\`E la distanza\r\npercepita nella mente del consumatore rispetto a quello che lui si aspettava dopo una campagna di marketing e\r\npromesse. Viene definito quando questa\r\ndistanza \\`e cos\\`\\i ampia tra il prodotto promesso e quello realmente\r\npercepito.\r\n\\end{itemize}\r\n\r\n\\begin{center}\\includegraphics[width=3.34583in,height=2.33333in]{img/image25.png}\\end{center}\r\n\r\n\r\n\\section{La Gesione delle Operazioni}\r\n\\subsection{L\'Essenziale delle Operations e la Prospettiva di processo}\r\nL\'\\textbf{Operation Management} è la disciplina che si occupa della progettazione, pianificazione, controllo e miglioramento continuo dei processi, attraverso i quali un\'organizzazione trasforma degli \\textbf{input} e degli \\textbf{output}, creando un valore reale per il cliente. \\\\ \r\nAdottare una \\textbf{Prospettiva di Processo} significa guardare all\'azienda come ad un meccanismo di trasformazione. In ingresso troviamo 2 categorie di risorse:\r\n\\begin{itemize}\r\n  \\item \\textbf{Risorse da Trasformare}: materiali fisici, le informazioni o persino i clienti stessi\r\n  \\item \\textbf{Risorse Trasformanti}: lo staff, le strutture e gli impianti che agiscono fisicamente sugli input.\r\n\\end{itemize}\r\nIl cuore del sistema è detto \\textbf{Processo di Trasformazione}, che elabora questi elementi per restituire in uscita dei beni e servizi finiti. Questa logica si può applicare a qualsiasi organizzazione, l\'esempio lampante è l\'azienda aerea nella quale gli input sono i passeggeri, il processo è lo spostamento fisico e infine l\'output è il passeggero trasportato a destinazione.\\\\  \r\nL\'analisi di questi flussi può avvenire a \\textbf{diversi livelli di risoluzione}, partendo dal \\textbf{supply network}, la rete di fornitura globale, si passa poi al secondo livello dove si analizza ogni singola \\textbf{operation}, osservando il flisso delle funzioni interne di un\'impresa. Infine abbiamo lo studio di ogni singolo \\textbf{processo}, analizzando il flusso operativo tra le specifiche macchine o risorse umane.\r\n\r\n\\subsection{La Natura dell\'Offerta e la Dinamica delle Quattro V}\r\nLa distinzione classica tra chi produce beni e chi offre servizi oggi è ampiamente superata. Le imprese moderne adottano un modello ibrido , attraverso il processo di \\textbf{Servitizzazione}. Questo processo permette ad un\'azienda manifatturiera di integrare alla vendita del bene fisico, una \\textit{serie di servizi a valore aggiunto}, trasformando il proprio modello di business in una \\textbf{soluzione orientata al cliente}. \\\\\r\nParallelamente le aziende di servizi puri utilizzano i \\textbf{Tangible Cues}, elementi fisici \\textit{tangibili}, come per esempio le carte regalo fisiche dei loro prodotti vendute nei supermercati.\\\\ \r\nOgni processo operativo che procura bei o servizi, si posiziona lungo 4 fondamentali, dette le \\textbf{Quattro V}:\r\n\\begin{itemize}\r\n    \\item \\textbf{Volume}: un proceso ad \\textit{alto volume} garantisce alta repetibilità e forte standardizzazione, un impiego intensivo di capitale e costi estremamente bassi. Mentre un processo a \\textit{basso volume} definisce una maggiuore flessibilità e comporta costi elevati.\r\n    \\item \\textbf{Varietà}: un\'\\textit{alta varietà} definisce prodotti con grande flessiobilità e complessità. Quando la \\textit{varietà è bassa} invece il prodotto mantiene una routine rigida ed efficiente.\r\n    \\item \\textbf{Varietà della Domanda}: definisce la variazione della domanda nel tempo, se la domanda è \\textit{altamente variabile} quando l\'azioenda deve avere una capacità produtiva enormemente flessibile adattabile a picchi durante certi periodi. Se la domanda è costante l\'azineda deve garantire la massima efficienza produttiva.\r\n    \\item \\textbf{Visibilità}: intesa coem il gradi dicontatto diretto col cliente durante il processo. Un\'\\textit{alta visibilità} richiede spiccate abilità relazionali dello staff e bassi costi di attesa. Una \\textit{bassa visibilità} nasconde il processo al consumatore, permettendo la massima standardizzazione e ottimizzazione dei tempi di lavoro.\r\n\\end{itemize}\r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide1411.png}\r\n\\end{center}\r\n\r\n\\subsection{Dalla Mass Customization alle Strategie di Evasione}\r\nStoricamente le imprese industrili costringevano il cliente ad adattarsi all\'efficienza produttiva. Oggi per gestire la varietà in modo efficienter le aziende adottano la \\textbf{Mass Customization}. Dal punto di vista pratico questo significa progettare un sistema produttivo \\textit{standardizzato e modulare}. Mentre il cliente percepisce un\'enorme libertà di scelta, alla fine il prodotto è lo stesso con vari moduli inclusi.\\\\ \r\nPer implementare queste scelte si devono stanilire le proprie \\textbf{Strategie di Evasione della Domanda}, identificando il \\textbf{Punto di Disaccoppiamento} (PD). Questo punto cruciale divide le attività guidate dalle previsioni e dalla pianificazione interna, definite \\textbf{Logiche Push} e dalle attività definite dagli ordini dei clienti, dette \\textbf{Logiche Pull}.\\\\ \r\nEsistono varie strategie di marketing per arrivare ad una Must Customization. La prima è la  \\textbf{Make to Stock} (\\textbf{MTS}), la quale prevede che la produzione sia \\textit{interamente guidata dalle previsioni}. Abbiamo poi l\'\\textbf{Approccio to Order} posiziona il punto di disiaccoppiamento subito prima dell\'assemblamento finale. La strategia \\textbf{Make to Order} invece spinge il punto ancora più indietro, tenendo in magazzino solamente le materie prime e assemblare solo quando si ha l\'ordine finale. Se le materire prima non sono specifiche invece abbiamo una strategia \\textbf{Purhcase to Order} dove in magazzino non si tiene nulla e si ordina il tutto solo quando si ha l\'ordine. Infine abbiamo la \\textbf{Engeneer to Order} che sposta il punto di disassembliametno proprio al principio del prodotto, duante la sua ingenierizzazione.\\\\ \r\n\r\n\\subsection{La Gestione dei Materiali e i Sistemi Informativi}\r\nPer i processi produttivi che prevedono aassemblaggi complessi, lo strumento case è la \\textbf{Distinta Base} o \\textbf{Bill of Materials}, nella quale si ha un \\textit{approccio gerarchico} di tutti i materiali, componenti, ecc. necessari per realizzare il prodotto finale. La distinta base non si limita a dire cosa serve, ma quanfitica esattamente le porzioni di ogni singola materia e mostra le relazioni di assemblaggio \\textit{utilizzando un diagramma ad albero}.\\\\ \r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide1414.png}\r\n\\end{center}\r\nLe informazioni contenue nella distinta base sono il motore del \\textbf{Material Requirements Planning} (\\textbf{MRP}), ovvero il sistem adi pianificazione dei fabbisogni dei materiali. Viene derivato dal piano principale, con la distinta base e i dati sulle scorte fisicametne presenti in magazzino. L\'obbiettivo del MRP è deterrminare matematicametne quali materiali mancano, in quale quantità acquistarla o produrni e quando dovranno essere resi disponibili. Nelle aziende moderne gli MRP sono integrati nel sistema di \\textbf{Enterprise Resource Planning} o \\textbf{ERP}, un sistema centralizzato che permette di monitorare, coordinare e pianificare l\'azienda dalla produzione fino alle risorse umane, bypassando i vecchi dipartimenti aziendali.\r\n\r\n\\subsection{La Progettazione dei Processi e le Tipologie Produttive}\r\nLe La letteratura manageriale dimostrache gli elementi di progettazione di processo sono vincolati dall\'\\textbf{equilibrio tra volume e varietà}. Esistea una \"\\textit{linea naturale di adattamento}\", una diagonale teorica che indica come un\'azienda debba far corrispondere varietà e volume. Su questo si identificano \\textbf{5 Tipologie di Processi Manifatturieri}:\r\n\\begin{itemize}\r\n    \\item \\textbf{Progetto}: alta verietà e basso volume, caratterizzato dalla realizazione di prodotti unici e complessi.\r\n    \\item \\textbf{Job Shop}: basso volume e alta varietà, definisce la produzione per reparto. Qui i componenti si muovono tra diverse isole di lavorazione, raggruppate per funzione logica.\r\n    \\item \\textbf{Lotti}: medio volume e alta varietà, viene inserito un certo livello di automazione, ma l\'azienda deve produrre blocchi omogenei di prodotti.\r\n    \\item \\textbf{Linea}: alto volume e bassa varietà, i prodotti scorrono lungo un percorso fisso in cui i il tempo di ciclo detta il ritmo dell\'intera fabbrica. \r\n    \\item \\textbf{Ciclo Continuo}: domina quando il flusso di materiali non può fisicamente essere interrotto per ragioni tecnologiche o chimiche, si opera 24/7 per ammortizzare i costi degli impianti.\r\n\\end{itemize}\r\nQuesto approccio si declina con altrettanta precisione nelle \\textbf{Tipologie di Servizi}, nel quale abbiamo 5 anelli in base alla \\textit{personalizzazione del prodotto}. Più al\'esterno troviamo i \\textbf{Professional Services}, servizi di consulenza aziendale mirata e su misura. Abbiamo poi i \\textbf{Service Shop}, che standardizzano i propri prodotti però in diversi ambienti. Infine al centro abbiamo i \\textbf{Mass Services}, dove la varietà è minima, dove l\'infrastruttura tecnologica regna sovrana per gestire in modo massificato le utenze.\r\n\r\n\\subsection{L\'Organizzazione dello Spazio: Il Layout dei Processi}\r\nOgni process operativo deve fisicamente esistere in uno spazio ben progettato. Il \\textbf{layout} è proprio la disciplina che\\textit{studia la disposizione spazila e e logisticadelle risorse umane, tecnologiche e di capitale dell\'interno delle strutture aziendale}. L\'obiettivo è sempre avere un buon layout per un\'azienda.\\\\ \r\nValutare un layout significa soppesare numerosi criteri contrasteanti: \\textbf{sicurezza}, \\textbf{minimizzazione della larghezza del flusso}, \\textbf{utilizzo ottimane del volume} e \\textbf{massima chiarezza per i clienti}.\\\\ \r\nVengono definite delle \\textit{tipologie di layout di base}:\r\n\\begin{itemize}\r\n    \\item \\textbf{Layout a Posizione Fissa}: è obbligatorio quando il prodotto \\textit{non si può spostare}, garantendo massima flassibilità, ma costi vertiginosi per colpa degli spazi.\r\n    \\item \\textbf{Layout Funzionale}: raggruppa disicamente le macchine e le persone che svolgono funzioni simili, generando scorte e accumuli di prodotti.\r\n    \\item \\textbf{Layout di Cella}: le risorse anche se diverse vengono raggruppate per famiglie con esigenze afficni. Questosistema abbassa la flessibilità, ma aumenta la produttività e la velocità di attraversamento.\r\n    \\item \\textbf{Layout di Linea}: o layout per prodotto, dove tutti i prodotti scorrono ininterrottamente lungo un percorso unico. Questa soluzione abbatte i costi, ma diminuisce drasticamente l\'introduzione di nuovi mix di prodotti.\r\n\\end{itemize}\r\n\r\n\r\n\\section{La Gestione Strategica delle Operations}\r\n\\subsection{Differenza tra Gestione Quotidiana e Visione Strategica}\r\nFin\'ora abbiamo parlato della gestione delle Operations, la \\textbf{Operation Strategy}, invece, prende le decisioni fondamentali che determinano le \\textbf{Capacità Operatative} dell\'azienda a \\textbf{lungo termine}, assircurando che le risorse fisiche e umane supportino la visione globale, mantenendo l\'azienda coerente col mercato.\\\\\r\nIn altre parole, la strategia decide e costruisce il sistema, mentre il \\textit{management lo manovra}. La strategia opera su un livello macro e aggregato, ragionando su scale temporali, che arrivano al devennio e ponendosi domande di natura quasi filosofica.\\\\ \r\nUn esempio fondamentale è \\textbf{Apple}, che fornsice prodotti spettacolari, con cicli di vita brevi e presentazioni spettacolari. Per fare ciò l\'azienda deve definire una \\textbf{Flessibilità Operativa} assolut, manifestandola in 3 forme diverse: la \\textbf{New Product Flexibility}, la capacità di introdurre nuove tecnologie su grande scala in tempi record, avere una \\textbf{Volume Flexibility}, che permette diavere molte unità pronte in poche settimane dal lancio e infine la \\textbf{Product Mix Flexibility}, che garantisce una varietà rigorosa e controllata.\r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide1504.png}\r\n\\end{center}\r\n\r\n\\subsection{L\'evoluzione Storica del Vantaggio Competitivo Operativo}\r\nNel mondo delle Operations, i metodi per creare \\textbf{Vantaggio Competitivo}, si sono evoluti nei decenni. Prima degli anni \'60 si puntava principalmente sull\'\\textbf{efficienza}, puntando all\'\\textbf{economia di scala}. Si evolve questo poi nella creazione di \\textbf{fabbriche flessibili} e l\'aumento della varietà del prodotto. Negli anni \'80 e \'90 abbiamo un incremento della \\textbf{qualità} del prodotto, considerata un buon investimento per il futuro. Al giorno d\'oggi siamo arrivati alla \\textbf{customizzazione} del prodotto al più possibile. \r\n\r\n\\subsection{Le Quattro Prospettive della Strategia delle Operations}\r\nPer allineare le esigenze del mercato con le capacità interne, la Strategie delle Operations deve essere analizzata secondo \\textit{4 prospettive interconnesse}:\r\n\\begin{itemize}\r\n    \\item \\textbf{Top-Down Perpectiove}: visione \"\\textit{dall\'alto verso il basso}\" in cui la direzione aziendale detta ciò che le operations devono fare. \r\n    \\item \\textbf{Bottom-Up Perspective}: visione \"\\textit{dal basso verso l\'alto}\" dove è l\'esperienza operativa dei diepndenti a dettare i passi strategici futuri.\r\n    \\item \\textbf{Market Requirement Perspective}: guarda verso l\'esterno per capire cosa la posizione sul mercato desiderata esige dal sistema in termini di prestazioni.\r\n    \\item \\textbf{Resources Perspective}: guarda l\'interno dell\'azienda le risorse tangibili e non, analizzando cosa sono effettivamente in grado di realizzare in quel momento.\r\n\\end{itemize}\r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide1506.png}\r\n\\end{center}\r\n\r\n\\subsection{I Lato del Mercato: Qualificatori e Vincitori dell\'Ordine}\r\nNelle operations abbiamo una evoluzione della precedente vista \\textit{analisi PESTLE}. L\'obiettivo è compreendere intimanmente i bisogni dei clienti, per definire un \\textbf{posizionamento} dei propri prodotti.\\\\ \r\nTuttavia la strategia operativa impone di riconoscere che i requisiti di mercato \\textbf{non sono mai statici}, ma mutano in base al \\textbf{Stage in the Lifecycle}. Proprio per questa evoluzione, la teoria operativa introduce un concetto fondamentale per misurare l\'importante delle priorità compettiive. Da una parte troviamo gli \\textbf{Order Qualifiers}, i \\textbf{fattori qualificati}, che rappresentano il livelli indispensabile di prestazioen richiesto dal mercato. Dall\'altra parte abbiamo gli \\textbf{Order Winners}, i \\textbf{fattori vincitori dell\'ordine}, elemnenti distintivi e superiori che convincono il cliente.\\\\ \r\nA margine esistono anche gli \\textbf{Order Losers}, ovvero quei difetti o mancanze che impediscno attivamente al prodotto di essere considerato.\r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide1509.png}\r\n\\end{center}\r\n\r\n\\subsection{Il Lato delle Risorse e le Decisioni Operative}\r\nIl secondo e ultimo lato dell\'equazione è il lato interno delle Operations. Si innescano all\'interno dello studio la creazione delle \\textbf{Operations Capabilities}, ovvero le \\textit{abilità operative del sistema}.\\\\ \r\nQueste capacità indirizzano le \\textbf{Aree di Decisioni Strategica}, le quali a loro volta plasmano la confomazione fisica dei \\textbf{Processi Operativi}.\r\n\r\n\r\n\\section{La Gestione della Qualità}\r\n\\subsection{La Progettazione e i Parametri di Valutazione dei Processi}\r\nUn processo aziendale non è un\'etità statica, ma un meccanismo che deve esser costantemente misurato e perfezionato. La \\textbf{Progettazione dei Processi} inizia con una fase ad alto livello, chiamata \\textbf{Process Positioning}, in cui si decide la posizione strategica del processo intermini di volume e varietà. Si scende poi verso l\'\\textbf{Analisi di Processo}, nella quale si definisce il \\textbf{layout fisico}, scegliendo al tecnologia appropriata e si progettano le singole mansioni lavorative.\\\\ \r\nPer capire se questo allineamento ha successo bisogna definire dei metodi per valutare i vari processi. Al primo posto troviamo la \\textbf{Qualità}, intesa come capacitò di produrre senza errori. Abbiamo poi la \\textbf{Velocità}, definita come i tempi di attesa e l\'affidabilità del sistema. Al terzo posto c\'è l\'\\textbf{Affidabilità}, definita come la qualità dei servizi dell\'azienda e quanto sono affidabili. LA quarta dimensione è la \\textbf{Flessibilità}, la quale definisce la capacità di adattare il processo per rispondere ad eventuali modifiche del prodotto richieste dal mercato. Al quinto posto abbiamo il \\textbf{Costo}, la capacità di dare un prezzo adeguato, eliminando gli sprechi delle materie. All\'ultimo posto abbiamo la \\textbf{Sostenibilità Ambientale}, che valuta l\'impronta ecologica del prodotto.\r\n\r\n\\subsection{Il Superamento dei Trade-off e il Modello a Cono di Sabbia}\r\nStoricamente se si voleva presentare un prodotto di altissima qualità, bisognava accettare i tempi lunghi e costi esorbitanti per abbattere i costi. Le moderne teorie del management hanno scartato questa versione con la \\textbf{Teoria del Cono di Sabbia}. \\\\ \r\nQuesto modello suggeriscce che l\'eccellenza operativa non si ottiene scambiando un vantaggiocon un altro, ma \\textbf{costruendo le prestazion in modo cumulativo e sequenziale}. La base imprescindibile è la \\textbf{Qualità} del prodotto, senza di essa l\'efficienza decade. Una volta stabilizzata la qualità, il prodotto deve avere l\'\\textbf{Affidabilità} intrinsicamente, per poi passare alla \\textbf{Velocità} di produzione del prodotto. In cima alla struttura creata abbiamo il \\textbf{Costo} del prodotto.\r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide1612.png}\r\n\\end{center}\r\n\r\n\\subsection{La Dinamica del Flusso e la Legge di Little}\r\nL\'\\textbf{Analisi del Flusso} introduce 3 nuove variabili per l\'analisi del prodotto all\'interno del sistema:\r\n\\begin{itemize}\r\n    \\item \\textbf{Work in Progress}: indica il numero fisico di unità (clienti, pratiche o materiali) che si trovano in fase di lavorazione.\r\n    \\item \\textbf{Cycle Time}: rappresenta il tempo medio che passa dall\'uscita di un prodotto all\'uscita del successivo.\r\n    \\item \\textbf{Throughput Time}: il tempo totale che una singola unità impiega dall\'istante in cui entra nel processo fino a che non è completa.\r\n\\end{itemize}\r\nQUeste 3 metriche sono legate nella legge conosciuta come \\textbf{Legge di Little}. Questa stabilisce che:\r\n\\begin{center}\r\n$\\text{WIP} = \\frac{\\text{Throughput Time}}{\\text{Cycle Time}}$\r\n\\end{center}\r\n\r\n\\subsection{Pilastri del Lean Management e le Sette Forme del MUDA}\r\nIl \\textbf{Lean Management} è un ideale di azienda che si basa su pochi aspetti principali per aumentare le performance e la reddittività di quest\'ultima. Questa idea è nata da \\textbf{Toyota} e dal suo fondatore \\textbf{Taiichi Ohno}.\\\\\r\nIl primo pilastro principale è la \\textbf{Elimiazione degli Sprechi}, definito dai giapponesi \\textbf{MUDA}. Il secondo pilastro è il \\textbf{Rispetto per le Persone}, definito da pratiche organizzative per farantire una buona relazione coi collaboratori.\\\\ \r\nLa letteratura Lean modifica gli sprechi in diverse \\textit{macro-aree}: \\textbf{Quantità}, \\textbf{Persone} e \\textbf{Qualità}.\\\\ \r\nLa prima macro area è la \\textbf{Quantità} e viene divisa in:\r\n\\begin{itemize}\r\n    \\item \\textbf{Sovrapproduzione}: rappresetna il problema del management di produrre troppe unità del prodott che andranno invendute.\r\n    \\item \\textbf{Trasporto}: quqando le scorte in lavorazione sis spostano inutilmente da un reparto all\'altro senza subire trasformazioni.\r\n    \\item \\textbf{Magazzino}: l\'accumulo di componenti o prodotti fisici in stoccaggio in azienda che bloccano spazio e capitale.\r\n\\end{itemize}\r\nLa seconda macro-area invece sono le \\textbf{Persone} e si dividono in:\r\n\\begin{itemize}\r\n    \\item \\textbf{Attesa}: quando gli opeartori rimangono fermi in attesa degli arrivi dei componenti.\r\n    \\item \\textbf{Movimento}: inefficienza ergonomica ceh costrunge lo staff a coprire lunghe distanze fisiche per arrivare al completamento del prodotto.\r\n    \\item \\textbf{Lavorazione}: passaggi non necessari, anche burocratici.\r\n    \\item \\textbf{Difetti}: costose lavorazioni su pezzi scartati internamente.\r\n\\end{itemize}\r\n\\begin{center}\r\n    \\includegraphics[width=0.5\\textwidth]{img/slide1710.png}\r\n\\end{center}\r\n\r\n\\subsection{Mappare e Misurare il Valore: Value Stream Mapping}\r\nLo strumento principale di analsii degli sprechi è il \\textbf{Value Stream Mapping} (\\textbf{VSM}), un diagramma di flusso dettagliato in ogni singola fase del processo, fino al consumatore finale. \\\\ \r\nIn questa analisi le attività aziendali vengono divise in 3 categorie: \\textbf{Attività a Valore Aggiunto} (\\textbf{VA}), ovvero le sole operazioni per le quali il cliente è effettivamente disposto a pagare, le \\textbf{Attività Senza Valore Aggiunto} (\\textbf{NVA}), che rappresentano lo spreco pure che il cliente non vuole finanziare e infine abbiamo le \\textbf{Attività Senza Valore Aggiunto ma Necessarie} (\\textbf{BNVA}), operazioni che non cambiano al cliente, ma che l\'impresa è obbligata a controllare per motivi legali.\\\\ \r\n\r\n\\subsection{L\'Organizzazione Visiva e Operativa: Le 5S e il Gemba Walk}\r\nQuando abbiamo effettuato tutte le analisi del caso è il momento di \\textit{agire sull\'impresa}. In questo caso entrano in gioco il \\textbf{Sistema delle 5S}:\r\n\\begin{itemize}\r\n    \\item \\textbf{SEIRI} (Separare): impone di scartare senza pietà tutto ciò che è inutile all\'azienda.\r\n    \\item \\textbf{SEITON} (Riordinare): rimettere \"\\textit{ogni cosa al suo posto}\", contrassegnando spazi per ogni unità e processo.\r\n    \\item \\textbf{SEISO} (Pulire): trasfoprma l\'igiene in un\'ispezione quotidiana dei macchianri.\r\n    \\item \\textbf{SHITSUKE} (Sostenere): l\'autodisciplina necessaria per mantenere nel tempo i nuovi standard senza ricadere nelle vecchie abitudini.\r\n\\end{itemize}\r\nPer avviare questo cambiamento i manager devono praticare costantemente il \\textbf{Gemba Walk}, andando fisicamente sulel linee di produzione per osservare i processi con i propri occhi, parlando direttamente con gli operai e individuando problemi da risolvere.\r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide1714.png}\r\n\\end{center}\r\n\r\n\\subsection{Il Flusso Sincronizzato: Just-In-Time, Heijunka e Kanban}\r\nIl traguardo ultimo della filosofia Lean è la creazione di un flusso continuo e perfettamente cadenzato. Questo si ottiene tramite il \\textbf{Just-In-Time}, una logica che punta a sincronizzare la produzione al ritmo della domanda dettata dal cliente. Il JIT rovescia la storica definizione della produzione detta \\textbf{push}, nel quale si elaborano previsioni di vendita e si iniziano a produrre lotti enormi, ad una logica \\textbf{pull}, nel quale la produzione di avvia esclusivamente in base alla domanda.\\\\ \r\nPer far funzionare fluidamente la logica di pull, la teoria Lean definisce l\'\\textbf{Heijunka}, il livellamente spinto della produzione. Invece di produrre $n$ unità di un singolo modello e altre $n$ unità di un altro modello, definiamo una sequenza continua di \\textit{lotti misti}.\\\\ \r\nIl cuore pulsante che regola questo traffico è il \\textbf{Kanban}, che definisce che l\'impresa deve produrre unicamente una sola unità per volta, per evitare la sovrapposizione.\r\n\r\n\\subsection{L\'Eccellenza Statistica e la Riduzione della Variabilità: Il Metodo Six Sigma}\r\nMentre il poorocesso Lean si concentra sul flusso e taglio dello sprechi, negli anni \'80 è nata una filosofia che attacca l\'inefficienza i nmodo matematico, detta \\textbf{Six Sigma}.\\\\\r\nQuesta disciplina ha lo scopo di annullare totoalmente i difetti, riducendo la variabilità dei processi in modo estremo. Il \"\\textit{livello 6 sigma} definisce che un processo ha una percentuale di $99.9997\\%$ di processi perfetti.\\\\ \r\nIl parametro fondamentale per raggiungere questo livello è la \\textbf{Capability} di un processo, ovvero l\'indice matematico che confronta l\'ampiezza dell\'intervallo di tolleranza richiesto dal cliente.\\\\ \r\nPer raggiungere il livello Six Sigma si segue il protocollo \\textbf{DMAIC}:\r\n\\begin{itemize}\r\n    \\item \\textbf{Define}: identificazione del problema.\r\n    \\item \\textbf{Measure}: raccolta dati e misurare input e output.\r\n    \\item \\textbf{Analyse}: sviluppare un ipotesi delle cause.\r\n    \\item \\textbf{Improve}: progettare e proporre soluzioni operative.\r\n    \\item \\textbf{Control}: stabilire standard di prestazioni duraturi.\r\n\\end{itemize}\r\n\r\n\\subsection{Strumenti Analitici di Precisione: Ishikawa e Tecnica dei 5 Perché}\r\nDurante il DMAIC o nei processi di monitoramento continuo i manager possono costruire un \\textbf{Diagramma di Ishikawa}, conosciuto anche come \\textbf{Diagramma a Lisca di Pesce}. Questo modelloposiziona il probvlema a destra come la \"\\textit{testa del pesce}\", e da essa diorama una spina dorsale centrale nel quale si innestano diagonali che rappresentano le macro-categorie delel potenziali fonti di errore.\\\\ \r\nPer scavare più a fondo nelle problematiche, non basta schematizzare, qui entra ingioco la \\textbf{Why-Why Analysis}, enlla quale ci si domanda \\textit{almeno 5 perché} sulla problematica per definire il problema alla radice.\\\\ \r\n\r\n\\subsection{Il Bivio Strategico: Miglioramento Continuo o Ringegnrizzazione Radicale}\r\nQuando un organizzazione comprende di dover cambiare marcia si trova davanti ad una filosofica scelta: \\textbf{Miglioramento Continuo} o \\textbf{Business Process Reengineering} (\\textbf{BPR}).\\\\ \r\nIl percorso del miglioramento permette l\'utilizzo del TQM e Six Sigma. È un approccio democratico e collettivo, dove \\textbf{tutti} i dipendenti mettono in gioco le proprie conoscenze per affinare le operazioni quotidiane.\\\\ \r\nDall\'altro lato invece abbiamo la \\textbf{Reigegnerizzazione dei Processi Aziendali}. In questocaso non è un aggiornamento ma un \\textit{itervento discontinuo e brusco}. Non intacca le persone, ma vengono asoldati dei consulenti esperti nel settore, per garantire una \\textbf{crescita tecnologica} per generare \\textbf{profitto} imemdiato.\\\\\r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide1702.png}\r\n\\end{center}\r\n\r\n\r\n\\section{Digitalizzazione ed Innovazione Industriale}\r\n\\subsection{Le Decisioni Aziendali e la Gestione dell\'Incertezza}\r\nLe Operations aziendali, includono molte attività che richiedono decisioni continue. Queste decisioni si basano su innumerevoli \\textit{variabili strettamente indipendenti tra loro}. Il \\textbf{Processo Decisionale} è reso molto complicato da 2 principali variabili: i \\textbf{Vincoli Produttivi} e le \\textbf{Risorse Limitate}.\\\\ \r\nLe decisioni vengono quasi sempre prese in condizioni di \\textbf{incertezza}. L\'incertezza può essere definita come la \\textit{carenza di informaziuoni disponibili rispetto a quelle che sarebbero teoricametne necessarie per completare un\'attività in compoleta sicurezza}. A causare qeusta incertezza è principalmente la \\textbf{variabilità della domanda} e le continue fluttuazioni delle \\textbf{condizioni del mercato globale}. Per ovviare a questo le decisioni aziendali vengono prese in base alle \\textbf{previsioni}, le quali forniscono un possibile futuro di mercato da dover seguire, considerando comunque sempre un \\textit{margine di errore non eliminabile}.\\\\ \r\nIn passato la teoria organizzativa si basava sulla \\textbf{Razionalità Assouluta}, valutando tutto in modo assolutamente logico per massimizzare il proprio vantaggio. Tuttavia l\'uomo è \\textit{incapace di eseguire questo modello}, a causa di \\textbf{Vincoli Informativi} e la difficoltà cronica nel prevedere le possibili conseguenze delle proprie azioni. Per risolvere questo problema \\textit{Herbert Simmon} inventa la \\textbf{Razionalità Limitata}, nel quale \\textbf{le decisioni aziendali non sono mai \"ottimali\" o perfette}, ma ci accontentiamo di avere \\textbf{decisioni soddisfacenti}.\\\\ \r\n\r\n\\subsection{Il Modello Tradizionale: L\'Esperienza e i suoi Limiti}\r\nIn assenza di dati completi e razionalità assoluta, molte organizzazioni si affidano alla \\textbf{Conoscenza Tacita}, dove le decisioni opeartive \\textit{si basano unicamente sull\'esperienza personale e sull\'intuizione del singolo decisore}. Questo approccio è noto come \\textbf{Experience-Based Decision Making}. L\'esperienza ne lsettore viene definita solitamnete da una \\textit{tecnico senior} che riese a prevedere possibili problematiche future (anche un semplice rumore differente in un macchinario), definiti comunemente come \"\\textit{trucchi del mestiere}\".\\\\ \r\nLa Conoscenza Tacita è difficilmente formalizzabile e rappresenta un bel problema per la \\textbf{standardizzazione} dei processi di un\'azienda. I \\textbf{limiti} del modello decisionale basato sull\'esperienza sono definti da vari problemi, tra i quali i principali:\r\n\\begin{itemize}\r\n    \\item \\textbf{Replicabilità}: è diofficile formare una persona all\'interno di un ambiente in modo rapido e sicuro, creando una forte dipendenza da una sola persona.\r\n    \\item \\textbf{Bias Cognitivi}: limitissima capacità del cervello umano di elaborare troppo dati.\r\n    \\item \\textbf{Trasparenza}: difficile capacità lato umano di avere opacità sulle decisioni. \r\n    \\item \\textbf{Strumenti Strutturati}: non vengono elaborate soluzioni precisamente sui dati, ma su variabili cognitive non ben definite.\r\n\\end{itemize}\r\n\r\n\\subsection{Le Sfumature della Digitalizzazione e l\'Approccio Data-Driven}\r\nIl passaggio da unazienda basata sull\'esperienza ad una basata sui dati, avviene attraverso un processo di \\textbf{digitalizzazione}. Questo processo segna un vero e proprio \\textbf{cambiamento strutturale} profondo nell\'ideologia aziendale e permette di modificare il metodo con cui le decisioni e le attività quotidiane vengono gestite e organizzate.\\\\ \r\nÈ essenziale differenziare 4 concetti interconnessi ma nettamente differenti all\'interno di questi processi: \r\n\\begin{itemize}\r\n    \\item \\textbf{Digitalizzazione}: atto tecnico che punta a trasformare l\'informazione da un \\textit{dato analogico} ad uno \\textit{digitale}. Il focus è prettamente sul \\textit{Dato}.\r\n    \\item \\textbf{Digitalizazzione}: significa utilizzare i dati resi digitali per riprogettare e migliorare un processo aziendale. Qui iol focus è sul \\textit{Progetto}.\r\n    \\item \\textbf{Automazione}: riguarda l\'esecuizione di specifiche attività operative, con un intervento umano minimo o del tutto assente. Qui il focus è sull\'\\textit{Esecuzione}.\r\n    \\item \\textbf{Innovazione}: implica un salto di paradigma, un cambiamento ampio che va a toccare i prodotti o addirittura l\'interno modello di business, creando \\textit{nuovo valore per i clienti}. Qui il focus è il \\textit{Valore}\r\n\\end{itemize}\r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide1811.png}\r\n\\end{center}\r\nQuesti strumenti digitali si diramano in 2 grandi categorie di supporto alla mente umana. Nel \\textbf{Decision Support} il sistema informatico elabora i dati, ma la \\textbf{responsabilità finale resta alla mano umana}. Nel \\textbf{Decision Automation}, invece, è la macchina ad avere il pieno controllo e a compiere scelte in autonomia.\\\\ \r\n\r\n\\subsection{Prerequisiti, Limiti e Rischi della Trasformaione Digitale}\r\nLa sola disponibilità di oceani di dati non garantisce che le decisioni prese dai manager siano migliori. L\'azienda deve sempre assicurarsi di avere \\textbf{4 prerequisiti} fondamentali: \r\n\\begin{itemize}\r\n    \\item I dati devono essere \\textit{sufficientemente affidabili}.\r\n    \\item I \\textit{sistemi informativi devono essere integrati in azienda e non devono esserci compartimenti stagni}.\r\n    \\item I \\textit{processi aziendali devono essere prima descritti e mappati in modo comprensibile}.\r\n    \\item Lo \\textit{staff deve avere le }\\textbf{competenze} \\textit{adeguate sui nuovi strumenti}\r\n\\end{itemize}\r\nSe amnca anche uno solo di questi requisit si richia di amplificare i problemi già esistenti, generando problematiche future nel prendere decisioni in fretta senza una logica.\\\\ \r\nPer evitare questi prerequisiti solitamente vengono applicate logiche \\textbf{GIGO} (\\textit{Garbage In, Garbage Out}, nel quale viene definito in questo caso che: \\textbf{digitalizzare un processo mal progettato rende semplicemente più veloce un problema, ma non lo risolve}.\\\\ \r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide1818.png} %quella in alto a sinistra\r\n\\end{center}\r\nInoltre la digitalizzazione espone l\'azienda a \\textbf{rischi} collaterali che vanno mitigati. Una \\textbf{scarsa qualità dei dati}, causata da record incompleti o incoerenti porta gli algoritmi verso decisioni errate.\\\\ \r\nL\'adozione di piattaforme proprietarie esterne opuò causare una forte \\textbf{dipendenza da fornituri}, innalzando così i costi nel lungo periodo e riducendo il potere negoziale dell\'impresa e riducendo il potere dell\'impresa.\\\\ \r\nA livello umano la digitalizzazione rende esplicite delle regole organizzative aumentando la \\textbf{standardizzazione}, generando però al contempo una \\textbf{resistenza al cambiamento organizzativo}. Il vero scoglio è quindi avere si una digitalizzazione presente nell\'impresa, ma al contempo mantenere una certa \\textbf{flessibilità}.\r\n\r\n\\subsection{L\'Industria 4.0 e le Tecnologie Abilitanti}\r\nDal 2011 viene a galla un nuovo tipo ti infrastruttura chiamata \\textbf{Industria 4.0}, nella quale vediamo una rivoluzione con l\'utilizzo di \\textbf{tecnologie abilitanti}. Tra queste troviamo l\'utilizzo sempre più presente del\'IoT e li\'IA per l\'analisi dei \\textbf{big data}. Si sfruttano strumenti come i \\textbf{Digital Twin} che permettono la costruzione di una simulazionervirtuale perfetta di un impianto per testare aulche \"\\textit{what-if}\" aziendale.\\\\ \r\n\r\n\r\n\\section{Bilancio Aziendale}\r\n\\subsection{Il Bilancio Aziendale: Strumento di Trasparenza e Governance}\r\nIl \\textbf{bilancio aziendale} rappresenta il nucleo informativo fondamentale per qualsiasi valutazione di natura economica all\'interno di un\'organizzazione, definend oil risultato economico chel\'azienda ha sapuot generare lungo un arco temporale ben preciso, definito \\textbf{periodo amministrativo}.\\\\ \r\nDefinisce un mezzo di comunicazione e di coordinamento informativo tra l\'azienda e l\'ambiente esterno. Attraverso questo bilancion traduciamo la complessità delle operazioni aziendali, come indicatori confrontabili da poter sfruttare durante le analisi.\\\\\r\nLa redazione del bilancio risponde ad una duplice esigenza organizzativa, fungendo da strumento conoscitivo interno per i manager e la direzione, permettendo la valutazione delle scelte aziendali. In un sistema economico moderlo il bilancio è \\textit{lo strumento eletto per sancire la trasparenza verso l\'esterno}.\\\\ \r\n\r\n\\subsection{La Mappa degli Stakeholder e l\'Utilità Informativa}\r\nIl bilancio viene destinato a degli \\textbf{stakeholder}, ovvero coloro che si occupano della analisi del bilancio, trovando quali future decisioni sono meglio di altre. Gli stakeholder si dividono in 2 grandi macro-categorie in base ai loro confini organizzativi:\r\n\\begin{itemize}\r\n    \\item \\textbf{Stakeholder Interni}: sono la maggioranza dei soci, la direzione aziendale e i manager operativi. La loro analisi consente di capire se i margini industriali sono sufficienti a coprire i costi fissi e gli investimenti, o se la digitalizzazione sta portando un milgioramento notabile.\r\n    \\item \\textbf{Stakeholder Esterni}: sono una vasta platea divisa in vari settori. Inanzittutto abbiamo gli \\textbf{istituti di credito} (banche), che analizzano il bilancio e valutano il merito creditizio dell\'azienda, verificando la loro \\textit{liquidità}. Subito dopo ci sono i \\textbf{fornitori}, interessati a capire se i loro crediti commerciali stiano fruttando.\r\n\\end{itemize}\r\nIl bilancio quindi principalemnte permette di analizzare la \\textbf{reddittività} di un\'azienda e permette all\'\\textbf{amministrazione finanziaria} dello Stato di calcolare le imposte in base alla reddittività dell\'azienda.\r\n\r\n\\subsection{I Principi Redazionali del Bilancio}\r\nPer garantire che le informazioni contenute nel bilancio siano affidabili si tenta sempre a guardare i \\textbf{principi di redazione}. Questi configurano regole fisse che i redattori devono seguire per creare il bilancio finale dell\'azienda.\\\\ \r\nIl principio cardine dell\'intero sistema è: \\textbf{Clarissima, Veridicità e Correttezza}, spesso definito come la clausola generale del bilancio. Definendo in maniera concreata che il bilancio dve essere il più veritiero possibile. \\\\\r\nIl bilancio è definito da vari principi:\r\n\\begin{itemize}\r\n    \\item \\textbf{Principio di Prudenza}: impone di iscrivere nel bilancio solo i guadagni \\textit{efferttivamente realizzati}, mentre impone l\'\\textbf{obbligo} di inserire tutte le perdite e potenziali rischi dopo la chiusura del periodo amministrativo.\r\n    \\item \\textbf{Principio di Continuità Aziendale}: ele valutaazioni delle voci di bilancio devono essere eseguire assumento che l\'impresa continui regolarmente la sua attività operativa nel prevedibile futuro, evitando quindi di valutare beni di un\'azienda che sta per essere liquidata o venduta.\r\n    \\item \\textbf{Principio della Competenza Economica}: stabilisce che l\'effetto delle transazioni e degli altri eventi deve essere rilevato nel momento in cui essi si verificano economicamente, e non quando avviene il movimento di cassa o la manifestazione finanziaria. \r\n    \\item \\textbf{Principio di Costanza dei Criteri di Valutazione}: vieta di modificare da un anno all\'altro i metodi scelti per valutare le voci di bilancio.\r\n\\end{itemize}\r\n\r\n\\subsection{La Struttura Tripatita: Stato Patrimoniale, Conto Economico e Nota Integrativa}\r\nLa struttura principae di bilancio si articola principalmente in 3 \\textit{elementi fondamentali}:\r\n\\begin{itemize}\r\n    \\item \\textbf{Stato Patrimoniale}: definisce la situazione del patrimonio dell\'azienda in un preciso istante, solamente la mezzanotte di fine anno. Esso mette in contrapposizione ciò che l\'azienda possiede e i loro debiti verso terzi. \r\n    \\item \\textbf{Conto Economico}: descrive la dimanica reddituale dell\'impresa lungo il corso dell\'anno. Attraverso un\'architettura scalare permette di visualizzare la reddittività dell\'azienda, mettendo in mostra i componenti positivi di reddito e sottraendoci le componenti negative, aarrivando ad un computo che definisce se la gestione ha generato utile o una perdita.\r\n    \\item \\textbf{Nota Integrativa}: commenta, illustra e dettaglia le cigre ottenutoe nello Stato Patrimoniale e nel Conto Economico. Nella nota vengono esplicitati i criteri di valutazione adottani, tabelle di movimento e informazioni extra necessarie per garantire completa trasparenza.\r\n\\end{itemize}\r\n\r\n\\subsection{Approfondimento dello Stato Patrimoniale}\r\nPer addentrarsi nella logica contabile, è fondamentale sviscerare l\'architettura dello \\textit{stato patrimoniale}, il quale si presenta a sa vlta diviso in 2 sezioni prinicpali: le \\textbf{Attività} e la sezione che racchiude \\textbf{Passività} e \\textbf{Patrimonio Netto}.\\\\\r\nLe \\textbf{Attività} accolgono tutti gli \\textbf{impieghi} di risorse effettuati dall\'azienda. AL loro interno troviamo le \\textbf{immobilizzazioni}, ovvero i beni destinati a rimanere durevoli, divisi in \\textit{immateriali} e \\textit{finanziarie}. Accanto alle immobilizzazione troviamo l\'\\textbf{attivo circolante} che comprende gli elementi patrimoniali destinati a tornare in forma liquida in tempi brevi.\\\\ \r\nAbbiamo poi la sezione delle \\textit{fonti}, le quali si dividono in \\textbf{capitale di terzi} e \\textbf{capitale proprio} o \\textbf{patrimonio netto}. Quest\'ultimo rappresenta le risorse conferite direttamtne ai soci, insieme alle riserve di utile generate negli anni e all\'utile/alla perdita delle attività.\r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide1937.png} %quella in basso\r\n\\end{center}\r\nCome possiamo notare dal momento che l\'azienda presa in carico compie un\'\\textit{azione finanziaria di saldo del debito}, la voce \\textbf{cassa} subisce un decremento immediato. Contemporaneamente sul fronte opposto la voce di \\textbf{Debito Verso Fornitori} viene azzerata, scomparendo dalle passività. A seguito di questa operazione lo stato patrimoniale viene ricomposto sul nuovo livello. Questo è il funzionamento della \\textbf{Partita Doppia}, dove ogni singola azione gestionale \\textit{modifica la composizione qualitativa o quantitativa delle fonti, senza mai alterare il perfetto bilanciametno numerico nei 2 lati}.\r\n\r\n\\subsection{Il Conto Economico Scalare e il Ruolo della Nota Integrativa}\r\nMentre lo Stato Patrimoniale fotografa la ricchezza, il \\textbf{conto economico} spiega l\'origine di quella ricchezza attraverso la misurazione del flusso dei costi e dei ricavi generati nell\'esercizio. La normalitva civile impone una struttura di tipo \\textbf{scalare}, la quale sviluppa verticamente procedendo per aggregati, rendendo la lettura del bilancio più fluida.\\\\ \r\nCominciamo con il \\textbf{Valore della Produzione}, che aggrega i ricavi delle vendite delle merci alla variazione delle rimanenze di prodotti finiti in corso di lavorazione. Da questo primo blocco si sottraggono i \\textbf{costi di produzione}, i quali comprendono tutte le spese che riguardano la produzione, e gli \\textbf{ammortamenti}, i meccanismi contabili per cui il costo pluriennaledi un\'immobilizzazione viene ripartito e spalmato lungo gli anni di vita di utile dell\'azienda.\\\\ \r\nSuccessivamente la struttura scalare somma algebricamente tutti i blocchji ee giunge al \\textbf{risulato prima delle imposte}. Una volta sottratte le imposte sul reddito si ottiene il finale che rappresenta l\'\\textbf{utile netto} o la \\textbf{perdita netta}. \\\\ \r\nTale risultato economico viene poi traghettato all\'interno dello Stato Patrimoniale nella sezione del Patrimonio Netto e con la \\textit{nota integrativa} spiegamo in termini discorsivi l\'andamento dell\'esercizio.\r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/gemini1.png}\r\n\\end{center}\r\n\r\n\\subsection{Il Valore e i Costi della Produzione}\r\nEntrando nei dettagli la prima grande macro categoria che incontriamo durante la definizione del Conto Economico è il \\textbf{Valore della Produzione}. Questo non rappresetna semplicmente quanto l\'azienda ha fatturato vendendo i propri prodotti, ma esprime il valore complessivo di \\textit{tutto ciò che l\'impresa ha generato in un dato periodo}. Questo valore rappresenta la \\textbf{capacità produttiva} e la \\textbf{dimensione operativa} dell\'azienda. \\\\ \r\nSuccessivamente troviamo i \\textbf{Costi della Produzione}, i quali rappresentano la totalità degli oneri sostenuti dall\'azienda per trasformare fisicamente le materie prime in prodotti finali. Questi costi sono molto importanti perché determinano il costo totale del processo produttivo. All\'intenro di questa categoria troviamo diverse suddivisioni specifiche: i \\textbf{costi per materie prime e servizi}, i \\textbf{costi della manodopera}, i \\textbf{costi di realizzazione} e infine le \\textbf{spese generali di produzione}.\r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide2005.png}\r\n\\end{center}\r\n\r\n\\subsection{La Gestione Finanziaria e le Rettifiche di Valore}\r\nProseguendo nel conto economico vengono fuori 2 voci che parlano della gestione del capitale, i \\textbf{Proventi} e \\textbf{Oneri Finanziari}. Questi raggruppano le uscite di natura puramente finanziaria che l\'azienda ha generato o subito nel periodo di bilancio:\r\n\\begin{itemize}\r\n    \\item \\textbf{Proventi}: i guadagni deriuvanti dalle attività finanziarie, come interessi derivanti da investimenti o dividendi ricevuti dal possesso si azioni.\r\n    \\item \\textbf{Oneri}: al contrario dei proventi, determinano l\'ottenimento di prestiti o il mantenimento delle attività, includendo gli interessi pagati sulle obbligazioni o commissioni bancarie.\r\n\\end{itemize}\r\nSempre nello stesso campo abbiamo la sezioen delle \\textbf{Rettifiche di Valore di Attività Finanziarie}, posseduti dall\'impresa, i quali riflettono i cambiamenti nelle condizioni di mercato. Possono essere \\textit{positivi}, diventando \\textbf{rivalutazioni}, o \\textit{negativi}, diventando \\textbf{svalutazioni}.\r\n\r\n\\subsection{Il Ruolo delle Imposte sul Reddito}\r\nPriam di concludere il bilancio l\'impresa deve calcolare e sottrarre il \\textit{carico fiscale}. Le \\textbf{imposte} rappresentano gli importi obbligatori che l\'organizzazione deve versare al governo, \\textit{calcolati in base ai profitti generati dall\'azienda }.\\\\ \r\nQuesta voce racchiude tutte le spese date dalla tassazione, tra cui la più importante, le \\textbf{imposte sul reddito}, ovvero le tasse pagate direttametne sull\'utile netto prodotto dall\'azienda. A queste si aggiungono l\'\\textbf{imposta sul valore aggiunto} (\\textbf{IVA}), applicate sui beni e servizi venduti ai clienti e infine le \\textbf{imposte sulle proprietà}, ceh colpiscono il valore dei beni immobili o dei macchinari posseduti dall\'azienda.\\\\ \r\nSottraendo questi valori al risultato \\textbf{lordo} otteniamo l\'\\textbf{utile} (o\\textbf{perdita}) \\textbf{dell\'esercizio}\r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide2006.png}\r\n\\end{center}\r\n\r\n\\subsection{Il Documento a Supporto della Trasparenza}\r\nCome accennato precendentemente, la \\textbf{Nota Integrativa} è un documento discorsivo che accompagna le tabelle numeriche. Si tratta di un documento essenziale del bilancio, che ha lo scopo di includere quelle informazioni necessarie per dare una spiegazione completa in merito alla situazione economica dell\'impresa. Tra le sue pagine vengono esplicitati i \\textbf{criteri contabili} che l\'azienda ha utilizzato per redigere il bilancio, fornendo spiegazioni dettagliate e i reali motivi rispetto all\'inclusione delle voci nello Stato Patrimoniale e Conto Economico.\\\\ \r\nLa nota dichiara formalmente se la società applica i \\textbf{principi contabili internazionali} e chiarisce le metodologie di stima. Viene definita anche la \\textit{classificazione temporale dei debilit}, chiarendo che i \\textbf{debiti finanziari} sono etichettati come passività correnti solo se il loro rimborso è previsto entro 12 mesi dalla chiusura del bilancio. Vengono dettagliate anche le \\textbf{strategie di pianificazione fiscale}, messe in atto per ottimizzre le tasse ne lrispetto delle normaltive, riportando che la presenza o meno di \\textbf{eventi succesivi alla data di chiusura}.\r\n\r\n\r\n\\section{Analisi di Bilancio}\r\n\\subsection{Finalità dell\'Analisi}\r\nIl bilancio diventa la materia prima per l\'\\textbf{Analisi di Bilancio}, un processo finalizzato al trattemento approfondito dei dati contenuti per estrapolare informazioni critiche riguardo il management. In particolare indaga la solidità della \\textbf{struttura patrimoniale} dell\'impresa e si valuta il \\textbf{grado di reddittività} degli investimenti effettuati. Viene inoltre scovata la \\textbf{solvibilità} e il \\textbf{grado di liquidità} dell\'azienda, ovvero la capacità di far fronte ai debiti dell\'impresa. Si esamina infine l\'\\textbf{efficienza strtuturale} complessiva e la \\textbf{capcità di generare flussi di liquidità} nel tempo.\\\\ \r\nQuesta analisi è divisa in divesrsi processi:\r\n\\begin{itemize}\r\n    \\item \\textbf{Acquisizione}: l\'azione di prendere uno o due bilanci della stessa azienda, spesso affiancati dai bilanci dei concorrenti.\r\n    \\item \\textbf{Verifica dell\'Attendibilità dei Dati}: processo di assicurazione per validare la correttenza dei dati.\r\n    \\item \\textbf{Riclassificazione del Bilancio}: rielaborazione dei dati secondo modelli matematici specifici che mettono in risalto determinate aree gestionali.\r\n    \\item \\textbf{Valutazione dei Risultati}: si cerca di rispondere alle domande strategiche fondamentali: \\textit{convien acquistare azioni dell\'azienda?}, \\textit{È opportuno concedere del credito finanziario?} o \\textit{Come performa rispetto alla concorrenza?}.\r\n\\end{itemize}\r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide2018.png}\r\n\\end{center}\r\n\r\n\\subsection{La Riclassificazioen Finanziaria}\r\nPer poter analizzare la struttura con efficacia, lo Stato Patrimoniale deve essere riclassificato seguendo un preciso \\textbf{criterio finanziario}. Questo criterio suddivide le voci in 2 grandi blocchi:\r\n\\begin{itemize}\r\n    \\item \\textbf{\\textit{Impieghi}}: esprimonio il fabbisogno finanziario dell\'impresa per effettuare i suoi investimenti e vengon odefiniti in base alla loro liquidabilità. Troviamo le \\textbf{Attività Correnti} (risorse convertivili in contatni entro 12 mesi) e \\textbf{Attività Immobilizzate} (tutti gli investimenti a lungo termine esigibili opltre la barriera dei 12 mesi).\r\n    \\item \\textbf{\\textit{Fonti}}: i mezzi scelti dall\'azienda per ottenere copertura economica degli impieghi, costituite dal \\textbf{passivo} e dal \\textbf{patrimonio netto}. Anche queste si dividono in \\textbf{Passività Correnti} (debiti da saldare entro 12 mesi), \\textbf{Attività Immobilizzate} (debiti estinguibili oltre i 12 mesi, come il TFR) e infine il \\textbf{Patrimonio Netto} (rappresenta la solida ricchezza di proprietà dei soci).\r\n\\end{itemize}\r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide2020.png}\r\n\\end{center}\r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide2021.png}\r\n\\end{center}\r\nProprio come lo Stato Patrimoniale, anche il Conto Economico deve essere riclassificato, tramite il metodo del \\textbf{valore aggiunto}. Questa riclassificazione esprime la capacità reale dell\'impresa di ricreare nuova ricchezza rispetto al costo delle materie prime. IUl calcolo parte dal \\textbf{Valore della Produzione}, dal quale vengono sottratti i \\textit{costi esterni di gestione}, per ottenere il \\textbf{Valore Aggiunto} generato. Sottraendo da quest\'ultimo il costo del personale, l\'azienda ottien eil \\textbf{Margine Operativo Lordo}, dato più importante riguardante la gestione dell\'azienda.\\\\ \r\nDa qui in poi il calcolo integra le componenti non caratteristiche, sommando o sottraendo i risultati delle altre aree, per giungere al \\textbf{Risultato Ante Imposte} che, dopo aver sottratto le imposte ritorna il \\textbf{Risultato d\'Esercizio}.\r\n\r\n\\subsection{Margine di Tesoriera e Capitale Circolante Netto}\r\nUna volta riclassificato lo Stato Patrimoniale, l\'analisi prcede col \\textit{calcolo dei margini}. Il \\textbf{Margine di Tesoriera} (MT) è un indicatore monetario che permette di esprimere la capacità dell\'azienda di far fronte al pagamento dei propri debiti a breve termine utilizzando esclusivamente le proprie liquidità imemdiate. Siottieme \\textit{sommando la liquidità immediata e diretta, per poi sottrarre le passività correnti}. Per definire una situazione aziendale come ottimale \\textbf{questo valore deve essere positivo}.\\\\\r\nIl \\textbf{Capiitale Circolanete Netto} (CCN) invece, accerta la capacità dell\'azienda di coprire gli impegni a breve termine sfruttando tutte le attività correnti, includendo le scorte in magazzino. Avere un CCN negativo risulta allarmante per l\'azienda, perché sancisce matematicamente, che persino con le rimanenze in magazzino si è carenti di scorte e molti clienti non verrebbero soddisfatti.\r\n\r\n\\subsection{Gli Indici di Qualità}\r\nAd affiancare i magini troviamo gli indici calcolati tramite rapporti:\r\n\\begin{itemize}\r\n    \\item \\textbf{Indice di Liquidità} (IL): valuta la capacità dell\'impresa di ripagare i debiti a breve termine utilizando esclusivamente le attvitià già liquide o quelle liquidabili molto rapidamente. Se scende sotto lo 0,5 la situazioen è ritenuta critica, mentre se sale sopra 1 l\'azienda è in uno stato ottimale.\r\n    \\item \\textbf{Indice di Struttura Primario} (ISP): indica la capacità dell\'impresa di coprire interamente le proprie immobilizzazioni finanziarie utilizzando il proprio Patrimonio Netto. Un ISP sopta 0.7 indica un\'azineda con una linea ottimale.\r\n    \\item \\textbf{Indice di Solidità} (IS): si calcola dividendo \\textit{la somma di tutte le passvità per il patrimonio netto} e mostra il grado di indipendenza dell\'azienda rispetto a finanziamenti esterni. Se l\'IS è maggiore di 2 l\'azienda si trova in una situazione critica, emntre se è minore di 1 siamo in uno stato ottimale.\r\n\\end{itemize}\r\n\r\n\\subsection{Il Ritorno}\r\nL\'ultima fase dell\'analisi di bilancio si basa sugli \\textbf{Indici di Reddittività}. Ce ne sono 4 principali:\r\n\\begin{itemize}\r\n    \\item \\textbf{Return of Investments} (ROI): indicatore principe per la misura della reddittività. Viene definito come \\textbf{Capitale Operativo} diviso per il \\textbf{Capitale Investito} e aiuta il management a comprednere se le strategie operative adottate sono soddisfacenti sul guadagno finale. \r\n    \\item \\textbf{\\textit{Return on Sales}} (ROS): si ricava nel rappoorto \\textbf{Reddito Operativo} fratto \\textbf{Valore della Produzione}.. è molto importante dato che indica con chiarezza quanto profitto viene generato per ogni singol oeuro di ventdite incassato, valudando in modo diretto la capacità dell\'azienda di mantenere bassi i propri costi, massimizzando i ricavi.\r\n    \\item \\textbf{\\textit{Return of Assets}} (ROA): valuta l\'efficienza complessiva dell\'azienda. Viene definito come \\textbf{Reddito Operativo} fratto il \\textbf{totale degli Impieghi}. A differenza del ROI si fornisce una prospettiva allargata sull\'impiego di tutte le risorse fisiche e intangibili a disposizione dell\'impresa.\r\n    \\item \\textbf{Return of Debts} (ROD): Si ottiene calcolando al divisione tra \\textbf{Oneri Finanziari} e il \\textbf{Totale delle Passività}. A differnza dei precedenti operatori è più specifico riguardo al lato passivo dei finanziamenti. Più questo valore è basso, più l\'azienda reisce a pagare tassi di interessi agevolati.\r\n\\end{itemize}\r\n\r\n\r\n\\section{Project Management}\r\n\\subsection{Il Concetto di Progetto e le Variabili del Project Management}\r\nUn \\textbf{progetto} è definito formalmente come uno sforzo temporaneo intrapreso per realizzare un prodotto o un servizio specifico.\\\\ \r\nÈ fondamentale distinguere due entità fondamentali in questo caso:\r\n\\begin{itemize}\r\n    \\item \\textbf{Programma}: un\'iniziativa a lungo termine che tipicamente racchiude molteplici progetti.\r\n    \\item \\textbf{Compito}: uno sforzo a brever termine compost oda attività elementari di durata limitata, l\'insieme dei compiti costruisce il progetto.\r\n\\end{itemize}\r\nDurante il ciclo di vita, ogni progetto è governato da 4 variabili iterdipendenti che il PM deve gestire:\r\n\\begin{itemize}\r\n    \\item \\textbf{Tempi}: durate e scadenze operative.\r\n    \\item \\textbf{Costi}: includono l\'itnero budghet e i costi diretti ed indiretti.\r\n    \\item \\textbf{Risorse}: personale o attrezzature materiali.\r\n    \\item \\textbf{Qualità}: rigoroso rispetto delle specifiche tecniche richiesti dal committente.\r\n\\end{itemize}\r\nOltre a queste risorse la gestione del progetto ha anche una risorsa intangibile, la \\textbf{conoscenza}, le lezioni apprese dai fallimenti in competenze specialistiche e in migliori pratiche aziendale.\r\n\r\n\\subsection{Il Processo di Project Management}\r\nIl primo punto fondamentale è la \\textbf{Pianificazione} del progetto, nella quale viene definita la portata del progetto, definendo obiettivi e si organizza strategicamente il team.\\\\ \r\nA questa parte segue lo \\textbf{Scheduling} che definisce la programmazione temporale, dove allocare le persone e i materiali e quando, per raggiungere il progetto finale. Segue la fase di \\textbf{Controllo}, dove viene fatto un monitoraggio continuo delle risorse, per garantire tempi e costi precisi come definito nella fase di pianificazione.\\\\ \r\nCiò che rende effettivamente complessa la pianificazione iniziare viene definta da 3 principali dimensioni analitiche: la \\textbf{Scala}, la grandezza economica del budget impiegato, la \\textbf{Complessità}, riuscire a inserire il progetto all\'inmterno delle numerose attivitàe infine l\'\\textbf{Incertezza}, nella quale si devono definire i requisiti fondamentali seguendo rigorosamente ciò che il mittente ha riferito.\\\\ \r\nPer definire queste barriere sfruttiamo 2 punti principali: i \\textbf{Project Objectives}, che stabiliscono i risultati attesi, il \\textbf{Project Scope}, che traccia confini netti per chiarire copsa sia incluso e cosa no nella consegna del progetto, e infine il \\textbf{Project Approach}, nel quale definiamo i metodi nelle varie fasi.\\\\ \r\nPer misurare precisamente il raggiungimento dei vari pilastri, sfruttiamo i \\textbf{Key Performance Indicators} (KPI), indicatori quantitativi che possono tracciano l\'avanzamento dei valori. La teoria di questi indici viene definita \\textbf{S.M.A.R.T.}, stabilendo che in undice deve essere:\r\n\\begin{itemize}\r\n    \\item \\textbf{Specific}: speicifico e puntuale.\r\n    \\item \\textbf{Measurable}: misurabile tramite logiche oggettive.\r\n    \\item \\textbf{Achievable}: raggiungibile con la situazione attuale aziendale.\r\n    \\item \\textbf{Relevant}: rilevanti ai fini del business.\r\n    \\item \\textbf{Time-bound}: delimitato aall\'interno di una cornice di scadenza. \r\n\\end{itemize}\r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide2115.png}\r\n\\end{center}\r\n\r\n\\subsection{La Struttura e la Schedulazione del Progetto}\r\nUltimata la strategia di progetto, si applica il processo filosofico del \"\\textit{divide et impera}\" detto \\textbf{Work Breakdown Structure} (WBS), la scomposizione gerarchica del progetto in porzioni più piccole e gestibili. Alla base si annotano i \\textbf{Work Packages} (WP), i pacchetti di lavoro fondamentali che rappresetnano le unità di basso livello, rappresentano un blocco di azione d\'azione isolato che prende specifici inpute ritorna specifici output.\\\\ \r\nA fare da collante lungo il percorso abbiamo le \\textbf{Milestone}, che sono dei compiti operativi, che danno una direzione con punti di verifica intermedi.\\\\ \r\nApprovati i pacchetti di lavoro , bisogna posizionarli nel tempo tramite il \\textbf{Diagramma di Gantt}, introdotto nel 1910. Si tratta di un grafico a barre dove l\'asse orizzontale misura lo scorrere del tempo e l\'asse verticale elenca i WP. La lunghezza della barra indica quant otempo il WP occuperà.\\\\\r\nIl grandissimo pregio manageriale del Gantt sta nella predisposzione di \\textbf{visualizzare le precedenze}, considerando i WP con tempi maggiori, calcolando così anche il tempo totale stimato.\r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide2124.png}\r\n\\end{center}\r\nPer le commesse più complicate ingegneristicamente solitametne viene lasciato in parte il Gantt e viene sfruttato il \\textbf{Critical Path Method} (CPM), una tecninca matematica che decodfica e modella il progetto trasformandolo in un grafo orientato, detto \\textbf{Network Diagram}. In questo tipo di grafico definiamo dei nodi rotondi, collegatida delle frecce che calcolano le dipendenze logiche e temporali. Questo tipo di grafico permette di visualizzare e calcolare le tempistiche per ogni stazione di lavoro. Vengono deiniti dei tempi dalla creazione di questo grafico:\r\n\\begin{itemize}\r\n    \\item \\textit{Earliest Start Time}\r\n    \\item \\textit{Earliest Finish Time}\r\n    \\item \\textit{Lastest Start Time}\r\n    \\item \\textit{Lastest Finish Time}\r\n\\end{itemize}\r\nTramite questi 4 parametri possiamo calolare il \\textbf{Float} (tolleranza), la quale se ha un valore pari a 0 signiica che l\'attività non ha margine di slittamento. \r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide2127.png}\r\n\\end{center}\r\n\r\n\\subsection{Il Controllo dei Costi e l\'Accelerazione delle Attività}\r\nUna volta definito il progetto e cominciata la produzione, il management deve occuparsi del \\textbf{supervisionamento} del processo. Questa supervisione viene solitamente fatta tramite il \\textbf{Budgeted Cost of Work Scheduled} (BCWS), che esprime in termini monetari l\'ammontare esatto dei costi che avremmo dovuto sostenere in base al lavoro programmato fino a quel giorno. La realtà del processo viene invece solitametne catturata tramite l\'\\textbf{Actual Cost of Work Performed} (ACWP), che quantifica i costi usciti veramente dalla cassa. Col terzo indicatore \\textbf{Budgeted Cost of Work Performed} (BCWP) trova un risultato concreto utilizzando gli altri due metodi, controllando iul valore oggettivo della ricchezza prodotta rispetto a ciò che è stato speso.\\\\ \r\nSe sottraiamo l\'ACWP al BCWP otteniamo il \\textbf{Cost Variance}. Se questo valore è negativo abbiamo uno \\textit{sforamento del budget deciso precedentemente}. \\\\ \r\nSe invece sottraiamo il BCWS ai BCWP otteniamo la \\textbf{Schedule Variance}. Se il valore è sott o0 il progetto procede molto più lentametne di quello che è stato prospettato. \r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide2131.png}\r\n\\end{center}\r\nQuando i grafici certificano quando la tempistica è in affanno o qual\'ora il cliente esiga una compressione drastica sui tempi. Per risolvere questi problemi viene utilizzata la tecnica del \\textbf{Crashing}, nella quale si cerca di accellerare a dismisura e abbreviare forzatamente la duratura residua del progetto, riversandovi sopra imponenti dosi di risorse. \\\\ \r\nTale iniezione genera un \\textbf{costo marginale crescente}, nel quale riduciamo i tempi operativi, andando però a gravare sulle casse aziendali.\r\n\r\n\\subsection{L\'Ecosistema delle Risorse: MAtrice, RACI e la Figura del Project Manager}\r\nPEr definire strategie in modo matematico e sicuro vengono utilizzate strutture specifiche. Una di queste è l\'utilizzo della \\textbf{Organizzazione a Matrice}. In questa matrice da una parte abbiamo il \\textbf{Manager di funzione}, il quale ha il compito di mantenere intatti gli standard di efficenza del proprio dipartimento. Dall\'altro lato abbiamo il \\textbf{Manager di Progetto}, che fisicamente convoglia, indirizza e canalizza le risorse umane ottenute dai singoli reparti dell\'azienda. \r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide2133.png}\r\n\\end{center}\r\nPer avere degli \"\\textit{argini}\" per proteggere l\'azienda da eventuali crisi, viene inserito l\'utilizzo della \\textbf{Matrice RACI}, uno scudo formale concepito unicamente per definire le responsabilità nominali associate ad ogni specifica mansione. \\textbf{RACI} sta per:\r\n\\begin{itemize}\r\n    \\item \\textbf{Responsible}: chiunque prenda in consegna un processo, deve portare il lavoro a compimento e ne è il referente.\r\n    \\item \\textbf{Accountable}: autorità definitiva preposta a garantire che tutto venga svolto in regola. Si impone sempre che sia presente un unico Accountable per ogni riga di compito.\r\n    \\item \\textbf{Consulted}: personalità esperta coinvolta frequentemente e sollecitata al fine di offrire input o informazioni ai partecipanti al processo.\r\n    \\item \\textbf{Informed}: ruolo puramente intellettuale e distaccato, assegnato a chiunque debba rivevere la notizia del risultato maturato.\r\n\\end{itemize}\r\nColui che ha il compito ufficiale di gestione generale del progetto è il \\textbf{Project Manager} (\\textbf{PM}). Questo ruolo consiste nel impegnare risorse e input per raggiungere l\'obiettivo finale di progetto. Il PM deve possedere, oltre che le conoscenze specifiche sulle tecnologie di processo, avere una \\textbf{visione strategica} della catena di processo e una raffinata \\textbf{capacità predittiva}, per gestire al meglio il processo di creazione del prodotto finale. A questo ne consegue ovviamente la capacità di avere grandi capacità di \\textit{leadership} e \\textit{coordinamento} sulle risorse.\\\\ \r\nAd affiancare il PM solitamente è presente la figura del \\textbf{Project Management Office} (\\textbf{PMO}), un ufficio burocratico che ha una completa autorità che sta sopra il PM e decide lo schedule dei progetti, che risorse utilizzare e ha la possibilità di apportare modifiche strategiche a piacimento. \r\n\r\n\r\n\\section{La Gestione Strategica delle Supply Chain}\r\n\\subsection{Definizione e Livelli di Analisi}\r\nIl panorama aziendale moderno sfrutta un modello di \\textbf{Supply Chain}. Questo modello riprende la \\textit{catena del valore}, coinvolgendo non solo i processi interni, ma inglobando tutta quella che la storia di creazione di un processo, partendo dalle materie prime al cliente finale. La gestione di questa catena viene gestito dal \\textit{supply chain management} (\\textbf{SCM}), diviso in 3 componenti principali:\r\n\\begin{itemize}\r\n    \\item \\textbf{Supply Netword}: visuale panoramica dei flussi commerciali e procedurali del processo.\r\n    \\item \\textbf{Operation}: studio dei macro-processi e i movimenti che avvengono tra loro.\r\n    \\item \\textbf{Processo}: studio del processo nel suo piccolo, per ogni operazione fatta nella catena.\r\n\\end{itemize}\r\nLe attività primarie che sostengolo la catena logistica solo a loro volta altre 3 categorie, divise in \\textbf{Producement} (acquisti a monte), \\textbf{Make} (produzione interna) e \\textbf{Deliver} (cliente finale).\\\\ \r\nTuttavia le aziende moderne considerano l\'utilizzo di una supply chain di questo tipo ormai obsoleta. Al giorno d\'oggi vigono le catene dette \\textbf{circolari}. In questo modello vige la \\textbf{Reverse Logic}, nella quale vediamo un modello per il quale la catena ingloba si tutte le procedure viste fin\'ora e viene aggiunto una parte alla fine nella quale l\'\\textit{azienda viene a recuperare il prodotto a fine ciclo di vita} direttamente dal cliente, creando così un processo automatizzato di \\textit{riciclo}, \\textit{rinnovo} e \\textit{smaltimento ecologico}.\\\\ \r\nGestire tutti i processi descritti è solitamente molto complicato, per riuscire perciò a dominare all\'interno del settore dobbiamo appoggiarci a dei pilastri fondamentali, tra cui \\textbf{abbattimento dei costi totali del sistema}, \\textbf{responsiveness} (reattività fulminea a variazioni non prevedibili), \\textbf{secutrity} (sicurezza nella catena anche durante l\'utilizzo del cliente finale), \\textbf{resilienza} (velocità di rialzo dopo periodi di crisi) e infine \\textbf{innovazione}.\r\n\r\n\\subsection{Dinamiche, Ottimizzazione e Conflitti Interni}\r\nPer sopravvivere alla quantità di richieste da parte dei clienti per un prodotto, oggi le aziende tentano di \\textit{abbandonare l\'idea di catena unica} per il proprio prodotto, passando al modello di \\textbf{Supply Chain Dedicate}, nel quale possiamo seguire diverse regole di costruzione del prodotto finale:\r\n\\begin{itemize}\r\n    \\item \\textbf{Built-to-Order}: lotti anche singoli di ordini dedicati.\r\n    \\item \\textbf{Build-to-Plan}: lotti basati su previsioni standard sul mercato.\r\n    \\item \\textbf{Build-to-Stock}: ampie scorte in magazzini.\r\n    \\item \\textbf{Build-to-Spec}: in base a dei contratti costruiamo secondo specifiche precise con grandi lotti.\r\n\\end{itemize}\r\nPer ottimizzare i processi viene utilizzato un processo di \\textbf{Cross-Docking}, nel quale abbiamo un centro di smistamento che contiene prodotti di ogni tipo da smistare verso le singole filiali.\r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide2212.png}\r\n\\end{center}\r\nAl Cross-Docking si aggancia istantaneamente il \\textbf{Vendor-Managed Inventory} (VMI), per il quale non sono le singole filiali a ordinare dal centro di smistamento, ma è quest\'ultimo, in base ai dati dei diversi venditori, a decidere a chi mandare cosa e quando.\\\\ \r\nL\'ostacolo più grande da superare per avere una supply chain fluida è il superamento degli \\textbf{Obiettivi in Conflitto}, nel quale bisogna evitare di avere enormi stoccaggi di materie prime (data la varietà degli ordini) e al contempo avere una manodopera in continuo cambio di metodi per le varie catene di produzione. La soluzione che è stata trovata negli anni è quella di mantenere \\textbf{rasenti a 0 le materie prime in stoccaggio}, così da mantenere una salda struttura aziendale.\r\n\r\n\\subsection{L\'Incertezza e la Sidrome del Bullwhip}\r\nData la varietà della domanda di mercato, definita dal \\textbf{forecasting} (termine statistico che indica l\'imprevedibilità umana), potrebbe generarsi all\'interno della gestione aziendale un\'\\textbf{incertezza}. Quest\'ultima viene incrementanta da molti fattori, tra i quali i \\textbf{lead time} (tempi di macchinari e trasporti mai precisi e molto variabili), le \\textbf{tempeste geopolitiche}, ecc. generando un ecosistema fluttuante continuo.\\\\ \r\nLa conseguenza all\'incertezza genera il problema, già incontrato negli scorsi capitoli, dell\'\\textbf{Effetto Frusta}, o \\textbf{Effetto Bullwhip}, una situazione aziendale nella quale \\textit{una piccola modifica nella domanda del cliente può risultare fatale} e comportare ingenti cambi nella produzione dell\'azienda a monte della catena di distribuzione di un prodotto. \r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide2216.png}\r\n\\end{center}\r\nQuesto effetto viene solitamente contrastato con una \\textbf{capacità produttiva in eccessp}, saturando i magazzini e portando i tempi di consegna alle stelle.\r\n\r\n\\subsection{La Progettazione Strategica e il Modello di Fisher}\r\nPer disegnare un architettura logica perfetta di un\'azienda, nel 19978 Mark Fisher introduce un modello diventato pietra miliare nell\'ambito imprenditoriale, il \\textbf{Modello di Fisher}. In questo modello vediamo una divisione dei prodotti in 2 macro-famiglie: i \\textbf{Prodotti Funzionali}, quei prodotti con un ciclo di vita infinito, detti \\textit{generi di prima necessità} (pane, passata di pomodoro,...). Questi prodotti sono un grande vantaaggio dal punto di vista delle vendite, per la loro vita, ma offrono \\textit{margini di profitto relativamente bassi} a causa delle molte variabili che ci stanno dietro. Dall\'altr olato troviamo i \\textbf{Prodotti Innovativi}, quei prodotti che si bruciano in fretta, ma vendono molto bene nel loro ciclo di vita (occhiali da sole all\'ultima moda, nuovo iPhone,...). Questi prodotti soffrono del \\textbf{rischio di obsolescenza}: se restano invenduti il loro valore si azzera molto velocemente.\\\\ \r\nL\'errore letale per un\'azienda è tentare di gestire i prodotti funzinali come prodotti innovativi o il contrario. I prodotti innovativi devono disporre di una \\textbf{supply chain efficiente}, nel quale si cerca di minizzare i costi, viaggiare a pieno carico e tagliare le scorte per estrarre un profitto dai margini. Per i prodotti innovativi invece è essenziale sfruttare una \\textbf{supply chain responsive}, nel quale si ha un ecosistema veloce ed elastico, disposto a pagare ingenti somme di denaro per non perdere neanche una singola occasione di vendita. Quando si invertono queste due catene si arriva in una fase di \\textbf{mismatch}. nella quale l\'azienda si troverà perennemente con gli scaffali vuoti nel momento di picco o sarà costretta alla svendita del prodotto.\\\\ \r\nPer avere una gestione delle vendite efficiente dei prodotti funzionali, solitamente un\'impresa si affida ad una dottrina \\textbf{lean} (\\textit{snella}), nella quale abbiamo un approvvigionamento \\textbf{Just-in-Time}, con pochissimi fornitori locali. Al contrario per le filiere responsive con prodotti innovativi viene adottata una tecnica \\textbf{agile}, nella quale tutto ciò che conta è la velocità e l\'immensa flessibilità operativa. In scenari ibridi viene sfruttata un\'insieme di dottrina agile e lean, nella tecnica del \\textbf{postponement}: l\'ingegneria progetta basi fisiche modulari e standardizzate a basso costo, ritardando la personalizzazione all\'ultimo istante prima di vendere il prodotto finale.\r\n\r\n\r\n\\section{Sustainable SCM}\r\n\\subsection{I Fondamenti della Sostenibilità nella Supply Chain}\r\nPer decenni l\'idea di sostenibilità fu intesa come lo sviluppo in grado di soddisfare i bisogni del presente senza compromettere le generazioni future. Applicando questa filisofia venne adottato il principio del \\textbf{Triple Bottom Line}, nel quale si impone di misurare il successo aziendale consderando \\textit{3 variabili principali}: \\textbf{Persone} (aspetto sociale), \\textbf{Pianeta} (impatto ecologico) e \\textbf{Profitto} (aspetto economico). Questi criteri al giorno d\'oggi sono racchiusi sotto la sigla \\textbf{ESG} (\\textit{Environment Social Governance}, i quali definiscono le performance e gli standard etici con cui un\'impresa deve operare. L\'importanza di questi standard è stata recentemente blindata a livello normativo nella direttiva \\textbf{CSRD} (\\textit{Corporate Sustainability Reporting Directive}), la quale impone alle imprese l\'obbligo di rendicotare in modo standardizzato e misurabile i propri ESG lungo tutta la catena di produzione.\\\\\r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide2305.png}\r\n\\end{center}\r\nSempre in quegli anni per seguire le continue modifiche di sostenibilità all\'interno del supply chain management, vengono definite 2 strategie di base, tutt\'ora molto utilizzare:\r\n\\begin{itemize}\r\n    \\item \\textbf{Strategia di Gestione dei Fornitori per Rischi e Performance}: evitare disastri reputazionali ed economici ponendo severi standard ambientali e sociali ai fornitori come clausole di acquisto.\r\n    \\item \\textbf{Strategia di Gestione della Supply Chain per Prodotti Sostenibili}: questa strategia non si limita a difendersi dai rischi, ma punta a creare valore lungo l\'intero cicli di vita del prodotto, supportando lo sviluppo dei fornitori verso logiche \"\\textit{green}\" e incrementando la comunicazione.\r\n\\end{itemize}\r\nNel SSCM diventa fondamentale una grande cooperazione tra industrie e imprese collaboratrici. Per questo motivo ad oggi si parla di \\textbf{Supply Chain Collaboration}, nella quale si ha la creazione di \\textbf{Multi-Stakeholder Initiatives} (MSI), potenti piattaforme politiche operative in cui si possono formare delle alleaneze tra competitor e non per afrontare le sfide aziendali più ardue.\\\\ \r\n\r\n\\subsection{La Dimensione Ambientale e la Corsa al Net-Zero}\r\nPer affrontare il problema ecologico del pianeta viene imposto alle aziende di \"superare\" la sfida detta \\textbf{GKG Protocol} (\\textit{Green Gashouse Protocol}, nella quale so devono classificare e misurare le emissioni aziendale in 3 \\textit{Scope}:\r\n\\begin{itemize}\r\n    \\item \\textbf{Scope 1}: emissioni dirette generate dagli impianti o veicoli dell\'azienda.\r\n    \\item \\textbf{Scope 2}: emissioni indirette derivandi dall\'utilizzo di energia elettrica o termica utilizzata durante i processi di creazione del prodotto.\r\n    \\item \\textbf{Scope 3}: tutte le emissioni indirette sprigionate lungo la catena del valore, partendo dall\'estrazione delle materie prime, fino alla consegna del prodotto finale.\r\n\\end{itemize}\r\nDato che lo Scope 3 racchiude tutta l\'impronta carbonica dell\'azienda, su questo scope definiamo il concetto di \\textbf{Net-zero Supply Chain Management}, nel quale le aziende vengono obbligate a raggiungere un 90\\% di impronta carbonica durante la produzione entro il 2050.\r\n\\begin{center}\r\n    \\includegraphics[width=0.8\\textwidth]{img/slide2315.png} %sotto\r\n\\end{center}\r\nLa semplice riduzione del danno però non comporta solamente l\'invertire la rotta presa anni fa dalle industrie, ad oggi infatti si punta ad una veras e propria rivoluzione con le \\textbf{Supply Chain Rigenerative}, nel quale si sfrutta il potere d\'acquisto e i contratti aziendali per creare \\textit{ecosistemi fiorenti e curare materialmente il territorio}.\\\\ \r\n\r\n\\subsection{La Dimensione Sociale, Economica e i Contratti di Filiera}\r\nPer mitigare le possiibli problematiche che vengono fuori dall\'utilizzo delle varie supply chain, viene definita l\'abilità del \\textbf{Supply Chain Risk Management}, abilità vitale per scovare e mitigare anticipatamente le vulnerabilità sociali ed economiche dell\'azienda.\\\\ \r\nNella dimensione delle \\textit{Persone} le aziende hanno delel leggi salde a cui far fronte durante la scelta della manodopera. L\'etica moderna impone l\'approccio del \\textbf{Living Income}, un prezzo minimo di riferimento da coprire tutti i possibili costi e i margini per mantenere il lavoro pulito e sicuro per il personale. \r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\\end{document}',1,'University');
INSERT INTO `LatexNotes` (id, title, content, userId, type) VALUES (3,'Relazione Grid + Supervisor Tirocinio','\\documentclass{article}\n\\usepackage{graphicx} % Required for inserting images\n\\graphicspath{{C:/Users/sbattisti/AgoraDocumenti/media/Relazione\\_Grid\\_+\\_Supervisor\\_Tirocinio} {/Users/Simone/agora_documenti/media/Relazione\\_Grid\\_+\\_Supervisor\\_Tirocinio}}\n\\usepackage{geometry}\n\\usepackage{subcaption}\n\\geometry{a4paper, top=1 cm, bottom=1.5cm, left=1.5cm, right=2cm, bindingoffset=5mm}\n\\newenvironment{sistema}% \n{\\left\\lbrace\\begin{array}{@{}l@{}}}% \n{\\end{array}\\right.} \n\\usepackage{hyperref}\n\\usepackage{color}\n\\usepackage[T1]{fontenc}\n\\usepackage{amssymb}\n\\usepackage{amsmath}\n\\usepackage{textcomp}\n\\hypersetup{\n    colorlinks=true, \n    linktoc=all,     \n    linkcolor=black,  \n}\n\\DeclareMathSizes{11}{11}{11}{11}\n\\definecolor{dkgreen}{rgb}{0,0.6,0}\n\\definecolor{gray}{rgb}{0.5,0.5,0.5}\n\\definecolor{mauve}{rgb}{0.58,0,0.82}\n\\usepackage{xcolor}\n\\colorlet{keyword}{blue!100!black!80}\n\\colorlet{comment}{green!90!black!90}\n\n\\usepackage{listings}\n\n\\definecolor{codegreen}{rgb}{0,0.6,0}\n\\definecolor{codegray}{rgb}{0.5,0.5,0.5}\n\\definecolor{codepurple}{rgb}{0.58,0,0.82}\n\\definecolor{backcolour}{rgb}{0.95,0.95,0.92}\n\\definecolor{codeblue}{rgb}{0.0,0.0,0.8}\n\\definecolor{kotlinorange}{rgb}{0.95, 0.45, 0.13}\n\\definecolor{kotlinpurple}{rgb}{0.65, 0.28, 0.85}\n\n\\lstdefinestyle{JAVA}{\n    backgroundcolor=\\color{backcolour},   \n    commentstyle=\\color{codegreen},\n    keywordstyle=\\color{codeblue}\\bfseries,\n    numberstyle=\\tiny\\color{codegray},\n    stringstyle=\\color{codepurple},\n    basicstyle=\\ttfamily\\small,\n    breakatwhitespace=false,         \n    breaklines=true,                 \n    captionpos=b,                    \n    keepspaces=true,                 \n    numbers=left,                    \n    numbersep=5pt,                  \n    showspaces=false,                \n    showstringspaces=false,\n    showtabs=false,                  \n    tabsize=4,\n    language=Java\n}\n\n\\lstdefinestyle{BASH}{\n    backgroundcolor=\\color{black!90},\n    basicstyle=\\ttfamily\\small\\color{white},\n    commentstyle=\\color{gray},\n    keywordstyle=\\color{cyan},\n    numberstyle=\\tiny\\color{gray},\n    stringstyle=\\color{orange},\n    breaklines=true,\n    frame=single,\n    framerule=0pt,\n    language=bash,\n    morekeywords={sudo, chmod, chown, grep, awk, sed},\n    numbers=none\n}\n\n\\lstdefinestyle{KOTLIN}{\n    backgroundcolor=\\color{backcolour},   \n    commentstyle=\\color{codegreen},\n    keywordstyle=\\color{kotlinpurple}\\bfseries,\n    numberstyle=\\tiny\\color{codegray},\n    stringstyle=\\color{codegreen},\n    basicstyle=\\ttfamily\\small,\n    breakatwhitespace=false,         \n    breaklines=true,                 \n    captionpos=b,                    \n    keepspaces=true,                 \n    numbers=left,                    \n    numbersep=5pt,                  \n    showspaces=false,                \n    showstringspaces=false,\n    showtabs=false,                  \n    tabsize=4,\n    language=Java,\n    morekeywords={val, var, fun, suspend, coroutineScope, launch, it, when, data, object, init, typealias, internal, expect, actual, Boolean, String, Int},\n    deletekeywords={public, static} \n}\n\n\\title{Relazione Supervisor \\& Grid}\n\\author{Simone Battisti - Interactive Media SpA}\n\\date{}\n\n\\begin{document}\n\n\\maketitle\n\n\\section{Supervisor}\n\\subsection{Introduzione al Componente}\nIl componente \\textbf{com.imsl.supervisor} è definito come un \"\\textit{daemon di monitoraggio}\" per i vari componenti all\'interno delle macchine con ambiente MIND. Analizza tramite un servizio di \\textit{polling} lo stato di ogni componente in esecuzione. I servizi possono essere \\textbf{Service} o \\textbf{GridService} (se si tratta di servizi definiti dalla libreria \\textit{Grid}). \\\\\nFornisce una supervisione completa del sistema mind sulla macchina ospitante, fornendo allarmi in caso di failure dei componenti e, se necessario, fornisce servizi di riavvio di componenti.\n\n\\subsection{Funzionamento del Componente}\nPer avviare il file JAR del Supervisor viene richiesto un argomento. L\'argomento principale per avviare il componente è \"\\textit{server}\", il quale avvierà un \\textbf{server TCP/UDP} con parametri di porta e host custom. Una volta avviato il server viene avviato il servizio di \\textbf{SeverListener} che, come dice il nome, funge da \\textit{listener} per le chiamate che arrivano su quella porta.\\\\\nMentra il sistema è \"fermo\" è in uno stato definito \\textbf{listenLoop}. Quando arriva una richiesta al loop viene richiamata la classe \\textbf{ServerActionHndler} che gestisce le azioni arrivate dalla richiesta e le gestisce in modo asincrono sul sistema. Viene inanzitutto definito il tipo di richiesta che arriva, il quale può essere:\n\\begin{itemize}\n    \\item \\textbf{HearthBeatReq}: ping di controllo.\n    \\item \\textbf{ActionReq}: richiesta di eseguire un\'azione (\\textit{start, stop, restart,...}).\n    \\item \\textbf{StatusReq}: richiesta dello stato corrente di tutti i componenti in esecuzione sul sistema.\n    \\item \\textbf{SubscribeReq}: manda aggioranmenti in tempo reale sullo stato dei servizi.\n    \\item \\textbf{UnsubscribeReq}: smetti di mandare aggioranmenti in tempo reale sullo stato dei servizi.\n    \\item \\textbf{EventReportReq}: fornisce un report degli eventi degli ultimi n giorni.\n\\end{itemize}\n\n\\subsection{LifeCycle dei Componenti Grid Lato Supervisor}\nCome detto precedentemente il Supervisor può avviare \\textbf{Service} o \\textbf{GridService}. Il Service rappresenta un processo di sistema operativo standard, solitamente l\'avvio di componenti tramite script o systemD. I GridService invece rappresentano servzi definiti dalla \\textbf{libreria Grid}, la quale fornisce la possibilità di avviare dei server/servlet custom. Il Supervisor per capire quali componenti deve avviare e dove cercarli ha a disposizione il suo file di configurazione \\textit{settings.xml}, il quale fornisce una lista di tag \\textit{Service} o \\textit{GridService}, definiti dai parametri: \\textit{id, serviceName, pollCycle} (per Service) p \\textit{id, component, pollCycle, memoryLimit} (per GridService).\\\\\nPer i componenti Grid se ne occupa la classe \\textbf{ActionGridService} che con la funzione \\textbf{start()} fa partire il servizio di avvio di un GridService. Questo processo inanzitutto legge il grid\\_service.xml del componente, nel quale determina se il si tratta di un componente PHP o JAVA. Genera poi un comando tramite la funzione \\textbf{generateFullCommand(ESBData)} con il quale verrà avviato il componente grid.\\\\\nTutti i dati per generare il comando di avvio derivano dagli \\textbf{ESBData}, una classe che determina le informazioni di:\n\\begin{lstlisting}[style=KOTLIN]\ninternal data class ESBData(\n	val componentName: String,\n	val language: Language,\n	val command: String,\n	val workerNumber: Int,\n	val redirect: String,\n	val javaProperties: String,\n    val version2: Boolean = false\n)\n\\end{lstlisting}\nPrima di avviare il comando vengono fatti dei check precisi nella funzione \\textbf{start()} riguardo la \\textbf{version2} e se il processo deve essere un \\textbf{asyncStart} (avvio in modo asincrono o no). Viene poi generato un \\textbf{flagfile} nel quale verranno stampati gli status che il Supervisor andrà a leggere. Viene poi infine generato e avviato il comando per far partire il componente.\\\\\nPer la precisione il comando è un comando \\textbf{nohup} (\\textit{No-Hang-Up}), composto da:\n\\begin{itemize}\n    \\item Massimo heap utilizzabile solitamente a 2GB (\\textit{-Xmx2G}).\n    \\item Esecuzione del file JAR (\\textit{-jar}).\n    \\item Selezione dell\'output dei log su output.log.\n    \\item Definizione di stderror e stdout.\n    \\item Lancio del processo in background.\n\\end{itemize}\nInfine questo comando viene lanciato in \\textit{sh -c} (che permette di avviare il programma in una shell dedicata) e con davanti il \\textit{nuhup} per far si che il processo non vada mai giù.\\\\\nUna volta terminato il processo di avvio il componente è in stato \\textbf{OK}/\\textbf{FAILURE} e possiamo attuare varie azioni tramite Supervisor su di esso, come:\n\\begin{itemize}\n    \\item \\textbf{RESTART} [hot=true]: il processo viene ricreato completamente tramite un \\textit{kill -15} del processo.\n    \\item \\textbf{RESTART} [hot=false]: il processo non viene ricreato, ma solo stoppato e fatto ripartire (stop\\&start). \n    \\item \\textbf{STOP}: il processo viene stoppato con un \\textit{kill -15  $\\langle\\langle PID \\rangle\\rangle$}.\n    \\item \\textbf{KILL}: il processo viene eliminato con un \\textit{kill -9 $\\langle\\langle PID \\rangle\\rangle$}\n\\end{itemize}\nIl restart con hot a true o false viene definito nella configurazione XML del supervisor, il quale può definire un parametro \\textbf{hotRestart}. Questo viene poi parsato nella \\textbf{ElementConfiguration.createGridService()}, che genera un \\textbf{Element.GridService} il quale conterrà il parametro hotReload. Questo parametro viene poi letto dall\'\\textbf{ActionGridService.reastart()} (\\textit{riga 191}) che farà il kill -15 se true.\\\\\nIn questo schema viene descritto il modello di \\textbf{stop} di un componente Grid:\n\\begin{center}\n    \\includegraphics[width=0.8\\textwidth]{Diagramma di Sequenza Grid Supervisor.drawio.png}\n\\end{center}\n\n\\subsection{Avvio dei Componenti con JarWrapper}\nPer avviare un componente Grid il Supervisor può farlo utilizzando il JarWrapper (componette che permette di trattare i file JAR come dei normali avviabili) del componente. Vengono definiti due diversi comandi in base se il componente utilizza JarWrapper o no. Questa distinzione viene fatta direttamente nel \\textit{grid-service.xml} nel quale possiamo definire il campo \"\\textbf{JarFile}\" il quale conterrà il nome del componente. Questo nome definisce se è presente JarWrapper dalla sua estensione:\n\\begin{itemize}\n    \\item Se termina con \\textit{.jar} $\\rightarrow$ \\textbf{Non} c\'è JarWrapper.\n    \\item Se non termina con \\textit{.jar} $\\rightarrow$ C\'è JarWrapper.\n\\end{itemize}\nPer quanto riguarda il comando la modifica principale viene fatta nella disposizione dei vari parametri:\n\\begin{itemize}\n    \\item \\textbf{JAR Standard}: \n    \\begin{center}\n        \\begin{lstlisting}[style=BASH]\njava -Xmx2G -jar /usr/mindsmerecorder.jar ESB\n        \\end{lstlisting}\n    \\end{center}\n    Come si nota dal comando la definizione dei memory limit a 2 GB vengono definiti subito dopo aver richiamato Java e prima del \\textit{-jar}, dato che vogliamo che il limite di heap avvenga sul processo dell\'avviabile (se lo mettessimo dopo il \\textit{-jar} andrebbe sul processo di avvio del JAR). \n\n    \\item \\textbf{JarWrapper}:\n        \\begin{center}\n        \\begin{lstlisting}[style=BASH]\n/usr/mind ESB -- -Xmx1024M\n        \\end{lstlisting}\n    \\end{center}\n    Come definito prima possiamo avviare il componente come se fosse un vero e proprio avviabile, gli argomenti vengono separati rispetto al memory limit da $--$. In questo caso il memory limit viene posto alla fine, dato che il wrapper è il \\textit{processo principale}, non più Java. Il separatore definisce che gli argomenti sono specifici per il wrapper e non comandi per la shell.\n\\end{itemize}\n\n\n\\subsection{Monitor di Stato}\nDopo aver avviato il server TCP/UDP il Supervisor in parallelo avvia un servizio definito dalla classe \\textbf{ServerState}. Questo servizio genera una \\textbf{ScheduleThreadPool}, dove abbiamo gli \\textit{executor per ogni elemento} che fa partire il polling periodico per il monitoraggio dei componenti.\\\\\nViene generato un thread per ogni componente (\\textit{Element}) del sistema che andrà a monitorare lo specifico servizio, tutto in parallelo col resto del sistema e gli altri threads di monitor. Il thread avvia il proprio monitor ogni n millisecondi definiti dal \\textit{pollCycle} definito in configurazione del servizio. Questo servizio è praticamente invariato tra i servizi GridService e i normali Service.\\\\\nOvviamente al Supervisor per monitorare tutti i processi ha bisogno dei PID dei processi che stanno girando. Il Supervisor però non è a conoscenza di tutti i PID dei vari componenti, ma conosce i loro nomi. Grazie a ciò viene gestita una ricerca tramite \\textbf{pgrep} sui processi avviati e viene ritrovato il PID e lo stato del processo.\\\\\nQuesta ricerca avviene all\'interno della classe \\textbf{MonitorQueryProcess}, che estende l\'interfaccia MonitorQuery. Nello specifico all\'interno della funzione \\textbf{query()} viene fatta questa ricerca, passando per la funzione \\textbf{searchProcesses(processName: String)} la quale ritorna una lista di \\textit{ProcessInformation}, definiti così:\n\\begin{lstlisting}[style=KOTLIN]\nProcessInformation (\n    val pid: Int,\n    val fullName: String\n)\n\\end{lstlisting}\nPer ogni componente viene applicato questo processo e in base se la \\textit{size} della lista è:\n\\begin{itemize}\n    \\item 0 $\\rightarrow$ \\textit{FAILURE}: il componente non è stato avviato.\n    \\item $>$1 $\\rightarrow$ \\textit{OK}: il componente è avviato e sta funzionando correttamente.\n    \\item other $\\rightarrow$ \\textit{OK}: dato che la funzione \\textit{size} non può dare valori negativi, se ci sono più processi vuol dire che il processo è su ma più volte.\n\\end{itemize}\nPer i processi GRID il sistema è lo stesso, cambiano un solamente le classi prese in considerazione. Infatti esiste una classe apposita chiamata \\textbf{MonitorQueryGridService}, che implementa sempre la funzione \\textbf{query()}, che in questo caso richiama la funzione \\textbf{findGridServices(componentName: String)} che fa sempre un \\textbf{pgrep} di sistema, ma in questo caso filtra tramite una funzione \\textbf{isGridService(componentName: String, process: ProcessInformation,...)} la quale fa uno stretto controllo e conferma se:\n\\begin{itemize}\n    \\item è presente un FlagFile nel comando che sta eseguendo il processo.\n    \\item Se il nome del componente è uguale a quello cercato.\n    \\item Legge \\textit{/proc/$<PID>$/cmdline} per validare il comando.\n\\end{itemize}\nQuesto processo viene poi utilizzato per le funzioni di \\textit{start, restart e stop} dei servizi GRID. Nellp specifico vengono utilizzate le funzioni di \\textbf{find} per trovare la lista dei PID del/i processo/i che vogliamo riavviare, fermare o far partire. \\\\\nCome per l\'avvio dei componenti anche in questo caso ci sono 2 metodi di ricerca differnti per i processi avviati tramite JarWrapper o direttamente dal file JAR:\n\\begin{itemize}\n    \\item \\textbf{Con JarWrapper}\n    \\item \\textbf{Senza JarWrapper}\n\\end{itemize}\n\n\\subsection{Problematiche di Estrarre PID tramite pgrep}\nL\'utilizzo del pgrep per trovare i PID dei processi Grid può comportare diverse problematiche:\n\\begin{itemize}\n    \\item \\textbf{Falsi Positivi}: il pgrep potrebbe fare match su un processo non equivalente a quello cercato e quindi ritornare uno stato errato.\n    \\item \\textbf{Race Conditions}: il problema delle Race Condition indica la \"gara\" di un processo per arrivare ad una risorsa. Lo stesso problema possiamo averlo in questo caso, dove la risorsa è il PID del componente Grid, la quale può cambiare nel tempo. Il problema sta mentre il supervisor tenta di mandare il pgrep su un componente e questo intanto cambia di stato, cambia PID o termina.\n    \\item \\textbf{Processi Zombie}: un processo zombie è un processo che non termina quando finisce la propria esecuzione, cioè quando il padre di quel processo non richiama la syscall \\textit{wait()} sul figlio per farlo terminare. Questo comporta problemi al Supervisor, il quale leggerà uno stato di un processo che non esiste, o comunque in failure finché systemd non richiama il periodico \\textit{wait()} che va ad eliminare i processi zombie.\n    \\item \\textbf{Performance}: l\'invocazione del pgrep è molto pesante per i sistemi UNIX, soprattutto su sistemi molto ampli e con tanti processi avviati. L\'avvio di più subshells all\'interno del sistema, come fa il Supervisor con $sh -c$ per avviare i pgrep per la ricerca dei PID, comporta un rallentamento del sistema e incrementa le possibilità di blocco dato che stiamo chiudendo e riaprendo subshells di continuo ad ogni ciclo di polling.\n\\end{itemize}\n\n\\subsection{Avvio del Supervisor}\nL\'avvio del processo del Supervisor è completamente definito nel \\textit{mindsupervisor.service} del componente. Dal file possiamo notare il comando di avvio:\n\\begin{lstlisting}[style=BASH]\n/bin/bash {{IMSL_HOME}}/usr/com.imsl.supervisor/active/systemd.sh start --pid-file=%t/%N.pid\n\\end{lstlisting}\nCome si vede dal comando bash il servizio viene attivado da un file \\textbf{systemd.sh}. Da questo possiamo definire una fase di avvio:\n\\begin{itemize}\n	\\item \\textbf{Il Processo \"Padre\"}: il processo avviato dallo script in \\textit{systemd.sh} è il processo padre. Il \\textit{mindsupervisor.service} lancia il processo tramite lo script facendo avviare il processo con paramtri di $ExecStart$ e i $--pid-file$. \n	\\item \\textbf{Controlli di Sicurezza}: lo script fa dei controlli di sicurezza per fare un check sull\'esistenza di \\textit{IMSL_HOME} E \\textit{IMSL_USER_HOME}.\n	\\item \\textbf{Forking}: se i controlli passano il \\textit{systemd.sh} avvia il forking e genera un processo figlio, creando il processo in background del Supervisor. Con l\'avvio del processo viene \\textbf{specificato il PID che il processo avrà} e andrà scritto nel PIDFile specifico.\n	\\item \\textbf{Servizio Attivo}: il servizio viene considerato attivo da systemd dopo aver visto che il processo padre (\\textit{systemd.sh}) è terminato (dato che è avviato con \\textbf{forking}) e va a leggersi il PID del processo dal PIDFile.\n\\end{itemize}\n\n\n\n\\subsection{Schema Funzionamento Supervisor}\n\\begin{center}\n    \\includegraphics[width=1.05\\textwidth]{Diagramma Supervisor.png}\n\\end{center}\n\n\\pagebreak\n\n\\section{Grid}\n\\subsection{Introduzione alla Libreria}\nLa libreria Grid è un framework interno per la gestione custom delle chiamate API HTTP e SOAP. La libreria è fondata su 3 attori principali: \n\\begin{itemize}\n    \\item \\textbf{Service}: i processi indipendenti che implementano le funzionalitù richieste, notificando il proprio stato sul sistema.\n    \\item \\textbf{Server}: funge da registro centrale e raccoglie gli aggiornamenti di stato del Service. Integra un \\textit{Balancer} per la distrubuzione del carico ed un \\textit{Gateway} che permette l\'accesso all\'esterno tramite le chiamate HTTP.\n    \\item \\textbf{Client}: è colui che gestisce il processo interrogando il server tramite una \\textit{GridRequest} e si connette al Service per l\'esecuzione.\n\\end{itemize}\nIl Grid permette la generazione di un server custom tramite host e porta personalizzati. Inizialmente carica la propria configurazione XML e richiama nel main la funzione \\textbf{SystemService.server(GridServer, Options)}. Questa classe a sua volta chiama la funzione \\textbf{GridServlet.run() $\\rightarrow$ init()}, la quale definisce una serie di passaggi per avviare il \\textit{Servlet} dedicato per quel componente:\n\\begin{itemize}\n    \\item Setup del Logging \n    \\item Caricamento delle liberie definite in configurazione del Grid (\\textit{all\'interno del settings.xml del Grid sono presenti i path alle librerie utilizzate}).\n    \\item Viene avviato il \\textbf{GridServiceImplementation} e la sua funzione \\textbf{start()} la quale crea la vera e propria istanza del server.\n    \\item Genera i providers di chiamata HTTP per ogni configurazione.\n    \\item Avvia la macchian di servizio.\n    \\item Gestisce eventuali shutdown graceful tramite \\textbf{addShutdownHook()}.\n\\end{itemize}\n\n\\subsection{Lifecycle di un componente Grid}\nLa creazione di un GridServlet (classe estesa da HttpServlet) bisogna sovrascrivere alcuni parametri fondamentali, come:\n\\begin{itemize}\n    \\item \\textit{componentName}: strigna identificativa di un componente.\n    \\item \\textit{gridServiceConfiguration}: configurazione del servizio, che definisce i server di registry ai quali connettersi, i protocolli da utilizzare e le porte.\n    \\item \\textit{gridFunctions e httpFunctions}: delle mappe \\textbf{Map$<$String, Function$>$} che associano un endpoint di una funzioone ad una specifica funzione da risolvere.\n\\end{itemize}\nCome definito prima un servlet viene avviato tramite la funzione \\textbf{GridServlet.init()} e poi le chiamate vengono gestite tramite il \\textbf{GridServiceImplementation}.\\\\\nUn GridServlet viene distrutto tramite la funzione \\textbf{destroy()} che stoppa il servlet, impiega un timeout per finire tutte le pending calls e rilascia le risorse di rete.\\\\\nMentre il servlet è un wrapper del servizio le vere e proprie funzioni sono gestite dal Service, il quale filtra le chiamate sulla rete e valida le routes con i nomi delle gridFunctions definite in configurazione. \n\n\n\\subsection{Flagging degli Stati del Grid}\nIl server viene avviato in un thread apposito ed allo stesso tempo viene generato un altro thread parallelo per il \\textbf{monitoring del server}. Il servizio di monitoring si basa sull\'utilizzo dei \\textbf{flag} di sistema, definiti \\textbf{com.imsl.grid.flag}. Lo status di un server può essere:\n\\begin{itemize}\n    \\item \\textbf{INITIALIZING}\n    \\item \\textbf{ACTIVE}\n    \\item \\textbf{FAILED}\n    \\item \\textbf{STOPPING}\n    \\item \\textbf{STOPPED}\n\\end{itemize}\nQuesti flag vengono poi letti dal Supervisor tramite \\textit{polling} così che possa determinare lo stato dei vari servizi.\nIl flagging viene definito su 2 livelli. Il primo viene gestito dal \\textbf{ServicePusher}, il quale avvia un thread tdi background che ogni \\textit{1\' secondi} avvia un evento. Questo evento definisce un payload che contiene un id univoco, gli indirizzo locali del nodo, le funzioni esposte e lo \\textbf{status} attuale del servizio.\\\\\nLo stato può essere uno di quelli definiti prima (\\textit{INITIALIZING, ACTIVE, FAILED, STOPPING o STOPPED}) e viene sovrascritto per ogni evento. Quando abbiamo un cambio di sato il thread invia immediatamente un evento, \\textbf{scavalcando il delay di 10 secondi}, per velocizzare il rilevamento del cambio da parte del Supervisor.\\\\\nIl secondo livello invece determina un metodo di riconoscimento dello stato senza dover interrogare la rete. La JVM vien avviata passando la property \\textbf{com.imsl.grid.flag}, che contiene \\textbf{il path ad un file} che viene utilizzato come \\textbf{registro sincrono}.\\\\\nOgni volta che lo stato cambia il file viene sovrascritto con lo stato corrente del componente Grid.\n\n\\section{Interazione Grid-Supervisor}\n\\begin{center}\n    \\includegraphics[width=0.8\\textwidth]{GridAndSupervisor.png}\n\\end{center}\n\n\n\\section{Common}\n\\subsection{Forking dei Processi}\nIN un sistema UNIX quando un processo padre vuole creare un processo figlio, richiama la funzione di \\textbf{forking}, per la precisione la syscall $fork()$. QUando viene chiamta questa system call da un processo padre, viene generato nell\'albero dei processi un processo figlio \\textbf{identico al padre}. Il ritorno della funzione di forking è il PID del processo figlio appena creato. \\\\\nQuando viene creato il processo figlio il PID visto dal padre può essere:\n\\begin{itemize}\n  \\item \\textbf{0}: il forking è andato a buon fine.\n		\\item \\textbf{$<0$}: il forking non è andato a buon fine e c\'è stato un errore.\n		\\item \\textbf{$>0$}: il forking è andato a buon fine e il processo sta già aspettando il wait del padre perché ha già finito la sua funzione.\n\\end{itemize}\nGrazie a ciò viene generato un nuovo processo ed un nuovo PID, a cui poi verrà assegnato una diversa funzione tramite la syscall $exec()$. Quando avviamo questa funzione vienee caricato il file binario in memoria. Il processo padre ha ora il compito di avviare il figlio e aspettare tramite la funzione di $wait()$.\n\n\\subsection{Kill Signal}\nIn systemi UNIX i segnali sono una forma di \\textbf{forma di comunicazione fra processi}, definita come \\textbf{IPC} (\\textit{Inter Process Communication}), dove vengono generati dei messaggi asincroni che vengono inviati ad un processo dopo la verifica un determinato evento, sia lato utente sia lato sistema operativo.\\\\\nUno di questi segnali è il segnale di \\textbf{kill}, che \"\\textit{uccide}\" i processi terminando la loro esecuzione. In realtà il kill signal non serve solametne per uccidere un processo, ma per inviare segnali tra processi, il problema è che la maggior parte di questi segnali sono segnali di terminazione, da qui il nome.\\\\\nQuando avviamo un segnale, anche con un semplice $Ctrl+C$  o utilizzando il comando $kill$ mandiamo un segnale che il kernel recepisce immediatamente e viene gestito in 3 modi diversi:\n\\begin{itemize}\n  \\item \\textbf{Default Action}: eseguie l\'azione prevista sul sistema.\n		\\item \\textbf{Catch}: solitamente funzioni custom che intercettano i segnali (come ad esempio la possibilità di salvare un file prima di chiudere).\n		\\item \\textbf{Ignore}: il segnale viene ignorato.\n\\end{itemize}\nOgni segnale è identificato dal prefisso \\textbf{SIG} e poi un numero identificativo. Ce ne sono di vari tipi:\n\\begin{itemize}\n  \\item \\textit{SIGTERM - SIG15}: segnali predefiniti inviati dal comando kill base. Una richiesta moderata di terminazione di un processo non forzato.\n		\\item \\textbf{SIGKILL - SIG9}: segnali sempre per avviare un \\textit{kill -9}, che chiede al kernel di \\textbf{terminare forzatamente il processo}.\n		\\item \\textbf{SIGINT - SIG2}: come il segnale SIG15 ma per il processo corrente nella shell. È il segnale che viene mandato con un $Ctrl+C$.\n		\\item \\textbf{SIGSTOP - SIG19}: mette in pausa l\'esecizione del processo.\n		\\item \\textbf{SIGCONT - SIG18}: segnale di continuazione, dice ad un processo in pausa di continuare la propria esecuzione. \n\\end{itemize}\nPer avviare un kill signal semplciemente avviamo un $kill <PID>$, se il processo non viene terminato possiamo forzare lo stop con $kill -9 <PID>$\n\n\\subsection{Systemd Options}\nLe unit service inculdono una sezione \\textbf{Service} che porta le informazioni sul servizio e sul processo monitorato. L\'opzione \\textbf{Type} type configura il meccanismo con cui il servizio comunica al gestore che l\'avvio è stato completato; sono disponibili le seguenti opzioni:\n\\begin{itemize}\n    \\item \\textbf{simple}: systemd considera che il processo è stato avviato subito dopo il forking, \\textbf{prima ancora di lanciare l\'exec()}. Systemd passerà immediatamente ad avviare i servizi successivi, senza aspettare l\'avvio del primo. Il problema con questo parametro è che se il comando esplicitato nel $ExecStart=\"\"$ del file .service contiene un errore i comando fallisce ma systemd lo saprà solamente quando controlla lo stato dei servizi, invece che prima che parta\n    \\item \\textbf{exec}: abbiamo un sostituto di simple nel quale systemd aspetta che il programma reale venga eseguito in memoria. Ritarda l\'avvio dei servizi successivi per assicurarsi che il servizio sia avviato. A differenza di \\textit{simple} in questo caso systemd saprà se il servizio ha funzionato o no.\n    \\item \\textbf{oneshot}: systemd aspetta che il processo termini completamente prima di considerarlo \"\\textit{avviato}\". Una volta che il programma finische il servizio passa dallo stato \"\\textit{active}\" direttamente a \"\\textit{dead}\". È utile per quelli script appunto \"\\textit{one-shot}\" che iniziano e si chiudono, ma comporta problematiche se avviamo un servizio che rimane in loop nel tempo (come server che girano in background).\n    \\item \\textbf{forking}: segue il comportamento classico dei servizi UNIX. Il processo viene avviato e cera un clone di se stesso (il \\textit{child process}) e lo avvia. Systemd considera il processo concluso solo quando viene chiuso il processo padre. (\\textit{A questa soluzione viene proposta come alternative notify}).\n    \\item \\textbf{dbus}: molto simile a \\textit{simple} ma systemd aspetta che il servizio acquisista un nome specifico sul bus di sistema \\textit{D-bus}. Non appena il nome viene registrato il servizio è considerato pronto e partito sul sistema.\n    \\item \\textbf{notify}: è il livello successivo al \\textit{exec}. Systemd avvia il programma ma non lo considera pronto fino a che non viene inviato dal processo una \\textit{notifica} $\\{READY=1\\}$ con il quale viene notificato systemd che il processo è partito e sta eseguendo. Per i servizi complessi è mlto importante, soprattutto per quei servizi che impiegano del tempo ad avviarsi. Questo servizio viene solitamente integrato con la libreria bash di \\textbf{sd\\_notify} o API equivalenti.\n    \\item \\textbf{notify-reload}: è identico a \\textit{notify}, ma aggiunge un protocollo speciale per la ricarica delle configurazioni. Invece di configurare un comando $ExecReload=$ systemd invia un segnale $\\{SIGHUP\\}$, il programma risponde con un $\\{RELOADING=1\\}$e parte col riavvio. Finito il riavvio come per il normale notify invia un $\\{READY=1\\}$.\n    \\item \\textbf{idle}: comportamento simile a \\textit{simple} ma c\'è un \\textit{ritardo artificiale} con cui systemd \"aspetta\" che tutti i job in coda vengano smaltiti prima di eseguire il programma vero e proprio.\n\\end{itemize}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\\end{document}\n',1,'Work');
INSERT INTO `LatexNotes` (id, title, content, userId, type) VALUES (4,'Relazione Cronologica Progetto Agent Template','\\documentclass{article}\n\\usepackage{graphicx} % Required for inserting images\n\\graphicspath{{C:/Users/sbattisti/AgoraDocumenti/media/Relazione\\_Grid\\_+\\_Supervisor\\_Tirocinio} {/Users/Simone/agora_documenti/media/Relazione\\_Grid\\_+\\_Supervisor\\_Tirocinio}}\n\\usepackage{geometry}\n\\usepackage{subcaption}\n\\geometry{a4paper, top=1 cm, bottom=1.5cm, left=1.5cm, right=2cm, bindingoffset=5mm}\n\\newenvironment{sistema}% \n{\\left\\lbrace\\begin{array}{@{}l@{}}}% \n{\\end{array}\\right.} \n\\usepackage{hyperref}\n\\usepackage{color}\n\\usepackage[T1]{fontenc}\n\\usepackage{amssymb}\n\\usepackage{amsmath}\n\\usepackage{textcomp}\n\\hypersetup{\n    colorlinks=true, \n    linktoc=all,     \n    linkcolor=black,  \n}\n\\DeclareMathSizes{11}{11}{11}{11}\n\\definecolor{dkgreen}{rgb}{0,0.6,0}\n\\definecolor{gray}{rgb}{0.5,0.5,0.5}\n\\definecolor{mauve}{rgb}{0.58,0,0.82}\n\\usepackage{xcolor}\n\\colorlet{keyword}{blue!100!black!80}\n\\colorlet{comment}{green!90!black!90}\n\n\\usepackage{listings}\n\n\\definecolor{codegreen}{rgb}{0,0.6,0}\n\\definecolor{codegray}{rgb}{0.5,0.5,0.5}\n\\definecolor{codepurple}{rgb}{0.58,0,0.82}\n\\definecolor{backcolour}{rgb}{0.95,0.95,0.92}\n\\definecolor{codeblue}{rgb}{0.0,0.0,0.8}\n\\definecolor{kotlinorange}{rgb}{0.95, 0.45, 0.13}\n\\definecolor{kotlinpurple}{rgb}{0.65, 0.28, 0.85}\n\n\\lstdefinestyle{JAVA}{\n    backgroundcolor=\\color{backcolour},   \n    commentstyle=\\color{codegreen},\n    keywordstyle=\\color{codeblue}\\bfseries,\n    numberstyle=\\tiny\\color{codegray},\n    stringstyle=\\color{codepurple},\n    basicstyle=\\ttfamily\\small,\n    breakatwhitespace=false,         \n    breaklines=true,                 \n    captionpos=b,                    \n    keepspaces=true,                 \n    numbers=left,                    \n    numbersep=5pt,                  \n    showspaces=false,                \n    showstringspaces=false,\n    showtabs=false,                  \n    tabsize=4,\n    language=Java\n}\n\n\\lstdefinestyle{BASH}{\n    backgroundcolor=\\color{black!90},\n    basicstyle=\\ttfamily\\small\\color{white},\n    commentstyle=\\color{gray},\n    keywordstyle=\\color{cyan},\n    numberstyle=\\tiny\\color{gray},\n    stringstyle=\\color{orange},\n    breaklines=true,\n    frame=single,\n    framerule=0pt,\n    language=bash,\n    morekeywords={sudo, chmod, chown, grep, awk, sed},\n    numbers=none\n}\n\n\\lstdefinestyle{KOTLIN}{\n    backgroundcolor=\\color{backcolour},   \n    commentstyle=\\color{codegreen},\n    keywordstyle=\\color{kotlinpurple}\\bfseries,\n    numberstyle=\\tiny\\color{codegray},\n    stringstyle=\\color{codegreen},\n    basicstyle=\\ttfamily\\small,\n    breakatwhitespace=false,         \n    breaklines=true,                 \n    captionpos=b,                    \n    keepspaces=true,                 \n    numbers=left,                    \n    numbersep=5pt,                  \n    showspaces=false,                \n    showstringspaces=false,\n    showtabs=false,                  \n    tabsize=4,\n    language=Java,\n    morekeywords={val, var, fun, suspend, coroutineScope, launch, it, when, data, object, init, typealias, internal, expect, actual, Boolean, String, Int},\n    deletekeywords={public, static} \n}\n\n\\title{Relazione Supervisor \\& Grid}\n\\author{Simone Battisti - Interactive Media SpA}\n\\date{}\n\n\\begin{document}\n\n\\maketitle\n\n\\section{Supervisor}\n\\subsection{Introduzione al Componente}\nIl componente \\textbf{com.imsl.supervisor} è definito come un \"\\textit{daemon di monitoraggio}\" per i vari componenti all\'interno delle macchine con ambiente MIND. Analizza tramite un servizio di \\textit{polling} lo stato di ogni componente in esecuzione. I servizi possono essere \\textbf{Service} o \\textbf{GridService} (se si tratta di servizi definiti dalla libreria \\textit{Grid}). \\\\\nFornisce una supervisione completa del sistema mind sulla macchina ospitante, fornendo allarmi in caso di failure dei componenti e, se necessario, fornisce servizi di riavvio di componenti.\n\n\\subsection{Funzionamento del Componente}\nPer avviare il file JAR del Supervisor viene richiesto un argomento. L\'argomento principale per avviare il componente è \"\\textit{server}\", il quale avvierà un \\textbf{server TCP/UDP} con parametri di porta e host custom. Una volta avviato il server viene avviato il servizio di \\textbf{SeverListener} che, come dice il nome, funge da \\textit{listener} per le chiamate che arrivano su quella porta.\\\\\nMentra il sistema è \"fermo\" è in uno stato definito \\textbf{listenLoop}. Quando arriva una richiesta al loop viene richiamata la classe \\textbf{ServerActionHndler} che gestisce le azioni arrivate dalla richiesta e le gestisce in modo asincrono sul sistema. Viene inanzitutto definito il tipo di richiesta che arriva, il quale può essere:\n\\begin{itemize}\n    \\item \\textbf{HearthBeatReq}: ping di controllo.\n    \\item \\textbf{ActionReq}: richiesta di eseguire un\'azione (\\textit{start, stop, restart,...}).\n    \\item \\textbf{StatusReq}: richiesta dello stato corrente di tutti i componenti in esecuzione sul sistema.\n    \\item \\textbf{SubscribeReq}: manda aggioranmenti in tempo reale sullo stato dei servizi.\n    \\item \\textbf{UnsubscribeReq}: smetti di mandare aggioranmenti in tempo reale sullo stato dei servizi.\n    \\item \\textbf{EventReportReq}: fornisce un report degli eventi degli ultimi n giorni.\n\\end{itemize}\n\n\\subsection{LifeCycle dei Componenti Grid Lato Supervisor}\nCome detto precedentemente il Supervisor può avviare \\textbf{Service} o \\textbf{GridService}. Il Service rappresenta un processo di sistema operativo standard, solitamente l\'avvio di componenti tramite script o systemD. I GridService invece rappresentano servzi definiti dalla \\textbf{libreria Grid}, la quale fornisce la possibilità di avviare dei server/servlet custom. Il Supervisor per capire quali componenti deve avviare e dove cercarli ha a disposizione il suo file di configurazione \\textit{settings.xml}, il quale fornisce una lista di tag \\textit{Service} o \\textit{GridService}, definiti dai parametri: \\textit{id, serviceName, pollCycle} (per Service) p \\textit{id, component, pollCycle, memoryLimit} (per GridService).\\\\\nPer i componenti Grid se ne occupa la classe \\textbf{ActionGridService} che con la funzione \\textbf{start()} fa partire il servizio di avvio di un GridService. Questo processo inanzitutto legge il grid\\_service.xml del componente, nel quale determina se il si tratta di un componente PHP o JAVA. Genera poi un comando tramite la funzione \\textbf{generateFullCommand(ESBData)} con il quale verrà avviato il componente grid.\\\\\nTutti i dati per generare il comando di avvio derivano dagli \\textbf{ESBData}, una classe che determina le informazioni di:\n\\begin{lstlisting}[style=KOTLIN]\ninternal data class ESBData(\n	val componentName: String,\n	val language: Language,\n	val command: String,\n	val workerNumber: Int,\n	val redirect: String,\n	val javaProperties: String,\n    val version2: Boolean = false\n)\n\\end{lstlisting}\nPrima di avviare il comando vengono fatti dei check precisi nella funzione \\textbf{start()} riguardo la \\textbf{version2} e se il processo deve essere un \\textbf{asyncStart} (avvio in modo asincrono o no). Viene poi generato un \\textbf{flagfile} nel quale verranno stampati gli status che il Supervisor andrà a leggere. Viene poi infine generato e avviato il comando per far partire il componente.\\\\\nPer la precisione il comando è un comando \\textbf{nohup} (\\textit{No-Hang-Up}), composto da:\n\\begin{itemize}\n    \\item Massimo heap utilizzabile solitamente a 2GB (\\textit{-Xmx2G}).\n    \\item Esecuzione del file JAR (\\textit{-jar}).\n    \\item Selezione dell\'output dei log su output.log.\n    \\item Definizione di stderror e stdout.\n    \\item Lancio del processo in background.\n\\end{itemize}\nInfine questo comando viene lanciato in \\textit{sh -c} (che permette di avviare il programma in una shell dedicata) e con davanti il \\textit{nuhup} per far si che il processo non vada mai giù.\\\\\nUna volta terminato il processo di avvio il componente è in stato \\textbf{OK}/\\textbf{FAILURE} e possiamo attuare varie azioni tramite Supervisor su di esso, come:\n\\begin{itemize}\n    \\item \\textbf{RESTART} [hot=true]: il processo viene ricreato completamente tramite un \\textit{kill -15} del processo.\n    \\item \\textbf{RESTART} [hot=false]: il processo non viene ricreato, ma solo stoppato e fatto ripartire (stop\\&start). \n    \\item \\textbf{STOP}: il processo viene stoppato con un \\textit{kill -15  $\\langle\\langle PID \\rangle\\rangle$}.\n    \\item \\textbf{KILL}: il processo viene eliminato con un \\textit{kill -9 $\\langle\\langle PID \\rangle\\rangle$}\n\\end{itemize}\nIl restart con hot a true o false viene definito nella configurazione XML del supervisor, il quale può definire un parametro \\textbf{hotRestart}. Questo viene poi parsato nella \\textbf{ElementConfiguration.createGridService()}, che genera un \\textbf{Element.GridService} il quale conterrà il parametro hotReload. Questo parametro viene poi letto dall\'\\textbf{ActionGridService.reastart()} (\\textit{riga 191}) che farà il kill -15 se true.\\\\\nIn questo schema viene descritto il modello di \\textbf{stop} di un componente Grid:\n\\begin{center}\n    \\includegraphics[width=0.8\\textwidth]{Diagramma di Sequenza Grid Supervisor.png}\n\\end{center}\n\n\\subsection{Avvio dei Componenti con JarWrapper}\nPer avviare un componente Grid il Supervisor può farlo utilizzando il JarWrapper (componette che permette di trattare i file JAR come dei normali avviabili) del componente. Vengono definiti due diversi comandi in base se il componente utilizza JarWrapper o no. Questa distinzione viene fatta direttamente nel \\textit{grid-service.xml} nel quale possiamo definire il campo \"\\textbf{JarFile}\" il quale conterrà il nome del componente. Questo nome definisce se è presente JarWrapper dalla sua estensione:\n\\begin{itemize}\n    \\item Se termina con \\textit{.jar} $\\rightarrow$ \\textbf{Non} c\'è JarWrapper.\n    \\item Se non termina con \\textit{.jar} $\\rightarrow$ C\'è JarWrapper.\n\\end{itemize}\nPer quanto riguarda il comando la modifica principale viene fatta nella disposizione dei vari parametri:\n\\begin{itemize}\n    \\item \\textbf{JAR Standard}: \n    \\begin{center}\n        \\begin{lstlisting}[style=BASH]\njava -Xmx2G -jar /usr/mindsmerecorder.jar ESB\n        \\end{lstlisting}\n    \\end{center}\n    Come si nota dal comando la definizione dei memory limit a 2 GB vengono definiti subito dopo aver richiamato Java e prima del \\textit{-jar}, dato che vogliamo che il limite di heap avvenga sul processo dell\'avviabile (se lo mettessimo dopo il \\textit{-jar} andrebbe sul processo di avvio del JAR). \n\n    \\item \\textbf{JarWrapper}:\n        \\begin{center}\n        \\begin{lstlisting}[style=BASH]\n/usr/mind ESB -- -Xmx1024M\n        \\end{lstlisting}\n    \\end{center}\n    Come definito prima possiamo avviare il componente come se fosse un vero e proprio avviabile, gli argomenti vengono separati rispetto al memory limit da $--$. In questo caso il memory limit viene posto alla fine, dato che il wrapper è il \\textit{processo principale}, non più Java. Il separatore definisce che gli argomenti sono specifici per il wrapper e non comandi per la shell.\n\\end{itemize}\n\n\n\\subsection{Monitor di Stato}\nDopo aver avviato il server TCP/UDP il Supervisor in parallelo avvia un servizio definito dalla classe \\textbf{ServerState}. Questo servizio genera una \\textbf{ScheduleThreadPool}, dove abbiamo gli \\textit{executor per ogni elemento} che fa partire il polling periodico per il monitoraggio dei componenti.\\\\\nViene generato un thread per ogni componente (\\textit{Element}) del sistema che andrà a monitorare lo specifico servizio, tutto in parallelo col resto del sistema e gli altri threads di monitor. Il thread avvia il proprio monitor ogni n millisecondi definiti dal \\textit{pollCycle} definito in configurazione del servizio. Questo servizio è praticamente invariato tra i servizi GridService e i normali Service.\\\\\nOvviamente al Supervisor per monitorare tutti i processi ha bisogno dei PID dei processi che stanno girando. Il Supervisor però non è a conoscenza di tutti i PID dei vari componenti, ma conosce i loro nomi. Grazie a ciò viene gestita una ricerca tramite \\textbf{pgrep} sui processi avviati e viene ritrovato il PID e lo stato del processo.\\\\\nQuesta ricerca avviene all\'interno della classe \\textbf{MonitorQueryProcess}, che estende l\'interfaccia MonitorQuery. Nello specifico all\'interno della funzione \\textbf{query()} viene fatta questa ricerca, passando per la funzione \\textbf{searchProcesses(processName: String)} la quale ritorna una lista di \\textit{ProcessInformation}, definiti così:\n\\begin{lstlisting}[style=KOTLIN]\nProcessInformation (\n    val pid: Int,\n    val fullName: String\n)\n\\end{lstlisting}\nPer ogni componente viene applicato questo processo e in base se la \\textit{size} della lista è:\n\\begin{itemize}\n    \\item 0 $\\rightarrow$ \\textit{FAILURE}: il componente non è stato avviato.\n    \\item $>$1 $\\rightarrow$ \\textit{OK}: il componente è avviato e sta funzionando correttamente.\n    \\item other $\\rightarrow$ \\textit{OK}: dato che la funzione \\textit{size} non può dare valori negativi, se ci sono più processi vuol dire che il processo è su ma più volte.\n\\end{itemize}\nPer i processi GRID il sistema è lo stesso, cambiano un solamente le classi prese in considerazione. Infatti esiste una classe apposita chiamata \\textbf{MonitorQueryGridService}, che implementa sempre la funzione \\textbf{query()}, che in questo caso richiama la funzione \\textbf{findGridServices(componentName: String)} che fa sempre un \\textbf{pgrep} di sistema, ma in questo caso filtra tramite una funzione \\textbf{isGridService(componentName: String, process: ProcessInformation,...)} la quale fa uno stretto controllo e conferma se:\n\\begin{itemize}\n    \\item è presente un FlagFile nel comando che sta eseguendo il processo.\n    \\item Se il nome del componente è uguale a quello cercato.\n    \\item Legge \\textit{/proc/$<PID>$/cmdline} per validare il comando.\n\\end{itemize}\nQuesto processo viene poi utilizzato per le funzioni di \\textit{start, restart e stop} dei servizi GRID. Nellp specifico vengono utilizzate le funzioni di \\textbf{find} per trovare la lista dei PID del/i processo/i che vogliamo riavviare, fermare o far partire. \\\\\nCome per l\'avvio dei componenti anche in questo caso ci sono 2 metodi di ricerca differnti per i processi avviati tramite JarWrapper o direttamente dal file JAR:\n\\begin{itemize}\n    \\item \\textbf{Con JarWrapper}\n    \\item \\textbf{Senza JarWrapper}\n\\end{itemize}\n\n\\subsection{Problematiche di Estrarre PID tramite pgrep}\nL\'utilizzo del pgrep per trovare i PID dei processi Grid può comportare diverse problematiche:\n\\begin{itemize}\n    \\item \\textbf{Falsi Positivi}: il pgrep potrebbe fare match su un processo non equivalente a quello cercato e quindi ritornare uno stato errato.\n    \\item \\textbf{Race Conditions}: il problema delle Race Condition indica la \"gara\" di un processo per arrivare ad una risorsa. Lo stesso problema possiamo averlo in questo caso, dove la risorsa è il PID del componente Grid, la quale può cambiare nel tempo. Il problema sta mentre il supervisor tenta di mandare il pgrep su un componente e questo intanto cambia di stato, cambia PID o termina.\n    \\item \\textbf{Processi Zombie}: un processo zombie è un processo che non termina quando finisce la propria esecuzione, cioè quando il padre di quel processo non richiama la syscall \\textit{wait()} sul figlio per farlo terminare. Questo comporta problemi al Supervisor, il quale leggerà uno stato di un processo che non esiste, o comunque in failure finché systemd non richiama il periodico \\textit{wait()} che va ad eliminare i processi zombie.\n    \\item \\textbf{Performance}: l\'invocazione del pgrep è molto pesante per i sistemi UNIX, soprattutto su sistemi molto ampli e con tanti processi avviati. L\'avvio di più subshells all\'interno del sistema, come fa il Supervisor con $sh -c$ per avviare i pgrep per la ricerca dei PID, comporta un rallentamento del sistema e incrementa le possibilità di blocco dato che stiamo chiudendo e riaprendo subshells di continuo ad ogni ciclo di polling.\n\\end{itemize}\n\n\n\n\\subsection{Schema Funzionamento Supervisor}\n\\begin{center}\n    \\includegraphics[width=1.05\\textwidth]{Diagramma Supervisor.png}\n\\end{center}\n\n\\pagebreak\n\n\\section{Grid}\n\\subsection{Introduzione alla Libreria}\nLa libreria Grid è un framework interno per la gestione custom delle chiamate API HTTP e SOAP. La libreria è fondata su 3 attori principali: \n\\begin{itemize}\n    \\item \\textbf{Service}: i processi indipendenti che implementano le funzionalitù richieste, notificando il proprio stato sul sistema.\n    \\item \\textbf{Server}: funge da registro centrale e raccoglie gli aggiornamenti di stato del Service. Integra un \\textit{Balancer} per la distrubuzione del carico ed un \\textit{Gateway} che permette l\'accesso all\'esterno tramite le chiamate HTTP.\n    \\item \\textbf{Client}: è colui che gestisce il processo interrogando il server tramite una \\textit{GridRequest} e si connette al Service per l\'esecuzione.\n\\end{itemize}\nIl Grid permette la generazione di un server custom tramite host e porta personalizzati. Inizialmente carica la propria configurazione XML e richiama nel main la funzione \\textbf{SystemService.server(GridServer, Options)}. Questa classe a sua volta chiama la funzione \\textbf{GridServlet.run() $\\rightarrow$ init()}, la quale definisce una serie di passaggi per avviare il \\textit{Servlet} dedicato per quel componente:\n\\begin{itemize}\n    \\item Setup del Logging \n    \\item Caricamento delle liberie definite in configurazione del Grid (\\textit{all\'interno del settings.xml del Grid sono presenti i path alle librerie utilizzate}).\n    \\item Viene avviato il \\textbf{GridServiceImplementation} e la sua funzione \\textbf{start()} la quale crea la vera e propria istanza del server.\n    \\item Genera i providers di chiamata HTTP per ogni configurazione.\n    \\item Avvia la macchian di servizio.\n    \\item Gestisce eventuali shutdown graceful tramite \\textbf{addShutdownHook()}.\n\\end{itemize}\n\n\\subsection{Lifecycle di un componente Grid}\nLa creazione di un GridServlet (classe estesa da HttpServlet) bisogna sovrascrivere alcuni parametri fondamentali, come:\n\\begin{itemize}\n    \\item \\textit{componentName}: strigna identificativa di un componente.\n    \\item \\textit{gridServiceConfiguration}: configurazione del servizio, che definisce i server di registry ai quali connettersi, i protocolli da utilizzare e le porte.\n    \\item \\textit{gridFunctions e httpFunctions}: delle mappe \\textbf{Map$<$String, Function$>$} che associano un endpoint di una funzioone ad una specifica funzione da risolvere.\n\\end{itemize}\nCome definito prima un servlet viene avviato tramite la funzione \\textbf{GridServlet.init()} e poi le chiamate vengono gestite tramite il \\textbf{GridServiceImplementation}.\\\\\nUn GridServlet viene distrutto tramite la funzione \\textbf{destroy()} che stoppa il servlet, impiega un timeout per finire tutte le pending calls e rilascia le risorse di rete.\\\\\nMentre il servlet è un wrapper del servizio le vere e proprie funzioni sono gestite dal Service, il quale filtra le chiamate sulla rete e valida le routes con i nomi delle gridFunctions definite in configurazione. \n\n\n\\subsection{Flagging degli Stati del Grid}\nIl server viene avviato in un thread apposito ed allo stesso tempo viene generato un altro thread parallelo per il \\textbf{monitoring del server}. Il servizio di monitoring si basa sull\'utilizzo dei \\textbf{flag} di sistema, definiti \\textbf{com.imsl.grid.flag}. Lo status di un server può essere:\n\\begin{itemize}\n    \\item \\textbf{INITIALIZING}\n    \\item \\textbf{ACTIVE}\n    \\item \\textbf{FAILED}\n    \\item \\textbf{STOPPING}\n    \\item \\textbf{STOPPED}\n\\end{itemize}\nQuesti flag vengono poi letti dal Supervisor tramite \\textit{polling} così che possa determinare lo stato dei vari servizi.\nIl flagging viene definito su 2 livelli. Il primo viene gestito dal \\textbf{ServicePusher}, il quale avvia un thread tdi background che ogni \\textit{1\' secondi} avvia un evento. Questo evento definisce un payload che contiene un id univoco, gli indirizzo locali del nodo, le funzioni esposte e lo \\textbf{status} attuale del servizio.\\\\\nLo stato può essere uno di quelli definiti prima (\\textit{INITIALIZING, ACTIVE, FAILED, STOPPING o STOPPED}) e viene sovrascritto per ogni evento. Quando abbiamo un cambio di sato il thread invia immediatamente un evento, \\textbf{scavalcando il delay di 10 secondi}, per velocizzare il rilevamento del cambio da parte del Supervisor.\\\\\nIl secondo livello invece determina un metodo di riconoscimento dello stato senza dover interrogare la rete. La JVM vien avviata passando la property \\textbf{com.imsl.grid.flag}, che contiene \\textbf{il path ad un file} che viene utilizzato come \\textbf{registro sincrono}.\\\\\nOgni volta che lo stato cambia il file viene sovrascritto con lo stato corrente del componente Grid.\n\n\\section{Interazione Grid-Supervisor}\n\\begin{center}\n    \\includegraphics[width=0.8\\textwidth]{GridAndSupervisor.png}\n\\end{center}\n\n\n\\section{Common}\n\\subsection{Forking dei Processi}\nIN un sistema UNIX quando un processo padre vuole creare un processo figlio, richiama la funzione di \\textbf{forking}, per la precisione la syscall $fork()$. QUando viene chiamta questa system call da un processo padre, viene generato nell\'albero dei processi un processo figlio \\textbf{identico al padre}. Il ritorno della funzione di forking è il PID del processo figlio appena creato. \\\\\nQuando viene creato il processo figlio il PID visto dal padre può essere:\n\\begin{itemize}\n  \\item \\textbf{0}: il forking è andato a buon fine.\n		\\item \\textbf{$<0$}: il forking non è andato a buon fine e c\'è stato un errore.\n		\\item \\textbf{$>0$}: il forking è andato a buon fine e il processo sta già aspettando il wait del padre perché ha già finito la sua funzione.\n\\end{itemize}\nGrazie a ciò viene generato un nuovo processo ed un nuovo PID, a cui poi verrà assegnato una diversa funzione tramite la syscall $exec()$. Quando avviamo questa funzione vienee caricato il file binario in memoria. Il processo padre ha ora il compito di avviare il figlio e aspettare tramite la funzione di $wait()$.\n\n\\subsection{Kill Signal}\nIn systemi UNIX i segnali sono una forma di \\textbf{forma di comunicazione fra processi}, definita come \\textbf{IPC} (\\textit{Inter Process Communication}), dove vengono generati dei messaggi asincroni che vengono inviati ad un processo dopo la verifica un determinato evento, sia lato utente sia lato sistema operativo.\\\\\nUno di questi segnali è il segnale di \\textbf{kill}, che \"\\textit{uccide}\" i processi terminando la loro esecuzione. In realtà il kill signal non serve solametne per uccidere un processo, ma per inviare segnali tra processi, il problema è che la maggior parte di questi segnali sono segnali di terminazione, da qui il nome.\\\\\nQuando avviamo un segnale, anche con un semplice $Ctrl+C$  o utilizzando il comando $kill$ mandiamo un segnale che il kernel recepisce immediatamente e viene gestito in 3 modi diversi:\n\\begin{itemize}\n  \\item \\textbf{Default Action}: eseguie l\'azione prevista sul sistema.\n		\\item \\textbf{Catch}: solitamente funzioni custom che intercettano i segnali (come ad esempio la possibilità di salvare un file prima di chiudere).\n		\\item \\textbf{Ignore}: il segnale viene ignorato.\n\\end{itemize}\nOgni segnale è identificato dal prefisso \\textbf{SIG} e poi un numero identificativo. Ce ne sono di vari tipi:\n\\begin{itemize}\n  \\item \\textit{SIGTERM - SIG15}: segnali predefiniti inviati dal comando kill base. Una richiesta moderata di terminazione di un processo non forzato.\n		\\item \\textbf{SIGKILL - SIG9}: segnali sempre per avviare un \\textit{kill -9}, che chiede al kernel di \\textbf{terminare forzatamente il processo}.\n		\\item \\textbf{SIGINT - SIG2}: come il segnale SIG15 ma per il processo corrente nella shell. È il segnale che viene mandato con un $Ctrl+C$.\n		\\item \\textbf{SIGSTOP - SIG19}: mette in pausa l\'esecizione del processo.\n		\\item \\textbf{SIGCONT - SIG18}: segnale di continuazione, dice ad un processo in pausa di continuare la propria esecuzione. \n\\end{itemize}\nPer avviare un kill signal semplciemente avviamo un $kill <PID>$, se il processo non viene terminato possiamo forzare lo stop con $kill -9 <PID>$\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\\end{document}\n',1,'Work');
INSERT INTO `LatexNotes` (id, title, content, userId, type) VALUES (5,'Appunti OS','\\documentclass{article}\n\\usepackage{graphicx} % Required for inserting images\n\\graphicspath{{/Users/simone/agora\\_documenti/media/Appunti\\_OS} {/home/simone/agora/media/Appunti\\_OS} {C:/Users/sbattisti/AgoraDocumenti/media/Appunti_OS}}\n\\usepackage{geometry}\n\\usepackage{subcaption}\n\\geometry{a4paper, top=1 cm, bottom=1.5cm, left=1.5cm, right=2cm, bindingoffset=5mm}\n\\newenvironment{sistema}% \n{\\left\\lbrace\\begin{array}{@{}l@{}}}% \n{\\end{array}\\right.} \n\\usepackage{hyperref}\n\\usepackage{color}\n\\usepackage{amssymb}\n\\usepackage{amsmath}\n\\usepackage{textcomp}\n\\hypersetup{\n    colorlinks=true, \n    linktoc=all,     \n    linkcolor=black,  \n}\n\\DeclareMathSizes{11}{11}{11}{11}\n\\definecolor{dkgreen}{rgb}{0,0.6,0}\n\\definecolor{gray}{rgb}{0.5,0.5,0.5}\n\\definecolor{mauve}{rgb}{0.58,0,0.82}\n\\usepackage{xcolor}\n\\colorlet{keyword}{blue!100!black!80}\n\\colorlet{comment}{green!90!black!90}\n\\usepackage{listings}\n\n\\lstdefinelanguage{C}{\n  morekeywords={\n    void, int, int64, while, for, boolean, bool, true, false\n  },\n  morecomment=[l]--\n}\n\\lstdefinestyle{C}{\n  language     = C,\n  basicstyle   = \\ttfamily,\n  keywordstyle = [1]\\color{keyword}\\bfseries,\n  keywordstyle = [2]\\color{STD}\\bfseries,\n  commentstyle = \\color{comment}\n}\n  \n\n\n\\title{Operating Systems Notes}\n\\author{Simone Battisti}\n\\date{2026-03-10}\n\n\\begin{document}\n\n\\maketitle\n\\tableofcontents\n\\pagebreak\n\n\\large\n\n\\section{Introduction}\n\\subsection{What\'s an Operating System Made Of?}\nA computer to run needs to be followed by some principal components, like: \\textbf{hardware}, \\textbf{operating system}, \\textbf{application programs} and \\textbf{users}.\\\\ \nThe hardware is composed by the \\textbf{CPU}, the \\textbf{memory} and I/O \\textbf{devices}. The \\textbf{application programs} instead defines the processes, compiler, etc that permits the system to run something that the user can see or not. We can also view the \\textbf{OS} like an union of hardware, software and data, defining a proper use for the user that can work on it doing the operation he needs to reach an objective.\\\\ \nThe user\'s view of an \\textbf{OS} can vary in base of the \\textbf{UI} he wants to use. The design of this \\textbf{UI} needs to afford the \\textbf{ease of use} mantaining also the importance of the \\textbf{resource utilization}, maintaining the system clear and flowless. \\\\ \nIn other cases the system can be a single computer withour \\textbf{UI}, that, when powered on, usually only shows a terminal where you can run commands, or access from \\textbf{other systems}/\\textbf{machines}.\\\\ \nOther cases provides WORKSTATIONSconnected to networks, where users have a uniquely defined resources that can access.\\\\ \nFrom the computer pov the oprating system  can be the program it needs to use to tolk and retrieve resources. The computer needs to manage trough the \\textbf{OS} a lot of parameter, like \\textbf{CPU} time, memory spacel, file storage, I/O, etc, defining noumerous problems generated by the use of resources in some ways or the use of too much operations. \\\\ \nAn \\textbf{OS} can be defined like a \\textbf{control program} that manages \\textbf{execution} of users programs to prevend errors and improper use of the computer.\\\\ \nAt the end we don\'t have a proper definition of what an \\textbf{OS} is, because a simple pov can defere the definition of it.\\\\ \nOne of the most known part of an \\textbf{OS} is the \\textbf{kernel}, a program that runs all the time we power on the system. Along with it we have different other programs like, \\textbf{system programs}, that manages the resources of a system and are always on during the use of the computer.\n\n\n\\subsection{Computer System Organization}\nA modern general pourpose computer system consists in \\textbf{one or more} CPUs and a number of device controllers connected to it. Each device controller is in charge of a specific role (memory, audio, display,...). The \\textbf{CPU} and the device controllers can execute in parallel, but they need to have a stricted resource access to avoid problems of overriding, racing problems,...\\\\ \nWhen a computer runs starts the initial program called \\textbf{bootstrap program}, stored in the computer hardware into the a \\textbf{read}-\\textbf{only memory} (\\textbf{ROM}), because if we modify it with an error the computer will not be able to start again, usually known as \\textbf{firmware}.\n\\begin{center}\n		\\includegraphics[width=0.5\\textwidth]{img/page7.png}\n\\end{center} \nThe bootstrap program has the main goal to \\textbf{localte the kernel and load it into memory}. Once it is loaded and is executing normally. the other system programs runs, starting the boot of the machine with \\textbf{system processes} (or \\textbf{system daemons}), that run the entire time the kernel is running. On \\textbf{unix} OSs these processes are stored on the \\textbf{init} process that starts all the other initial ones.\\\\ \nThe occurrence of an event on the \\textbf{OS} is usually called \\textbf{interrupt} that can be \\textbf{software} or \\textbf{hardware} interrupt in base of from where the event is called. Software interrupts usually call \\textbf{system calls} (or \\textbf{monitor calls}), special operations that can be runned only by them. \\\\ \nWhen a \\textbf{CPU} is interrupted it stops what it was doing previously and instantly move the processes interest on the location that calls the interrupt, that always contains the the starting adderess where the routine starts. Interruptions are a very imporitant part of the system and usually each type of system has his own interrupt mechanism, but several functions are in common. \\\\ \nInterrupts must be handled instantly, so the system defines \\textbf{table of pointers}, stored in low memory, that provide all the informations about the interrupt called (starting address, location of call, etc). This table is stored into an array called \\textbf{interrupt vector}, that stores the unique deviece address that points to the device and routine of the called interrupt.\n\n\n\\subsection{Storage Structure}\nThe \\textbf{CPI} can load instructions onluy fropm memory, so for the programs that runs need to store there. Most of the computers run their programs on a re-writable memory called \\textbf{main memory} or \\textbf{RAM}. Computers use other forms of memory as well, because \\textbf{ROM} cannot be modified, so we cannot save informations.\\\\ \nAll the memory are defined by an \\textbf{array of bytes}, where each byte has his own address. The interaction with this bytes is made with \\textbf{load} and \\textbf{store} instructions. The load instruction \\textbf{moves} A \\textbf{saved byte into} A \\textbf{register} in the \\textbf{CPU} and the store moves the contrnt of a register to main memory- Aside of loads and store instructions the \\textbf{CPU} automatically loads instruction from main memory for execution.\\\\ \nA typical instruction on a \\textbf{von neumann architecture} system, first fetches an istruction from meory and stores it in the \\textbf{instruction register}. The instruction is nexft decided and can retrieve from memory other instructions to complete the operation. \\\\\nIdeally we want toe programs anda data to be stored in main memory permanently, but we can\'t because of:\n\\begin{itemize}\n	\\item Main memory is usually small.\n	\\item Main memory is \\textbf{volatile}, so the device loses what is stored in it when is rebooted.\n\\end{itemize}\nAll the systems nowdays provides aside the \\textbf{RAM} a \\textbf{secondary memory}, usually a \\textbf{macnetic disk} that provide a bigger storage where all the programsa and adata are stored. Many programs uses the disk as both the source and the destination of a process.At the end we can define a \\textbf{storage hierarchy} of memory, where most we go down, most the space will be bigger and the speed of operation slower. \n\\begin{center}\n		\\includegraphics[width=0.5\\textwidth]{img/page11.png}\n\\end{center} \n\n\\subsection{I/O Structure}\nStorage is contained in a systema as a part of I/O. A large part of \\textbf{OS} code is defined on I/O management to improve the performance and the ease of use. In a general pourpose computer system the \\textbf{CPU} has multiple \\textbf{device controllers} connected to it with common bus, where each controller is defined for a single I/O device.\\\\ \nTypically an \\textbf{OS} has a \\textbf{device driver} for each device controller, that understands it and provides tto the rest of the \\textbf{OS} an interface to use his I/O device.\\\\ \nTo start n I/O operation the device driver loads the appropriate registers and selects the device controller. The device controller examines the content of the registers and determins what action to take. The controller next starts the transfer of data from thedevice to its \\textbf{local buffer}, that, once finished, informs the device driver that returns the control of the \\textbf{CPU} to the \\textbf{OS} that can perform the action connected to the I/O device.\\\\ \nThis form of management is caled \\textbf{interupt}-\\textbf{driven} I/O, that is usually fine when the device needs to move small amounts of data, but can be problematic when the amout of data grows.\\\\ \nTo solve this problem is used the \\textbf{direct memory access} (\\textbf{DMA}), that after settings up buffers, pointers and coutners for the I/O device, connects the device controller and trsnfers an entire block of data directly to or from its own buffer storae to memory. With this only one interruption is made on the \\textbf{CPU} that so only needs to boot the \\textbf{DMA} that will manage lonely these operations, while the \\textbf{CPU} manages all the others functions.\n\n\\subsection{Computer System Architecture}\nUntil more recent computer systems, a single \\textbf{CPU} where used. On a single processor system ther eis only \\textbf{one main cpu} capable of executing general pourpose instructions. \\\\ \nUsually singel processor systems has other special purpose processors for disks, keyboard or graphics controller. All of these special purpose processors run a limited instruction set and \\textbf{do not run user processes}. Sometimes they are managed by the \\textbf{OS} that sends informations and monitor their status. This arrangement relieves the main \\textbf{CPU} to be overhead of all the other devices scheduling.\n\n\\subsection{Multiprocessor Systems}\nIn the last years the \\textbf{multiprocessors systems} (or \\textit{parallel systems}) have begun to dominate the other devices. These systems has the possibility to support multiple operations at the same time with the use of multiple processors. Multiprocessor systems have several advantages:\n\\begin{itemize}\n  \\item \\textbf{Increase Throughput}: increasing the number of processors the speed-up ratio of the system is severely encreased. This means that we can run multiple programs at the same time using all the processors disposed by the machine. \n		\\item \\textbf{Economy of Scale}: multiprocessor systems can cost less than a single processor ones. If several programs operates on the same data it\'s cheaper to store those data on one disk that shares them to all the processes running on the other processors.\n		\\item \\textbf{Increased Reliability}: if functions can be distrubuted properly among several processors then the failure of one of them will not stop the entire system.		\n\\end{itemize}\nThe ability to continue providing services also one a \\textbf{warning mode} (there has been errors during the compilation of other processes) is cannded \\textbf{graceful degradation}. Other system has surclassed graceful degradation, pointing to \\textbf{fault tolerant} systems that can support failures of any single component and continue to run, but with a little more expensive maintaining cost.\\\\\nThe most of the nowadays systems define a \\textbf{Symmetric Multiprocessing} (\\textit{SMP}), where each processor can \\textbf{perform a task} in the OS. SMP means that all processors are \\textbf{peers} and there is no \\textit{boss-worker relationship}.\n\\begin{center}\n		\\includegraphics[width=0.5\\textwidth]{img/page15.png}\n\\end{center} \nMultiprocessing adds CPIs to encrease the computing power, this increments also the memory addressable in the system by the added registers for CPU. At the same time this method of computing can cause provlems to \\textit{memory access models}, so normally are implemented \\textbf{Uniform Memory Access} (\\textit{UMA}) or \\textbf{Non-Uniform Memory Access} (\\textit{NUMA}). UMA defines a solution where each access to the RAM from any CPU needs to take some amount of time equal for all CPUs, NUMA instead defines that each RAM access can take a different time to access.\\\\\nA recent trand in CPU is the use of \\textbf{multiple computing on a single CPU} using \\textbf{cores}. This method divide the processor in multiple cores that can be immagined as different CPUs running on a single one, permitting \\textbf{parallel computing} on a single CPU.\\\\\nMore recent are the \\textbf{Blade Servers} where we have multiple processors boards but different from the usual multiprocessor systems because each processor here boots \\textbf{independently} and \\textbf{runs his own OS}.\n\\begin{center}\n		\\includegraphics[width=0.5\\textwidth]{img/page16.png}\n\\end{center} \n\n\\subsection{Clustered Systems}\nAnother type of multiprocessor systems are \\textbf{Clustered Systems}. Clustered systems are different from the multiprocessor systems because they are considered \\textbf{loosely coupled}, where each node may be a siingel processor or a multicore system.\\\\\nClustering is usually used to provide \\textbf{high-availability service} (a service needs to continue to work in every state), generally obtained by adding \\textit{level of redoundancy} in the system. Clusters are divided in \\textbf{cluster nodes}, where each node can monitor the other ones and if the monitoring fails the full machine can take the full control of the system restarting the processes that are stucked or in failure.\\\\\nClustering can be \\textbf{asymmetric} or \\textbf{symmetric}:\n\\begin{itemize}\n  \\item \\textbf{Asymmetric Clystering}: one machine is in \\textit{hot-standby mode}, while the other is running the applications. The hot-standby one only monitors the system and active his functions only in system failure of the other one.\n		\\item \\textbf{Symmetric Clustering}: in this case we have 2 or more hosts that are running the applications monitoring each other. This strucutre is more efficient, but requires more than one application to be available to run.\n\\end{itemize}\nSince a cluster consist of several computer systems connected via \\textbf{network}, clusters can also provide \\textbf{high-performance computing} environments, involving the use of \\textbf{parallelization functions} that permits to divde a program into separate components that run in parallel on individual clusters.\\\\\nAlso in this case we can have problems of memory access, so the clustered systems implements the \\textbf{Distributed Lock Manager} (\\textit{DLM}) that manages to add \\textit{locks and access control} to the shared memory to avoid conflicts operations.\\\\\n\n\\subsection{Operating-System Structure}\nOne of the most important aspects of OSs is the use of \\textbf{multiprogramming} that increases the CPU usage to organize \\textbf{jobs}. The OS keeps several jobs in memory that needs to run simultaneously. The space in memory that contains this jobs is called \\textbf{Job Pool}, that consists in a list of processes that waits for their allcoation in memory to be runned.\\\\\nThe job of the OS is to maintain the list of jobs and monitor it, sending to the CPU the jobs that needs to be allocated into memory, like if there is a job that needs to wait for a data section in memory the OS needs to remove it from the currently run and compile a different job that can run instantly.\\\\\nMost of the systems implement a \\textbf{multitasking} process where the CPU runs multiple processes and \\textit{switch} between them. Multitasking needs an \\textbf{interactive} computer system, where an user can directly contact the OS with his peripherals and needs to have feedbacks from the OS instantly in a very little \\textbf{response time}.\\\\\nAll of this parallel functions in the systems needs to be \\textbf{scheduled} so the OS implements the \\textbf{CPU Scheduling} a program that when multiple processes are running can schedule them in different ways.\\\\\n\n\\subsection{Operating-System Operations}\nModern OSs are defined as \\textbf{Interrupt Driven Systems} where there system has not soem processes to run in a buffer, no I/O operations or events, but is \\textit{waiting for something to happen}. In these types of systems we use the \\textbf{traps} (or \\textit{exceptions}), software generated interrupts, where for each of them we allocate some code in memory to be runned into a process. The OS has the job also to identify errors on user programs that can interfere with system programs, avoiding the entire system block when the user is doing something on the machine.\\\\\nTo ensure proper execution of the OS the machine defines a distinction between \\textbf{user defined code} and \\textbf{operating system defined code}. The system separates the functions in \\textbf{user mode} and \\textbf{kernel mode} with the use of a bit called \\textbf{mode bit} defiend as: \\textit{kernel (0) and user (1)}.\\\\\nAt system boot time the hardware starts in kernel mode, loading all the functions that needs to boot the system deactivating the user mode to avoid problems and only at the end starts the dualism maintaining as main the user mode. Whenever an interruption arrives the system instantly switches to kernel mode. At the end of each operation the system \\textbf{always switches to user mode}.\\\\\nThe concept of modes can be extended when CPUs supports \\textbf{virtualization} where we will have another mode defined by the \\textbf{Virtualization Machine Manager} (\\textit{VMM}). In this mode the VMM has more privileges then a user mode but fewer then a kernel mode. \n\n\\subsection{Timer}\nTo avoid block of the systems for a big amount of time usually OSs defines \\textbf{timers} that is usually used to interrupt the computer after a specific period. The system usually implements a \\textbf{variable timer} where there is a fixed time that can be modified.\\\\\nIf a timer expires during user mode the control of the system passes to the kernel mode and tries to reboot the process and if not possible tries to kill it.\n\n\n\\section{Operating System Structures}\n\\subsection{Operating System Services}\nAn operating system provides an environment for the execution of programs, like certain services to program and to users of those programs. The specific sevices provided differ from one OS to another:\n\\begin{center}\n		\\includegraphics[width=0.5\\textwidth]{img/page56.png}\n\\end{center} \nThere are some services that are often in common between all OSs:\n\\begin{itemize}\n  \\item \\textbf{User interface}: all OSs provides an UI, that can be a \\textbf{CLI} (Command Line Interface), which provides user\'s a location where it can run commands/syscalls that modifies the processes running on CPU. Another type is the \\textbf{Batch interface} where the command and directives are usually files saved into memory that are loaded into CPU and run. Another and the most common is the \\textbf{GUI} (Graphical User Interface), where the system provides an \\textit{user friendly interface} that can be used from anyone.\n		\\item \\textbf{Program Execution}: the system must be able to load a program into memory and run that program.\n		\\item \\textbf{I/O Operations}: a running program may require I/O to run, that are not only the use of mouse and keyboard, but sometime the DVD reader. For security of the system usually the user cannot directly interfere with the usage of I/O.\n		\\item \\textbf{File System Manipulation}: program needs to use the file systems to run, and usually needs to create or delete some of them, so the OSs can provide \\textit{permissions management} when we install some programs on our system.\n		\\item \\textbf{Communication}: these can be implemented into a system using \\textit{shared memory} where two or more processors can provide data, or with the use of \\textit{message passing}, where packets of data are moved between processes by the OS.\n		\\item \\textbf{Error Detection}: Errors may occur in the CPU or other peripherals, so the system needs to \\textit{handle the errors} to make the OS not to crash during the user use. \n\\end{itemize}\nAnother set of OS functions exists not for helping the users, but to provide the OS a usability of resources and processes:\n\\begin{itemize}\n  \\item \\textbf{Resource Allocation}: CPU and users needs usually to allocate some data in memory during the use of an OS, so it needs to implement function that permits the allocation of memory avoiding errors and some. So the OS can implement some deirective like CPU-scheduling routines to speed up the CPU usage, or other routines to allcoate pointers, read USB peripherals and others.\n		\\item \\textbf{Accounting}: we want to keep track of all the resources on the PC, because some of them can be used fro accounting and billing or simply to accumulate usage statistics.\n		\\item \\textbf{Protection and Security}: the system needs to provide the user security on his data and resources, while giving security between different processes to avoid problems during the resource management, because the main risk is the lost of some data.\n\\end{itemize}\n\n\\subsection{User and Operating System Interface}\nSome operating systems include the command interpreter in the kernel, others like windows and UNIX tret the command interpreter as a special program. On systems with multiple command interpreters we can choose between them using the \\textbf{shells}. The main functions of the command interpreter is to get and eexecute \\textit{user-specific commands}.\\\\\nA second strategy for interfacing the user with the system is the use of \\textbf{GUI}, where the user has a user-firendly system to communicate to the programs with icons, folders and UI to make calls.\\\\\nAt the end both of them calls programs into shell to run commands on the system and provide feedback to the user. This list of commands are defiend \\textbf{shell scripts} that usually can be also provided manually by the user into the command-line into some systems only like UNIX or MacOS.\n\n\\subsection{System Calls}\nSystem calls provide an \\textit{interface to the user} to make calls on the system and run processes. These calls are generally coded in fast programming languages such as C++ or C. They can be named in differnt methods in base of the OS we are running.\\\\\nSystem calls are called every time we provide an action on the OS, actions like the movement of a mouse can implement different syscalls.\\\\\nThe syscalls are not machine language code, they can communicate with the OS with an \\textbf{API} (\\textit{Application Programming Interface}), that provides a list of functions available to an application prorgammer, including the parameter that needs to be passed to the functions. The most common API in this case is called \\textbf{libc}.\n\\begin{center}\n		\\includegraphics[width=0.5\\textwidth]{img/page63.png}\n\\end{center} \n\\begin{center}\n		\\includegraphics[width=0.5\\textwidth]{img/page64.png}\n\\end{center} \nFor the most of programming languages the run-time system provides a \\textbf{System Call Interface} that links the code to specific syscalls without the need of call them directly.\n\\begin{center}\n		\\includegraphics[width=0.5\\textwidth]{img/page65.png}\n\\end{center} \nThe caller of this system calls interface or in general of the syscalls doesn\'t need to know how these syscalls are implemented, but only what they produce and which parameters they need to produce their outputs.\\\\\nThere are 3 main methods to pass parameters to an OS:\n\\begin{itemize}\n  \\item \\textbf{Registers}: we load the parameters directly into the CPU registers where it can read and use them.  \n		\\item \\textbf{Block/Table}: we load the parameters into the blocks of data in memory. Parameters can be \\textit{pushed} into the \\textit{stack} by a program and \\textit{popped} out when the program has finished. \n		\\item \\textbf{Stack}: this approach is equal to the registers one, but in this case we don\'t have limits on the number of resources/parameters to be allocated. \n\\end{itemize}\n\n\\subsection{Types of System Calls}\nSyscalls are grouped into 6 \\textbf{major categories}:\n\\begin{itemize}\n  \\item \\textbf{Process Control}\n  \\item \\textbf{File Manipulation}\n  \\item \\textbf{Device Manipulation}\n  \\item \\textbf{Information Maintenance}\n  \\item \\textbf{Communications}\n  \\item \\textbf{Protection}\n\\end{itemize}\n\n\\subsubsection{Process Control}\nA running program needs to be able to end or stop a process currently running if it\'s blocking the system or causing error traps with \\textbf{end()} or \\textbf{abort()} syscalls.\\\\\nThe dump when a process blocks is written into memory system and usually \\textbf{debugged} finding out the bugs into the code.\\\\\nThe operating system in these circumstances the OS needs to transfare the control to the command interpreter, that reads the next command. Usually when we have a not-GUI system the command interpreter simply runs the next command and doesn\'t wait for a user command, in GUI systems there is usually a popup window alerting for the error. Sometimes the systems has some \\textbf{recovery functions} that needs to run after a main process is terminated.\\\\\nOther types of Process Control syscalls can be the \\textbf{load()} and \\textbf{execute()} another program, that allows command interpreter a program when the user, for example, clicks on it.\\\\\nWhen a program terminates the of the existing prorgam is saved, but when we have multiple programs running? In this case we can have the \\textbf{create\\_process()} or \\textbf{submit\\_job()} syscalls, that createa new job or process.\\\\\nWe also have timers syscalls like \\textbf{wait\\_time()} or \\textbf{wait\\_event()} syscalls that defines a process to wait for a specific time or event in the system to happen before run/continue.\\\\\nTo ensure integrity of data during these processes we can \\textbf{lock} shared data, to lock the data on a single process so that other programs cannot override them. This is made using the \\textbf{acquire\\_lock()} and \\textbf{release\\_lock()} syscalls.\\\\\nTo start a new process the shell uses the \\textbf{fork()} syscall. Then, selected the program is loaded into memory and executed with the \\textbf{exec()} syscall. Either the type of program the shell decides to run it and wait for the end of it, or run it \\textit{in background}. If the program is runned in background the user is free to run other programs on the CPU in parallel.\n\n\\subsubsection{File Management}\nPrograms usually needs to be able to \\textbf{create()} and \\textbf{delete()} files in memor, both of these syscalls require the name of the file and some other attributes. Once the file is created we can \\textbf{open()} it and so be able to \\textbf{read()}, \\textbf{write()} or \\textbf{reposition()} it.\\\\\nWe can also do operations to get information on this file with the \\textbf{get\\_file\\_attributes()} or \\textbf{set\\_file\\_attributes()}. Some OSs define also the syscalls for \\textbf{move()} or \\textbf{copy()} files and their content.\n\n\\subsubsection{Device Management}\nA process may need several resources available in registers, RAM or disks, this is made by the use of these syscalls. The various resources controleld by the OS can be provided by different syscalls in base of the model of the OS. If we are in a multi-user system first we need to \\textbf{request()} a resource and after we have finished we need to \\textbf{release()} it. Like file management syscalls we can also \\textbf{read()}, \\textbf{write()} or \\textbf{reposition()} these resources.\n\n\\subsubsection{Information Maintenance}\nSome syscalls can also provide simple information on the system. These can me the \\textbf{time()} or \\textbf{date()} syscall that returns the current date or time on the OS running. Another set of system calls can be useful when we want to make opearations on memory, like the \\textbf{dump()} syscalls that provides an useful trace list of each syscall that has been executed. \n\n\\subsubsection{Communication}\nThere are 2 common models of interprocess communication: the \\textbf{message passing} and the \\textbf{shared-memory}. In the message-passing model the information by the use of messages that are shared betwenn the n processes that needs to get that information. Messages can be exchanged \\textbf{directly} or \\textbf{indirectly} through a \\textbf{common mailbox}.\\\\\nEach process has a process name and this is translated to an \\textbf{unique identifier}. This is very useful to the message passing because eaasily with the syscalls \\textbf{get\\_hostid()} and \\textbf{get\\_processid()} we can provide the unique name the process that needs to receive the information. Most processes will be receive a connection are special-pourpose processes \\textbf{daemons}.\\\\\nIn shared-memory model instead processes usae a \\textbf{shared\\_memory\\_create()} and \\textbf{shared\\_memory\\_attach()} syscalls to create and gain access to regions of memory owned by other processes. There they can share informations by reading and writing them. The security of shared memory is defined  by the rule that \\textit{we need at least 2 processes in agreement if we want to remove a resource}.\n\n\\subsubsection{Protection}\nProtection provides a mechanism for controlling access to the resources on an OS. Typically syscalls provide protection with the \\textbf{set\\_permission()} and \\textbf{get\\_permission()} to manipulate the user\'s permissions, like with \\textbf{allow\\_user()} and \\textbf{deny\\_user()}.\n\n\\subsection{System Programs}\nSystem programs, also known as \\textbf{system utilities}, provide a convenient environment for program developement and execution. They can be divided into 3 main categories:\n\\begin{itemize}\n  \\item \\textbf{File management}: programs to create, delete, copy and modify files.\n		\\item \\textbf{Status information}: some programs to simply ask for current date, systems specs as free disk memory or number of users. Others more suffisticated for logging or print on terminal files content.\n		\\item \\textbf{Programming Language Support}: compilers, assemplrs and devuggers for the most used programming languages.\n		\\item \\textbf{Program loading and execution}: programs that provides compilation of programs to execute them or debugging programs for more complex applications.\n		\\item \\textbf{Communications}: programs that provide processes communication and share of data.\n		\\item \\textbf{Background service}: programs that can run in the background and constatly running on the machine also whan we are doing something else. They don\'t interfere with foreground programs. \n\\end{itemize}\nAlong with system programs most OSs asre supplied with programs that are useful to solve most common problems called \\textbf{application programs}, such as web browsers, database reading languag supports, compiulers and games.\n\n\n\\subsection{Operating-System Design and Implementation}\nThe first problem in designing a system is to define goals and specification. At the highst level the design will be aggected by the choice of hardware and type of system, beyond this highest level design the requirements are a lot hardware to specify. We can divide requirements into 2 main categories: \\textbf{user goals} and \\textbf{system goals}.\\\\\nThe users obviously wants some easyspecification and properties for their system, so the system needs to provide an \\textit{ease of use system goals} and requirements to provide this specification.\\\\\nThere is no short answare or solution to this problem, the operating system developement needs to be based on user ease of use and security at the same time, sowe need to find a middle way between the 2.\\\\\nAn important part of the system mechanisms is to follow a \\textbf{policy} on their \\textbf{mechanism}. Mechanism defines \\textit{how} the system needs to work, instead the policies defines \\textit{what} the system will follow to work.\\\\\nUsually this division is followed by the use of \\textbf{primitive building blocks} to maintain stable the mechanism if the policie changes.\\\\\nOnce an OS is designed must to be \\textbf{implemented}. Because operating systems are  a \\textbf{collection of programs} written by many peaple over a log period of time, it\'s difficult to make general statements about how they are implemented. Earely OSs where written in Assembly language, but nowadays ones are usually written the most in C or C++, but is common to see other programming languages implemented, like Python or PERL.\\\\\nThe advantage of writing the OS in an High Level Language is commonly the ease of refactor and reading, with also the possibility of implementing application programs easily (also usually written in high level langauages) and is more \\textbf{portable} because is written in a language understandable from the most of the compilers and computers.\\\\\nThe only disadvantages of building in high level is the fact of the \\textbf{reduced speed and computational cost}, because we have an extra layer of assembler before reach the machine language. \n\n\\subsection{Operating System Structure}\nModern OSs must be engeneered carefully beacause needs to be easy to modify and correct. A common approach is to partition the task into small components, or \\textit{modules}, rather then have a \\textbf{monolitic system}. Each of these modules should be a well-defined portion of the system. Many OSs do not have well defined structures because they started as a little OS and with the years grown too much to maintain the structure.\n\\begin{center}\n		\\includegraphics[width=0.5\\textwidth]{img/page78.png}\n\\end{center} \nWith a proper hardware support OS can eb broken into peaces that are smaller and more appropriate than those allowed by original OSs (UNIX or MS-DOS). A system can be made \\textit{modular} in different ways. The most common is the \\textbf{layered approach}, wher ethe OS is divieded into a number $N$ of layers (\\textit{levels}), the bottom layer (\\textit{layer0}) is the hardware and the last layer (\\textit{layerN}) is the UI. The structure is defined:\n\\begin{center}\n		\\includegraphics[width=0.5\\textwidth]{img/page80.png}\n\\end{center} \nThe ebst advantage of a layered system approach is the simplicity of debugging and contructions. The layers are selected so that each uses functions and services \\textbf{only of the lower-level layers}. The first level can be debugged without concern for the rest of the system, because it only use basic hardware functions. If an error is found during the debugging of assingle layer, the error will remain there  and not propagate to higher ot lower levels. The debug is very easy because we can literally start from the layer0 and pass to the next one when it\'s running and so on. A layer doesn\'t need to know how these operations are implemented, it needs only which operand use and which parameters pass to make them work. The major difficulty with the layered approach starts in designing it, because we need to create a \\textbf{well defined level structure} and choose properly which functions can be defined in a single layer.\\\\\nA final problem of layered system implementation is that they tend to be less efficient then other types, because when we make a call the information needs to be propagated between layers and this causes slowness of the system.\\\\\nAnother commopnly used approach is the \\textbf{microkernel} one, where the OS is structured by removing unessensials components from the kernel and implementing ghem as system and user level programs. Typically mikrokernel provide \\textbf{minimal process and memory management}, in addition to an \\textbf{easy communication}:\n\\begin{center}\n		\\includegraphics[width=0.5\\textwidth]{img/page81.png}\n\\end{center} \nThe main function of microkernels is to provide communication between client and program, usually using \\textbf{message passing}.\\\\\nOne benefit of microkernel systems is that it makes extending the OS easier, because all new services are added to user space and consequently doesn\'t need to recompile the kernel every time. Unfortunately the microkernel approach can suffer due to \\textbf{increased system-function overhead}.\\\\\nAnother commonly used approach is the usage of \\textbf{loadable kernel modules}. Here the kernel has a set of core components and links in additional su usual services using \\textbf{modules}. The idea of the design is for the kernel to provide core services while other services are implemented dynamically. The method is very similar to microkernel, but is more efficient because we don\'t need to use message passing in order to communicate.\n\\begin{center}\n		\\includegraphics[width=0.5\\textwidth]{img/page83.png}\n\\end{center} \nThe last type of system approach are the \\textbf{Hibrid Systems}, where er combine different structures defining a complete union of all the most common properties of each approaches viewed until now.\n\n\\subsection{Operating System Debugging}\nDebugging is the activity to find out errors in a system. Performance problems are considered \\textbf{bugs}, so debugging includes \\textbf{performance tuning}, removing usually \\textbf{bottlenecks}.\\\\\nIf a process fails most operating systems writes the error on a \\textbf{log file} to alert the system operators or users of the problem occurred. The OS can also take a \\textbf{core dump}m a capture of memory of the processes run that has recently runned to help during the debug.\\\\\nDebugging user level process code is a challange, because kernel debugging is very difficult because the usual size of the kernel, that is not so much helped from the user debugging systems. A failure in the kenel is called a \\textbf{crash}, that when occours is saved in a log file and instantly provides a \\textbf{crash dump}. OS debugging and process debugging frequetly is provided with different tools and techniques to help the most the debugging of the system.\\\\\nPerfomrance tuning is defined by the seeks of problems that can provide a bad performance of the system, this is made using loggers timelines and usually \\textbf{profielers} that analyze (where is possible) the code and finds out the usage of RAM and peripherals.\n\n\\subsection{Operating System Generation}\nWhen we ahve designed a system and implemented it we need to generate it. TO do this we need to configure it using a \\textbf{system generation SYSGEN}. This SYSGEN program downloads a CD-ROM or, most commonly, an \\textbf{ISO File} that contains all the inforamtions for the install of the OS on all machines.\\\\\nTo configure the OS we need to solve some important configuration questions, like:\n\\begin{itemize}\n  \\item \\textbf{What CPU will be used?}\n		\\item \\textbf{How will the boot disk formatted?}\n		\\item \\textbf{How much memory is available?}\n		\\item \\textbf{What devices are available?}\n		\\item \\textbf{What OS options are desired or what parameters needs to be implemented and instanced?}\n\\end{itemize}\n\n\\subsection{System Boot}\nAfter an OS isgenerated it must be made available for use by the hardware. The procedure of starting a computer by loading the kernel, this passage is called \\textbf{booting}. On most computer systems a small piece of code known as the \\textbf{boostrap program/loader} locates the kernel in disks and loades it into memory. Some computers has also a 2-step process in which a simple bootstrap loader fetches more boot programs from the disk with the kernel.\\\\\nWhen CPI receives a reset event (that happens on booting or rebooting the system) the \\textbf{Instruction Register} is loadede with a predefined location where all the programs will start and only now the \\textbf{bootstrap program} is loaded from the ROM memory (non-writable). The bootstrap program runs multiple tasks, to run usually dignostics, initialize registers and device controllers.\\\\\nThe problem here is that if we want to modify the boostrap routine into bootstrap program we need to access the ROM and \"violate\" it modifing the file. This problem is solved in some systems witthe use of \\textbf{EPROM} (\\textit{Erasable Programmable Read-Only Memory}), which can be writed with some permission and a specific command. \\\\ \nAll forms of ROM are also known as \\textbf{firmware}. The part of the firmware where the bootstrap routine files are saved is called \\textbf{boot block} and the OS only knows the address of these files. A program stored in ROM that is commonly used because is Open Source is \\textbf{GRUB} that also provides a shell to run commands a see logs.\\\\\nA PC disk usually has a partition dedicated to boot called \\textbf{boot disk} or \\textbf{system disk}.\n\n\n\\section{Processes}\n\\subsection{Process Concept}\nA batch system executes \\textbf{jobs}, or can run \\textbf{user programs} or \\textbf{task}, every single one of them is defined into a well defined structure that defines the compilation of some code. This entity is called a \\textbf{process}. A process is more than the only proram code, but contains it in the \\textbf{text section}, includes also the \\textbf{program counter} and the contents of the processor\'s registers. A process generally includes also a \\textbf{stack} which contains temporary data, a \\textbf{data section} that contains global variables and a \\textbf{heap} where to allocate memory.\\\\\nIs better to identify a difference between a \\textit{program} and a \\textit{process}, because the program is a \\textit{passive entity} that contains instructions stored in the disks in an \\textbf{executable file}, a process instead is an \\textit{active entity} that specifies which code needs to be executed, when, which resources the code needs and which is the next code to execute.\\\\\nA program at the end is an \\textbf{union of processes} that run independently on the machine, so that are defined in a separate execution sequence.\\\\\nProcesses can have different states:\n\\begin{itemize}\n  \\item \\textbf{New}: process nearely created.\n		\\item \\textbf{Running}: instruction is being executed.\n		\\item \\textbf{Waiting}: the process is waiting for some event to occur to end his function.\n		\\item \\textbf{Ready}: the process is waiting to be assigned toi a processor.\n		\\item \\textbf{Terminted}: the process has finished his execution function.\n\\end{itemize}\nTo each process is assigned a \\textbf{Process Control Block} or \\textbf{PCB}, also called \\textbf{task control block}. PCBs contains differnt informations about the process:\n\\begin{center}\n		\\includegraphics[width=0.5\\textwidth]{img/page108.png}\n\\end{center}\n\\begin{itemize}\n  \\item Process state: state mentioned before.\n		\\item Program Counter (PC): indicates the address of the next task to execute.\n		\\item CPU Registers: information about the registers in the CPU that the process will use.\n		\\item CPU-Scheduling Information: process priority, a value points to scheduling queues.\n		\\item Memory Management Information: all the information about items in registers or in disk segment the process can access.\n		\\item Accounting Information: amount of CPU used in real time, time limits, list of opened files.\n		\\item I/O Status Information: status of the I/O devices connected to the CPU.\n\\end{itemize}\nMost modern OSs have extended the process concept to allow a process have \\textbf{multiple threads}. Each thread represent the \\textbf{execution of a processm not the process itself}. This possiblitiy can be happen only when we develop on a \\textbf{multicore system} where multiple threads can run in parallel. \n\n\\subsection{Process Scheduling}\nThe objective of multiprogrammin is to have some process runnin at all time maximizing the CPU utilizatio. This method instead can cause some problems to the system when the processes needs to write or read resources in the system at the same time. For this problem the CPU implements nativelya \\textbf{process scheduler} that selects the available process for executiuon and defines a queue.\\\\\nWhen a process enters in the system is puttted into a \\textbf{job queue} tha contains all the processes of the system. The processes are residing in main memory and are well defined yet. Next when the processes defines a status of Ready or Waiting are kept in a list called \\textbf{ready queue}. The ready queue has a header that consist of a pointer to the processes contained\' PCBs, where each one ofthem contains a pointer to the next one etc. When a process is allocated the CPU executes for a while until is interrupted from another process or finishes. The system also includes other queues for processes, like the \\textbf{device queue} that stores all the processes that are waining for a particular I/O operation to run. Each device has its own device queue:\n\\begin{center}\n		\\includegraphics[width=0.5\\textwidth]{img/page111.png}\n\\end{center}\nA common representation of process scheduling is the \\textbf{queueing diagram}:\n\\begin{center}\n		\\includegraphics[width=0.5\\textwidth]{img/page112.png}\n\\end{center}\nIn this diagream the rectangular box represnets a queue. There are represented 2 types of queues: the \\textit{ready queue} and a set of \\textit{deviece queues}.\\\\\nA new process is initialluy put into theready queue, it waits until is selected for execution (\\textbf{dispatched}), once is allocated the CPU and is executing a serie of events is executed:\n\\begin{itemize}\n  \\item The process couls issue an I/O request and then be placed in I/O queue.\n		\\item The process couldcreate a new child process and wait for it to finish.\n		\\item The process coulf be removed from the CPU by an interruption and put back in ready queue.\n\\end{itemize}\nA process goeas though various queues during its lifetime and this selection is made by the \\textbf{scheduler}. There are 2 main types of schedulers: the \\textbf{long-term scheduler} or \\textbf{job scheduler} selects processes from his pool and loads them into memory for execution, and the \\textbf{short-term scheduler} or \\textbf{CPU scheduler} that selects the process that will be allocated from the ones that are in a ready state and can execute immediately.\\\\\nThe primary distinction between these 2 is the fact that the short term scheduler is faster than a long term one, but a process can simply be in a ready state, execute for a few milliseconds and then go into a waiting state for an I/O operation.\\\\\nThe long term instead is executed fewer times then a short term, controlling the \\textbf{degree of multiprogramming} (the \\textit{number of processes in memory}), but it takes more time to execute all the processes because of the longer interval between executions, so takes more time to choose which process run.\\\\\nSome OSs defines a \\textbf{middle-term scheduler}, where the main property here is the fact tha tremoving some processes is usually very convinient, reducing so the degree of multiprogramming. These processes will be reimplemented into memory and restarts their execution \\textbf{from where they has been stopped}. This scheme is called \\textbf{swapping} and is only possible in medium-term schedulers.\\\\\nOS can switch constantly the task that is currently in exexcution into the CPU, this is defined as the \\textbf{context switch}, when a process is interrupted and the CPU needs to run another one. The context is represented buy the PCB of the process that has interrupted the current one, that will give the CPU the information on how to run the process. The last process is so interrupted and his \\textbf{state} is saved into memory, so it can restart from where it has leaved the execution with a \\textbf{state restore}.\\\\\nSwitching speeds various tasks of the OS, that will run other processes, usually faster than previous ones, speeding out the most common operation to make to the user the most performant system to use. \n\n\\subsection{Operations on Processes}\nDuring the course of execution a process may create \\textbf{several new processes}. The one who is careating the processes is called a \\textbf{parent process} and the one that is created will be the \\textbf{child process}, that can also have childs and so on. This conformation defines a \\textbf{tree of processes}.\\\\\nEach process is identified by his \\textbf{PID} (\\textit{Process Identifier}) , which typically is an integer number, so that we can identify the processes during execution of programs. \n\\begin{center}\n		\\includegraphics[width=0.5\\textwidth]{img/page116.png}\n\\end{center}\nAs we can see the first process is the \\textbf{init} one, that usually has the PID = 1, then we have all of his childs. In general when a process creates a child process will needs certain resources (\\textit{CPU time, memory, files, I/O devices connected}. The child process will obtain the resource directly from the OS or, most commonly, \\textbf{gets the parent resources}. The parrent needs to partition its resources to the childrens.\\\\\nWhen a parent creates a child process:\n\\begin{itemize}\n  \\item \\textbf{The parent continues to execute with the children in parallel}\n		\\item \\textbf{The parent waits for the child process to finish to finish itself} (\\textit{most common})\n\\end{itemize}\nThere are also 2 address-space possibilities fornew processes;\n\\begin{itemize}\n  \\item The child process is a \\textbf{duplicate of the parent process}.\n		\\item The child process has a \\textbf{new program loaded into it}.\n\\end{itemize} \nA new process is created with a \\textbf{fork()} syscall that generartes a process identical to the parent. This function returns the PID of the child process that \\textbf{needs to be 0}, if is below zero we have an error, if is greater than 0 the process has returned to the parent. Then we run the \\textbf{exec()} syscall that loads the binary file into memory and starts the execution of the child proces. The parent process when the childrens run can create other child processes, or use the \\textbf{wait()} function to wait for the children to finish to finish himself and be deleted from the tree.\\\\\nHere is an example of \\textbf{process creation} in C:\n\\begin{center}\n		\\includegraphics[width=0.5\\textwidth]{img/page118.png}\n\\end{center}\nWhen a process finish his execution it calls the \\textbf{exit()} function, the parent stops the wait() syscall and executes/finishes itself.\\\\\nWhen a process terminates and uses the exit syscall the OS will delete it from the tree, all the resources are free and deallocated. \nA parent can also interrupt the executiuon of one of its childrens for a variety of reasons, such as:\n\\begin{itemize}\n  \\item The child exceeded its usage of a resource allocated.\n		\\item The task assigned to the child is no longer required.\n		\\item The parent is exiting and the OS does not allow a child to run if the parent is exited.\n\\end{itemize}\nSome system do not allow a child to exist if its parent has termianted, in this case the system terminates the children with a \\textbf{cascading termiantion} when the father is terminated.\\\\\nA proces that has been terminated but whose parent has not called a wait() syscall yet is called as a \\textbf{zombie process} and remains in this status until the father calls the wait. If the parent doesn\'t invoke the wait and instead terminates, the process is called \\textbf{orphan process}. To resolve the orphan problem the init process (parent of all other processes) \\textbf{periodically calls a wait() syscall} on the whole tree to clean it up.\n\n\\subsection{Interprocess Communication}\nProcesses executing concurrently in the OS may be either independent processes or \\textbf{cooperating processes}. A process is defined independent if it cannot affect or be affected by other processes executing, the cooperating one is the reverse.\\\\\nThere are several reason on the because a process needs other ones:\n\\begin{itemize}\n  \\item \\textbf{Inforamtion Sharing}: share status of the process running to other processes.\n		\\item \\textbf{Computational Speedup}: 2 processes running in parallel on different resources can arrive to finish faster then a single one.\n		\\item \\textbf{Modularity}: moduling the system in different processes is usually more careful and useful during debugging.\n		\\item \\textbf{Convenience}: individual work is usually slower then cooperation work compiling in parallel.\n\\end{itemize}\nCooperation between processes needs an \\textbf{Interprocess Communication} mechanism (\\textbf{IPC}). There are 2 most known IPCs:\n\\begin{itemize}\n  \\item \\textbf{Shared Memory}: in a shared memory mode the processes can access to a space in memory where they can share resources or information rapidly.\n		\\item \\textbf{Message Passing}: the processes here can send between them some messages that contains resources or informations.\n\\end{itemize}\nBoth of these methods are usually \\textbf{implemented in parallel} on the OS. Shared memory is usually faster than message passing, because the send of message is done with a syscall that uses CPU and takes time. In shared memory insted we have a single syscall done when the process needs to connect to the space in memory shared, then once the connection is established the process doesn\'t need other syscalls to run.\\\\\n\n\\subsubsection{Shared Memory Systems}\nThe concept on processes intercommunication can be defined in a simple \\textit{producer-consumer} problem. The \\textbf{producer process} produce some resources and the \\textbf{consumer process} can retrieve and use them.\\\\\nOne solution is the shared memory system wher ethe producer and the consumer have access to a partition of memory where the produce can load his resources and the consumer can get them. This space of memory is defined by \\textbf{buffers}. There are 2 main types of buffers: \\textbf{unbounded buffer} that has no limits, where the consumer needs to wait the producer to put into the buffer its resources. Then we have the \\textbf{bounded buffer}, that has a fixed size and the consumer must wait for the buffer to be empty to search and the producer needs to wait to input other resources when the buffer is full.\\\\\nThe shared buffer is implemented as a \\textbf{cyrcular array} with 2 logical pointers to the \\textit{out} and the \\textit{in}.\\\\\n\n\\subsubsection{Message-Passing Systems}\nMessage passing provides a system whre the process can communicate  and synchronize their actions withoru sharing the same address space. The message passing is defined with 2 main syscalls:\n\\begin{center}\n		\\textbf{send(}\\textit{message}\\textbf{)} - \\textbf{receive(}\\textit{message}\\textbf{)}\n\\end{center}\nIf 2 processes wants to communicate they need to define a \\textbf{comunicatio link} where exchange informations. This communication can be:\n\\begin{itemize}\n  \\item \\textbf{\\textit{Direct or Indirect communication}}: direct communication defines a system where each process that wants to communicated must explicitlyu name the recepient or sender of the communication in his send and receive syscalls:\n\\begin{center}\nsend(P, message) --sends a message to process P\\\\	\nreceive(Q, message) --receives a message from process Q\\\\				\n\\end{center}\nThe communication link in this case needs to be established autmatically between the processes, needs to be associated with 2 processes only and between those 2 processes needs to exists one link only. The scheme above represents a \\textit{symmetry} style of communication, but it can be also \\textit{asymmetric} whith the receive functions that takes the id of the communicating process. The indirect communication instead defines an exchange where we have a \\textbf{central mailbox} shared between 2 or more processes where they can exchange informations. In this canse the sendand receive syscalls will be:\n\\begin{center}\nsend(A, message) --sends a message to mailbox A\\\\	\nreceive(A, message) --receives a message from mailbox A\\\\				\n\\end{center}\nThe problem here is which process can receive a resource when we sand a resoruce from another process. In this case we can choose between different methods: the link can associates only 2 processes per mailbox, in the mailbox only one process at the time can execute the receive() or allor whe system to arbitrary assign the resource to the processes calling the syscall.\n\n		\\item \\textbf{\\textit{Synchronus or Asynchronus communication}}: called also \\textit{blocking} and \\textit{non blocking} communication, we can have different types of the send and receive syscalls in this case:\n\\begin{itemize}\n  \\item \\textbf{Blocking send}: the sending process is blocked unti the message is received by the receiving process or mailbox.\n		\\item \\textbf{Nonblocking send}: the sending process sends message and resumes operation\n		\\item \\textbf{Blocking receive}: the receiver blocks until a message is availavle.\n		\\item \\textbf{Nonblocking receive}: the receiver retrieve a valid message or a null.\n\\end{itemize}\n\n\n		\\item \\textbf{\\textit{Automatic or Explicit buffering}}: the easiest way of message passing because in this case we have a temporary queue created with 3 main types:\n\\begin{itemize}\n	\\item \\textit{Zero Capacity}: the queue has a maximum length of 0 so the link cannot wait for messages in the buffer but needs to receive them immediately.\n		\\item \\textit{Boudned Capacity}: limited queue of messages where processes can search for their ones.\n		\\item \\textit{Unbounded Capacity}: unlimited queue.\n\\end{itemize}\n\\end{itemize}\n\n\\subsection{Client Server Systems Communication}\nClient server systems usually communicates with \\textbf{sockets}. A socket is identified with an IP address concatenated with a port number, and are in general used in client server applications to run on HTTP services.\\\\\nWne a client process initiates a request for connection is assigned to it a port number by the host, that combined with its IP address defines the \\textit{address of the process} (ex: 123.01.123.343:8080):\n\\begin{center}\n		\\includegraphics[width=0.5\\textwidth]{img/page137.png}\n\\end{center}\nThe connection between sockets can be with \\textbf{TCP} module or \\textbf{UDP} module.\\\\\nThe server begins \"\\textit{listening}\" on the port chose and with the \\textbf{accept()} syscall can accept requests from the client.\\\\\nThe 127.0.0.1 is called\\textbf{loopback address} because defines a server that runs in \\textbf{localhost}, so on the system onluy and is reachable oly from the system itself.\\\\\nAnother type of communication in client server is the use of \\textbf{pipes}. These are \"\\textit{conduits}\" between the processes where the informations are shared.\\\\\nPipes can be \\textbf{ordinary pipes} that allows 2 processes to communicate in a standard method, where a producer can \\textbf{write-end} on the pipe and a consumer can \\textbf{read-end} from the pipe:\n\\begin{center}\n		\\includegraphics[width=0.5\\textwidth]{img/page143.png}\n\\end{center}\nOrdinary pipes \\textbf{are not acessible from outside} and are typically used to create communication between child and parent processes and is created on the fork() operation.\\\\\nPipes can be also \\textbf{named pipes}. In this case named pipes provide a much more powerful communication tool with a \\textbf{bidirectional communication} and \\textbf{no parent-child relation required}. Named pipes are essentially FIFOs createdwith a \\textbf{mkfifo()} syscall and manipulated with the ordinary open(), read() and write() syscalls.\n\n\n\\section{Threads}\n\\subsection{Introduction}\nA system can define on his architecture the \\textbf{threads}. Threads defines the \\textbf{execution} of a process and can run on a single core of our CPU.\\\\\nA system can be \\textbf{single-threated} or \\textbf{multi-threated}:\n\\begin{center}\n	\\includegraphics[width=0.5\\textwidth]{img/page164.png}\n\\end{center}\nThreads define on a system various important features like \\textbf{responsiveness} (don\'t need to wait for an action to complete before doing something), \\textbf{resource sharing} (more methods of resourse sharing than processes), \\textbf{economy} (because threads share resources the problem of allocating memory is passed) and \\textbf{scalability} (threads can run in parallel on different \\textit{cores}).\\\\\nThe most common use of threads is during the client-server communication where when we launch a request to the server it can define a thread on the system that runs in parallel while the server continuously checkes for other requests:\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page165.png}\n\\end{center}\n\n\\subsection{Multicore Programming}\nAll the system that can define a structure on parallel computing needs to run on a \\textbf{multicore/multiprocessor system}, where a mechanism provices a more efficient use of the cores of a CPU. In this systems the keyword is \\textbf{concurrency}, the process where more than one thread can run in parallel on the system.\\\\\nFirstly is better to do a distinction between \\textit{parallelism} and \\textit{concurrency}. A system is parallel if can compute more than one task at the same time. In contrast a concurrent system can perform task in parallel and at the same time permits to the processes to \\textit{make progress}.\\\\\nThe multi thread computing defines its performance with the \\textbf{Amdhal Law}:\n\\begin{center}\n	$speedup \\leq \\frac{1}{S+\\frac{(1-S)}{N}}$\n\\end{center}\nThis formula defines the performance of a syustem with N processing core on a S portion of the application. As we can see the Amdhal law defines a logic where, instead of what can be thought, the more threads and parallel processes we have doesn\'t enhance the performance of the system, but decrease it. This defines that on a system we need to find the right number of threads to stabilize the performance.\\\\\nProgramming with threads is not easy as talking about them. In general there are 5 areas of challenge in multicore system programming:\n\\begin{itemize}\n  \\item \\textbf{Identify Task}: examine all the application to find areas that can run in different parts of the CPU at the same time (so find out the areas that doesn\'t require one the other because the resource will be runned in parallel).\n		\\item \\textbf{Balance}: while deciding which task can run in parallel, the developer needs to find out if the task can run the same in parallel or in single.\n		\\item \\textbf{Data Splitting}: as the application is divided into differnt tashs the data accessed and manipulated from these tasks needs to be divided at the same.\n		\\item \\textbf{Testing and Debugging}: testing and debugging in parallel can be very difficult because we never know which task is running.\n\\end{itemize}\n\n\\subsection{Types of Parallelism}\nWe can define 2 main typs of parallelism:\n\\begin{itemize}\n  \\item \\textbf{Data parallelism}: this type of paralleluis focuses on distributing subsets of the same data across multiple computing cores, performing the same operation foreach core. Each core defines the same task at the same time in parallel but with different usage of resources.\n		\\item \\textbf{Task Parallelism}: the data are distributes to tasks in base of which resources they need. Each process in this case defines a unique operation.  \n\\end{itemize}\nFoundamentally data pareallelism involves the distribution of data across muiltiple cores, while task parallelism involves the distribution of  data across multiple cores.\n\n\\subsection{Multithreading Models}\nThreads also are not the same each time. We can divide them into \\textbf{user threads} and \\textbf{kernel threads}. User threads are supported above the kernela anda define all the actions that don\'s involve the kernel at all. Kernel threads instead defines all the functions that needs kernel support and are created by the OS only.\\\\\nThere needs to be a relationship between the kernel threads and the user threads, so we can define the: \\textit{maky-to-one model}, the \\textit{one-to-one model} and \\textit{meny-to-many model}:\n\\begin{itemize}\n  \\item \\textbf{Many-to-One Model}: this model maps one to one the user level threads to one kernel thread. However the system will block if a single thread is blocked. An because we have only one thread at the time to run we cannot perform a multithreaded system. \n\\begin{center}\n		\\includegraphics[width=0.5\\linewidth]{img/page169.png}\n\\end{center}\n\n		\\item \\textbf{One-to-One Model}: the one to one model the maps each thread to a kernel thread, providing more concurrency into the system and \\textit{allowing multithreading}. The only drawback of this model is the fact that creating a user threads requires creating a corrsiponding kernel thread each time.\n\n		\\item \\textbf{Many-to-Many Model}: many to many model defines many kernel threads in base of other user threads, but not as one to one, it creates m kernel threads from n user threads, where $<>m$. Many to many model suffers from neither of the other defined problems, because it allows the multithreading and doesn\'t block the system to create kernel threads. Many-to-many model can be named also \\textbf{two-level model}.\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page171.png}\n\\end{center}\n\\end{itemize}\n\n\\subsection{Thread Libraries}\nA threads library provide to the developer an API to create, delete and modify threads in an easy way. We can have 2 different approcaches: the first one is to provide a library entirealy in an \\textit{user space} wit hno kernel support, all code and data structures only exists into user space and never touches kernel threads.\\\\\nThe second approach is to implement a \\textit{kernel-level library} supported directly from the OS. In this case the ocde and data structures are defined into kernel space and managed directly by the OS.\\\\\nThere are 3 main threads libraries: \\textbf{POSIX PThreads, Windows Thread Library and Java}.\\\\\nPthreads is a threads extension to the POSIX standard and can \\textit{provide user and kernel threads} management. Windows Thread library is a \\textit{kernel-level library} provided only on Windows systems. Java Thread API defines the allocation of thread and their managemnt directly from the Java code.\\\\\nPthread is the most used and the one that we will use in the whole course. It defines a \\textbf{specification} for thread behavior, not an \\textbf{implementation}. We can use the libarary directly in C and C++ with an include:\n\\begin{lstlisting}[style=C]\n#include <pthread.h>\n#include <stdio.h>\n\n\nint sum; //data shared by the threads\nvoid *runner(void *param); //threads will call this function\n\nint main(int argc, char *argv[]){\n    pthread_t tid; //thread identifier\n    pthread_attr_t attr; //set of attributes to the thread\n\n\n    pthread_attr_init(&attr); //get the default attributres for a thread\n    pthrea_create(&tid, &attr, runner, argv[1]); //create the thread\n    pthread_join(tid, NULL); //wait for the thread to exit\n\n    cout << \"sum=\" << sum << endl;	\n	\n}\n\nvoid *runner(void *param)\n{\n    int i, upper = atoi(param)\n    sum = 0;\n    for (i = 1; i <= upper; i++){\n        sum += i;\n    }\n    pthread exit(0);	\n}\n\\end{lstlisting} \nAs we can see in the code we run a thread tu run the \\textit{runner()} function. We define the thread and then give it the normal initial attributes provided from the Pthread library. With the \\textit{pthread\\_join} funciton we run the thread and we wait for a \\textit{pthread\\_exit} function.\n\n\\subsection{Implicit Threading}\nNowadays is more useful to separate threading from the application, like in Java create a Driver class that functions as controller of the threads.\\\\\nThe problems with theads can be various, the time we need to create a thread, the fact that thread stop existing after the execution, too much threads can saturate the CPU memory and others. One solution to the problem is to use a \\textbf{thread pool}. In general a threadpool creates a number of threads at startup and places them into a \\textit{pool} where they sit and wait for a work. When the system needs a thread it takes out one from the pool and after the thread completes its work it goes back to the pool in waiting state. If the pool doesn\'t have threads left the system waits for a thread to be free and gets it.\\\\\nThread pools offer these benefits to the system:\n\\begin{itemize}\n  \\item Servicing a request with an existing thread is faster than create a new one each time.\n		\\item Thread pool limits the number of threads so we cannot sature the CPU.\n		\\item Thread pool separate tasks on the system.\n\\end{itemize}\nMore sophisticated the thread pool architecture is, more the system is performant. \\\\ \nAnother way to resolve the thread problems is the use of \\textbf{OpemMP}, a set of compiler directives, like an API, that identifies \\textbf{parallel regions} as blocks of code that may run in parallel. We can define the regions directly in pure C:\n\\begin{lstlisting}[style=C]\n#include <omp.h>\n#include <stdio.h>\n\nint main(int argc, char *argv[]){\n    /*Other Code*/\n\n    #pragma omp parallel\n    {\n        printlf(\"I\'m a parallel region\");	\n    }\n    \n    /*Other Code*/\n\n    return 0;\n}\n\\end{lstlisting} \nThe OpenMP directive \\textit{\\#pragma omp parallel} defines a creates as many threads as the cores on the system. All theads executes simultaneously in the parallel regiom and exit to it when they are finished.\\\\\nOpenMP parallel regions can define also pragmas for the for cycles, with a \\textit{\\#pragma omp parallel for} before a for statement, and defines a series of parallel levels and regions in the system.\n\n\\subsection{Threading Issues}\nWe have defined before the syscalls to manage the threads, like the \\textit{exec()} and the \\textit{fork()} functions. If one thread  in a program calls a \\textit{fork()} function does the new process duplicate the single thread or all the threads on the system? Some UNIX system have chose to create 2 versions of this function, one duplicates a single thread and the other one the whole system threads.\\\\\nThe \\textit{exec()} function typically works in the same way as defined before , but if a process runs the function with specified parameters the function will replace the entire process including all the threads.\\\\\nTo resolve these problems has been defines the \\textbf{signal} into UNIX systems to notify that a process that a particular event is occurred. A signal may be received sychronously or asynchronously, depending on the source and on the reason of the notification, both follows the same pattern:\n\\begin{itemize}\n \\item A signal is generated by the occurance of an event.\n	\\item The signal is delivered to a process.\n	\\item Once delivered the signal must be handled.		\n\\end{itemize}\nA signal may be handled by 2 possible handlers:\n\\begin{itemize}\n  \\item A \\textbf{default signal handler}\n		\\item An \\textbf{user-defined signal handler}\n\\end{itemize}\nEvery signal has a \\textbf{default signal handler} that the  kernel runs when handling that signal. This defauls action can be instead overridden by a \\textbf{user-defined handler} that has the priority to override the default one.\\\\\nSome signals when handled are \\textit{ignored} and other can be handled by the termination of a process.\\\\\nDelivering signals is more complicated on a multithreaded system, where prcesses have several threads, because we beed to respond each time to the question: \\textit{should the signal be delevered?}. We can follow 4 different options:\n\\begin{itemize}\n  \\item Deliver the signal to the thread which the signal applies.\n		\\item Deliver the signal to every thread in the process.\n		\\item Deliver the signal to certain threads in the process.\n		\\item Assign a specific thread ti receive all signals for the process.\n\\end{itemize}\nThe standard function to deliver signals is the \\textit{kill()} syscall:\n\\begin{center}\n\\textit{kill}(pid\\_t pid, int signal)\n\\end{center}\nThis function specifies the single process the signal needs to be deleverd. POSIX Pthread library implements this syscall with the \\textit{pthread\\_kill(...)} function\n\n\\subsection{Thread Cancellation}\nThread cancellation involves deleting a thread and stop its execution before is completed. For example if multiple threads are currently searching through a database and one thread returns the result, the other ones are cancelled. Another situation can be on web img/pages that use threads to load resources in parallel, when a user process presses the stop button or recharge bottom button of the img/page the threads are cancelled.\\\\\nAnother thread that is to be canceled is often referred to as \\textbf{target thread}. The cancellation of a target thread can be defined:\n\\begin{itemize}\n  \\item \\textbf{Asynchronus Cancellation}: one thread immediately termiantes the target thread.\n		\\item \\textbf{Deferred Cancellation}: the target thread periodically checks whether it should terminate allowing it an opportunity to terminate itself in an orderly fashion.\n\\end{itemize}\nThe difficutly with cancellation occurs i situations where resources have been allocated to a canceled thread or where a thread is cancelled while is updating some data. Often the OS will reclaim system resources from acanceled thread but will not reclaim all resources. \\\\\nThe cancellation of a thread can be made only if the thread is \\textbf{checked with a flag} if needs to be calcelled or not. In Pthreads the cancellation of a thread is made with the \\textit{pthread\\_cancel()} function and supports 3 cancellation modes:\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page186.png}\n\\end{center}\nA cancellation occours only when the tthread reaches a \\textbf{cancellation point}. We can verify the cancellation point with the Pthread function \\textit{pthread\\_testcancel()}. If a cancellation request is found to be pending a function called \\textbf{cleanup handler} is invoked and cancells all the thread in pending for cancellation.\\\\\n\n\\subsection{Thread-Local Storage}\nThreads belonging to a process share data of athe process. This sharing provides aone of the benefits of multithreading programming. However each thread might needs its own copy of certain data. Here comes the \\textbf{thread-local storage} or \\textbf{TLS}. TLS is a sapce of memory where the thread can allocate his data and resources. Its easy to switch TLS with local variables, the main difference is that the local variables are availabvle and visble during the singel function invocations, the TLS instead are data shared across all the threads in the system. In some ways the TLS is similar to \\textbf{static datas}.\n\n\\subsection{Scheduler Activations}\nFinal issue in threads can be the \\textbf{scheuling of threads}. Many systems implement their own many-to-many architecture in a structure between the kernel and the user threads. This structure is usually called the \\textbf{lightweight process} or \\textbf{LWP}. TO user-thread library the LWP is a virtual processor on which the application can schedule a user thread to run. Each LWP is attached to a kernel thread and it is kernel threads that the OS schedules to run fisical processors. An application may requre any number of LWPs to run efficiently. Like for I/O applications will need a big amount of LWPs to work. \\\\\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page187.png}\n\\end{center}\nOne scheme for communication between the user-thread library and the kernel is known as bscheduler activation. It works as follows: the kernel provides an application with the set of virtual processors (LWPs) and the application can schedule user threads onto an available virtual processor. Next the kernel must inform an application about ertail events with an \\textbf{upcall} procedure. Upcalls are handled by the thread library with an \\textbf{upcall handler} that needs to run on a virtual processor itself. One event that can occour on an application is when a process is going to block. In this scenario the application gets the upcall from the kernel that allocates a new virtual processor for the application. The application runs the upcall handler on this new processor on which the blockign thread is running and then the upcall handler schedules another thread that can run without blocking. After the blocked thread is newly available to run the upcall handler schedules an eligible thread to run on an available virtual processor. \n\n\n\\section{Process Synchronization}\n\\subsection{Background}\nProcess can be interrupted during their execution and their processing cores can be assigned to other processes. Until now we have seen only the system defined by a \\textbf{consumer-producer architecture}, but sometimes this system may not function correctly, usually when we are programming the modification of some registers.\\\\\nThe main problem behind the consumer-producer architecture are the \\textbf{race conditions}, \\textit{the problem where several processes access and manipulate the same data concurrently and the outcome of the execution depends on the particular order in which the access takes place}.\\\\\nTO guard agains race conditions we need to ensure that only one process at time can manipulate a variable, so defining a \\textbf{synchronizatin method between processes}.\n\n\\subsection{Critical Section Problem}\nCOsidering a system of n processes ${P_0, P_1,...P_n}$ each process has a segment of code, called \\textbf{critical section} in which the process may be changing common variables, updating a table, a file, and so on. THE important feature of the system is that, when it\'s in its critical section \\textbf{no other process is allowed to execute}. The \\textit{cricial-section problem} is do define a protocol that the processes can use to cooperate.\\\\\nThe section of code implementing this request is the \\textbf{entry section}. The critical section may be followed by an \\textbf{exit section}. The remaining code is defined in another section called \\textbf{remainder setion} defining a structure like this:\n\\begin{center}\n		\\includegraphics[width=0.5\\linewidth]{img/page206.png}\n\\end{center}\nThe critical section has 3 main requirements that needs to be followed:\n\\begin{itemize}\n  \\item \\textbf{Mutual Exclusion}: if a process P is executing in its critical section no other process can execute.\n		\\item \\textbf{Progress}: if no process is executing in its critical section and some processes wish to enter their critical section only the processes that are not executing their reminder section can decide who is going to execute its critical section.\n		\\item \\textbf{Bounded Waiting}: there needs to be a bound on how many times a process can enter in its critical section.\n\\end{itemize}\nTwo general approaches are maintained to handle critical sections: \\textbf{preemptive kernels} and \\textbf{non preemptive kernels}. A preemptive kernel allows process to be \\textbf{preempted} (\\textit{preemption: possibility to be interrupted during execution}) while it\'s running in kernel mode. A nonpreemptive kernel does not allow the system to preempt processes in kernel mode.\\\\\nObviously nonpreemptive processes are essentially free from race conditions, instead the preemptive kernels needs to be perfectly scheduled and watched to prevent the race conditions, but are also used because their rectivity and responsiveness, since there is less risk that a kernel-mode process will run for a long period of time before releasing the processor.\\\\\n \n\\subsection{Peterson\'s Solution}\nA classic software based solution for race condition and critical section is the \\textbf{Peterson\'s Solution}.\\\\\nModern architectures performs basic machine-language instructions, such as \\textit{load} and \\textit{store} syscalls. Peterson\'s solution is restricted to 2 process that alternate execution between their critical sections and remoinder sections. The processes are numbered $P_0$ and $P_1$, but for convenience we define $P_i$ and $P_j$ where $j=1-i$. Peterson\'s solution requires the 2 processes to shaer 2 data items:\n\\begin{lstlisting}[style=C]\nint turn;\nboolean flag[2];\n\\end{lstlisting} \nThe variable \\textit{turn} indicates whose turn it is to enter its critical section (i or j). The \\textit{flag} array instead is used to indicate if a process is ready to enter in its critical section. FOr example if \\textit{flag[i]} is true indicates that $P_i$ is ready to enter its critical section. TO enter the critical section $P_i$ firsts sets \\textit{flag[i]} to true and sets the \\textit{turn} variable to the value $j$. If both processes try to enter at the same time, \\textit{turn} will be set to both i and j at roughly the same time. Only one of thos assignments will last, the other will ocur but will be overwritten immediately.\\\\\nThis solution is correct because:\n\\begin{itemize}\n  \\item Mutual exclusion is preserved.\n		\\item The progress requirement is satisfied.\n		\\item the bounded-waiting requirement is met.\n\\end{itemize}\nThe complete algorithm of Peterson\'s Solution is:\n\\begin{lstlisting}[style=C]\ndo{\n    flag[i] = true;\n    turn = j;\n    while(flag[j] && turn == j){\n        // CRITICAL SECTION\n    }\n    flag[i] = false;\n    // REMINDER SECTION\n}while(true);\n\\end{lstlisting}\n\n\\subsection{Synchronization Hardware}\nWe have described one software-based solution to the critical section problem. However, as mentioned, software based solutions are not guaranteeed to work on modern computer architectures. There are instead differnt solution that doesn\'t require support from the architecture itself, called the \\textbf{hardware-based solutions} that providess API to resolve the race conditions and critical section problems directlu via hardware. All these solutions are based on the premise of \\textbf{locking} (\\textit{protecting the critical regions with the use of locks}).\\\\\nWe can start by representing simple hardware instructions in a single-processor environment.The critical secion problem could be resolved simply in a single processor environment if we could prevent interruptions from occurring while a shared variable is modified. In this way we could completely resolve race condition problems.\\\\\nUsually nonpreemptive kernels use this approach, but unfortunately this procedure cannot be actived on multiprocessros environments. Disabling interrupts on a multiprocessor can be time consuming, since the message is passed to all the processors. So usually modern systems do all the operation that can cause a race condition \\textbf{atomically}, an \\textbf{non-interruptable unit}.\\\\\nThere are 2 main concepts behind these types of instructions:\n\\begin{itemize}\n  \\item \\textbf{test\\_and\\_set()}: instruction can be defined as:\n\\begin{lstlisting}[style=C]\nboolean test_and_set(boolean *target){\n    boolean rv = *target;\n    *target = true;\n    return rv;\n}\n\\end{lstlisting}\nWhere each execution is executed atomically. Thus if 2 \\textit{test\\_and\\_set()} operations are executed simultaneaously on different CPUs they will be executed sequentially in some arbitrary order.\n		\\item \\textbf{compare\\_and\\_swap()}: in contrast to \\textit{test\\_and\\_set()} function this operates on 3 operands:\n\\begin{lstlisting}[style=C]\nint compare_and_swap(int *value, int expected, int new_value){\n    if(*value == expected){\n    *value = new_value;\n    }\n    return temp;\n}\n\\end{lstlisting}\nIn this case the operatd value is set to \\textit{new\\_value} only if the expression \\textit{(*value == executed)} is true. Regardless, \\textit{compare\\_and\\_swap()} function always returns the original value of \\textit{value}. Like \\textit{test\\_and\\_set()} function also \\textit{compare\\_and\\_swap()} is executed \\textbf{atomically}. Mutual exlucsion can be provided as follows: a global variable \\textbf{lock} is declared and initialized to 0. The first process that invokes the \\textit{compare\\_and\\_swap()} will set lock to 1. It will then enter its critical section and all the other \\textit{compare\\_and\\_swap()} instructions sended will not be able to run until the lock doesn\'t come back to 0. \n\\end{itemize}\nALthough these agorithms satisfy the mutual-exclusion requirement they doon\'t satisfy the bounded-waiting requirement.\n\n\\subsection{Mutex Locks}\nOS designers build software tools to sole critical-sectiomn problem. The simplest of these is the \\textbf{mutex lock}. Mutex lock protects critical regions and prevent race conditions. Mutex locks are what a process must acquire (acquire a \\textbf{lock}) before entering in a critical section and release it after its finished. The syscalls to do this are simply the \\textbf{acquire()} and \\textbf{release()} functions. All of these are defined over the \\textbf{available} variable, that, as the name says, defines when the lock is available to other processes or its locked from a process.\\\\\nThe definition of \\textit{acquire()}:\n\\begin{lstlisting}[style=C]\nacquire(){\n    while(!available){\n        // busy wait\n        available = false;\n    }\n}\n\\end{lstlisting}\nProcesses needs to follow so these rules to run their critical section:\n\\begin{lstlisting}[style=C]\ndo{\n    AQUIRE LOCK [acquire()]\n    critical section\n    RELEASE LOCK [release()]\n    reminder section  \n}while(true);\n\\end{lstlisting}\nThe definition of release instead is defined as:\n\\begin{lstlisting}[style=C]\nrelease(){\n    available = true;\n}\n\\end{lstlisting}\nCalls to either acquire nad relase function must be performed atomically. The main disadvantage of mutex locks is the requirement of \\textbf{busy waiting}. While a process is in its critical secition any other process that tries to enter its one must loop continuously an acquire function. In fact these types of mutex locks are called \\textbf{spinlock}. Spinlocks have, however, an advantage: no context switch is required when a process musst wait for a lock.\\\\\n\n\\subsection{Semaphores}\nMutex lockas are generallu considered the simplest of synchronization tools. Another hardware solution for race condition and critical section synchronization are the \\textbf{semaphores} \\textit{S}. The semaphores are an integer variable that is accessed only through 2 standard atomic operations: \\textbf{wait()} and \\textbf{signal()}. We can define the \\textit{wait} operation:\n\\begin{lstlisting}[style=C]\nwait(S){\n    while(S<=0){\n        ; //busy wait\n    }\n    S--;\n}\n\\end{lstlisting}\nand the signal operation appears like this:\n\\begin{lstlisting}[style=C]\nsignal(S){\n    S++;\n}\n\\end{lstlisting}\nSemaphores can be divided into 2 main categories: \\textbf{counting semaphores}, semaphores with an \\textbf{unrestricted domain} of ount and the \\textbf{binary semaphores}, with a domain of \\textbf{0 and 1}.\\\\\nCounting semaphores can be used to provide a process a resource and synchronize the accesses to that resource. To start using them we initialize the count to the number of resources on the system available. Each process that wants to access that resource needs to call the \\textit{wait()} instruction that decrement the count. Next when a process  releases that resource it performes a \\textit{signal()} operation, incrementing the count. When the count of a semaphore goes to 0 it means that all resources on the system are being used.\\\\\nWe can also use semaphors to resolve synchronization problems using it like a proper semaphore and giving the possibility to a process to start or not, this is usually done with the binary semaphores.\\\\\nWe can implement semaphores like this: when a provess executes a \\textit{wait()} operation and finds that the semaphore value is not positive it must wait, but his will introduce busy waiting on our system, so instead of doing this the process can \\textbf{block itself} and be putted into a queue of waiting processes for resource, then the computational control is transfared to the CPU scheduler that knows when to allocate the processes that are waiting. \nTo impelment these types of semaphores we can define a structure like this:\n\\begin{lstlisting}[style=C]\ntypedef struct{\n    int value;\nstruct process *list;\n}semaphore;\n\\end{lstlisting}\nEach semaphore has so a list of processes and an integer value. When a process must wait on a semaphore it\'s added to the list of processes and only a \\textit{signal()} operation can remove it from there.\\\\\nNow the wait function needs to be updated:\n\\begin{lstlisting}[style=C]\nwait(semaphore *S){\n    S->value--;\n    if(S->value < 0){\n        // Add this process to S->list;\n        block();\n    }\n}\n\\end{lstlisting}\nand so also the signal function needs to be refactored:\n\\begin{lstlisting}[style=C]\nsignal(semaphore *S){\n    S->value++;\n    if(S->value<=0){\n        // Pop process from the list\n        wakeup(P);\n    }\n}\n\\end{lstlisting}\nThe block operatnd suspends the process that invokes it andthe wakeup()P) operation resumes the passed process critical section.\\\\\nThe implementation of a semaphore with a waiting queue may result a situation where 2 or more processes are waiting for a deifined resource used by a blocked process, making the other ones loop continuously on the wait check. In this case the processes are defined as \\textbf{deadlocked}. We can so define that a systam is deadlocked when: \\textbf{every process in the set is waiting for na event tht can be caused only by another process in the set}.\\\\\nAnother problems related to deadlocks are \\textbf{infinite blocking} or \\textbf{starvation}, where processes wait idefinitely within the semaphore defining an infinite block of the system.\\\\\nAnother semaphore problem can be the \\textbf{priority inversion}. Usualy deadlocks happens when a low priority process stucks a resource for the high priority ones. The situation becomes more complicated when a lower priority prorcess is preempted by a higher priority one. This particular problem happens on systems with more that 2 priorities for processes.\\\\\nThe posible solution of this problem is the \\textbf{priority-inherticance protocol}. This protocol defines that all processes that are tring to access a resource needed by an higher priority process, the other processes that need that resource in high priority \\textbf{inherit the priority level} from the first one. When they are finished their priority is reverted to the original values.\\\\\n\n\\subsection{Classic Problems of Synchronization}\n\\subsubsection{Bounded-Buffer Problem}\nThe bounded buffer problem is commonly used to illustrate the power of synchronization primitives. The system in case is a general structure scheme without any particular implementation. We have a \\textit{consumer-producer} architecturewith the following data structures:\n\\begin{lstlisting}[style=C]\nint n;\nsemaphore mutex = 1;\nsemaphore empty = n;\nsemaphore full = 0;\n\\end{lstlisting}\nW define a pool of $n$ buffers each capable of holding one item. The \\textit{mutex} semaphore provides a mutual exlusion fo accesses tothe buffer pool and is initialized to 1. The \\textit{empty} and \\textit{full} semaphores count the number of empty anbd full buffers. The semaphore empty is initialize to n and the full to 0.\\\\\nThe producer is producing full buggerts fo r the consumer and the reverse (the consumer is producing empty buffers for the proucer).\n\n\\subsubsection{Readers-Writers Problem}\nSupposing that a database is to be shared among several processes , some of the processes may want to read the database and some update it. We distinguish so 2 types of processes, the \\textbf{readers} and the \\textbf{writers}. Obviously instantly gets out a problem when readers and writers \\textbf{access the same data simoultaneously}.\\\\\nTo resolve this problem we can provide the writers an \\textbf{exslusive} access to the data when they are writing data, but this will slow completely down the whole system. This is called \\textbf{readers-writers problem} and it has various variations, all related to priorities.\\\\\nThe simplest one is referred to the first readers and writers problem, where no reader should wait for other readers to finish, simply because a writer is writing. A second variant requires that, if a writer is waiting to access an object, no new readers can enter in the system.\\\\\nA solution to either problem will be the starvation, where or writers or readers will starve, so has been defined single one solutions. For the first writer-reader problem we can define these data structures:\n\\begin{lstlisting}[style=C]\nsemaphore rw_mutexx = 1;\nsemaphore mutex = 1;\nint read_count = 0;\n\\end{lstlisting}\nThe semaphore \\textit{mutex} and \\textit{rw\\_mutex} are initialized to 1to ensure mutual exclusion when the \\textit{read\\_count} variable is updated. The \\textit{read\\_count} variable defines the number of processes that are currently reading the data.\\\\\nReader writer problems has developed their own \\textbf{reader-writer locks} on some systems, where \\textbf{the lock is provided either in read or write access}. Whe na process wished only to read a shared data it requests the reader-writer lock in read mode, same thing in write more dor the processes that want to write data. So we can define a mutual lock for the processes where for defintion \\textit{only one process at the time will write/read data}, because only one lock at the time can be provided. Reader-writer locks are useful in:\n\\begin{itemize}\n  \\item Application hwere it\'s easy to itendify which process only reads shared data and which writes only data.\n		\\item Applications that have mode readers than writers, because the write of data require more oveerheato the establish semaphores or mutual locks and more execution time.\n\\end{itemize}\n\n\\subsubsection{Dining-Philosphers Problem}\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page222.png}\n\\end{center}\nConsider having 5 philosophers who spend their lives thinking and eating. The philosophers share a circular table surrounded by five chairs, wach belonging to one philosopher. In the center of the table there is a \\textit{rice bowl} and the table is laid with five single chopstickes. When a philosopher thinks he doesn\'t interact with his collegues. From time to time a philospher gets hungry and tries to picj up the 2 chopsticks that are the closest to him (each chopstick is between him and a near collegue, one on the right and one on the left). A philospher mau pick up a chopstick at the time and when the philospher has both of the chopsticks at his right and left can eat, withour releasing the chopsticks to his collegues. When is finished eating he puts down the chopsticks making them available for his near collgues.\\\\\nThe \\textbf{dining philosphger problem} is considere d a classic synchronization problem because is an example of large class of concurrency-protocol problem. It is a simnple representation of the need to allocate several resources among several processes in adeadlock-free and starvation-free state.\\\\\nOne simple solution is to represent each chopstick with a semaphore. A philosopher tries to get a chopstick by executing \\textit{wait()} operation on that semaphore. When hte using chopstick\'s philosopher realeases it, the chopstick executes a \\textit{signal()} opearaion to the appropriate semaphore.\\\\\nWe can define a philosopher structure like:\n\\begin{lstlisting}[style=C]\ndo{\n    wait(chopstick[i]);\n    wait(chopstick[(i+1)%5)]);\n    /* eat for a while */\n    signal(chopstick[i]);\n    signal(chopstick[(i+1)%5)]);\n    /* think for a while */\n}while(true)\n\\end{lstlisting}\n\n\\subsection{Monitors}\nSemaphores are optimal for synchronization problems, but using them wrong can cause serious problems to our system performance or find out errors, like the producer-consumer count problem:\n\\begin{itemize}\n  \\item A process interchanges the order in which the \\textit{wait()} and \\textit{signal()0} are executed on the \\textit{mutex} semaphore:\n\\begin{center}\n    \\begin{tabular}{c}\n        \\begin{lstlisting}[style=C]\nsignal(mutex);\n...\n// critical section\n...\nwait(mutex);\n        \\end{lstlisting}\n    \\end{tabular}\n\\end{center}\n\n		\\item Suppose that a process replaces the \\textit{signal()} operation with the \\textit{wait()} operation:\n\\begin{center}\n    \\begin{tabular}{c}\n        \\begin{lstlisting}[style=C]\nwait(mutex);\n...\n// critical section\n...\nwait(mutex);\n        \\end{lstlisting}\n    \\end{tabular}\n\\end{center}\n\n		\\item Suppose that a process omits the \\textit{wait()} or the \\textit{signal()} operation blocking the entire system.\n\\end{itemize}\nTo deal with such as errors there is an \\textbf{high level solution} with an high level synchronization construct called \\textbf{monitor}.\\\\\n\\begin{lstlisting}[style = C]\nmonitor monitor_name{\n    /*shared variables declarations*/\n    function P1(...){\n        ...\n    }\n    function P2(...){\n        ...\n    }\n    function P3(...){\n        ...\n    }\n    ...\n    function Pn(...){\n        ...\n    }\n    initialization_code(...){\n        ...\n    }\n\n}\n\\end{lstlisting}\nMontiors are an \\textbf{abstract data type} (\\textbf{ADT}) that encapsulates data with a set of functions to operatie on them.\\\\\nA \\textit{montior type} is an ADT that includes a set of programmer defined operations tha are provided withj mutual exlusion within the monitor. The functions defined into monitors can access only to the shared variable defined at the start, no other resources.\\\\\nA programmer that needs to wirte more condition can define one or more variables with the type \\textit{condition}:\n\\begin{lstlisting}[style=C]\ncondition x,y;\n\\end{lstlisting}\nThe only operations that can be called on the condition variables are the \\textbf{wait()} and \\textbf{signal()} operations:\n\\begin{lstlisting}[style=C]\nx.wait()\nx.signal()\n\\end{lstlisting}\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page227.png}\n\\end{center}\nThe montiros are a powerful synchronization module that we can use to resolve the previous problems, like the \\textbf{Dining Philophers one}, where we define an enumerator variable for the state of a philosopher:\n\\begin{lstlisting}[style=C]\nenum [THINKING. HUNGRY, EATING] state[5];\n\\end{lstlisting}\nAnd we check over it the state of a philosopher:\n\\begin{center}\n    \\includegraphics[width=0.8\\linewidth]{img/page228.png}\n\\end{center}\nTo create this type of monitor we need to define an external condition: \\textit{condition state[5];}.\\\\\nDoing this we can definea monitor to resolve the problem simply with:\n\\begin{lstlisting}[style=C]\nDiningPhilophers.pickup(i);\n...\n// eat\n...\nDiningPhilophers.putdown(i);\n\\end{lstlisting}\nAlso in monitors the processes can be stopped and resumed. For this pourpose the \\textbf{conditional wait} \\textit{x.wait()}, can be used like we had seen before. The allocation of resources can be made with a \\textbf{ResourceAllocator} R, another monitor that calls the \\textit{acquire(t)} and \\textit{release()} operation to get the resources the process needs to work.\\\\\n\n\\subsection{Alternative Approaches}\nIs commmonly used nowdays into OSs the concept of \\textbf{transactional memory} that provides a common suyncronization procedure to follow usually used into database managements.\\\\\nWe use a \\textbf{memory transaction}, a sequence of memory read-write operation that are atomic. If all operations are copleted the transaction is \\textbf{committed}, if not is \\textbf{aborted} and is computed a \\textbf{rollback} to the state of the memory before the operations.\\\\\nThis procedure avoids theuse of \\textit{acquire()} and \\textit{release()} operations, adding a new construct to the code called \\textit{atomic\\{...\\}}:\n\\begin{lstlisting}[style=C]\nvoid update(){\n    atomic{\n        /*modify shared data*/\n    }\n}\n\\end{lstlisting}\nTransactional memory can be implemented into the system using the \\textbf{Software Transactionsl Memory} (\\textbf{STM}) or the \\textbf{Hardware Transactional Memory} (\\textbf{HTM}). The STM provides an implementation of memory exclusively using software, inserting instrumentation code instare \\textbf{transaction blocks}. The code is inseterf into the compiler and managed each transaction identifing which one can be runned and committed. The HTM instead defiens an hardware protocol for the transactions, involving shared data in different processors\' caches. HTM requires no special code implementation, but has less overhead then STM.\\\\\nAnother alternative we can use is the OpenMP pragrmas for the critical sections and the parallel regions management. OpenMP defines code pragmas structures like \\textbf{\\#pragma omp parallel} to identify and createa a parallel region of memory managed by an amount of threads equals to the maximum managed from the CPU, or the \\textbf{\\#pragma omp critical} that identifies into the code the critical section of a process, so that the compiler can manually manage the threads with semaphores or mutex lock to make that single processor run in its critical section lonely.\\\\\nUsually for coding we have used \\textbf{imperative} (or \\textbf{procedural}) langauges. In these langauges the flow of the algorithm is crucial to its correct operation and the state of the algorithm is defined from other structure or flags. An alternative that can be useful in processors synchronization are the \\textbf{functional programming languages}, where the states are not maintained and when a variable gets a value is \\textbf{immutable} for the rest of the algorithm. \n\n\n\\section{CPU Scheduling}\n\\subsection{Basic Concepts}\nIn a single processor system only one processor at the time can run, the aother needs to wait for the CPU to be free and allocate into it. The objective of multiprogramming is very simple, we have multiple CPUs with multiple cores where each core can run a single process at the time, creating the \\textit{parallelization} of the code running on a system.\\\\\nThis method does not come free, because multicore systems can define problems that single processor system can even think, like the \\textit{resource handling}, \\textit{race conditions}, etc.\\\\\nA resolver for the most of the problems behind the multiprogramming is the \\textbf{CPU Scheduling}, where we can define a scheduling for processors that can enter into the CPU. The lifecycle of a process can be divided into 2 main categories: the \\textbf{I/O Burst} and the \\textbf{CPU Burst}. Both of the bursts arrive sequetially one after the other, until the CPU Burst time is used to termiante the process:\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page262.png}\n\\end{center}\nThe selection of processes that can enter in the CPU in order is made by the \\textbf{short-term scheduler} or \\textbf{CPU scheduler} that selects the porocess from memory that are ready to execute and allocates the CPU to that proess.\\\\\nThe CPU scheduler is called when:\n\\begin{itemize}\n  \\item A process switches from the running state to the waiting state.\n		\\item A process switches from the running state to the ready state.\n		\\item A process switches from the waiting state to the ready state.\n		\\item A process terminates.\n\\end{itemize}\nWhen a scheduling takes place into these for circumstances we say that the scheduling scheme is \\textbf{nonpreemptive} or \\textbf{cooperative}, otherwise is \\textbf{preemptive}. Under nonpreemptive scheduling, once the CPU has allocated the process, it takes the CPU for itself until is finished and realeses it only on termination or when it switches to a waiting state. Preemptive scheduling instead si the reverse, where a process can be interrupted and so is bound to leave the CPU. Unfortunately iun preemptive scheduling we can find \\textit{race condition problems}.\\\\\nAnother component for the CPU scheduling the \\textbf{dispatcher}, that provides a module to give the CPU the permissions to:\n\\begin{itemize}\n  \\item Switch context.\n		\\item Switch to user mode.\n		\\item Jump to a proper location in the user program to restart it.\n\\end{itemize}\nThe dispatcher should be the fastest of all the components, if it takes time we define this delay as \\textbf{dispatch latency}.\n\n\\subsection{Scheduling Criteria}\nMany criteria have been suggested for comparing CPU scheduling algorithms. These criteria represents caracteristics that the processes can have or not, that needs to be compared to schedule the best:\n\\begin{itemize}\n  \\item \\textbf{CPU Utilization}: we want to keep the CPU as busy as possible. Conceptually in a very performant system the CPU utulization on a 0 to 100 scale should range between 40 and 90\\%.\n		\\item \\textbf{Throughput}: defines how much time the process will spend into the CPU.\n		\\item \\textbf{Tournaround Time}: the sum of the periods spent waiting to get into memory, waiting in the ready queue, executing on CPU and doing I/O opeartions.\n		\\item \\textbf{Waiting time}: defines the time a process has spent into waiting queue.\n		\\item \\textbf{Response Time}: the time it takes to start responiding from the process, not the time to the output of the response.\n\\end{itemize}\n\n\n\\subsection{Scheduling Algorithms}\nCPU dealing with scheduling can be made using various algorithms that defines different types of queues.\n\\subsubsection{First-Come, First-Serve Scheduling (FCFS)}\nThe simplest algorithm of CPU scheduling is surely the \\textbf{First-Come, First-Served} (\\textit{FCFS}) algorithm, that, as the name says, defines a policy where we define a \\textbf{FIFO queue}. Whe na proces enters in the ready queue its PCB is linked onto the tail of the queue, when the CPU is free it is allocated to the process at the head of the queue.\\\\\nOne negative site of the FCFS algorithm is the \\textbf{waiting time}, that is quite long for processes that needs least time than others, because FCFS \\textbf{doesn\'t implement priority values}, defining a \\textbf{convoy effect} of short execution time processes waiting for longer execution time processes to finish.\n\\begin{center}\n    \\includegraphics[width=0.25\\linewidth]{img/page266.png}\n\\end{center}\n\\begin{center}\n    \\includegraphics[width=0.6\\linewidth]{img/page267.png}\n\\end{center}\n\n\\subsubsection{Shortest-Job-First Scheduling (SJF)}\nA different approach instead of FCFS, the SJF \\textbf{Shortest-Job-First} algorithm, as the name says, will define a scheduling queue in base of the \\textbf{burst time of a process}. This resolves the problems of FCFS, increasing the complexity of the algorithm, but increasing also the CPU utilization and performances. In a list of processes SJF searches for the \\textbf{shortest-next-CPU-burst} and defiens his queue:\n\\begin{center}\n    \\includegraphics[width=0.25\\linewidth]{img/page268-1.png}\n\\end{center}\n\\begin{center}\n    \\includegraphics[width=0.6\\linewidth]{img/page268-2.png}\n\\end{center}\nThe next CPU birst is generally predicted with an \\textbf{expoinential average} of the processes, because obviously we cannot know at the start how much burst time a process can use. \n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page269.png}\n\\end{center}\nWhen the SJF algorithm is preemptive it can be called \\textbf{shortest-remaining-time-first scheduling}, where in each execution unit of time we check for the arrived processes and if a process has less burst time then the one is executing we interrupt the current process and allocate the CPU on the process with less burst time:\n\\begin{center}\n    \\includegraphics[width=0.3\\linewidth]{img/page270-1.png}\n\\end{center}\n\\begin{center}\n    \\includegraphics[width=0.6\\linewidth]{img/page270-2.png}\n\\end{center}\n\n\\subsubsection{Priority Scheduling}\nA special type of SJF is the \\textbf{priority-scheduling algorithm}, that defines its queues in base of the priority, without only checking the burst time. \n\\begin{center}\n    \\includegraphics[width=0.3\\linewidth]{img/page270-3.png}\n\\end{center}\n\\begin{center}\n    \\includegraphics[width=0.6\\linewidth]{img/page271.png}\n\\end{center}\nAlso priority scheduling can be preemptive or nonpreemptive like SJF.\\\\\nA majour problem on priority scheduling is the \\textbf{process starvation}, where low priorioty processes will starve between high priority processes with longer burst time. A solution for this problem is the \\textbf{aging} procedure, where the priority of the lower priority processes will increase gradually on each CPU unit time, when they are waiting, until they reach the priority of an high priority process and get its place allocating the CPU.\n\n\\subsubsection{Round-Robin Scheduling}\n\\textbf{Round Robing} (\\textbf{RR}) algorithm is one of the most known algorithms in Operating System developement. It\'s defined by a parameter called \\textbf{time quantum} or \\textbf{time slice}. This parameter gets a value usually between 10 and 100 millieconds. It gets a queue of processes like a FIFO and starts processing the processes like FCFS, but in this case if a process allocates the CPU for more time than the quantum, the process will lose the allocation of CPU and will pass to the next process available in the queue. In this example a quantum of 4 has been choosen:\n\\begin{center}\n    \\includegraphics[width=0.25\\linewidth]{img/page272-1.png}\n\\end{center}\n\\begin{center}\n    \\includegraphics[width=0.6\\linewidth]{img/page272-2.png}\n\\end{center}\nThe performance of this algorithm depends a lot on the size of the quantum. If we choose an exetremely large quantum time the algorithm will be a normal FCFS, instead if we decide a small quantum we will continously interrupt a process and the problem is clear.\\\\\nThe main rule to follow when choosing quantum is that we need to define a quantum where the 80\\% of the CPU burst is shorter than the time quantum.\\\\\n\n\\subsubsection{Mutlilevel Queue Scheduling}\nOn our system we can make simple level divisions for processors. A simple division that is usually made is between \\textbf{foreground} and \\textbf{background} processes. Both have different response time one from the other. For this is usually common to implement a \\textbf{multilevel queue scheduling algorithm}.\\\\\nIn this case the processes are permanently assigned to one queue, generally based on properties of the process, like memory access, priority, burst time, etc. Each queue has its own scheduling algorithm. An example and very common method of multilevel scheduling can be the division between:\n\\begin{itemize}\n  \\item System processes\n		\\item Interactive Processes\n		\\item Interactive editing processes\n		\\item Batch processes\n		\\item Student processes \n\\end{itemize}\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page275.png}\n\\end{center}\n\n\\subsubsection{Multilevel Feedback Queue Scheduling}\nThe \\textbf{multilevel feedback queue} scheduling algorithm alloows processes to move between queues. The main idea bihind is that if a process uses too much CPU time to be executed it will be moved int a lower priority queue. At hte same time a process that waits too long in a lower priority queue will increase its level to an higher priority queue and so on.\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page276.png}\n\\end{center}\nIn general multilevel feedback queue scheduler is defined by these parameters:\n\\begin{itemize}\n  \\item The number of queues.\n		\\item The scheduling algorithm for each queue.\n		\\item The method used to determine when to upgrade a process to an higher priority queue.\n		\\item The method used to determine when to upgrade a process to an lower priority queue.\n		\\item The method used used to detrermine which queue a process will enter when that process needs service. \n\\end{itemize}\n\n\\subsection{Thread Scheduling}\nThe system usually implemenmts a \\textbf{process-contention scope} (\\textbf{PCS}), a aparticular scheme where the processes are running for CPU allocation, both user and kernel threads, both lieing on their scheduling priority.\\\\\nTo decide which kernel thread to schedule onto a CPU kernel uses the \\textbf{system-contention scope} (\\textbf{SCS}).\\\\\nThe PCS usually choose the higher  priority process to run and allocates the CPU on it. User level threads priority is defined by the programmer, so is our job to give each process the right  priority.\\\\\n\n\\subsection{Mutlitple-Processor Scheduling}\nIf multiple CPUs are available \\textbf{load sharing} becames impossible to do. One approach that has been tested is the asymmetric multiprocessing, a simple algorithm where only one processors accesses the system data structure reducing the need of data sharing. A second approach is the \\textbf{symmetric multiprocessing} (\\textbf{SMP}) where each processor is self-scheduing. All processes may be in a common ready queue or each processor may have its own private queue of ready processes.\\\\\nBecause of the high cost of migrating a process from a processor to another, OSs usually define the situaion of \\textbf{processor affinity}, where a process is more affine to run on a specific processor.\\\\\nA process can be affine to a processor and the OS tries to make it stay into it. If the process has also the possibility to migrate to another processor the system is in a state called \\textbf{soft affinity}. If the OS provide system calls to provide a specific set of processors that are bounded to run on a specific processor, the system is in a state of \\textbf{hard affinity}.\\\\\nOn SMP systems is important toi keep the workload balanced among all processors. The OS needs to implement the action of \\textbf{load balancing} where it attempts to keep the workload evenly distrbuted across all processors. There are 2 general approcaches on load balancing:\n\\begin{itemize}\n  \\item \\textbf{Push Migration}: a specific task periodically checks the load on each processor, moving the processes from overloaded to idele or less-busy processors. \n		\\item \\textbf{Pull Migration}: in this case when an idle processor pulls a waiting task from a busy processor. \n\\end{itemize}\nPush and pull migrations need to be mutually exclusive and aare in fact often implemented in parallel.\\\\\nTraditionally SMP systems have allowed several threads to run concurrently by providing multiple phisical processors. But the nowadays logic defines a processor with \\textit{multiple cores}, defining a \\textbf{multicore processor}. Each corea maintains its achitectural state and appears to the OS as a single processor.\\\\\nIn general there are 2 ways to multithread a processing core:\n\\begin{itemize}\n  \\item \\textbf{Coarse-grained Multithreading}: where a thread executees on a processor until a long-latency eventy sych as \\textbf{memory stall} (\\textit{infinite search of memory}) occours. Because opf the deay caused by the long-latency event the processor must switch to another thread to begin its execution, but this increase the the costs of the procedures. \n		\\item \\textbf{Fine-grained Multithreading}: in this case we switch between threads, reducing the cost of the operations.  \n\\end{itemize}\n\n\\subsection{Real-Time CPU Scheduling}\nCPU scheduling for real time systems can be distinguished in base of the system we are operating on. We can have \\textbf{soft real-time systems}, that provides no guarantee as to wen a critical real time process will be scheduled, it only guarantee that a process will be given in a certain time. Or we can have the \\textbf{hard real-time systems} wher ewe have more stricted rules, like that the processes needs to stop after a \\textit{deadline} and each process needs to be scheduled.\\\\\nOn real-time systems the property that counts the most is the \\textbf{event latency} that defines the time from where \\textit{an event occours} to when the real time system responds with the result of this event:\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page284-1.png}\n\\end{center}\n2 other types of latency determins the performance of a real-time system:\n\\begin{itemize}\n  \\item \\textbf{Interrupt Latency}: the period of time from the arrtival of an interrupt on the CPU to the start of the routine that interrupt carries. When an interrupt occurs the OS must complete the instruction is executing and determine the type of the interrupt occurred, then it saves the state of the current process with the ISR and starts the new event of the interrupt. \n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page284-2.png}\n\\end{center} \n\n		\\item \\textbf{Dispatch Latency}: defines the amount of time required for the sheduling dispatcher to stop one process and start another on. The most known action we can do to decrease dispatch latency is to use \\textit{preemptive kernel}, to make the interruptions faster. \n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page285.png}\n\\end{center}\n\\end{itemize}\n\n\\subsubsection{Priority-Based Scheduling}\nAn important feature of real-time systems is that the system immediately responds to a process as soo nit needs the CPU allocated. The CPU scheduler of real time system will so need to give \\textbf{priorities} to his processes in base of their importance on the system.\\\\\nIn a real time OS the processes are considered \\textbf{periodic}, so on a certain period each process will return to the CPU. The times a periodic task comes to the CPU is called its \\textbf{rate} and with all these caracteristics the schedulers can easily schedule at the best the processes, because we \\textbf{already know when and which process is coming on a specific time}.\\\\\n\n\\subsubsection{Rate-Monolitic Scheduling}\nThe \\textbf{rate monolitic scheduling} is a scheduling algorithm tha scedules perdioc tasks using \\textbf{static priority policy with preemption}. If a lower priority process is runnign and an higher priority one becomes available to run, the system will preempt the current process  to make the higher priority one run.\\\\\nThe scheduler also this time meets the \\textbf{deadlines}, where if a process goes for more time than its deadline, the process will be preempted, its state is saved and the next process in queue allocates the CPU.\\\\\n\\begin{center}\n    \\includegraphics[width=0.6\\linewidth]{img/page287.png}\n\\end{center}\n\n\n\\subsubsection{Earliest-Deadline-First Scheduling}\nEarliest deadline first scheduling algorithm (\\textbf{EDF}), as the name says, schedules the processes in base of their \\textbf{deadlines}.\\\\\nTo use this scheduling the system needs toevery step watch the deadlines of the processes, because if a deadline exceeds the process will be deleted. Each pass of time we need to define which process has the earliest deadline and if the process that is currently running has a longer deadline than the one waiting, the system needs to preempt the current process and run the other one. Like in this example:\n\\begin{center}\n    \\includegraphics[width=0.6\\linewidth]{img/page289.png}\n\\end{center} \nIn this case we have $P_1$ with a deadline of 50 and its burst time at 25 and $P_2$ with a deadline of 80 and a burst time of 35. We can see in the example that we check always when P1 starts because its deadline count starts when the process is ready to run.\n\n\\subsubsection{Proportional Share Scheduling}\nProportional share schedulers operate allocating \\textit{T} shares among all application. An application receives \\textit{N} shares of time, and that ensures that the application has \\textit{T/N} time in CPU to spend.\n\n\n\\subsection{Algorithm Evalutation}\nTo select an algorithm we need to define some criterias to manage the best model for our system. Those criterias are:\n\\begin{itemize}\n    \\item \\textbf{CPU Maximization} with a maxium response time of 1 second.\n    \\item \\textbf{Thoughput Maximization} with a tournaround time linearly proportional with the total execution time.\n\\end{itemize}\nThere are different techniques of algorithms evaluation, one is the \\textbf{analytic evalutation}, that uses the algorithm and applies the results on the system evaluating it in the performance. \\\\\nThere is next the \\textbf{deterministic modeling}, a subsection of the analytic evaluation , that takes a prticular predeterminated workload and defines the performance of each algorithm in base of that workflow.\\\\\nWe can also determinate on a system the \\textbf{distribution of CPI and I/O burst}, misured with a simple estimation. From these 2 distribution it\'s possible to compute the average \\textit{thoughput, utilization, wating time and so on} for the most of the algorithm. Beccause systems are defined as a \\textit{network of servers} the study of the performance of an OS and its algorithms is called \\textbf{queueing-network analisys}.\\\\\nA very common formula used in this study is the \\textbf{Little\'s Formula}, where known $n$ the average queue length, $\\lambda$ the average arrival rate of a new proves and $W$ the average waiting time in a queue we can define:\n\\begin{center}\n    $n=\\lambda\\times W$\n\\end{center}\nTo get more accurate evaluations we can also use the \\textbf{Simulations}, that permit to run simulations of the algorithm directly on the system, evaluating the performance.\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page303.png}\n\\end{center}\nThe distribution-driven simulations may be inaccurate, to resolve this we can use the \\textbf{trace tapes}, a trace that monitors the system and provide excellent values of comparanton between the algorithms.\n\n\n\\section{Deadlocks}\n\\subsection{System Model}\nA system is defined by a finite number of resources distrubuted among the available processors. Examples of the resources are the I/O devices, the CPU cycles or simple files. If a system has 2 CPUs the resources needs to be available in instances for each CPU.\\\\\nIfa process requests an \\textbf{instance of a resource}, the system needs to allocate a resource toi that process that satisfy its requests. A process must request a resources, use it and then needs to release it after it has finished. Under a normal mode of operations the processes need to follow this sequence:\n\\begin{itemize}\n  \\item \\textbf{Request}: the process requests the reosource, if it cannot be granted immediately, the process needs to wait until the resource is free.\n		\\item \\textbf{Use}: the process operates on the resource, reading or modifing it.\n		\\item \\textbf{Realease}: the process releases the resource obtained.\n\\end{itemize} \nFor these operations we need a lot of syscalls seen before:\n\\begin{itemize}\n  \\item \\textit{request()}\n		\\item \\textit{release()}\n		\\item \\textit{allocate()}\n		\\item \\textit{open()}\n		\\item \\textit{close()}\n		\\item \\textit{wait()}\n		\\item \\textit{signal()}\n		\\item \\textit{acquire()}\n\\end{itemize}\nA \\textbf{system table} records all the operations made on that resource and the process that allocated it and allocates it now. \\\\\nWe can define that a set of processes are in a \\textbf{Deadlocked State} when \\textbf{every process in the set is waiting for an event that can be caused only another process in the set}.\\\\\n \n\\subsection{Deadlocks Characterization}\nThe deadlocks as before sad are a state of the machine where processes in a set are stucked because of another process in the same set. To generate these types of stucks needs to arise simultaneously these 4 conditions:\n\\begin{itemize}\n  \\item \\textbf{Mutual Exclusion}: at least one resource needs to be maintained from only one process and the resource needs to be maintained one process per unit time. \n		\\item \\textbf{Hold and Wait}: a process must be holding at least one resource and waits to acquire additional resources, holded by other processes.\n		\\item \\textbf{No Preemption}: if the system is define with preemption the problems are resolved instantly, so the system needs to have processes that cannot be preempted.\n		\\item \\textbf{Circular Wait}: in a set of $n$ processes the process $P_0$ is waiting the resource of $P_1$ and so until $P_n$ is waiting $P_0$. \n\\end{itemize}\nDeadlocks can be described with a \\textbf{system resource-allocation graphs}, where we have a set of vertices $V$, a set of nodes $P$ that defines the processes in the system and a set of resources $R$ that defines the available resources on the system. We can connect the edges of the graph with the processes and define the state of the machine. The edges can be of 2 types: \\textbf{request edges} or \\textbf{assignment edges}. Also resources can have \\textbf{multiple instances} that can be allocated by multiple processes, each instance is designed with a \\textbf{point} into the resource square.\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page320.png}\n\\end{center}\nGiven the definition of the resource allocation graph and defined how to find a deadlocked system we can manage to define the \\textbf{resource allocation graph for a deadlocked system}. The graph represents a deadlocked state if the deadlocked state property are defined (\\textit{cyrcular wait, single instance for each resource,...}). Here is an example of a deadlocked state graph:\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page321.png}\n\\end{center}\n\n\\subsection{Handling Deadlocks}\nWe can deal with deadlock problem in 3 ways:\n\\begin{itemize}\n  \\item Use a protocol to prevent or avoid deadlocks so that the system never enters into a deadlocked state.\n		\\item We can allow, deny or detect the deadlocked state on a system automatically.\n		\\item Ingnore the problem and pretend that deadlocks never occurs on the system.\n\\end{itemize}\nTo ensure deadlocks never occurs we define 2 main action on the system: \\textbf{Deadlock Prevention} or \\textbf{Deadlock Avoidance}.\\\\\nDeadlock prevention defines a set of methods to ensure that at least one of the necessary conditions are never resolved. Deadlock avoidance instead providesrequeires that the OS has an additional information in advance concern the possbile resource deadlock state, so it can ddecide  when to wait for sending a process or use that resource.\n\n\\subsection{Deadlock Preventions}\nAs sad before the deadlock prevention needs to \\textbf{prevent the possible deadlock states} on a system. We can prevent deadlocks in base of all the informations that provides a deadlock state.\n\n\\subsubsection{Mutual Exclusion}\nThe mutual exclusion is the first of the indications to provide find out a deadlock state. This condition must be hold, vecause at least \\textbf{one resource must be nonsharable}. We cannot prevent deadlocks avoiding mutual exclusion, by making all sharable. An example of the problem can be tha mutex locks, that cannot be accessed simultaneously.\n\n\\subsubsection{Hold and Wait}\nTo ensiure that  the hold-and-wait condition never occurs on the sistem we need to consider that \\textbf{whenever a process requests a resource it need to realease the other ones}. With this constraint into the system we can use a protocol it requests that a process \\textit{before statrting must allocate all his resources}. An alternative protocol defines that a process can request resources \\textit{only when it has none allocated on it}.\\\\\nBoth of these protocols has 2 main disadvanteges:\n\\begin{itemize}\n  \\item Resource utilization \\textbf{may be low}, since the resources may be unused for a long period of time.\n		\\item \\textbf{Starvation is possible}, because if a process needs several resources may have to wait indefinitely.		\n\\end{itemize}\n\n\\subsubsection{No Preemption}\nTo ensure preemption on the system ee can use a protocol that defines if a process is holding some resources and requests another one that cannot be allocated immediately, all resources allocated on it \\textbf{are preempted}. This solution can be added to the lists of resources of other processes that can run before the waiting one.\\\\\nAlternatively if a process requests some resources we first check whether they are available. If yes we can allocate them, if are held by a waiting process or cannot be allocated the reqeusting process must wait. While is waiting his resources are preempted but \\textbf{only if another process requests them}. This protocol is often applied to resources whose state can be easily saved and restored.\n\n\\subsubsection{Circular Wait}\nTo ensure that the process sets doesn\'t define circular waits and provide a deadlocked state, we need to ensure that all the reouurces and processes in a system are ordered in on a specific queue.\\\\\nConsidering a set of resources $R=\\{R_1, R_2,..., R_n\\}$ we can assign to each resource an unique integeer nuymber that allows to compare them and uniquely define them, defining a function: $F: R\\rightarrow N$.\\\\\nNow that the system is setted up we can define a protocol to prevent circular waits: each process can \\textbf{request resources only in an increasing order of enumeration}. That means that a proces can request a resource from the resource set $R_i$, the next resource that it will requests $R_j$ needs to have $j>i$.\\\\\nAnother protocol we can use in alternatie requires that \\textbf{a process requestin an instance of a resource type $R_j$ must have released all other resources $R_i$ where $i<j$}.\nIf these 2 protocols are used then \\textit{the circular wait condition cannot be hold}.\n\n\\subsection{Deadlock Avoidance}\nDeadlock prevention algorithms are used to prevent deadlocks by liming the reuqest of resources. An alternative method can be the \\textbf{Deadlock Avoidance} that, as the name says, tries to avoid completely deadlocks. To do this the system needs to have additional informations baout how resources are to be requested from al the process set.\\\\\nOne of these resource is defined as the \\textbf{state of the system}. The system to work properlòy needs to be in a \\textbf{safe state}: \n\\begin{center}\n    \\textbf{The system is defined in a safe state if a sequence of processes $<P_1, P_2,..., P_n>$ if for each $P_i$ process the resource requests can be always satisfied when the process is running.} \n\\end{center}\nWhen the $P_i$ process terminates the $P_{i+1}$ process can get all the needed resources.\\\\\nIf this statement is not resolved the system will be in an \\textbf{unsafe state}, and so \\textbf{voulnerable to deadlocks}.\\\\\nWe can so divide the system into 2 main states: \\textit{unsafe state} and \\textit{safe state}. We can say also that \\textbf{if a system is in a safe state there is no possibility of deadlock states, although if the system is in an unsafe state there is the possibility a deadlock state, but is not sure}.\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page328.png}\n\\end{center}\nWe had seen before the \\textit{resource-allocation graph}. In deadlock avoidance we can define an algorithm called \\textbf{resource-allocation-graph algorithm} that can help us to prevent unsafe states. We can introduce in the graph the \\textbf{claim edge}, that goes from a process to a resource and indicates that a process \\textit{may request that resource}. This arrow is defined as a \\textbf{dashed line}.\\\\\nWe can catch into these graphs if the system will be forever in a safe state or not watching \\textbf{if there are cycles into the resource graph}. If no cycles axists the \\textbf{system is in a safe state},  if a cycle is found instead the system will be \\textbf{for sure in a deadlock state}.\\\\\n\n\\subsubsection{Banker\'s Algorithm}\nThere are multiple algorithms that permits the deadlock states avoidance with a permanent safe state on the system. The most used one in the \\textbf{Banker\'s Algorithm}. \\\\\nThe name is chosen because this is how the \\textbf{banks} needs to work if they want to avoid failure. \\\\\nWhen a new process enters in the system it must \\textbf{declare the maximum number of instances of resource type it needs}. This number may not exceed the total number of resources on the system. When a use requests a set of resources, the system mmust determine whether the allocation of these resources will leave the system in a safe state, if yes the resouyrces are allocated, otherwise the process must wait until some other processes release enough resources.\\\\\nTo maintain this algorithm procedure we need serveral structures:\n\\begin{itemize}\n  \\item \\textbf{Available}: a vector of $m$ length that indicates the \\textit{number of available resources} for each type.\n		\\item \\textbf{Max}: an $n\\times m$ matrix that defines the maximum demand of each process. If $Max[i][j]$ equals k, then the process $P_i$ may request at most $k$ instances of resource type $j$.\n		\\item \\textbf{Allocation}: an $n\\times m$ matrix that defines the number of resources of each type currently allocated to each process. If $Allocation[i][j]$ is $k$ the process $P_i$ has allocated $k$ instances of the resource $R_j$.\n		\\item \\textbf{Need}: an $n\\times m$ matrix that indicates the remaining resource need of each process. If $Need[i][j]$ equals $k$ then the process $P_i$ needs more $k$ resources $R_j$. We can calculate $Need[i][j]$ with the equation: $Need[i][j] = Max[i][j] - Allocation[i][j]$.\n\\end{itemize}\nNow that we have defined the algorithym structure we can define how the algorithm works and maintains the safe state:\n\\begin{itemize}\n  \\item \\textbf{1.} We define $Work$ and $Finish$ as 2 vectors of length $m$ and $n$, initialized by: $Work=Available$ and $Finish=false$.\n		\\item \\textbf{2.} Find an index $i$ that satisfies the value: $Finish[i]==false \\text{ } AND \\text{ } Need_i \\leq Work$. If no exists go to step 4.\n		\\item \\textbf{3.} Set $Work = Work+Allocation$, $Finish[i]=true$ and go to step 2.\n		\\item If $Finish[i]==true$ for all $i$ then the system is in a safe state.\n\\end{itemize}\nNext we can describe the algorithm to determine whether the requests can be safely granted. \nLet $Request_i$ be the \\textbf{request vector} for the process $P_i$. If $Request_i[j]==k$ it means that the process is requesting $k$ instances of the resource $R_j$. When the request is made by the process $P_i$ we need to perform the following actions:\n\\begin{itemize}\n  \\item \\textbf{1.} If $Request_i \\leq Need_i$ go to step 2. or rise an error condition.\n		\\item \\textbf{2.} If $Request_i \\leq Available$ go to step 3. Otherwise $P_i$ must wait since the resources are not available.\n		\\item \\textbf{3.} Have the system pretend to have allocated the requested resources and update the states:\n		\\begin{center}\n    $Avalabile = Available-Request$ \\\\ $Alllocation_i = Allocation_i + Request$ \\\\ $Need_i=Need_i-Request$\n		\\end{center}\n\\end{itemize}\n\n\\subsection{Deadlock Prevention}\nIf a system deosn\'t implement techniques of deadlock avoidance or deadlock prevention, it will occur surely into a deadlock state. In  this case we can operate in 2 methods:\n\\begin{itemize}\n  \\item Provide an algorithm that examinates the system and find out where the deadlock state is.\n		\\item Provide an algorithm to revocer from deadlock.\n\\end{itemize}\nWhen we have a system that defines a single instance for each resource we can define a new structure that inherit from the previous seen \\textit{resource allocation graph}, called the \\textbf{wait-for graph}. We can start from a resource allocation graph, remove the resources and find out which process needs another to finish to execute:\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page334.png}\n\\end{center}\nWe can also provide an algorithm inherited from the \\textit{Banker\'s Algorithm}. Also this algorithm defines the columns of \\textbf{Available} and \\textbf{Allocation}, adding the column \\textbf{Request}, defined as the $n\\times m$ matrix that indicates the current request for each process. In this case the path is a different:\n\\begin{itemize}\n  \\item \\textbf{1.} Let $Work$ and $Finish$ be vectors of $m$ and $n$ length, as before we can initialize $Work=Available$, but we initilize $Finish[i]=false$ if $Allocation_i\\neq 0$ else $true$\n		\\item \\textbf{2.} Find an index $i$ where: $Finish[i]=false\\text{ }AND\\text{ }Request_i\\leq Work$. If no exists go to step 4.\n		\\item \\textbf{3.} Set $Work=Work+Allocation$ and $Finish[i]=true$ and return to step 2.\n		\\item \\textbf{4.} If there is some index $i$ where $Finish[i]==false$ the system is in a \\textbf{deadlocked state} and, in particular, the process $P_i$ is deadlocked.\n\\end{itemize}\n\n\\subsection{Recovery from Deadlocks}\nWhen a system detects a deadlocked state and the deadlocked process, we can only \\textbf{recover the system} from the deadlocked state. \\\\\nTo do this we can follow different paths. The most common is the \\textbf{process termination}, where we terminate the deadlocked processes, releasing all their resources allocated.\\\\\nWe can follow 2 mathods:\n\\begin{itemize}\n  \\item \\textbf{Abort all deadlocked processes}: we terminate all the process that result deadlocked in the deadlock detection algorithms, breaking the cycle and making the processes evaluates their execution after.\n		\\item \\textbf{Abort one process at time until the deadlock cycle is eliminated}: this method defines a process termination also for processes that are not deadlocked, usually we need also to run a deadlock detection algorithm to find out in each termiantion if the system is still deadlocked.\n\\end{itemize}\nIf we use a partial termination we must determin the process that is in the deadlocked state. Many factors can defines the process choosen:\n\\begin{itemize}\n    \\item The priority of the process.\n    \\item How long the process is computing.\n    \\item How many and what types of resources the process uses.\n    \\item How many more resources the process needs to complete.\n    \\item How many processes will need to be terminated.\n    \\item If the process is inactive.\n\\end{itemize}\nEliminate a deadlock using resource preemption needs that all the resources will be free to go into other processes in the system. If preemption is required to resolve deadlocks we can encounter 3 major issues:\n\\begin{itemize}\n    \\item \\textbf{Select a Victim}: which resources and which processes are preempted? we need to define perfectly which process to termiante carefully to not encounter more deadlocks in the system.\n    \\item \\textbf{Rollback}: if we preempt a resource from a process that process cannot restart after from the state where we stopped it, so we need to completely reset the process and make it start from the beginning.\n    \\item \\textbf{Starvation}: we can ensure that starvation cannot be a problem we need to carefully select the process to terminate and \\textit{how many time the process can be termianted}, because our algorithm can terminate forever the same process causing starvation.\n\\end{itemize}\n\n\n\\section{Memory Management}\n\\subsection{Background}\nMain memory and the registers built into the processors are a \\textbf{generale-pourpose storage} that the CPU can access \\textbf{directly}. There are machine instructiuons that take memory address as parameters, but \\textit{no one gets them from the main disk}.\\\\\nRgisters that are buyild into the CPU are generally accessible into one cycle of CPU clock, the same cannot be said from the disks, wich can be accessed only by transacting from the busses. In these cases the processor needs usually to \\textbf{stall} the system since it has the data. The main memory instead can be accessed directly and on that are defined the \\textbf{cache}, a slot of disk memory decided by the machine that lives into the main memory and can be replaced whenever the system wonts. The caches are not permanent and each time we need to use a variable in the disk we can put it in cache and reuse forever, until we save it into the disks, this process is called \\textbf{caching}.\\\\\nEach process has a unique memory space for itself into main memory between registers, so each process needs to determin the space of processes where they have a \\textit{legal access}. The registers can be divided into the \\textbf{base register} that holds the smallest legal physical memory address, or a \\textbf{limit registers} that defines a specific size of the range.\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page353-1.png}\n\\end{center}\nThe system memory is protected strictly by the CPU. If the processes find out user kernel processes that tries to modify system memory it traps the system, preventing the user to modify OS data structures or code.\\\\\nThe base and limit registers can be loaded  by the OS, which uses a special privilegesd instruction, tha can be executed \\textbf{only in kernel mode} and the OS can load only kernel mode processes, \\textbf{the system is the only one that can load the base and limit registers}.\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page353-2.png}\n\\end{center}\nUsually a program resides on the disk as a \\textbf{binary file}, when it needs to be executed the OS will load it into the main memory to make it available to the CPU. The proceses on the dish that are waiting to be bought into memory are defined into an \\textbf{input queue}.\\\\\nThe normal single tasking procedure is to select one of the process in the input queue and load that process into memory, when the process has finished the system declares the main memory available for another program.\\\\\nThe addresses of the system can be different during the process lifecycle, typically the compiler \\textbf{binds} the symbolic address of a process into a \\textit{relocable address}. Classically the binding of instructions and data into memory addreses can be done at any step along the program execution:\n\\begin{itemize}\n    \\item \\textbf{Compile Time}: if we know at compile time where the process will reside into memory we can generate the \\textbf{absolute code} and start the code compilation from there directly.\n    \\item \\textbf{Load Time}: if we know where the process will reside into memory the compiler can direclty generate \\textbf{relocatable code}, so that the binding can be delayed unitl load time.\n    \\item \\textbf{Execution Time}: if the proces can be moved during its execution from one memory segment to another the binding needs to be delayed until runtime.\n\\end{itemize}\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page355.png}\n\\end{center}\n\nThe address into the CPU is defined as \\textbf{logical address} that will be loaded into the \\textbf{memroy-address register}, commonly referred to a \\textbf{physical address}. However the physical addresses are differnet from the execution time addresses binding. In this case the addresses are referred as \\textbf{virtual address}. All the logical addresses are generated from a program called \\textbf{logical address space}, for the physical addresses instead we have \\textbf{physical address space}.\\\\\nThe run-time mapping cannot be done from the CPU, because we\'ll block the CPU each time we need to load programs in memory, so we delegate these actions to the \\textbf{Memory-Management Unit} (or \\textbf{MMU}).\\\\\nTo obtain better space memorization we can use the \\textbf{dynamic loading}. In this case a runtime is loaded only when is called, all routines are kept on disk in a relocable load format. THe main program is loaded into memroy and executed, and only when the routine needs to call another one, the calling routine fist checks to see whether the other routin is loaded, if not, the relocable linking claoder is called to load the desired routin into memory and update the program\' addresses.\\\\\nThe advantage of dynamic loading is that a routine is loaded only when it is needed, instead of everytime. We can use dynamic linking also in \\textbf{libraries}, where with the use of \\textbf{dynamically linked libraries} we can load them only when we need them.\\\\\nWith dynamic linking a \\textbf{stub} is included in the image for each library-routine reference. This stub is a small piece of code that indicates how to locate the appropriate memory-resident library routine or how to load the library if the routine is not already present. When the stub is executed it checks to see whether the neede routine is already in memory and if not it loads it into the system.\n\n\\subsection{Swapping}\nA process needs to be in memory to be executed, however it can be \\textbf{swapped} temporarily out of memory to a \\textbf{abcking store} and then bought back to continue execution.\\\\\nThe \\textbf{standard swapping} manages  ot move proces between memory and backing store (usually a fast disk), large enough to accomodate copieds of all memoruy images for all users, providing direct access to these memory images.\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page358.png}\n\\end{center}\nThe system maintains a \\textbf{ready queue} consisting of all processes whose memory images are on hte backing store and are ready to run. \\\\\nTo change memory state of a process it will autmatically call 2 main systemcalls: the \\textit{request\\_memory()} to go into the swap and the \\textit{release\\_memory()} ot get out of it.\n\n\\subsection{Contiguous Memory Allocation}\nThe memory is usually divided into 2 main partitions: one for the \\textbf{resident OS} and one for the \\textbf{user processes}. We can place the OS in either \\textbf{low memory} and \\textbf{high memory}, because we need to place soomewhere the \\textbf{interrupt vector}. Usually is \\textit{placed into low memory} we will take it as granted.\\\\\nThe process are usually stored into the \\textbf{contiguous memory allocation}, where each proces \nis contained in a single section of memory that is contiguous to the section containing the snext process.\\\\\nWhen the CPU scheduler selects the next process to execute loads the relocation and limits the registers with the correct value for the process execution. The relocation-register scheme provides an effective way to make the OS size change dynamically, to change in base of the code for some drivers into the system. If those drivers are not commonly used that code is called \\textbf{transient OS code} and \\textit{comes and goes as needed}.\\\\\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page361.png}\n\\end{center} \nOne of the most common methods of memory management define into memory some \\textbf{partitions}, where each partition may contain exactly one process. In this \\textbf{multiple-partition method}, when a partition is free, a process is selected from the input queue and is loaded into it. When the process finishes the partition will be newly free and another process will take it.\\\\\nThe partition methods usually defines a \\textbf{variable-partition scheme} and the OS will maintain a table to define which memory parts are available and which are occupied. Initially all hte memory is available, defining a \\textbf{hole} constructed by the whole memory. When the processes starts to occupy this big hole, more little holes will be defined.\\\\\nIn general when a process arrives in the system it\'s scheduled and put into the waiting queue. When it\'s resources are completely disposable is allocated with the resources into the main memory, in particular into a partition where it can execute it\'s code. When the process is finished it leaves the memory partition and leaves a \\textit{hole}. This process is called \\textbf{dynamic storage-allocation problem}, which defines how to satisfy the rquest of $n$ processes from a list of free holes. We can define to resolve this problem 3 main paths:\n\\begin{itemize}\n  \\item \\textbf{first-fit}: allocates the first hole that is big enough to contain the process, it stops searching when it finds a hole large enough, without going further.\n		\\item \\textbf{best-fit}: allocates the smallest hole that is big enough to contain the process, so when it finds the holes that can fit the process it finds out the smallest one.\n		\\item \\textbf{worts-fit}: allocates the largets hole of the one that can contain the process. This method is usually defined for processes that needs to grow in the period of execution.\n\\end{itemize} \nBoth first-fit and best-fit suffer from \\textbf{external fragmentation}, where as processes are loaded and removed from memory the free memory space is broken into little piecies, that cannot fit an entire process separately, but only when put together.\\\\\nUsing more or not best or first fit strategies we can implement in the syste more or less fragmentation, arriving into the situation where we have no free memory space to contain a single process.\\\\\nAs external there is also the \\textbf{internal fragmentation}, where we break memory into fixed size blocks and allocate memory in units based on the block size.\\\\\nOne solution to external fragmentation is the \\textbf{compaction}, wher ewe shuffle memory contents to place the more of free memory together in one large block. Another possible solution is to permit the logical address space of the process to be \\textbf{noncontigouous}, allowing a process to be allocated physical memory whenever such memory is available.\n\n\\subsection{Segmentation}\nSegmentation is a memory management scheme that supports the programmer view of memory. Usually when we run a program we need to define code into different places, like functions, structures or methods, these are supported from Segmentation, that divides into memory these parts of the user\'s program:\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page365.png}\n\\end{center} \nNormally when a program is compiled, the compiler automatically constructs segments reflecting the input program. A C compiler might create separate segments for:\n\\begin{itemize}\n    \\item Code\n    \\item Global Variables\n    \\item Heap\n    \\item Stack\n    \\item C libraries\n\\end{itemize}\nSEgmentation is also supported by hardware, where the system defines a \\textbf{segment table}, defined by a \\textbf{segment base} and a \\textbf{segment limit}. The segment base contains the starting physical address where the segment resides in memory, the segment limit specifies the length of that segment.\n\n\\subsection{Paging}\nPaging is another memory management schema used into memory, as segmentation. Paging avoids the external sementation problem and doesn\'t need compaction.\\\\\nThe method consists into breaking physicial memory into fixed blocks called \\textbf{frames} and breaking the locical memory into blocks called \\textbf{pages}.\\\\\nThe hardware supports paging directly into the CPU, because every addresses generated by it are divided into 2 parts: \\textbf{page number} (\\textit{p}) and \\textbf{page offset} (\\textit{d}). The page number is used into the \\textbf{page table} as an index, and combined with the offset it defines into the table the full physical memory address of the page.\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page368.png}\n\\end{center} \nHArdware definition of paging can be defined using \\textbf{dedicated registers} with high speed logic to make the page\'s address retrieve more efficient, for the other operations are like common registers. The page table is usually maintained into main memory with the \\textbf{Page Table Base Register} (\\textit{PTBR}) a register that contains the address that points to the page table in memory.\\\\\nThe problem with this approach is the \\textit{time required to access a use memory location}. This porblem is resolved using a fast and hardwared cached lookup called \\textbf{Translation Look-aside Buffer} (\\textit{TLB}) that compares the value of a key to it\'s value, checking all the table simultaneously, making very fast the translation of addresses:\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page373.png}\n\\end{center} \nSome TLBs astores in memory the \\textbf{address-space identifiers} (\\textit{ASIDs}) for each TLB entry, that uniquely identifies each process and is used to procide address-space protection for that process. If the TLB does not support separate ASIDs the TLB must be \\textbf{flushed} to ensure that the next executing process does not use the wrong translation information.\nThe percetnage of time that a page address is found into the TLBs is aclled \\textbf{hit ratio}. An 80\\% hit ratio for example defines that we can find the page address into the first 80\\% of the TLB.\\\\\nIf we fail to find the page address into the TLB we need to watch directly into the system memory. Here we need to find the \\textbf{effective memory-access time} to ensure performance also in TBLs failure.\\\\\n\n\\subsection{Structure of a Page Table}\nMost modern computer systems support a large logical address space, where also the pages becames to much large to be so performant, and we cannot reduce them ebcause we cannot contiguously add pages to the main memory. One way is to use \\textbf{two-level paging algorithm}, where the page table itself is \\textit{paged}. For example we can consider a system with 32-bit logical address space and a page size of 4 KB, a locical address is divided into a page number of 20 bits each and an offset of 12 bits, the page number next is also newly divided into a 10-bit page number and a 10-bit page offset, defining an \\textbf{hierarchical solution}.\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page379.png}\n\\end{center}\nThis structure is called \\textbf{fowardedd-mapped page table}. \\\\\n\n\n\\section{Virtual Memory}\n\\subsection{Background}\nVirtual memory provides a separation of logical memory perceived by the users from the physical memory. This virtual memory can be provided also to the programmers when the memory where are working on is small, helping him because hte programmer nmo longer needs to worry about the amount of physical memory available.\\\\\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page399.png}\n\\end{center}\nThe \\textbf{virtual address space} of a process is the lkogical opr virtual memory space of how a process is stored into memory. Holes in these cases are called \\textbf{sparse address spaces} and can be filled when the stack or heap grows, or if we want to store shareed libraries.\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page400.png}\n\\end{center}\nThese leads to the following benefits:\n\\begin{itemize}\n    \\item System libraries can be shared between several proceses to through mapping of the shared objects into virtual memory.\n    \\item Processes can share memory into the virtual memory, and don\'t need the previously seen tools to share informations.\n    \\item Pages can be shared during the process creation with the \\textit{fork()} syscall.\n\\end{itemize}\n\n\\subsection{Demanding Pages}\nA problem of the virtual memory approach is that we initially \\textit{need} the entire program in memory to start. Supposing that a program starts with a list of available options, we need to load the whole need into memory to start. An alternative is to load pages only when they are needed, this method is very commonly used and is called \\textbf{demanding paging}.\\\\\nWith \\textit{demand-page virtual memory} pages are loaded only when the program is demanding them and the pages that are not accessed are stored into physical memory anda never loaded into main memory. \\\\\nAlso in this case we can use the \\textit{swapping} previously seen, and is called \\textbf{lazy swapper}, tha never swaps a page into memory unless the page is needed. This method is done by a swapper called \\textbf{pager}.\\\\\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page401.png}\n\\end{center}\nTo do this entire work we need to \\textbf{mark pages} to define which process needs which pages, to load them dynamically. The system cannot simply \"guess\" which pages th process will need, so we need to mark them with a \\textit{valid-not valid bit} into the page table entry.\\\\\nIf a page hasn\'t laoded into main memory when the process starts the system goes into a \\textbf{page fault proble}, trapping the OS with an interruption. The process of recover is very straight foreward:\n\\begin{itemize}\n    \\item Check an internal tale for this process ti determine if the access was valid or not.\n    \\item If the reference was invalid we terminate the process, instead if is valid we load the page.\n    \\item We find a free frame into main memory.\n    \\item We schedule a disk operation to load the desired page into the selected frame.\n    \\item When the disk read is complete we modify the page table to keep the process accessing that page and loading it.\n    \\item The OS restarts the instractiuon where it has interrupted from the trap.\n\\end{itemize}\nWe can also choose to starts all the processes without pages laoded into memory, going into a \\textbf{pure demanding page opeartion} where we load them only when needed. \\\\\nThe hardware supports demanding paging with the same tools for normal paging and swapping:\n\\begin{itemize}\n    \\item \\textbf{Page Table}: this table has the ability to mark an entry invalid through a valid bit.\n    \\item \\textbf{Secondary Memory}: this memory holds those pages that are not present in main memory. Is usuall an high speed disk and can use swapping named \\textit{swap space}.\n\\end{itemize}\nWith virtual memory we can compute the \\textbf{effective access time} for a demand page memory system. This is calculated via:\n\\begin{center}\n    $EFT=(1-p)\\times ma+p\\times \\text{page fault time}$\n\\end{center}\nWhere:\n\\begin{itemize}\n    \\item $ma$: memory-access time, usually from 10 to 200 ns.\n    \\item  $p$: the probabaility ($0\\leq p\\leq1$) of having page faults in the system, called \\textbf{page-fault rate}.\n\\end{itemize}\n\n\\subsection{Copy-on-Write}\nWhen we create a process with the \\textit{fork()} syscall, we need to bypass terh demanding pages, garanting more efficience in process creation. Calling the \\textit{fork()} we create a child process by creating a copy of the parent, then we change it\'s process with the \\textit{exec()} function. We can instead use a new technique called \\textbf{copy-on-write} which allows the parent and child processes to share the same pages initially, and when one of the 2 process makes some actions on the pages it creates a copy of the page, modifing the address of the process pages to the new copy.\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page408.png}\n\\end{center}\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page409.png}\n\\end{center}\n\n\\subsection{Page Replacement}\nIf we allocate more pages that the one the system can offer we are \\textbf{over-allocating} memory, increasing the processes failures and interruptions into the system. To resolve these problems the system has methods to free the memory pages, swapping out processes and freeling frames. These algorithms are called \\textbf{page replacement}.\\\\\nThe basic page raplacement algorithm simply defines that if no frames are free we find out one that is not cuyrrently being used and we free it. We can free the frame by writing it\'s content to swap space and change so the page table to indicate that is free and allocate the page for the process faulted. We need next to overwrite the page-fault service to include the page replacement. In general the process:\n\\begin{itemize}\n    \\item Find hte location of the desired page on the disk.\n    \\item Find a free frame:\n    \\begin{itemize}\n        \\item If there is a free frame occupy it.\n        \\item If there is not a free frame, find an unused one, called \\textbf{victim frame}, and free it.\n        \\item Write the cictim frame to the disj and change the page and frame table statuses.\n    \\end{itemize}\n    \\item Load the desired page into the freed frame-\n    \\item Continue the process from where it has faulted\n\\end{itemize}\nWe can improve the performance adding a \\textbf{modify bit} (or \\textbf{dirty bit}) on the hardware\'s page table to define if the page has been modified or not.\\\\\nTo use this algorithm we need to resolve 2 main problems, we need to develop a \\textbf{frame-allocation algorithm} and a \\textbf{page-replacement algorithm}. If we have multiple processes in memory we must decide how many frames to allocate to each process and when the page replacement is required. There are many page replacent algorithms, to choose the right one we need to \\textit{select the one with the less page-fault rate}, usually demonstrated with the \\textbf{page-fault rate curve}:\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page413.png}\n\\end{center}\n\\subsubsection{FIFO Page Replacement}\nThe simplest page-replacement algorithm is a \\textbf{first-in, first-out algorithm}, that associates with each page the time when that page is brought into memory. To work it uses a FIFO queue to hold all pages in memory and we replace the head page with the next one after the usage. When a page is brought into memory we put it as tail of the queue.\\\\\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page414.png}\n\\end{center}\nThe page-fault rate curve in this case we find out a problem where \\textbf{the number of faults for four frames is greater than the number of faults for three frames}, defining the problem called \\textbf{Belady\'s Anomaly}, defining a less performant algorithm.\n\\subsubsection{Optimal Page Replacement}\nAs a result of the Belady\'s Anomaly has been reserched for an \\textbf{optimal page-replacement algorithm}, and has been found the \\textbf{OPT} algorithm, that simply says:\n\\begin{center}\n    \\textit{Replace the page that will not be used for the longest period of time}\n\\end{center}\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page415.png}\n\\end{center}\nIn this example we can find at the start a FIFO algorithm, but instead of removing the head we remove the page that is not used for the longest period of time on the reference string. This algorithm is unfortunately impossible to create because we require a \\textbf{future knwoledge of which processes are going to request which pages} in all time, and is basically impossible to obtain this information.\\\\\n\\subsubsection{LRU Page Replacement}\nWe previously sad that the OPT is impossible to implement, but an \\textit{approximation of it is possible}. This approach is called the \\textbf{Least Recently Used Algorithm} (\\textbf{LRU}). LRU replacemnet associates with each page the time of that page\'s last use. With this information when aa page must be replaces, LRU chooses the page that has not been used for the longest period of time. In summary is an OPT that watches backwards and not foreward.\\\\\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page416.png}\n\\end{center}\nThe result of LRU defines that defines a total of 12 page faults, considering that the first 5 faults are the same of OPT. \\\\\nLRU is commonly used as page-replacement algorithm and there are 2 main implementation choosable:\n\\begin{itemize}\n    \\item \\textbf{Counters}: the simplest case, we associate with each page-table entry a time.of.use field that we modify at each CPU cycle, counting how much time the process has been used. In this way we always have the \"\\textit{time}\" of usage of each page in memory. The times must also be maintained when page tables are changed.\n    \\item \\textbf{Stack}: another approach is to implement LRU replacement to keep a stack of page numbers. Whenever a page is references it\'s removeed from the stacn and put on the top. In this way the most used page until now is at the top of the stack and the less used it\'s at the end. The LRU algorithm points to the tail of the stack and removes the referenced page from memory, making space for the new one.\n    \\begin{center}\n        \\includegraphics[width=0.5\\linewidth]{img/page417.png}\n    \\end{center}\n\\end{itemize}\nLike OPT, LRU replacement does not suffer of Badely\'s Anomaly. Both belong to a class of page replacement algorithms called \\textbf{stack algorithms} and that can never find out the anomaly. A stack algorithm is defined as an algorithm for which it can be shown that the set of pages in memory for $n$ frames is always a \\textit{subset} of the set of pages that would be in memory with $n+1$ frames.\\\\\nSome systems may not provide hardware supprots for LRU and for that the algorithm needs to be modified adding a \\textbf{reference bit} for pages, that can be setted whenever that page is referenced. Initially all bits are cleared to 0 and are set to 1 by the hardware, defining which pages has been used or not.\\\\\n\\subsubsection{Counting-Based Pge Replacement}\nThere are many other algorithms tha tcan be used for page replacement, like keeping a counter of the number of references made to each page and develop:\n\\begin{itemize}\n    \\item \\textbf{LFU} (Least Frequently Used): a page replacement algorihtm that requires the page with the smallest count to be replaced. The reson for this selection is taht an actively used page should have a large reference count,but problems arises when a page is used heavily diring the inital phase of a process and then never used again.\n    \\item \\textbf{MFU} (Most Frequently Used): based on the argumetn thatthe page with the smallest count was probably just brought in and hasn\'t be used yet.\n\\end{itemize}\n\n\\subsection{Allocation of Frames}\nThe next question we need to respond is \\textit{how we allocate the number of frames divided for each processes loaded onto memory?} A first strategy defines that when the frames are loaded are putted into the free-frame list and when a user process demands them the frames are allocated. When the process termiantes it free the frames that return into the free-frame list.\\\\\nThere are many variation of this strategy. We can require taht the OS allocate all its vuffer and table space from the free-frame list, when the space is not used it can be used as support for paging or we can try to maintain free this space reserved on the free-frame list.\\\\\nOne of the most common strategies is to allocate the \\textbf{minimum number of frames}, to improve performance on the system, so decreasing the page-fault rate, but at the same time we need to be sure to have all the frames the system needs. The minumum number of frames is defined by the \\textbf{computer architecture}.\\\\\nThe worst-case scenario occurs whenin the computer architectures that allows the \\textit{multimple levels of indirection}. Theoretically a simple load instruction could reference an indirect address taht cull reference an indirect address that could also reference an indirect address and so on, until every page in virtual memory had been touched\\\\\nThere are some algorithm that can help us to split $m$ frames among $n$ processes with an equal share, calculating $\\frac{m}{n}$ frames for each process. This scheme is defined as \\textbf{equal allocation}.\\\\\nAn althernative to it is to recognizee that various processes will need diverent amount of memory. To solve this problem we use the \\textbf{proportional allocation} where we allocate available memory to each process according to its size. The size of memory for a procees $p_i$ will be $s_i$ where:\n\\begin{center}\n    $S=\\sum s_i$\n\\end{center}\n Then if the total num,ber of available frames $m$ we allocate $a_i$ frames to a that process, where $a_i$ is approxximately:\n \\begin{center}\n     $a_i=\\frac{s_i}{S\\times m}$\n \\end{center}\nOf course we must adjust each $a_i$ to be an iunteger that is frater thant the minumum number of frames required from the process.\\\\\nIn this way al the processes are satisfied accorting to their \"\\textit{needs}\".\\\\\nAnother important factor in the way frames are allocated to the various processes is page replacement. With multimple processes competing for frames we can classify page-replacement algorithms into 2 main boards: \\textbf{global replacement} and \\textbf{local replacement}.\\\\\nGlobal replacement allows processes to select a replacement frame from the set of all frames, even if is currently allocated to another process. Local replacement instead requires that each process select from only its own set of allocated frames.\\\\\nOne problem of global replacement is taht a process cannot control its own page-fault rage, providing the possibility of a process of different execution times for each execution. In local replacement instead we resolve this because the set of frames is limited and pre-choosen. Thus the global replacement methods is more profitable in therms of performance with an higher throughput.\\\\\n\n\\subsection{Thrashing}\nIf the number of frames allocated to a low priority process is below the minimum number required buy the computer architecture, we need  to suspend that process\'s execution. We should then page out its remainingp ageing, freeing all itsa llocated frames. All of these is made because if a process does not have enough frames it will easily on page-fault. At this point it must replace some pages, however since all its pages are in active use it must resplace a page that will be needed again in future.\\\\\nThis high paging activity is called \\textbf{thrashing}. A proces is threshing if \\textbf{it\'s spending more time in paging phase then executing}.\\\\\nWe can limit the effects of thrashing using a \\textbf{local replacement algorithm} (or \\textbf{priority replacement algorithm}), where if a process starts threashing, it cannot steal frames from another process and cause it thrashing as well. The problem is not entirely solved with this, because the thrashing process is still in the queue and will remain there forever, increasing the page fault rate.\\\\\nTo prevent thrashing we must provide a process with as many frames as it needs. To know this information there are various ways. The most common is the \\textbf{locality model}, where as a process ececutes it moves \\textit{from locality to locality}, where a \\textbf{locality} is a set of pages tah are actively used together.\\\\\nAntoher method requires using the \\textbf{working-set model} based on the \\textit{assumption of locality}. Here we need a parameter $\\Delta$ to define the \\textbf{working-ser window}, that define the a set of pages that has recently viewed, called \\textbf{working set}. If a page is in active use, it will be in the working set, if not it will drop from it. \\\\\nThe accuracy of the working set depends on the selection of $\\Delta$, if it\'s too small, it will not encompass the entire locality. For that we can measure the \\textbf{working-set size} for each process in the system:\n\\begin{center}\n    $D = \\sum WSS_i$\n\\end{center}\nWhere $D$ is the total demand for frames. Each process is actively using the page in the working set, defining that the process $i$ needs $WSS_i$ frames, so the total demand on the system is $D$.\\\\\n\\textbf{If the total domand is greater then the total frames number thrashing will occour}.\\\\\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page429.png}\n\\end{center}\nThe warking set model its perfect for solving thrashing, but seems a little clumsy, so it\'s common to use a strategy taht uses the \\textbf{page-fault frequency} (\\textbf{PFF}). Because thrashing has an high page-fault rate value, when it\'s too high we know that the process needs more frames to work, instead if it\'s too small the process has too many frames and will not use all of them. We can so ensure an \\textbf{upper and lower bound} of page-fault rate where if we exceeds the upper limi we allocate the process other frames, if it fells below the lower limit we remove frames from it.\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page430.png}\n\\end{center}\n\n\\subsection{Memory-Mapped Files}\nConsider a sequential read of a file on disj using the standard syscalls \\textit{open(), read() and write()}, each file access requires it and together a memory access. Alternatively we can use virtual memory techniquest to access file I/O like routine memory access. This approach is known as \\textbf{memory mapping} a file adn allowa a part of the virtual address space to be logically associated with the file.\\\\\nTo make this work the system needs to map a disk block to a page (or more pages) in memory, We have an initial acces to th file with demand paging, and a portion on the file is read from the file system into a physical page. Subsequent reads and writes to the file are handled as routine memory accesses. Manipulating files through memory rather than incurring the use of normal syscalls simplifies and speeds up the file acess. \\\\\nSome OSs provide memory mapping opnly through a specific syscall and use the standard syscalls to perform all other file I/O, others choose memory map a file regardless of whether the file was specified as memory mapped. \nMutilple process may be allowd to amap the same file concurrently, to allow sharing of data, allowing each process its own copy of the file:\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page432.png}\n\\end{center}\nQuite oftn shared memory is in fact implemented using memory mapping files, and so process can communicate using this shared memory.\\\\\nIn case of I/O each I/O controller registrs hold commands and the data being transferred. Usually special I/O intstructions allow data transfers between there registers and system memory. To allow more convenient access many computers allows \\textbf{memory mapped I/O}, where ranges of memory addrresses are set aside and are mapped to the \\textbf{device registers}. Reads and writes to these memory addresses cause the data to be transferred to and from the device registers. \\\\\nMemory mapped I/O is also convenient for other decices, like serial and parallel ports used to connect the external devices. If in these cases the CPU uses polling to check the control bit we it uses a method of \\textbf{programmer I/O}, if instead uses interruptions is called \\textbf{interrupt driven} transfare of data.\n\n\\subsection{Allocating Kernel Memory}\nWhen a process is running in user mode requests additional memory, where pages are allocated from the list of the free ones, maintained in the kernel. Kernel memory is often allocated froma free-memory pool, \\textbf{differnet from the user processes} for 2 main reasons:\n\\begin{itemize}\n    \\item The kernel requests memory for data strucutres of varying sizes, some of which are less tahn a page in size. As a result the kernel must use memory conservatively and attempt to minize waste due to fragmentation.\n    \\item Pages allocated to user-mode processes do not necessarily have to be in contiguous physical memory.\n\\end{itemize}\nThere are 2 main strategies fo managing free memory assigned to kernel processes.\n\\subsubsection{Buddy System}\nThe buddy system allocates memory froma fixed size segment of physically contiguous pages. Memory si allocated from this segment using a \\textbf{power-of-2 allocator} which \\textit{satisfies the requests of unit size in power of 2} (2KB, 4KB, 16KB,...).\\\\\nAn advantage of the buddy system is how quickly adjacent buddies can be combined to form larger segments using a technique called \\textbf{coalescing}:\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page437.png}\n\\end{center}\nWith this method the kernel releases some units, the system calesces it into another unit forming bigger units.\\\\\nThere is instead a problem in buddy system, that is the \\textit{fragmentation} caused by using only power of 2 memory units, causing little fragments of memory unused allocated to processes (for  example if a process needs 33KB of pages the system will allocate 64KB of memory to it, wasting 31KB).\n\\subsubsection{Slab Allocation}\nA second strategy for allocating kernel memory is known as \\textbf{slab allocation}, wher ewe use \\textbf{slabs}, a memory unit made up of \\textit{one or more physically contiguous pages}, and \\textbf{caches} that consists of \\textit{one or more slabs}. Each cache is populated with \\textbf{objects} that are instantiations of kernel data structure the cache represents. \\\\\nThe \\textbf{slab allocation algorithm} uses caches to store kernel objects. When a cache is created a number of objects (\\textit{initially marked as free}) are allocated to the cache. The number of objects in the cache depends on the size of the assiciated slab.\\\\\nIn Linux a slab can be defined in 3 possible states:\n\\begin{itemize}\n    \\item \\textbf{Full}: all objects in the slab are marked as used.\n    \\item \\textbf{Empty}: all objects in theslab are marked as free.\n    \\item \\textbf{Partial}: the slab consists of both used and free objects.\n\\end{itemize}\nThe slabs allocator initially tries to resolve the requests with the partial slabs, if none existsd a free object is assigned from an empty slab.\\\\\nThe slab allocator provides 2 main benefits:\n\\begin{itemize}\n    \\item No memory is waisted with fragmentation, because each kernel structure has a dedicated cache.\n    \\item Memory requests are satisfied quickly, because kernel structuers aare created in advance and cane be quikly allocated from the cache.\n\\end{itemize}\n\n\\section{Mass Storage Structure}\n\\subsection{Overview of Mass Storage Structure}\n\\textbf{Magnetic disks} are the main hardware part of mass storage. Each \\textbf{platter} of the disks have a sort of \\textbf{CD} into and is covered by 2 magnetic material surfaces.\n\\begin{center}\n    \\includegraphics[width=0.5\\linewidth]{img/page468.png}\n\\end{center}\nOn the magnetic disk is runned a \\textbf{disk arm} that moves all the heads as a unit. The surface of the platter is divided into \\textbf{tracks}, also divided into \\textbf{sectors} between them. \\\\\nWhen the disk is in use a driver motor spins the platters to make the system read data. THe most of disks can rotate 60 to 250 times per second, if we sum then on minutes we can retrieve the \\textbf{RPM} (\\textit{Rotation Per Minute}) of a disk. The \\textbf{transfare rate} of the disk defines the data flow of files shared with the system.\\\\\nThe \\textbf{positioning time}, or \\textbf{random-access time} is divided into 2 main parts:\n\\begin{itemize}\n    \\item \\textbf{Seek Time}: the time necessary to take the desired sector of tracks.\n    \\item \\textbf{Rotation Latency}: the time necessary for the desire sector to rotate the disk head.  \n\\end{itemize}\nDisk platters are coated with a thin protective layer and the head can be damaged during the time, this issue is called \\textbf{head crash}.\\\\\nA disk can be \\textbf{removable} to permit an infinite number of disks installed on the mashine. Other forms of removable disks that works very similarly to mass storage sare the \\textbf{flash drivers}.\\\\\nEach drive has built into it a \\textbf{disk controller} to perform I/O disk operations without have to use the CPU only for them.\\\\\nUntil now we had seen the \\textbf{Hard Disk} usage, but nowadays the \\textbf{SSDs} (\\textit{solid-state disk}), a non volatile memory used like an hard drive. SSDs has the same caracteristics then HDD, but are more used because it\'s \\textbf{faster than an usual hard disk}, having in cons a shorter life and can be more limited in size instead of HDDs.\n\n\\subsection{Disk Structure}\nModer magnetic disk arrives addressed as a large one-dimensional arrays of \\textbf{logical books}, where the logical book is the \\textbf{smallest transfare unit} size in the system.\\\\\nThe size of the lofical book is usually of \\textit{512 bytes}, but sometimes we can find disks with a \\textit{1024 bytes} size logical books. Even if the structure is constructed into logical books, these are \\textbf{mapped to disk sectors-like structures}, but this translation can be difficoult, because most disks have some defective sectors, but the mapping substitute these sectors with other tracks in the system and because the number of sectors per track is not constant for some drivers.\\\\\n\n\\subsection{Disk Attachment}\nComputers can access to the disk storage in 2 main ways: via \\textit{I/O ports}, called \\textbf{host-attached storage} or via \\textit{remote hosts} with \\textbf{network-attached storage}:\n\\begin{itemize}\n    \\item \\textbf{Host-Attached Storage}: the system connectes the CPU with the I/O ports of the disks to share data. Usually in big server storage are used the \\textbf{fibre challels} or \\textbf{FC} to have an high speed trnsmission ratio. The FC can be of different types in base of the device that can handle we can have a \\textbf{SAN} or a \\textbf{FC-AL}.\n    \\item \\textbf{Network-Attached Storage}: called also \\textbf{NAS} defies a storage system that can be \\textit{accessed remotely}. THe remote procedures usually use the \\textbf{RCPs} transmitted via TCP or UDP. \n    \\begin{center}\n        % \\includegraphics[width=0.8\\textwidth]{img/page472.img}\n    \\end{center}\n\\end{itemize}\n\n\\subsection{Disk Scheduling}\nOne of the responsabilites of the OS is to \\textit{use the hardware efficiently}, this also means that also disks needs to be correctly managed for efficiency reasons.\\\\ \nWe can define 3 main variables on disk performance on a system:\n\\begin{itemize}\n    \\item \\textbf{Seek Time}: the time for the disk arm to move the heads to the cylinder containing the desiderated sector.\n    \\item \\textbf{Rotational Latency}: the additional time for the disk to rotate the desired sector to the disk head.\n    \\item \\textbf{Bandwidth}: $\\frac{\\text{Total bytes transfered}}{\\text{Time from first byte transfare} + \\text{Time from last byte transfare}}$\n\\end{itemize}\nWhenever a process needs I/O to or from the disk, it usses a syscall to the OS. The request needs to specify:\n\\begin{itemize}\n    \\item Whether the operation is input or output.\n    \\item What the disk address for the transfer is.\n    \\item What the memory address for the transfer is. \n    \\item What the number of sectors to be transferred is.\n\\end{itemize}\nAlso disk needs to be \\textit{scheduled}, so we can define some algorithms for the scheduling.\n\\subsubsection{FCFS Scheduling}\nThe simplest algorithm we had alread yseen. It\'s a queue algorithm where the first request of blocks for trasfer that arrives is the first scheduled.\n\\begin{center}\n    \\includegraphics[width=0.8\\textwidth]{img/page474.png}\n\\end{center}\n\n\\subsubsection{SSTF Scheduling}\nSSTF, \\textbf{shortest-seek-time-first}, selects the request with the \\textbf{least seek time} from the current head position in the queue of requests.\n\\begin{center}\n    \\includegraphics[width=0.8\\textwidth]{img/page475.png}\n\\end{center}\n\n\\subsubsection{SCAN Scheduling}\nThe SCAN scheduling algorithm defines a method of scheduling that doesn\'t use a strage method to schedule requests, but scrolls the cylinders into the disks and when reaches a sector that has been requested from an instance into the queue it performs the requested action on that sector. When it reaches the end it go backwards to the starts with the same methods and restarts.\n\\begin{center}\n    \\includegraphics[width=0.8\\textwidth]{img/page476-1.png}\n\\end{center}\n\n\\subsubsection{C-SCAN Scheduling}\nWith the same method of SCAN method, the C-SCAN makes the same action, but to \\textbf{perform a uniform wait time} to each request. To do this che C-SCAN scheduling when it reaches the end it goes directly to the start without performing backwards.\n\\begin{center}\n    \\includegraphics[width=0.8\\textwidth]{img/page476-2.png}\n\\end{center}\n\n\\subsubsection{LOOK Scheduling}\nSCAN and C-SCAN algorithm in systems are not implementete as is, but usually the arm that reads or writes on disks goes only as far as the final request in each direction, then it reverses direction immediately, without arriving to the end of the disk. In this cases the SCAN and C-SCAN algorithms change names in \\textbf{LOOK} and \\textbf{C-LOOK} scheduling.\n\n\\subsection{Disk Management}\nOS needs also to manage the disks installed on the machine. The new disks installed are usually \\textbf{blank} but before it can store data \\textit{it needs to be divided into sectors}. This process is called \\textbf{low-level formatting} or \\textbf{physical formatting}. This method fills the disk with a \\textbf{special data structure} for each sector. The header and the trailer contains informations used by the disk controller, such as the \\textit{secto number} and the \\textbf{error-correcting code} (\\textbf{ECC}), used usually to report a \\textit{soft error} that can be recoverable.\\\\\nBefore that disk can store files the OS needs to record its own data structures. The first step is to \\textbf{partition the disk} into one or more groups of cylinders.\\\\ \nThe second step is the \\textbf{logical formatting}, that defines the creation of the \\textbf{file-system data} and all the structures implementation.\\\\ \nVery frequently some sectors can become \\textit{defective}. Most disks even come from the factory with \\textbf{bad blocks} and depending on the disks and types of controller used, the system handles them in different ways.\\\\ \nOn simple disks bad blocks are handles manually. One strategy is to find bad blocks with a scan on the disk, flagging them while the system format the disk. If blocks fo bad durign an operation a special program (in Linux is the $badblock$ command) mu+st be run manually to lock them.\\\\ \nMore sophisticated disks are smarter about bad block recovery. The controller maintains a list list of bad blocks sectors, initlized during the low-level formatting at factory.\\\\ \nThe controller can be told to \\textbf{replace each bad sector logically with one for the spare sector}. A typical bad-sector transaction might be:\n\\begin{itemize}\n    \\item The OS tries to read teh block $n$.\n    \\item The controller calculates the ECC and finds thath the sector is bad and reports this to the OS.\n    \\item The next time the system is rebooted the controller adds the bad sector to the list.\n    \\item After that whenever the system requires the logical block $n$, the request is translated into a replacement sector\'s address by the controller.\n\\end{itemize}\nAn alternative to sector sparing, some controllers can replace a bad block with a \\textbf{sector slipping}, remapping all the sectors from the bad block to the \\textbf{first available spare follow sector}.\\\\ \n\n\n\\section{I/O Systems}\n\\subsection{I/O Hardware}\nComputers operate a greate many kind of services, most fit into general categories \\textbf{storage devices} (disks, tapes) \\textbf{transmission devices} (network, bluetooth) and \\textbf{human-interface devices} (screen, keyboard, mouse,...).\\\\\nA device communciates with a computer sending signals over a gable or through air. More specifically I/O communicates  via \\textbf{ports}. If devices share common wires is created a \\textbf{bus}, a set of wires and a rigid protocol that define the communication of certain messages. The most of the devices shares common bus that we can fine pretty everywhere. These common busses are the \\textbf{PCI bus} the common system bus that \\textit{connects the processor memory to fast devices}, and the \\textbf{expansion bus} that connects slow devices like keyboards or mices. We have also the \\textbf{SCSI bus} that connects disks to the system, the couple \\textbf{PCI Express} (\\textbf{PCIe}) and \\textbf{HyperTransport} to connect main parts of the computer.\n\\begin{center}\n    \\includegraphics[width=0.8\\textwidth]{img/page589.png}\n\\end{center}\nEach electric part of a system defines a \\textbf{controller}. The controller are different in base of the devices they are attached. The wires serial ports uses a simple device (chip or portion of a chip) in the computer that controls signalson teh wires. The SCSI bus controller instead is not so simple because teh SCSI protocol is more complex and is ususally implemented in an external chip. This protocol defines a connection called \\textbf{SATA} (\\textit{Serial Advanced Technology Attachment}), to perform the protocol the processor that runs the SATA has some registers for data and control signals. This controller is used also for \\textbf{memory mapped I/O}.\\\\\nAn I/O port typically consists of 4 registers, called \\textit{status, control, data-in} and \\textit{data-out} registers:\n\\begin{itemize}\n    \\item \\textbf{data-in register}: read by the host to get input.\n    \\item \\textbf{data-out register}: written by the host to send output.\n    \\item \\textbf{status regisrter}: contains bits that can be read by the host, that indicates states of the processes requested.\n    \\item \\textbf{control register}: can be written by the host to start a command or to change teh mode of a device.\n\\end{itemize}\n\\subsubsection{Polling}\nThe complete protocol for interaction between the host and che controller can be intricate, but the main handshake is simple. Assume that 2 bits are usd to coordinate teh \\textbf{consumer-producer relationship} between them, the controller indicates its state through the \\textit{busy bit} in hte \\textit{status register}, setting it when the controller is working and clearing it when is not busy.\\\\ \nUsually the system use a \\textbf{polling} method to find out if an I/O device is being used:\n\\begin{itemize}\n    \\item \\textbf{1.} The host repeatedly reads the \\textit{busy bit} until that bit becomes clear.\n    \\item \\textbf{2.} The host sets the \\textit{write bit} in the \\textit{command register} and writes a byte into the \\textit{data-out register}.\n    \\item \\textbf{3.} The host sets the \\textit{command-ready bit}\n    \\item \\textbf{4.} When the controller notivces that the \\textit{command-ready bit} is set, it sets the busy bit.\n    \\item \\textbf{5.} The controller reads teh command register and sees sees the \\textit{write command}, it rads the \\textit{data-out register} to ghet the byte and does teh I/O to the device.\n    \\item \\textbf{6.} The controller clears the \\textit{command-ready bit}, clears the \\textit{error bit} and indicates teh succeds of the I/O operation.\n\\end{itemize}\n\\subsubsection{Interrupts}\nThe basic I/O operations usually follow s the polling method, but also the \\textbf{interruption method} can be applied. We can define an \\textbf{interrupt-request line} that the CPU senses after executing every instruction. When the CPU detects taht the controller has asserted a signal on the line, the CPU performs a \\textbf{interrupt-handler routine}. \\\\ \nWith this we can define an interrupt on the system that manages the CPU to run the I/O operation requested, we can say that the I/O device \\textbf{raises} anb interrupt and teh CPU \\textbf{catches} it and \\textbf{dispatches} it to the interrupt handler. After the execution is done the handler needs to clear out the buffers and register used to perform the interruption.\\\\ \nIn modern computer architectures there 3 feastures are provided by the CPU and by teh \\textbf{interrupt-controller hardware}.\\\\\nMost of the CPUs have 2 interrupts request lines: a \\textbf{nonmaskable interrupt}, which is reserved for events such as unrecoverable memory errors, or the \\textbf{maskable interrupt}, that can be turned off by teh CPU before the execution of the interruption.\\\\ \nThe interrupts mechanism accepts teh \\textbf{address}, this address is connected to an interrupt routine into the table called \\textbf{interrupt vector}, taht contains the specialized interrupt handlers for the defined addresses.\\\\ \n\\begin{center}\n    \\includegraphics[width=0.8\\textwidth]{img/page594.png}\n\\end{center}\nOther implementations can use some system calls to run \\textbf{software interrupts} or \\textbf{traps}.\n\\subsubsection{Direct Memory Access}\nFor devices that needs to do large transfers its expensive to use a general-pourpose processor, instead is called a process called \\textbf{programmed I/O} (\\textbf{PIO}). Many computers avoid burdening the CPU with PIO and defines a special pourposed controller and processor called \\textbf{Direct Memory Access controller} (\\textbf{DMA}). The DMA is loaded into memory directly in a \\textit{block}. This block contains a \\textit{pointer to the source} of transfer, a \\textit{pointer to the destination} and a count of the \\textit{number of bytes that needs to be transfered}. When the DMA operated the CPU writes the address of its controller into the block of the DMA one time and then does the other works. The DMA controller proceeds to operate the memory bus directly, placing addresses on the bus to perform transfers without the help of the main CPU.\\\\ \nHandshaking between the DMa controller and de device controller is performed via \\textbf{DMA-requests} and \\textbf{DMA-acknowledge}.\\\\ \nSome computers architectures use physicalk memory addresses for DMA, but others perform \\textbf{Direct Virtual Memory Access} (\\textbf{DVMA}), using virtual addresses that undergo tranlation to physical addresses.\n\\begin{center}\n    \\includegraphics[width=0.8\\textwidth]{img/page596.png}\n\\end{center}\n\n\\subsection{Application I/O Interface}\nInthis section are described the interfaces and techniques to the OS that enable I/O devices. Each general kind is accessed through a standardized set of functions, an \\textbf{interface}. THe differences are encapsulated in kernel modules called \\textbf{device drivers}.\\\\ \n\\begin{center}\n    \\includegraphics[width=0.8\\textwidth]{img/page598.png}\n\\end{center}\nEach type of OSs has it\'s own standards for the \\textit{device driver interface}, they can defere in:\n\\begin{itemize}\n    \\item \\textbf{Character-stream or Block}: a character-stream device that transfers bytes \\textit{one by one} or can transfer in blocks.\n    \\item \\textbf{Sequental or Random Access}: the access o device data can be \\textit{random} or\\textit{sequential} in base of teh OS decision.\n    \\item \\textbf{Synchronous or Asynchronous}: the operations on the devices can be as always \\textit{sycnrhonus} or \\textit{asynchronous} in base of teh OS.\n    \\item \\textbf{Sharable or Dedicated}: a device can be defines \\textit{sharable} between processes/threads or \\textit{dedeicated} to a single process/thread.\n    \\item \\textbf{Speed of Operation}: device speed can be decided from the OS definition.\n    \\item \\textbf{Read-Write, Read-Only or Write-Only}: OS can decide in a device access can be \\textit{rw, r} or \\textit{w}.\n\\end{itemize}\nMost OSs also have an \\textbf{escale} (or \\textbf{back door}) that transparently passes arbitrary commands from an applicaztion to a device driver. \\\\\nAnother aspect of the syscall interface relates to the choice between \\textbf{blocking I/O} or \\textbf{nonblocking I/O}. If an application issues a \\textbf{blocking syscall}, the execution of the application is suspended, teh application is moved from the OS into a \\textit{wait queue}, and after the blocking mechanism is completed it restarts from where it has stopped. Some user level processes instead needs teh \\textbf{nonblocking I/O}, tha define the instant block of che current operation to run the process. One example can be the use of a keyboard or a mouse. The user wants that immediately when the mouse is moved the OS needs to react to it.\\\\ \nAn althernative alternative to nonblocking syscalls are the \\textbf{asynchronuous sycalls}, that define tha a syscall an run in parallel to the I/O until the completition. \nWe need to have different interfaces in base of the devices we are trying to use.\n\n\\subsubsection{Block and Character Devices}\nThe \\textbf{block-device interface} captures all the aspects necesary for accessing disk drivers and other block-oriented devices.\\\\ \nThe OS itself may prefer to access a blockdevice as a simple linear array of blocks. This mode of access is called \\textbf{raw I/O}. This access can be easily provided, but the access to disk can be very slow and can provide comflicts, when an applcation wants to read a block it can block the operations arriving from the OS. To avoid these types of conflicts UNIX systems provide the \\textbf{direct I/O}.\\\\ \nOther devices can be accessed only by the \\textbf{character-stream interface}, like \\textit{keyboards}, where the OS runs the basic syscalls of\\textit{get()} and \\textit{put()} one character. \n\n\\subsubsection{Network Devices}\nBecause the perfomrance and addressing characteristics of netword I/O differ significantly from those disk I/O, most OS provicde a \\textbf{network I/O interface} different from the usual \\textit{read()-write()-seek()} interface used from disks. Ther main interface used from UNIX and Windows, is the \\textbf{network socket interface}.\\\\ \nSyscalls in the socket interface enable application to create a socket, to connect a local socket to a remote address, to listen for any remote application to plug into the local socked, to enable receiving and sending packets over the connection.\\\\ \n\n\\subsubsection{Clocks and Timers}\nMost computers have hardware clocks and timers that provide 3 basic functions: \\textit{give the current time}, \\textit{give the elapsed time} and \\textit{set a timer to trigger an operation on a specific time}\nThe hardware to measure elapsed tiem and to triggeroperation is called \\textbf{programmable interval timer}. It can be set t owait a certain amount of time nad then generate an interrupt. The scheduler uses this mechanism to generate an interrupot that will preempt a process at the and of its time slice.\\\\ \n\n\\subsection{Kernel I/O Subsystem}\nTo schedule a set of I/O requests means to determine a good order in whcih to execute them. Scheduling can improve overall system performance, can share device access fairly among processes and can reduce the average waiting time for I/O to complete.\\\\ \nOS implements in base a \\textbf{wait list} of I/O operations where all the requests are stored when they arrive to the system. \\\\ \nWhen a kernel supports \\textbf{asynchronous I/O} it must be able to track of many I/O requests at the same time. For this pourpose the system maintains, attached to the wait queue, a \\textbf{dewvice-status table}, which contains an entry for each I/O device, with the current status of it.\n\\begin{center}\n    \\includegraphics[width=0.8\\textwidth]{img/page605.png}\n\\end{center}\nKernel implements for I/O also \\textbf{buffering} methods, memory areas that store data being transfered between 2 devices. \\\\ \nThe actual work of nowadays systems are defined by the \\textit{network connection buffering method}. In this case we havea modem that transfer data in a more rapid rate than the OS, to reolve this teh system enables a \\textbf{double buffering} method where we have a starting buffer that is used at the start of the request, the moment fills the first buffer and the OS is blocked. When the first buffer is full the system starts to empty it and in parallel the second buffer is filled with other data, and in the time that the second buffer is filled, the first one is empty.\\\\ \nA second use of buffering is to provide adaptation for \\textbf{devices that have differnet data-transfare sizes}. A device send via network a data splitted in various fragments, those are maintained into a \\textbf{reassemble buffer} wher ethe complete package is reuilt.\\\\ \nA third use of buffering is to \\textbf{sopport copy semantics for application I/O}. Suppose that an application runs a \\textit{write()} syscall providing a pointer to the buffer and an integer specifing the number of bytes. After the syscall returns, what happens if the application changes data in the buffer? With \\textbf{copy semantics}, is guaranteed that the syscall version will be the one provided at the end of the application cycle.\\\\ \nAnother system method to upgrade performance performed by the OS are the \\textbf{caches}, regions of data that have a fast access, where the system can store the most used data and inforamtions.\\\\ \n\n\n\\section{File System Interface}\n\\subsection{File Concept}\nComputer can store informations on various stoorage media, such as disks, tapes, etc. The OS abstracts from the physical properties of its storage devices to define a logical storage unit, the \\textbf{file}.\\\\ \nA file is a named collection of related information that is recodrded on a secondary storage. From a user\'s perspective a file is teh smallest amount of logical secondary storage, the \\textbf{only way to writedata into the secondary storage}.\\\\ \nThe information in a file are defined by its creator. A file can be defined a \\textbf{text file}, a sequence of characters organized into lines, a \\textbf{source file} a set of functions followed by executable statements or \\textbf{executable file} a series of code sections that the loader can load into memory and execute on the system.\\\\ \nA fine is named from the human user, but other attributes are constantly defined by the system. We can define some common attributes that all files has:\n\\begin{itemize}\n    \\item \\textbf{Name}\n    \\item \\textbf{Identifier}: unique tag, usually a number that uniquely identifies the file in the machine.\n    \\item \\textbf{Type}: information needed from the system to determine the type of file loaded into memory.\n    \\item \\textbf{Location}: the path of the directory of the file.\n    \\item \\textbf{Size}: the current size of the file.\n    \\item \\textbf{Protection}: access-control that informate the system on who can access the file and which operation each user can do on it.\n    \\item \\textbf{Time, date and User Identification}: datetime of creation and who created it and the last modifiying user.\n\\end{itemize}\nWe can do different operations on a file:\n\\begin{itemize}\n    \\item \\textbf{Creating a File}: we need to define 2 steps: teh space on the file system must be found and then the allocation of the file.\n    \\item \\textbf{Writing a File}: to write a file we make a syscall specifing the identifier of the fila and what we want to write on it. This is usually done with a \\textit{write pointer} to teh location in the file where the next line needs to be wrote.\n    \\item \\textbf{Reading the File}: to read a file we needs a syscall, specifing where the file currently is and where the file needs to be put. To do this we need a \\textit{read pointer} to the location of the fine in where next read is to take place. We also need to maintain a \\textit{current position pointer}.\n    \\item \\textbf{Repotisioning within a File}: repositioning as file need not to involve any I/O, we only need to \\textit{recreate the current position pointer}. This operation is known also as \\textbf{seek}.\n    \\item \\textbf{Deleting a File}: to delete a file we need to seearch the director for the file name and releaase all file space.\n    \\item \\textbf{Truncating a File}: the user may want to erase the contents of a file, but maintain its attributes. Rather tha nforcint the user to delete teh file and the nrecreate it, this function permits to empty the file without deleting it.\n\\end{itemize}\nMost of the operation named until now needs to find the associated directory to the file. To do this we need the \\textbf{open()} syscall. The OS maintains an \\textbf{open-file table}, containing the information about all open files. The open-file table maintains also a \\textbf{open count} associated with each file to indicate how many processes have open that file.\\\\ \nTo create and delete a file we have the \\textbf{create()} and \\textbf{delete()} sycall. When we open a file with \\textit{open()} we also need to close it using the \\textbf{close()} syscall to reload it into memory.\\\\\nFile implements \\textbf{locks} to allow one process to lock a file and prevend race conditions. \\textbf{File locks} provide functionality similar to \\textit{reader-writer locks}. A \\textbf{shared lock}  defines a lock that several processes can open, an \\textbf{exclusive lock} instead provides access to only one process.\\\\ \nFiles maintains their properties in base of teh \\textbf{extension of the file}. The extension defines the type of the file and usually what it can do. We have multiple extension in base of the OS we are using:\n\\begin{center}\n    \\includegraphics[width=0.8\\textwidth]{img/page511.png}\n\\end{center}\n\n\\subsection{Access Methods}\nFile store information must be accessed and read into the computer memory. We can access to files in \\textit{different methods}:\n\\begin{itemize}\n    \\item \\textbf{\\textit{Sequential Access}}: in \\textit{sequential access} the file is processed in order, one record after the other. This mode of access is the most common, and it\'s usually used by compilers and editors. It\'s composed b 2 main syscalls: hte \\textit{read\\_next()} and the \\textit{write\\_next()}, that define a read/write on the next record of a file.\n\n    \\item \\textbf{\\textit{Direct Access}}: in \\textit{direct access} a file is made up of\\textit{fixed length logical records}, that allow programs to read and write records rapidly. This method is based on a disk model ofa  filem since disks allow random access ot any file block. For this method the file operations needs to include the bloc number $n$ into the syscalls, having \\textit{read(n)} and \\textit{write(n)}. The block number provided is normally a \\textbf{relative block number}.\n\\end{itemize}\n\n\\subsection{Directory and Disk Structure}\nAs we said before a disk can be \\textbf{partitioned} into quarters, and each quarter can hold a separate file system. Storage devices can be also collected together into \\textbf{RAID sets} that improve protection form failure of a single disk.\\\\ \nAnu entity containing a file system is generally known as a \\textbf{volume}. The volume may be a subset of a device. Volumes can also store multiple operating systems, allowing a system to \\textbf{boot and run multiple OSs}.\\\\ \nEach volume that contains a file system must also contain information about the files in the system. This information is contained into the \\textbf{device directory} (or \\textbf{volume table of contents}).\n\\begin{center}\n    \\includegraphics[width=0.8\\textwidth]{img/page516.png}\n\\end{center}\nAs we had seen the system can define different directory, but a general pourpose system will contain:\n\\begin{itemize}\n    \\item \\textbf{tmpfs}: temporary file directory in volatile memory.\n    \\item \\textbf{objfs}: virtual file system tha gives debuggers access ot kernel symbols.\n    \\item \\textbf{ctfs}: virtual file system that maintains the informations about which processes run at system boot.\n    \\item \\textbf{lofs}: a loop back file system that allows one file system to be accessed in place of another.\n    \\item \\textbf{procfs}: a \"loop back\" file system that allows one file system to be accessed in place of another one.\n    \\item \\textbf{ufs,ufz}: general pourpose file systems.\n\\end{itemize}\nWe can define a directory as a symbol table that resolves the file addresses into memory. We can do different operations on a directory:\n\\begin{itemize}\n    \\item \\textbf{Search of a file}: in a directory we need to be able to search for a file.\n    \\item \\textbf{Create a file}: we need to be able to create a file in a directory.\n    \\item \\textbf{Delete a file}: we need to be able to create a file in a directory.\n    \\item \\textbf{List a directory}: we need to be able to list all the file in a directory.\n    \\item \\textbf{Rename a file}: we need to be able to rename a file in a directory.\n    \\item \\textbf{Traverse the file system}: we may wish to access every firectory and every file within a directory structure.\n\\end{itemize}\nDirectories can be defined in \\textbf{different schemas}.\n\n\\subsubsection{Single-Level Directory}\nThe simplest directory structure. All files are contained in the same directory. This solution is the simplest but the least maintanable, because when the file number increases the performance decreses.\n\\begin{center}\n    \\includegraphics[width=0.8\\textwidth]{img/page519-1.png}\n\\end{center}\n\\subsubsection{Two-Level Directory}\nIn the 2 level directory structure each user has his own \\textbf{user file directory} (\\textbf{UFD}). The UFDs have similar structures, but each one lists only its user\'s files.\\\\ \nWhen a user job starts the system \\textbf{master file directory} (\\textbf{MFD}) is searched, indexed by the user identifier and manages that user\'s files.\n\\begin{center}\n    \\includegraphics[width=0.8\\textwidth]{img/page519-2.png}\n\\end{center}\nTo create a file for a user the OS searches only taht user\'s UFD and ascertain whether if exists another file with that name.\\\\ \nThe user name and the file name defines the \\textbf{path of that file}.\n\n\\subsubsection{Tree-Structured Directories}\nIt\'s a generalization of the 2 levels structure. Allws users to create their own \\textbf{subdirectories} and to organize their files accordingly. \\\\ \nA subdirectory contains a se of files or subdirectories. A directory is defined like another file, but is treated in a different way.\\\\ \nThe \\textbf{current directory} usually contains the most of the files that are of urrent insterest ot the process. When a reference is made, the current directory is searched.\\\\ \nHere the file path is defined bu an \\textbf{absolute path}, that starts from the \\textbf{root directory} to the file location, and a \\textbf{relatve path name}, that starts from the current directory.\\\\ \n\\begin{center}\n    \\includegraphics[width=0.8\\textwidth]{img/page521.png}\n\\end{center} \n\n\\subsubsection{Acyclic-Graph Directories}\nA tree structure prohibits the sharing of files or directories. An \\textbf{acyclic graph} (\\textit{a graph with no cycles}), allows directores to share subdirectories and files. The same file or subdirectory may be in 2 different directories.\\\\ \nShared files and subdirectories can be implemented in several ways. A common way, exemplifired by many of hte UNIX system is to create a \\textbf{link}. A link is effectively a pointer to another fileor subdirectory. To access the file we \\textbf{resolve the link} by using tht path name to locate the real file. \\\\ \nAnother method is to \\textbf{duplicate directories} for all the users on the system, maintaining them identical on the system.\\\\ \n\\begin{center}\n    \\includegraphics[width=0.8\\textwidth]{img/page523.png}\n\\end{center}\n\n\\subsubsection{General Graph Directory}\nA serious problem using acycle-graph structure is ensring that there are no cycles in the graph. If we start with a 2 level directory, allowing each user to create subdirectorie, we create a tree-structured directory. However when we add links the tree structure is destroyed, resulting in a simple graph structure.\n\\begin{center}\n    \\includegraphics[width=0.8\\textwidth]{img/page525.png}\n\\end{center}\nIf cycles are allowed to exists in the directory, we want to avoid searching any component twice, for reasons of performance. The solution is to limit arbitraily the number of directoris tha twill be accessed during a search. \\\\ \nA similar problem exists when we are trying to determine when a file can be deleted. If cycles exists the reference count may not be 0 even when it\'s no longer possible to refer to a directory or file. This anomaly results from the possibility ofa cucle in the structure and to resolve it we need to use a \\textbf{garbage collection scheme} ot determine when the last refernce has been deleted and the disk space can be reallocated.\n\n\\subsection{File-System Mounting}\nJuset as a file must be opened before it is used, a file system must be \\textbf{mounter before it can be available} to process on the system.\\\\ \nThe mount procedure is straightforeward. The OS is given the name of the device and the \\textbf{mount point}, the location within the file structure where the file system is to be attached. Next the OS verifies that the device contains a valid file system. It does so by asking the device driver to read the device directory and verifying that the directory has the expecred format. Finally the OS notes in its directory structure thata file system is mounted at the specified mount point.\n\\begin{center}\n    %\\includegraphics[width=0.8\\textwidth]{img/page527.png}\n\\end{center}\n\n\\subsection{File Sharing}\nOnce multimple users are allowed to share files, the challenge is to extend sharing multimpl file systems, including remte file systems.\\\\ \nTo implemenet sharing and protection the system must maintain more file and directory attributes than are needed in a single-user system. Each file must define an \\textbf{owner}and a \\textbf{group}. The owner is who can change attributes and grant access to the file, usually who has created it. THe group attribute defines a \\textit{subset of users} who can share access to a file.\\\\ \nThrough the evolution of network and file technology, remote file-sharing methods have changed. The first implemented method was defined by transferring files between machines via programs. A second major method uses a \\textbf{Distributed File System} (\\textbf{DFS}), in which remnote directories are visible from a local machine. \n\n\\subsection{Protection}\nProtection mechanisms provide controller access by limiting the types of file access that can mbe made. Access is permitted or denied depending on several factors, one of which is the type of access requested. Several different types of operations may be controlled:\n\\begin{itemize}\n    \\item \\textbf{Read}\n    \\item \\textbf{Write}\n    \\item \\textbf{Execute}\n    \\item \\textbf{Append}\n    \\item \\textbf{Delete}\n    \\item \\textbf{List}\n\\end{itemize}\nThe most common approach to the protection of files is the implementation of the \\textbf{Access Control List} (\\textbf{ACL}) that specifies the user names and the types of accesses allowed for each user. When a user requests to access a particular fil, the OS reads if that user is listed for the requested access, the access is garanted, otherwise a protection violation occurs and the user job is denied.\\\\ \nThis technique has 2 underirable consequences:\n\\begin{itemize}\n    \\item Constructing such a lsit may be a tedious and unrewarding task.\n    \\item The directory entry must be of a variable size, resulting more complicated.\n\\end{itemize}\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\\end{document}',1,'University');
